window.CY = {"meta":{"city":"澎湖縣","slug":"penghu-county","updated":"2026-11-01","designer":"Allan Lo","designed":"2026/11/1","ai":"Claude Opus 5.5"},"config":{"slug":"penghu-county","name":"澎湖縣","short":"澎湖","center":[23.5,119.56],"zoom":10,"minZoom":8,"detailZoom":16,"timeZoom":11,"fitSites":true,"categories":["國定古蹟","縣定古蹟","歷史建築","紀念建築","聚落建築群","考古遺址","文化景觀"],"towns":["馬公市","湖西鄉","白沙鄉","西嶼鄉","望安鄉","七美鄉"],"ubikeAreas":[],"wiki":{"title":"維基百科「澎湖縣文化資產」","url":"https://zh.wikipedia.org/zh-tw/%E6%BE%8E%E6%B9%96%E7%B8%A3%E6%96%87%E5%8C%96%E8%B3%87%E7%94%A2"},"introTitle":"歡迎來到澎湖群島","quizTitle":"澎湖文資通","eraLabels":{"dutch":"宋元明與荷蘭時期（–1662）","zheng":"明鄭時期（1662–1683）","qing":"清代（1683–1895）"},"board":{"name":"菊島擲骰大冒險","start":"出發：馬公港","train":"跨海大橋","trainText":"騎上澎湖跨海大橋，前進 3 格！","food":"黑糖糕補給站"},"planner":{"speeds":{"car":30,"scooter":28,"bike":12,"walk":4.5,"ubike":12},"hints":{"car":"澎湖本島（馬公、湖西）、白沙、西嶼之間有中正橋、永安橋與澎湖跨海大橋相連，開車可以一路開到西嶼燈塔，從馬公出發約 50 分鐘。馬公市區巷弄窄、停車位少，車停在外圍再步行。到吉貝、望安、七美要搭船，車子不能一起過去。每站已預留約 8 分鐘停車時間。","scooter":"租機車是逛澎湖最常見的方式，可以騎過跨海大橋到西嶼。冬季東北季風（大約 10 月到隔年 3 月）風很大，騎上跨海大橋要小心側風、注意保暖；夏天日照強，記得防曬。到外島要搭船，上岸後再租車。","bike":"澎湖地勢平坦，但風大、日曬強，騎單車很考驗體力；馬公市區與近郊適合騎，單段超過 12 公里（例如馬公到白沙、西嶼）會建議改騎機車、開車或搭公車。","walk":"馬公的天后宮、中央街、四眼井、施公祠、順承門與日治時期的廳舍、郵便局彼此很近，適合步行串遊；單段超過 3 公里會建議改騎機車、搭公車或計程車。","ubike":"澎湖縣目前沒有 YouBike 站點，建議租機車、開車，或搭澎湖縣公車、計程車。"},"defaultMode":"scooter","lunchNote":"澎湖在地小吃：小管料理、海鮮粥、花枝丸，飯後來一碗仙人掌冰，伴手禮可帶黑糖糕、鹹餅；馬公市區店家最多","eveningNote":"晚上可以逛馬公中央老街、天后宮一帶，或到觀音亭看海景與西瀛虹橋；夏季的海上花火節日期以澎湖縣政府公告為準，部分店家較早打烊","walkMaxKm":3,"bikeMaxKm":12,"ubikeStationMaxKm":1.2,"farKm":60,"islands":[{"name":"吉貝","bbox":[23.715,119.58,23.765,119.64],"port":[23.73957,119.61185],"portName":"吉貝港","mainPort":[23.66877,119.60305],"back":"白沙赤崁（北海遊客服務中心）","seaMin":35,"note":"吉貝嶼在白沙島北方，從白沙赤崁的北海遊客服務中心一帶搭船，船程約 20 分鐘，夏季班次較多。島上可租機車、步行或騎單車。冬季東北季風期（大約 10 月到隔年 3 月）船班少、常因海象停航，出發前請向航商確認。","lunchNote":"吉貝的餐廳集中在吉貝港附近的村落，冬季淡季許多店家休息，建議先確認"},{"name":"望安","bbox":[23.33,119.46,23.4,119.545],"port":[23.36186,119.50835],"portName":"望安潭門港","mainPort":[23.56645,119.57242],"back":"馬公港（南海遊客服務中心）","seaMin":60,"note":"望安從馬公港南海遊客服務中心搭交通船到潭門港，船程約 40 到 50 分鐘，往七美的船通常先停望安；高雄也有小飛機飛望安。船票實名制，班次不多，冬季東北季風期（大約 10 月到隔年 3 月）常因海象停航，出發前請查詢最新船班。上岸後租機車逛花宅與西安。","lunchNote":"望安午餐多在潭門港與東安村一帶的小吃店，店家不多、部分不定休，建議先確認","links":{"七美":45}},{"name":"七美","bbox":[23.17,119.38,23.245,119.465],"port":[23.19521,119.4188],"portName":"七美南滬港","mainPort":[23.56645,119.57242],"back":"馬公港（南海遊客服務中心）","seaMin":120,"note":"七美從馬公港搭交通船，多半經望安再到南滬港，全程約 1.5 到 2 小時；也可以從馬公或高雄搭小飛機到七美機場，班次少、要提早訂位。冬季東北季風期（大約 10 月到隔年 3 月）船班常停航，出發前請查詢最新船班與航班。島上租機車環島約 1 小時。","lunchNote":"七美午餐多在南滬港與七美鄉公所一帶的小吃店，店家不多、部分不定休，建議先確認","links":{"望安":45}}],"noVisit":{"baisha-mudouyudengta":"目斗嶼位在吉貝北方外海，是無人島，沒有一般交通船，一般民眾無法自行登島；跳島行程多半只從船上遠眺燈塔。"}},"eras":{"dutch":{"layers":[],"paper":true,"end":1662,"note":"宋元明與荷蘭時期沒有實測地圖，底圖改成古紙風格，標示的是推定位置。"},"zheng":{"layers":[],"paper":true,"end":1683,"note":"明鄭時期沒有實測地圖，底圖改成古紙風格，標示的是推定位置。"},"qing":{"layers":["1904"],"end":1895,"note":"1904 年的臺灣堡圖測繪於日治初期，還看得到清代媽宮城的城牆與街道。"},"japan":{"layers":["1921","1945"],"end":1945,"note":"1921 年地形圖涵蓋整個澎湖群島；馬公市區另可切換 1945 年美軍繪製的城市地圖。"},"early-roc":{"layers":["1950"],"end":1960,"note":"1950 年的地形圖：戰後初期的澎湖。"},"roc60":{"layers":["1966"],"end":1981,"note":"1957–1969 年的地形圖：民國 60 年前後的澎湖，跨海大橋剛通車。"},"now":{"layers":["photo","1989"],"end":2026,"opacity":0,"note":"今天的澎湖縣。可疊上正射影像或 1989 年的地形圖做對照。"}}},"categories":["國定古蹟","縣定古蹟","歷史建築","紀念建築","聚落建築群","考古遺址","文化景觀"],"sites":[{"id":"magong-tianhougong","name":"澎湖天后宮","short":"澎湖天后宮","category":"國定古蹟","level":"國定古蹟","town":"馬公市","types":["寺廟"],"lat":23.564832,"lng":119.563924,"address":"澎湖縣馬公市中央里正義街1號","announced":"1983-12-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19831228000013","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-01/5cf883f4-a40d-4979-acf5-86a9406d3f31/T015 澎湖縣 澎湖天后宮 (一級)02.jpg","year":1604,"yearText":"1604年（明萬曆32年）已有可靠紀錄","era":"dutch","themes":["宗教信仰","牌坊碑碣"],"yearUnknown":false,"summary":"臺灣歷史最悠久的媽祖廟之一","intro":"澎湖天后宮位於馬公市中央里正義街，是闔澎三大公廟之首，也是臺灣歷史最悠久的媽祖廟之一。前身可能是宋元以來閩南漁民、商人在海邊搭建的小廟；最早的可靠紀錄是明萬曆32年（1604）都司沈有容在此諭退荷蘭將領韋麻郎，廟內保存的「沈有容諭退紅毛番韋麻郎等」石碑就是見證。明代這裡被稱為娘媽宮、媽宮，廟名後來成為地名，1920年才改稱馬公。今貌是1922年起由潮州大木匠師藍木主持重建，山川殿、正殿與清風閣依地勢逐進升高，石雕、鑿花與擂金畫都很精彩。","highlights":["清風閣內的「沈有容諭退紅毛番韋麻郎等」石碑","正殿後落少見的擂金畫，以深淺金色作畫","白灰硓𥑮石牆與起翹屋脊勾勒的天際線"],"funFact":"這塊石碑在2003年初遠赴台北故宮參加特展，那是它第一次離開澎湖。","photoSpot":"在正義街廟埕拍山川殿屋脊起翹","visitMin":40,"openNote":"位於馬公市中央里正義街，官方開放時間約7:00至17:00，參拜請保持肅靜、尊重儀式。距馬公港步行可達，可與中央街、四眼井、施公祠串成散步路線。","dialogue":[{"who":"R","text":"Allan，我考你一題，馬公這個地名是從哪裡來的？"},{"who":"A","text":"考到我的專業了！答案就在眼前，這座天后宮在明代被叫做媽宮，廟名後來變成地名。"},{"who":"R","text":"那為什麼現在叫馬公，不叫媽宮？"},{"who":"A","text":"1920年日本政府把媽宮改成馬公，念起來差不多，寫法卻變了，就像我的頭髮，看起來沒變，其實越來越少。"},{"who":"R","text":"好冷喔！那這間廟到底有多老？說個數字來聽聽。"},{"who":"A","text":"最早的可靠紀錄是1604年，明朝的沈有容在這裡勸退荷蘭將領韋麻郎，那塊石碑還保存在清風閣。"},{"who":"R","text":"400多年前的石碑，它有出過遠門嗎？"},{"who":"A","text":"有喔，2003年它到台北故宮參加特展，那是它第一次離開澎湖，算是最資深的出差族。"},{"who":"R","text":"那我進清風閣先跟這位出差族打招呼，找找碑上「韋麻郎」三個字！"}],"clues":["我的名字後來變成了整座城市的地名","我保存著沈有容勸退荷蘭人的石碑","我是馬公正義街上的闔澎公廟，主祀媽祖"],"quiz":[{"q":"天后宮內的古碑記錄沈有容勸退了誰？","options":["韋麻郎","鄭芝龍","雷爾生","劉國軒"],"answer":0,"explain":"1604年沈有容在此諭退荷蘭將領韋麻郎。"},{"q":"媽宮在哪一年改名為馬公？","options":["1895年","1904年","1920年","1945年"],"answer":2,"explain":"1920年日本政府將媽宮改名為馬公。"}],"images":[{"file":"PXL 20210522 澎湖媽祖宮 (1)立面 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/PXL_20210522_%E6%BE%8E%E6%B9%96%E5%AA%BD%E7%A5%96%E5%AE%AE_%281%29%E7%AB%8B%E9%9D%A2_%28cropped%29.jpg/960px-PXL_20210522_%E6%BE%8E%E6%B9%96%E5%AA%BD%E7%A5%96%E5%AE%AE_%281%29%E7%AB%8B%E9%9D%A2_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:PXL_20210522_%E6%BE%8E%E6%B9%96%E5%AA%BD%E7%A5%96%E5%AE%AE_(1)%E7%AB%8B%E9%9D%A2_(cropped).jpg","artist":"舟集 Boattoad","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-tianhougong-0.webp","small":"img/magong-tianhougong-0-s.webp"}]},{"id":"magong-fengguiweihelan","name":"馬公風櫃尾荷蘭城堡","short":"風櫃尾荷蘭城堡","category":"國定古蹟","level":"國定古蹟","town":"馬公市","types":["城郭"],"lat":23.553719,"lng":119.548544,"address":"澎湖縣馬公市風櫃西段2地號","announced":"2001-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20011121000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-01/f2ca24b3-2f21-4683-8919-6ec64a7d2a98/T032 澎湖縣 馬公風櫃尾荷蘭城堡 (一級)01.jpg","year":1622,"yearText":"1622年（明天啟2年）","era":"dutch","themes":["城垣礮臺","軍事遺構","戰爭史蹟"],"yearUnknown":false,"summary":"荷蘭人轉往大員前在澎湖築的堡壘","intro":"馬公風櫃尾荷蘭城堡位於馬公市風櫃里俗稱「蛇頭山」的小半島上。明天啟2年（1622）荷蘭東印度公司占領澎湖，在此築堡作為貿易據點，堡內有司令官住所與營舍。堡壘為小型歐式堡壘，平面正方形，長寬各約55公尺，四角有向外突出的稜堡，土垣高約7公尺，稜角上共安置29門大砲。天啟4年（1624）明軍圍攻，雙方達成協議，荷蘭人拆下可搬運的建材運往大員（今臺南安平）興建熱蘭遮城。此後僅存土垣與濠溝，歷代仍作為海防砲陣地，二戰後荒廢，現場只見遺跡。","highlights":["蛇頭山上隆起的土垣與濠溝遺跡","從稜堡位置想像正方形歐式堡壘的格局","隔著海灣眺望馬公市區的開闊視野"],"funFact":"荷蘭人撤離時把能拆的建材打包運到大員，拿去蓋熱蘭遮城，這座城堡等於是熱蘭遮城的前身之一。","photoSpot":"在蛇頭山坡頂拍土垣與海灣","visitMin":30,"openNote":"位於馬公市風櫃里蛇頭山，自由參觀，現場僅存土垣、濠溝等遺跡，沒有建築本體。建議騎機車或開車前往；海邊風大，冬季東北季風期間請注意保暖與安全。","dialogue":[{"who":"A","text":"歡迎來到蛇頭山！阿拉蕾，你現在站的地方，400年前是一座荷蘭城堡。"},{"who":"R","text":"城堡？Allan，我只看到草皮跟土堆，城堡是隱形的嗎？"},{"who":"A","text":"差不多算消失了。1622年荷蘭東印度公司在這裡築堡，四四方方，每邊約55公尺，四個角還有突出的稜堡。"},{"who":"R","text":"聽起來很氣派，那它怎麼不見了？"},{"who":"A","text":"1624年明軍圍攻，雙方談好條件，荷蘭人把能拆的建材搬走，運到大員去蓋熱蘭遮城。"},{"who":"R","text":"原來是整座城打包搬家！那這裡算是熱蘭遮城的老家囉？"},{"who":"A","text":"可以這麼說。當年稜角上架了29門大砲，荷蘭人走後，歷代政府也都把這裡當砲陣地。"},{"who":"R","text":"連拆剩的土堆都被重複利用，真是環保模範生。"},{"who":"A","text":"等一下沿著土垣走一段，找找看哪個角落最像當年突出去的稜堡！"}],"clues":["我在澎湖只站了兩年，就被拆去蓋另一座城","我是正方形堡壘，四角各有一座稜堡","我位在風櫃里俗稱蛇頭山的小半島上"],"quiz":[{"q":"荷蘭人撤離時，把建材運到哪裡蓋新城？","options":["雞籠","打狗","大員","淡水"],"answer":2,"explain":"建材運往大員（今安平）興建熱蘭遮城。"},{"q":"荷蘭人占領期間，堡壘稜角上共安置多少門大砲？","options":["29門","9門","19門","39門"],"answer":0,"explain":"官方資料記載稜角上共安置29門大砲。"}],"images":[{"file":"馬公風櫃尾荷蘭城堡 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/%E9%A6%AC%E5%85%AC%E9%A2%A8%E6%AB%83%E5%B0%BE%E8%8D%B7%E8%98%AD%E5%9F%8E%E5%A0%A1_peiiunwu.jpg/960px-%E9%A6%AC%E5%85%AC%E9%A2%A8%E6%AB%83%E5%B0%BE%E8%8D%B7%E8%98%AD%E5%9F%8E%E5%A0%A1_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%A6%AC%E5%85%AC%E9%A2%A8%E6%AB%83%E5%B0%BE%E8%8D%B7%E8%98%AD%E5%9F%8E%E5%A0%A1_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-fengguiweihelan-0.webp","small":"img/magong-fengguiweihelan-0-s.webp"}]},{"id":"xiyu-dengta","name":"西嶼燈塔(漁翁島燈塔)","short":"西嶼燈塔","category":"國定古蹟","level":"國定古蹟","town":"西嶼鄉","types":["燈塔"],"lat":23.562421,"lng":119.46958,"address":"澎湖縣西嶼鄉外垵村195號","announced":"1987-04-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19870417000003","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1295/photo/西嶼燈塔1.jpg","year":1875,"yearText":"1875年（清光緒元年）；前身塔燈始於1778年","era":"qing","themes":["燈塔航運"],"yearUnknown":false,"summary":"臺澎最早的西式燈塔，前身是清代石塔燈","intro":"西嶼燈塔又稱漁翁島燈塔，位於西嶼鄉外垵村西南端岬角，西側就是澎湖急流之一的「西流」，自古是臺廈航路的重要標識。1778年（清乾隆43年）臺灣知府蔣元樞與澎湖通判謝維祺在此建七級石塔，頂上點長明燈，是臺澎最早的燈塔。後來因燈光不足，應各國要求改建新式燈塔，由英國工程師韓得善設計，1875年（光緒元年）動工並於年底點燈，是臺澎最早的現代化西式燈塔。塔身為歐洲進口的預製鑄鐵，門楣鑄有「DAVID M. HENDERSON 1874」名牌。院內保存霧砲、閩海關界碑與清代碑記，院牆外還有守塔洋人女兒的十字墓碑。1987年指定為古蹟，今為國定古蹟。","highlights":["門楣上「DAVID M. HENDERSON 1874」鑄鐵名牌","院中的霧砲、閩海關界碑與清代碑記","院牆外守塔洋人女兒的十字墓碑"],"funFact":"官方說明它是臺灣營建史上第一座預鑄式建築，塔身是從歐洲進口的鑄鐵構件。","photoSpot":"在院牆邊拍白色塔身與霧砲","visitMin":40,"openNote":"位於西嶼鄉外垵村西南端。依官方資料開放時間為9:00–16:00，週一休館，請以現場公告為準。據資料前往燈塔需穿越國軍營區，請勿逗留或拍攝營區。可與西嶼西臺、外垵餌砲串遊。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"R","text":"Allan，這座白色燈塔矮矮胖胖的，比我想像中可愛耶！"},{"who":"A","text":"可別小看它，西嶼燈塔是臺澎最早的現代化西式燈塔，1875年就開始點燈了。"},{"who":"R","text":"1875年！那更早以前的船怎麼認路？"},{"who":"A","text":"早在1778年，臺灣知府蔣元樞就在這裡蓋了七層石塔，塔頂點長明燈，算是燈塔的阿公。"},{"who":"R","text":"燈塔也有家譜，真是航海界的書香世家！"},{"who":"A","text":"現在這座是英國工程師韓得善設計的，塔身是從歐洲運來的鑄鐵構件，組起來像大型積木。"},{"who":"R","text":"原來古早就有預製組合屋！還有什麼一定要看的？"},{"who":"A","text":"院子裡有起霧時用的霧砲，牆外還有一座守塔洋人女兒的十字墓碑，經過時記得放輕腳步。"},{"who":"R","text":"那我去找門楣上的鑄鐵名牌，看看上面寫的年份是不是1874！"}],"clues":["我的前身是清乾隆年間的七層石塔燈","我的門楣上鑄著英國設計師的名字和1874","我站在外垵村岬角，又叫漁翁島燈塔"],"quiz":[{"q":"1778年最早在西嶼建塔燈的是哪兩位官員？","options":["劉銘傳與吳宏洛","沈有容與施琅","蔣鏞與陳化成","蔣元樞與謝維祺"],"answer":3,"explain":"臺灣知府蔣元樞與澎湖通判謝維祺建七級石塔。"},{"q":"現今西嶼燈塔的塔身是什麼構造？","options":["花崗石砌造","預製鑄鐵","鋼筋混凝土","紅磚疊砌"],"answer":1,"explain":"塔身為歐洲進口的預製鑄鐵構造。"}],"images":[{"file":"漁翁島燈塔.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/%E6%BC%81%E7%BF%81%E5%B3%B6%E7%87%88%E5%A1%94.jpg/960px-%E6%BC%81%E7%BF%81%E5%B3%B6%E7%87%88%E5%A1%94.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BC%81%E7%BF%81%E5%B3%B6%E7%87%88%E5%A1%94.jpg","artist":"Joe Lo from Changhwa, Taiwan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/xiyu-dengta-0.webp","small":"img/xiyu-dengta-0-s.webp"}]},{"id":"huxi-gongbeipaotai","name":"湖西拱北礮臺","short":"拱北礮臺","category":"國定古蹟","level":"國定古蹟","town":"湖西鄉","types":["關塞"],"lat":23.562691,"lng":119.609654,"address":"澎湖縣湖西鄉城北段1387、1388、1389地號","announced":"2001-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20011121000003","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1272/photo/湖西拱北砲臺1.JPG","year":1886,"yearText":"1886年（清光緒12年）","era":"qing","themes":["城垣礮臺","戰爭史蹟","軍事遺構"],"yearUnknown":false,"summary":"清代唯一內陸砲台，現存完整的日式砲台","intro":"湖西拱北礮臺位於湖西鄉媽宮城外東方的拱北山上，是劉銘傳於清光緒12年（1886）在澎湖新築的九座新式砲台之一，也是其中唯一的內陸砲台，負責掩護媽宮港的背面。1895年馬關條約簽訂前，日軍登陸澎湖，以拱北砲台為首要目標，攻防戰中日軍陣亡2人、負傷17人，砲台失守後日軍隨即進占媽宮城，清軍防務瓦解。今日所見是日治時期改建的大型砲台，施工精緻，保留一座直徑約4公尺的圓形鑄鐵觀測塔，被認為是澎湖唯一完整的日式砲台。二戰末期曾回擊美軍機，戰後由國軍接收、部分設施改建。2001年指定為國定古蹟，目前仍屬軍事重地。","highlights":["直徑約4公尺、可推拉鐵窗的圓形鑄鐵觀測塔","清代九座新式砲台中唯一的內陸砲台","1895年澎湖之役的關鍵攻防地點"],"funFact":"觀測塔的鑄鐵窗扇可以推拉，增加眺望角度，也兼顧防禦，像一頂會開窗的鐵頭盔。","photoSpot":"軍事管制區，請勿拍攝，遠望拱北山即可","visitMin":10,"openNote":"位於湖西鄉拱北山，國定古蹟但目前為軍事重地，一般民眾無法入內參觀，請勿靠近管制區或拍攝軍事設施。附近的城北村有歷史建築林登豫古宅可參觀。","dialogue":[{"who":"A","text":"阿拉蕾，澎湖的砲台大多守在海邊，你猜哪一座偏偏蓋在內陸山上？"},{"who":"R","text":"躲在山上的砲台？它是怕暈船，所以不想住海邊嗎？"},{"who":"A","text":"哈哈，是拱北砲台。1886年劉銘傳在澎湖新築九座新式砲台，它是唯一的內陸砲台，負責守媽宮港背後。"},{"who":"R","text":"守後門的砲台！那它後來有派上用場嗎？"},{"who":"A","text":"1895年日軍登陸澎湖，第一個目標就是這裡。攻防戰中日軍陣亡2人、傷17人，砲台失守後媽宮城也被占領。"},{"who":"R","text":"原來這裡是那一戰的轉折點，聽起來心情好沉重。"},{"who":"A","text":"是啊，對清軍和當地人來說，都是改朝換代的開始。現在看到的是日治時期改建的砲台，還留著圓形鑄鐵觀測塔。"},{"who":"R","text":"聽起來好壯觀，我好想爬上去看看那座鐵塔！"},{"who":"A","text":"它目前是軍事重地，不能進去也不能拍。路過湖西時，遠遠找找拱北山的山頭就好！"}],"clues":["清代九座新式砲台裡，只有我蓋在內陸","1895年日軍登陸後把我當作首要目標","湖西鄉山上的國定古蹟砲台，有圓形鑄鐵觀測塔"],"quiz":[{"q":"拱北砲台在清代九座新式砲台中有什麼特別？","options":["唯一的內陸砲台","唯一的荷蘭砲台","唯一建在外島","唯一沒有大砲"],"answer":0,"explain":"它是劉銘傳新築九座砲台中唯一的內陸砲台。"},{"q":"拱北砲台保留的觀測所是什麼材質？","options":["咕咾石","紅磚","鑄鐵","木材"],"answer":2,"explain":"觀測塔是直徑約4公尺的圓形鑄鐵造建築。"}],"images":[]},{"id":"magong-magonggucheng","name":"媽宮古城","short":"媽宮古城","category":"國定古蹟","level":"國定古蹟","town":"馬公市","types":["城郭"],"lat":23.563036,"lng":119.562201,"address":"澎湖縣馬公市1.順承門至中興門（昔大西門位置）段：城牆長度約為239.08公尺，東自順承門往西銜接篤行十村段城牆，由篤行十村段城牆往北銜接至陸軍澎湖防衛指揮部的中興門（昔大西門），定著土地範圍即以古蹟投影面積為原則。","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000086","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-01/0ae899c8-81b6-4af8-a88e-b55cd3362ede/媽宮古城.jpg","year":1887,"yearText":"1887年（清光緒13年）動工，1889年竣工","era":"qing","themes":["城垣礮臺","軍事遺構"],"yearUnknown":false,"summary":"清領時期臺澎最後興築的海防城池","intro":"媽宮古城位於馬公市，是清法戰爭後為強化澎湖海防而建的城池。1885年法軍攻占澎湖，戰後清廷鑑於媽宮形勢散漫、無城可守，由首任澎湖鎮總兵吳宏洛督造，光緒13年（1887）動工、光緒15年（1889）竣工，是清領時期最後興築的一座城，完全以軍事考量優先。城牆以玄武岩砌牆身，上接硓𥑮石城垛，就地取材。日治時期因都市發展兩度拆城，西半部因屬軍事要地而保留，現存順承門（小西門）至中興門（大西門）一帶城垣約800公尺；順承門城樓具閩東建築特徵，相當罕見。","highlights":["順承門城樓，帶有臺灣少見的閩東建築特徵","玄武岩牆身上接硓𥑮石城垛的在地工法","沿篤行十村旁的城牆散步，比較城內外風景"],"funFact":"媽宮城原有6座城門，日治時期拆城的石材多拿去填海造港，如今只剩西側城垣與2座城門。","photoSpot":"在順承門外仰拍城門洞與城樓","visitMin":40,"openNote":"位於馬公市區西側，順承門與篤行十村旁的城牆自由參觀；中興門（大西門）一帶位在陸軍澎湖防衛指揮部營區，請勿擅入、勿拍攝營區。從馬公市區步行或騎機車可達，也可搭澎湖縣公車。","dialogue":[{"who":"A","text":"阿拉蕾，先別急著拍照，你腳下這道牆，是清朝在臺澎蓋的最後一座城。"},{"who":"R","text":"最後一座？Allan，清朝都快結束了，為什麼還要在澎湖蓋城牆？"},{"who":"A","text":"因為1885年清法戰爭，法軍攻占了澎湖。清廷痛定思痛，發現媽宮無城可守，才決定補蓋一座。"},{"who":"R","text":"所以是腳踏車被偷了，才趕快去買大鎖的概念嗎？"},{"who":"A","text":"比喻得很傳神！1887年總兵吳宏洛開工，兩年後完工，牆身用玄武岩，上面的城垛用咕咾石。"},{"who":"R","text":"那其他城牆呢？我怎麼只看到這一段？"},{"who":"A","text":"日治時期因為都市發展拆了兩次，西半邊是軍事要地才留下來，現在還有大約800公尺。"},{"who":"R","text":"靠著軍隊站崗才保住，原來城牆也需要靠山。"},{"who":"A","text":"沒錯。走到順承門下抬頭看看城樓，比比看它的屋頂和本島常見的閩南廟宇有什麼不同！"}],"clues":["清法戰爭後，我才匆匆被蓋起來","我是清領時期臺澎最後興築的一座城","我的順承門就在馬公篤行十村旁"],"quiz":[{"q":"媽宮古城是在哪一場戰爭之後興建的？","options":["甲午戰爭","清法戰爭","鴉片戰爭","英法聯軍"],"answer":1,"explain":"清法戰爭時法軍攻占澎湖，戰後清廷築城加強海防。"},{"q":"媽宮古城的城垛主要用哪種在地材料砌成？","options":["花崗岩","紅磚","硓𥑮石","檜木"],"answer":2,"explain":"牆身用玄武岩，上接硓𥑮石砌成城垛。"}],"images":[{"file":"PICT84562.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/PICT84562.jpg/960px-PICT84562.jpg","page":"https://commons.wikimedia.org/wiki/File:PICT84562.jpg","artist":"peellden","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","local":"img/magong-magonggucheng-0.webp","small":"img/magong-magonggucheng-0-s.webp"}]},{"id":"magong-jinguitoupaotai","name":"馬公金龜頭礮臺","short":"金龜頭礮臺","category":"國定古蹟","level":"國定古蹟","town":"馬公市","types":["關塞"],"lat":23.563284,"lng":119.557737,"address":"澎湖縣馬公市馬公段2664、2664-3、2664-4、2664-5地號","announced":"2001-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20011121000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-01/bd25ad16-29d1-4395-8ca3-bd95cf276357/T007 澎湖縣 馬公金龜頭砲臺 (國定)17.jpg","year":1887,"yearText":"1887年（清光緒13年）","era":"qing","themes":["城垣礮臺","軍事遺構","戰爭史蹟"],"yearUnknown":false,"summary":"清末全澎火力最強的海防礮臺之一","intro":"馬公金龜頭礮臺位於馬公市區西南端的金龜頭，扼守媽宮港。此地早在康熙56年（1717）就築有澎湖新城，同治3年（1864）稱金龜頭礮臺。清法戰爭後，光緒13年（1887）由總兵吳宏洛新築，配備7、10、12吋口徑阿姆斯壯後膛砲各一門，與西嶼東臺、西臺同為全澎戰力最強的礮臺。1895年日軍進攻媽宮時，從東門突破後占領此地；1902至1904年改建為天南礮臺。礮臺以條石牆基、紅磚拱頂的穹隆式兵房為特色，戰後長期作為營區，2001年指定為國定古蹟。","highlights":["條石牆基、紅磚拱頂的穹隆式兵房","需購票、分梯次參觀的地下坑道「澎湖戰役秘徑」","站在礮臺高處眺望馬公港口"],"funFact":"同一個山頭前後築過4次：康熙、同治、光緒各一次，日治時期再改建成天南礮臺。","photoSpot":"在穹隆兵房拱門前拍層層拱頂","visitMin":50,"openNote":"位於馬公市區西南端金龜頭。依官方資料週四至週一9:00至12:00、14:00至17:00開放，週二、週三休息，閉館前15分鐘停止入園；地下坑道「澎湖戰役秘徑」需購票，上午10:00、下午14:30梯次。出發前請再確認最新公告。從馬公市區步行或騎機車可達。","dialogue":[{"who":"R","text":"Allan，金龜頭這名字好可愛，這裡真的有一隻大烏龜嗎？"},{"who":"A","text":"烏龜沒有，砲台倒是蓋了一層又一層。這個山頭從康熙年間到日治時期，總共築了4次。"},{"who":"R","text":"4次？這根本是砲台界的重建狂魔吧！"},{"who":"A","text":"最關鍵的是1887年那次，總兵吳宏洛在這裡架了7吋、10吋、12吋的阿姆斯壯後膛砲各一門。"},{"who":"R","text":"12吋？那砲管是不是比我的腰還粗！"},{"who":"A","text":"絕對比你粗。它和西嶼東臺、西臺並列全澎火力最強，但1895年日軍從東門攻進媽宮，這裡還是被占領了。"},{"who":"R","text":"那後來日本人接手以後，又怎麼處理它？"},{"who":"A","text":"1902年開始改建成天南礮臺。你看這些兵房，條石砌牆、紅磚拱頂，像一排躺平的大吐司。"},{"who":"R","text":"還有地下坑道可以走耶！我先去買票，進坑道前數數兵房有幾道拱門！"}],"clues":["同一個山頭，我前後被蓋了4次","清末我配備了12吋阿姆斯壯後膛砲","我在馬公港口邊，日治時期改名天南礮臺"],"quiz":[{"q":"1887年金龜頭礮臺配備的是哪一種火砲？","options":["阿姆斯壯後膛砲","紅衣大砲","克虜伯高射砲","佛郎機砲"],"answer":0,"explain":"配備7、10、12吋口徑阿姆斯壯後膛砲各一門。"},{"q":"日治時期改建後的金龜頭礮臺稱為什麼？","options":["拱北礮臺","大山砲臺","東角砲臺","天南礮臺"],"answer":3,"explain":"1902至1904年改建，稱為天南礮臺。"}],"images":[]},{"id":"xiyu-dongtai","name":"西嶼東臺","short":"西嶼東臺","category":"國定古蹟","level":"國定古蹟","town":"西嶼鄉","types":["關塞"],"lat":23.565618,"lng":119.514055,"address":"澎湖縣西嶼鄉西嶼鄉內垵三段 12 及 13 地號土地。","announced":"1991-11-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19911123000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-01/9d46ecaa-10ae-4cec-880c-7234fd115bf7/T054 澎湖縣 西嶼東臺 (一級)01.jpg","year":1887,"yearText":"1887年（清光緒13年）動工，1889年完工","era":"qing","themes":["城垣礮臺","軍事遺構","戰爭史蹟"],"yearUnknown":false,"summary":"清法戰後興建、紅磚拱頂兵房完整的礮臺","intro":"西嶼東臺位於西嶼鄉內垵村，是清法戰爭後為加強澎湖海防所建的四座礮臺之一。清法戰爭期間，西嶼雖已有新建礮臺卻未安礮配兵，法軍輕易攻占西嶼與媽宮。戰後劉銘傳派吳宏洛來澎勘察，1887年（光緒13年）動工，1889年完工裝礮，與西嶼西臺共同扼守媽宮港外海。東臺坐南朝北，配備英國阿姆斯脫朗後膛礮三尊，以在地玄武岩疊砌牆身，官廳與兵房為紅磚砌的半圓穹窿，並以當時新式的「鐵土」（洋灰）加固，外覆土石作為掩體。1895年乙未之役中，西嶼礮臺曾持續轟擊。日治與戰後仍作軍事使用，1991年指定為一級古蹟，今為國定古蹟，2016年起局部開放。","highlights":["紅磚半圓穹窿構成的官廳、兵房與甬道","海崖上的礮座與外壕溝","清代、日治與國軍不同時期的軍事遺構"],"funFact":"清法戰爭前西嶼已蓋了新式礮臺，卻沒有購置新礮、也沒派兵，法軍砲轟時完全沒有還擊。","photoSpot":"在紅磚拱頂甬道口拍光影","visitMin":30,"openNote":"位於西嶼鄉內垵村，2016年起採局部開放，開放範圍與時間請以現場公告為準；周邊仍有國軍營區，請勿進入管制區或拍攝軍事設施。鄰近西嶼彈藥本庫。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"A","text":"站在東臺的海崖邊，阿拉蕾，你看這片海就是媽宮港的外海，這裡是當年的海上守門員。"},{"who":"R","text":"守門員？那它有沒有成功守住球門？"},{"who":"A","text":"說來心酸。清法戰爭前，西嶼已經蓋了礮臺，卻沒買新礮、也沒派兵，法軍轟過來完全沒有還擊。"},{"who":"R","text":"空城計完全失敗，這也太尷尬了吧！"},{"who":"A","text":"所以戰後劉銘傳派吳宏洛來，1887年動工，蓋了四座新礮臺，東臺就是其中之一。"},{"who":"R","text":"那這一次總算有裝上真的大礮了嗎？"},{"who":"A","text":"有！配了三尊英國阿姆斯脫朗後膛礮。兵房用紅磚砌成半圓拱頂，外面再覆土當掩體。"},{"who":"R","text":"紅磚拱頂藏在土堆裡，好像一座巨大的磚造防空洞！"},{"who":"A","text":"形容得好。走進甬道時抬頭看看，拱頂的紅磚是怎麼一圈一圈砌上去的！"}],"clues":["清法戰爭後，吳宏洛奉命來澎湖興建我","我曾配備三尊英國阿姆斯脫朗後膛礮","我在內垵村海崖上，和西邊的兄弟一起扼守媽宮港外海"],"quiz":[{"q":"西嶼東臺是在哪一場戰爭之後興建的？","options":["甲午戰爭","鴉片戰爭","日俄戰爭","清法戰爭"],"answer":3,"explain":"清法戰爭後，劉銘傳派吳宏洛興建四座礮臺。"},{"q":"西嶼東臺官廳與兵房的屋頂是什麼形式？","options":["木構斜屋頂","鐵皮平屋頂","紅磚半圓穹窿","茅草屋頂"],"answer":2,"explain":"官廳及兵房以紅磚砌成半圓穹窿。"}],"images":[{"file":"西嶼東臺古堡.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/%E8%A5%BF%E5%B6%BC%E6%9D%B1%E8%87%BA%E5%8F%A4%E5%A0%A1.jpg/960px-%E8%A5%BF%E5%B6%BC%E6%9D%B1%E8%87%BA%E5%8F%A4%E5%A0%A1.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%A5%BF%E5%B6%BC%E6%9D%B1%E8%87%BA%E5%8F%A4%E5%A0%A1.jpg","artist":"Philoschen","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/xiyu-dongtai-0.webp","small":"img/xiyu-dongtai-0-s.webp"}]},{"id":"xiyu-xitai","name":"西嶼西臺","short":"西嶼西臺","category":"國定古蹟","level":"國定古蹟","town":"西嶼鄉","types":["關塞"],"lat":23.564073,"lng":119.489281,"address":"澎湖縣西嶼鄉外垵村278地號","announced":"1983-12-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19831228000014","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-01/d9d9000d-258f-4bcd-822d-b902bf39ce7c/T053 澎湖縣 西嶼西臺 (一級)01.jpg","year":1887,"yearText":"清法戰爭後興建（約1886至1889年）","era":"qing","themes":["城垣礮臺","軍事遺構","戰爭史蹟"],"yearUnknown":false,"summary":"劉銘傳親題門額的清末海防礮臺","intro":"西嶼西臺位於西嶼鄉內垵與外垵之間、當地稱為「中鼻尾」的臨海高地，與西嶼東臺共同扼守澎湖西側海域。官方說明此地在1683年明鄭劉國軒備戰時就已築有礮臺。清法戰爭法軍占領媽宮後，清廷以吳宏洛為澎湖首任總兵，興建媽宮城與四座新式礮臺，西臺就是其中之一，配備阿姆斯壯後膛礮等火礮。外堡門門額「西嶼西臺」為劉銘傳所題。礮臺平面略呈內凹方形，有內外堡門、土垣與壕溝，兵房與甬道以磚石混砌，外層用當時新式的「鐵土」粉刷。1895年日艦避開西嶼火力，改由湖西裡正角登陸。日治時期改為西嶼西堡壘續用，1983年指定為一級古蹟，今為國定古蹟。","highlights":["外堡門上劉銘傳題的「西嶼西臺」門額","山形配置的長甬道與兩側兵房","南側土垣內的礮座與內外壕溝"],"funFact":"1895年日艦忌憚西嶼礮臺火力，改從湖西裡正角登陸；西臺位置偏西，無法支援東側戰事。","photoSpot":"在外堡門前拍劉銘傳題額","visitMin":40,"openNote":"位於西嶼鄉外垵村。依官方資料平常日8:00–17:30開放，旅遊旺季7:30–18:30，例假日照常開放；據資料需購票參觀，請以現場公告為準。可與西嶼燈塔、外垵餌砲串遊。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"A","text":"先別急著衝進去，阿拉蕾，抬頭看門額上的西嶼西臺四個字，是劉銘傳親筆題的。"},{"who":"R","text":"巡撫大人的簽名耶！這算是清朝版的名人簽名牆嗎？"},{"who":"A","text":"差不多啦！清法戰爭後，劉銘傳和吳宏洛在澎湖蓋了四座新礮臺，西臺就是其中之一。"},{"who":"R","text":"那這塊高地更早以前有沒有礮臺？"},{"who":"A","text":"官方說明，1683年明鄭的劉國軒為了迎戰施琅，就在西嶼頭一帶築過礮臺。"},{"who":"R","text":"原來這塊高地從明鄭時期就在站崗了！"},{"who":"A","text":"走進去會看到長長的甬道和兩側兵房，磚石牆外面還抹了當時最新潮的鐵土，也就是洋灰。"},{"who":"R","text":"鐵土聽起來好像鐵做的泥巴，超級硬派！"},{"who":"A","text":"很貼切。1895年日艦甚至避開西嶼，改從湖西登陸。請你找找南側的礮座，數數看一共有幾個！"}],"clues":["我的門額是一位臺灣巡撫親筆題的","我和東邊的兄弟一起守著媽宮港外海","我在內垵和外垵之間名叫中鼻尾的高地上"],"quiz":[{"q":"西嶼西臺外堡門的門額是誰題的？","options":["施琅","吳宏洛","劉國軒","劉銘傳"],"answer":3,"explain":"外堡門門額「西嶼西臺」為劉銘傳所題。"},{"q":"西臺兵房牆體外側用哪種當時的新材料粉刷？","options":["石灰糖水","鐵土洋灰","瀝青柏油","黃土稻草"],"answer":1,"explain":"牆體外側以當時最新的「鐵土」（洋灰）粉刷。"}],"images":[{"file":"澎湖-西嶼西台隧道內.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/%E6%BE%8E%E6%B9%96-%E8%A5%BF%E5%B6%BC%E8%A5%BF%E5%8F%B0%E9%9A%A7%E9%81%93%E5%85%A7.JPG/960px-%E6%BE%8E%E6%B9%96-%E8%A5%BF%E5%B6%BC%E8%A5%BF%E5%8F%B0%E9%9A%A7%E9%81%93%E5%85%A7.JPG","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96-%E8%A5%BF%E5%B6%BC%E8%A5%BF%E5%8F%B0%E9%9A%A7%E9%81%93%E5%85%A7.JPG","artist":"蔡宋琪","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/xiyu-xitai-0.webp","small":"img/xiyu-xitai-0-s.webp"}]},{"id":"xiyu-danyaobenku","name":"西嶼彈藥本庫","short":"西嶼彈藥本庫","category":"國定古蹟","level":"國定古蹟","town":"西嶼鄉","types":["其他設施"],"lat":23.569019,"lng":119.510171,"address":"澎湖縣西嶼鄉內垵村1-5號","announced":"2024-07-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20240723000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-23/85f04703-69db-432e-8cba-8557f23246b4/西嶼彈藥本庫.jpg","year":1900,"yearText":"1900年（明治33年）起陸續興建","era":"japan","themes":["軍事遺構","戰爭史蹟"],"yearUnknown":false,"summary":"藏在谷地裡的日治要塞彈藥倉庫","intro":"西嶼彈藥本庫位於西嶼鄉內垵東側、有地形掩護的谷地，是日治時期澎湖島要塞四大彈藥庫之一，負責供應西嶼南端各堡壘砲臺所需彈藥。1900年（明治33年）起陸續興建火藥本庫、彈丸本庫，日俄戰爭期間再增建臨時火藥庫。現存主體有三處：1930年改建的土窟式清涼彈藥庫，以及1935年的單窟式、1936年的雙窟式洞窟彈藥庫。土窟式有架高地板、通風口與避雷針，外圍以砌石防爆土垣環繞；洞窟式在山腹開鑿隧道，內庫以銅板包覆、地板鋪鉛板，嚴格控管溫濕度。它完整呈現日治時期彈藥庫技術的演進，2024年由縣定古蹟升格為國定古蹟。","highlights":["土窟式清涼彈藥庫的弧拱通風口與防爆土垣","單窟式洞窟彈藥庫內試驗防鏽塗料的銅板","雙窟式彈藥庫依山勢高低相連的斜坡甬道"],"funFact":"洞窟彈藥庫的內庫用銅板包覆、地上鋪2公厘鉛板，防潮之外也能遮蔽電磁波干擾。","photoSpot":"拍洞窟彈藥庫的拱形入口與山壁","visitMin":40,"openNote":"位於西嶼鄉內垵村。依官方資料，週四至週一9:00–12:00、14:00–17:00開放，週二、週三休館，閉館前30分鐘停止入園，請以現場公告為準。鄰近西嶼東臺。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"R","text":"Allan，這裡四周都是小山丘，看起來好安靜，真的是軍事設施嗎？"},{"who":"A","text":"就是要安靜才好！西嶼彈藥本庫故意蓋在有地形掩護的谷地，專門供應西嶼南端砲臺的彈藥。"},{"who":"R","text":"彈藥倉庫，聽起來比我的零食櫃危險一百倍。"},{"who":"A","text":"所以設計超講究。1930年改建的土窟式彈藥庫，地板架高、開了通風口，屋頂兩側還有避雷針。"},{"who":"R","text":"怕被雷打到引爆，真的是步步小心。"},{"who":"A","text":"後來有了飛機，日軍就往山腹挖隧道，蓋單窟式和雙窟式洞窟彈藥庫，從空中更難發現。"},{"who":"R","text":"海島這麼潮濕，洞裡面不會發霉嗎？"},{"who":"A","text":"內庫牆面包銅板，地板鋪鉛板，再加乾燥裝置，比博物館的典藏庫還要龜毛。"},{"who":"R","text":"那我要去找單窟式彈藥庫裡，那些試驗防鏽塗料的銅板！"}],"clues":["我躲在內垵東邊的谷地，替砲臺保管彈藥","我有土窟式和洞窟式兩種倉庫，內牆還包著銅板","我是日治時期澎湖島要塞四大彈藥庫之一"],"quiz":[{"q":"西嶼彈藥本庫是日治時期澎湖島要塞的幾大彈藥庫之一？","options":["二大","三大","五大","四大"],"answer":3,"explain":"它是澎湖島要塞四大彈藥庫之一。"},{"q":"洞窟式彈藥庫為什麼開鑿在山腹裡？","options":["方便漁船靠岸","提高隱蔽性防空襲","節省興建經費","靠近村落取水"],"answer":1,"explain":"因應航空器出現，開鑿山腹以提高隱蔽性。"}],"images":[]},{"id":"magong-shigongcijiwanjun","name":"施公祠及萬軍井","short":"施公祠及萬軍井","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["寺廟"],"lat":23.564605,"lng":119.56427,"address":"澎湖縣馬公市中央里中央街1巷(施公祠10號)","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000092","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2317/photo/2e399834-ff14-46ab-81c5-8813808c76c0.jpg","year":1684,"yearText":"1684年（清康熙23年）","era":"qing","themes":["宗教信仰","水利設施","牌坊碑碣"],"yearUnknown":false,"summary":"施琅生祠與傳說湧泉濟師的古井","intro":"施公祠及萬軍井位於馬公市中央街，天后宮東側。施公祠原稱施將軍廟，是康熙23年（1684）施琅受封靖海侯後所建的生祠，原址在今澎湖醫院一帶；道光12年（1832）後入祀海壇殉職官兵神位，改稱施公祠，1914年因興建病院遷入現址。祠內有道光15年「寰海皆春」古匾及兩塊道光年間古碑。萬軍井在祠斜對面巷內，傳說施琅攻澎時軍中缺水，禱於媽祖而井湧甘泉，數萬大軍汲之不竭，又稱師泉井；這則傳說原出自福建平海，後被附會到澎湖。荷蘭人1622年的紀錄已提到在廟旁水井取水，可見此井年代久遠。","highlights":["正廳前排紅臉的施琅神像與後排媽祖","道光15年澎湖水師副將詹功顯題的「寰海皆春」匾","斜對面巷內傳說「湧泉濟師」的萬軍井"],"funFact":"施琅曾在澎湖向漁民收取規費，每年1200兩，直到乾隆2年才由皇帝下令永遠禁止。","photoSpot":"在巷口同框拍萬軍井與中央街老屋","visitMin":15,"openNote":"位於馬公市中央里中央街1巷，施公祠官方開放時間8:00至17:00，萬軍井全天開放。與天后宮、四眼井、乾益堂相距很近，可步行串遊。","dialogue":[{"who":"R","text":"Allan，這間小廟裡紅臉的神像是誰？關公嗎？"},{"who":"A","text":"不是關公，是施琅，清朝打下澎湖的將軍。1684年他還在世時，就有人替他蓋了這座生祠。"},{"who":"R","text":"活著就有自己的廟？那他經過門口不會很尷尬嗎？"},{"who":"A","text":"應該是很得意吧！後來祠裡也入祀了殉職海壇官兵的神位，才改叫施公祠。"},{"who":"R","text":"那斜對面巷子裡那口井又有什麼故事？"},{"who":"A","text":"那是萬軍井。傳說施琅攻澎湖時軍中缺水，向媽祖祈禱後井湧甘泉，幾萬大軍喝都喝不完。"},{"who":"R","text":"古代版的飲料無限暢飲！是真的嗎？"},{"who":"A","text":"這則傳說其實先出現在福建平海，後來才被套到澎湖。不過1622年荷蘭人的紀錄就寫到廟旁有井可取水。"},{"who":"R","text":"傳說可能是借來的，井倒是貨真價實。我要去巷子裡找到萬軍井，看看井口長什麼樣子！"}],"clues":["傳說數萬大軍喝我的水都喝不完","我原本是為一位還在世的將軍蓋的生祠","我在天后宮東側，供奉紅臉的施琅"],"quiz":[{"q":"萬軍井還有哪一個別名？","options":["四目井","師泉井","大眼井","龍泉井"],"answer":1,"explain":"因湧泉濟師的傳說，又稱師泉井。"},{"q":"施公祠最早是為誰所建的生祠？","options":["沈有容","吳宏洛","施琅","蔡廷蘭"],"answer":2,"explain":"康熙23年施琅受封靖海侯後所建的生祠。"}],"images":[{"file":"施公祠.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/%E6%96%BD%E5%85%AC%E7%A5%A0.jpg/960px-%E6%96%BD%E5%85%AC%E7%A5%A0.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%96%BD%E5%85%AC%E7%A5%A0.jpg","artist":"TroyJiang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-shigongcijiwanjun-0.webp","small":"img/magong-shigongcijiwanjun-0-s.webp"}]},{"id":"magong-taishajiaohuiguan","name":"臺廈郊會館","short":"臺廈郊會館","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["寺廟"],"lat":23.563921,"lng":119.564179,"address":"澎湖縣馬公市中央里中山路6巷9號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000091","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2315/photo/d842aa54-3923-4792-b667-66e9f5615e61.jpg","year":1696,"yearText":"1696年（清康熙35年）創建水仙宮","era":"qing","themes":["宗教信仰","產業遺產"],"yearUnknown":false,"summary":"樓上拜水仙、樓下開商會的二層廟","intro":"臺廈郊會館位於馬公市中山路6巷，也就是水仙宮。康熙35年（1696）由澎湖水師右營游擊薛奎創建，奉祀保佑航海平安的水仙尊王。光緒元年（1875）媽宮街商民黃鶴年集資重修，當時這裡已作為「臺廈郊」的會所。臺廈郊由澎湖的台郊「金順利」與廈郊「金長順」組成，設有公所解決貿易紛爭。昭和4年（1929）改建為融合歐式風格的二層樓街屋，上層祀神、下層作為臺廈郊實業會辦公處，是澎湖第一間採二樓形式的廟宇。戰後商會組織轉變，如今主要是神明會組織。","highlights":["左右對稱、連接一二樓的木質扶梯","歐式上下拉窗與洗貝殼砂的仿石柱","一樓簷下四角亭，亭頂就是二樓廟埕"],"funFact":"創建水仙宮的游擊薛奎，同一年也創建了馬公觀音亭，是康熙年間的建廟雙響砲。","photoSpot":"在巷內仰拍二層立面與四角亭","visitMin":15,"openNote":"位於馬公市中央里中山路6巷，官方開放時間6:00至20:00；一樓開放自由參觀，二樓目前暫不對外開放。距天后宮、中央街步行即到。","dialogue":[{"who":"R","text":"Allan，這間廟怎麼長得像兩層樓的洋房？我差點以為走進銀行。"},{"who":"A","text":"你的直覺很準，它真的跟做生意有關。這裡是水仙宮，也是臺廈郊會館。"},{"who":"R","text":"臺廈郊是什麼？聽起來像一條公路。"},{"who":"A","text":"是商人公會啦！澎湖的台郊和廈郊合組成臺廈郊，還設了公所處理貿易糾紛。"},{"who":"R","text":"所以生意吵架吵到最後，大家都來水仙王面前講道理？"},{"who":"A","text":"有神明當見證，比較不敢亂來。1929年改建成二樓，上層祀神，下層給臺廈郊實業會辦公。"},{"who":"R","text":"樓上拜拜、樓下開會，這是澎湖最早的商辦大樓吧！"},{"who":"A","text":"可以這麼說，它是澎湖第一間二樓式廟宇。目前一樓開放參觀，二樓暫不開放。"},{"who":"R","text":"那我在一樓找找那兩座左右對稱的木扶梯，再數數立面有幾扇歐式上下拉窗！"}],"clues":["我樓上祀神、樓下曾是商人的辦公室","台郊金順利與廈郊金長順曾以我為會所","我是澎湖第一間二樓式廟宇，奉祀水仙尊王"],"quiz":[{"q":"臺廈郊會館奉祀的主神是誰？","options":["媽祖","水仙尊王","關聖帝君","玄天上帝"],"answer":1,"explain":"會館就是水仙宮，奉祀保佑航海的水仙尊王。"},{"q":"1929年改建後，水仙宮的建築有什麼特色？","options":["全澎最大的燕尾廟","全以花崗岩打造","澎湖第一間二樓式廟宇","設有三座鐘鼓樓"],"answer":2,"explain":"改建為二層樓街屋，是澎湖第一間二樓式廟宇。"}],"images":[{"file":"臺廈郊會館.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/%E8%87%BA%E5%BB%88%E9%83%8A%E6%9C%83%E9%A4%A8.jpg/960px-%E8%87%BA%E5%BB%88%E9%83%8A%E6%9C%83%E9%A4%A8.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%87%BA%E5%BB%88%E9%83%8A%E6%9C%83%E9%A4%A8.jpg","artist":"林偉樺 Alpha","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-taishajiaohuiguan-0.webp","small":"img/magong-taishajiaohuiguan-0-s.webp"}]},{"id":"magong-guanyinting","name":"馬公觀音亭","short":"馬公觀音亭","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["寺廟"],"lat":23.567663,"lng":119.561958,"address":"澎湖縣馬公市中興里14鄰介壽路7號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000093","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2323/photo/ad934842-adf5-4ac0-b717-5063a85bf0bb.jpg","year":1696,"yearText":"1696年（清康熙35年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"穿廊上置鐘鼓樓的海邊觀音古廟","intro":"馬公觀音亭位於馬公市中興里介壽路，康熙35年（1696）由澎湖游擊薛奎創建，主祀觀音大士。乾隆、嘉慶年間多次重修重建；光緒11年（1885）清法戰爭法軍侵澎，廟宇被毀，次年重建完成。昭和2年（1927）澎湖紳民再度重建，由後窟潭匠師謝江、謝自南父子主建，並在南側放生池增建涼亭；民國46年（1957）因蟻害修建，形成今日樣貌，2006年再完成整修。觀音亭規模較澎湖其他廟宇大，面闊五開間兩進，穿廊融合迴廊與護龍，上方設鐘鼓樓，是臺灣廟宇少見的作法。全澎農曆7月普渡也在這裡收尾。","highlights":["穿廊上方的鐘鼓樓，臺灣廟宇少見","登錄為古物的「薄海蒙庥」「如是觀」等古匾","昭和2年謝江父子主建的五開間格局"],"funFact":"清法戰爭時觀音亭被法軍毀壞，隔年就重建完成，是戰火與信仰並存的見證。","photoSpot":"從廟埕拍穿廊上的鐘鼓樓","visitMin":20,"openNote":"位於馬公市中興里介壽路，官方開放時間5:00至20:00、全年無休，參拜請保持肅靜。鄰近第一賓館，可步行串遊。","dialogue":[{"who":"A","text":"聽，有沒有聽到海浪聲？觀音亭就在馬公海邊，已經陪伴這片海300多年了。"},{"who":"R","text":"300多年？Allan，那它是哪一年蓋的？"},{"who":"A","text":"1696年，澎湖游擊薛奎創建，主祀觀音大士。有趣的是，同一年他也蓋了水仙宮。"},{"who":"R","text":"一年蓋兩間廟，這位將軍是建廟界的業績王吧！"},{"who":"A","text":"可以頒獎了。可惜1885年清法戰爭時，觀音亭被法軍毀壞，隔年才重建起來。"},{"who":"R","text":"那現在看到的樣子是什麼時候的？"},{"who":"A","text":"主要是1927年由謝江、謝自南父子主建，1957年再整修。穿廊上面還蓋了鐘鼓樓，臺灣很少見。"},{"who":"R","text":"晨鐘暮鼓就在走廊上方，路過的人都會被提醒要早睡早起。"},{"who":"A","text":"沒錯！進廟後抬頭找找鐘鼓樓，看看哪一邊掛鐘、哪一邊放鼓吧！"}],"clues":["清法戰爭時我被法軍毀壞，隔年重建","我的穿廊上方設有鐘鼓樓","我是介壽路海邊、主祀觀音大士的古廟"],"quiz":[{"q":"馬公觀音亭由誰創建？","options":["施琅","薛奎","吳宏洛","蔣鏞"],"answer":1,"explain":"康熙35年由澎湖游擊薛奎創建。"},{"q":"觀音亭的建築有什麼少見的特色？","options":["全廟兩層樓","屋頂全用銅瓦","廟前有護城河","穿廊上置鐘鼓樓"],"answer":3,"explain":"穿廊融合迴廊與護龍，上置鐘鼓樓，臺灣少見。"}],"images":[{"file":"Penghu Guanyin Temple.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Penghu_Guanyin_Temple.jpg/960px-Penghu_Guanyin_Temple.jpg","page":"https://commons.wikimedia.org/wiki/File:Penghu_Guanyin_Temple.jpg","artist":"Jgfhhgf942zo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-guanyinting-0.webp","small":"img/magong-guanyinting-0-s.webp"}]},{"id":"magong-siyanjing","name":"四眼井","short":"四眼井","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["其他設施"],"lat":23.565101,"lng":119.564938,"address":"澎湖縣馬公市中央里中央街40號厝前","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000094","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2336/photo/75f6d6c6-c50c-4d4e-aed0-32729cd5cdbb.JPG","year":1700,"yearText":"年代不詳","era":"unknown","themes":["水利設施","聚落地景"],"yearUnknown":true,"summary":"四個井口同時汲水的馬公老水源","intro":"四眼井位於馬公市中央街最北端，日治時期稱四目井，二戰後改稱四眼井。開鑿年代沒有確切史料，因位處東、西、北三面丘地圍繞的低谷，可匯集泉水，推測很早就有人在此取水，中央街舊稱「大井街」據說就是因這口大井得名。為了讓多人同時取水、維持秩序，居民用帆船從福建載來壓艙的花崗岩板搭成井面平臺，並留設4個取水口。約1930年代後期馬公有了自來水，四眼井改作洗滌用；1960年代後期才逐漸停用。1971年澎湖觀光起步後，它成為中央街的代表景點。","highlights":["6條花崗岩板拼成、比路面高約30公分的井臺","4個由整塊玄武岩鑿成、大小不一的井圈","井壁由下而上依序是玄武岩、硓𥑮石與紅磚"],"funFact":"4個井圈的尺寸和鑿法都不一樣，可能出自不同石匠甚至不同時期，至今還是個謎。","photoSpot":"從井臺斜上方拍4個井口與中央街","visitMin":10,"openNote":"位於馬公市中央街北端，全天開放的公共空間。請勿攀坐井欄、勿丟擲物品入井。旁邊就是乾益堂中藥行，往南步行可到天后宮。","dialogue":[{"who":"A","text":"阿拉蕾，介紹一位跟我很有緣的朋友，它也叫四眼，而且資歷比我深多了。"},{"who":"R","text":"Allan，你是說你的黑框眼鏡嗎？那明明是一口井啊！"},{"who":"A","text":"正是四眼井！井面上有4個取水口，從上面看就像四隻眼睛，跟我一樣是四眼田雞。"},{"who":"R","text":"哈哈，那為什麼要開4個洞？一個不夠用嗎？"},{"who":"A","text":"以前這裡是附近居民最重要的水源，開4個孔，大家可以同時打水，也比較好維持排隊秩序。"},{"who":"R","text":"好聰明！那井口那幾塊大石板是澎湖本地的嗎？"},{"who":"A","text":"是花崗岩板，據說是帆船從福建載來壓艙的石頭，到了澎湖就變成井面平臺。"},{"who":"R","text":"壓艙石下船還能轉職，真是斜槓人生。"},{"who":"A","text":"仔細看，4個井圈大小和鑿法都不同，只有西南角那個是渾然一體、沒有裂縫的，你去找找看！"}],"clues":["中央街舊稱大井街，據說就是因我而得名","日治時期，人們叫我四目井","我是井面有4個取水口的古井"],"quiz":[{"q":"四眼井井面的花崗岩板，據說原本是什麼？","options":["城牆拆下的石材","廟宇的舊石柱","砲台剩下的石料","帆船的壓艙石"],"answer":3,"explain":"據說是貿易帆船從福建載來的壓艙石。"},{"q":"四眼井在日治時期被稱為什麼？","options":["四目井","四孔泉","大井頭","萬軍井"],"answer":0,"explain":"日治時期稱四目井，二戰後改稱四眼井。"}],"images":[{"file":"The Four-eyed Well 20150618.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/The_Four-eyed_Well_20150618.jpg/960px-The_Four-eyed_Well_20150618.jpg","page":"https://commons.wikimedia.org/wiki/File:The_Four-eyed_Well_20150618.jpg","artist":"翁維德(Wei-Te Wong)","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/magong-siyanjing-0.webp","small":"img/magong-siyanjing-0-s.webp"}]},{"id":"magong-wenaochenghuang","name":"文澳城隍廟","short":"文澳城隍廟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["寺廟"],"lat":23.565515,"lng":119.583669,"address":"澎湖縣馬公市西文里3鄰25號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000090","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2309/photo/392222d6-d9b2-49b3-a3dd-bc34162d32c5.jpg","year":1730,"yearText":"約清康熙至雍正年間（1684至1730年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"澎湖最早創建的城隍廟","intro":"文澳城隍廟位於馬公市西文里，是澎湖最早創建的城隍廟。文澳舊名暗澳，清初設巡檢司，雍正年間改設澎湖糧捕廳，曾是澎湖的行政中心，城隍廟就在廳署之東。確切創建年代已不可考，約在康熙到雍正年間（1684至1730年）。光緒15年（1889）廳署遷往媽宮後，這裡轉為文澳的地方廟，由西文里分東、北、西三甲輪流推舉頭家辦理祭典。戰後於1950年集資重修並加深縱深，1967年再修，2011年三度修復。廟門花崗岩石鼓刻有鹿與鶴，室內大量使用梭柱，柱列整齊。","highlights":["廟門花崗岩石鼓上的鹿與鶴浮雕","室內整齊排列的梭柱","山門出櫸雕龍頭與蓮瓣垂花吊筒"],"funFact":"乾隆年間通判胡建偉在《澎湖紀略》就寫它「規模狹隘」，後來媽宮另建新廟，澎湖才有兩座城隍廟。","photoSpot":"蹲低拍廟門石鼓的鹿鶴浮雕","visitMin":20,"openNote":"位於馬公市西文里文澳聚落，官方開放時間5:00至20:00，參拜請保持肅靜。距馬公市區不遠，可騎機車、開車或搭澎湖縣公車前往；附近的文石書院可一併參觀。","dialogue":[{"who":"A","text":"看過媽宮城隍廟的朋友注意了，眼前這座文澳城隍廟，才是澎湖城隍的老家。"},{"who":"R","text":"老家？Allan，所以媽宮那間算是分出去的嗎？"},{"who":"A","text":"可以這樣說。清初文澳叫暗澳，是澎湖的行政中心，官署旁就有這座城隍廟，是澎湖最早的一座。"},{"who":"R","text":"那它到底幾歲了？有沒有出生證明？"},{"who":"A","text":"確切年代沒人說得準，大概在康熙到雍正年間。連乾隆時的通判都嫌它太小，還寫進書裡。"},{"who":"R","text":"被官員寫進書裡吐槽，也太慘了吧！"},{"who":"A","text":"後來官署搬到媽宮，它就變成文澳的地方廟，現在由西文里分東、北、西三甲輪流辦祭典。"},{"who":"R","text":"雖然退休了，還有街坊鄰居挺它，好溫馨。"},{"who":"A","text":"等一下到廟門口蹲下來，在花崗岩石鼓上找出鹿和鶴，牠們代表長壽福祿喔。"}],"clues":["乾隆年間的官員曾在書裡說我規模狹隘","我所在的聚落舊名暗澳，曾是澎湖行政中心","我是澎湖最早創建的城隍廟"],"quiz":[{"q":"文澳在清初的舊名是什麼？","options":["暗澳","媽宮澳","嵵裡澳","林投澳"],"answer":0,"explain":"文澳舊名暗澳，曾是澎湖的行政中心。"},{"q":"文澳城隍廟廟門石鼓刻有哪兩種動物？","options":["龍與虎","獅與象","鹿與鶴","魚與蝦"],"answer":2,"explain":"石鼓刻鹿與鶴，取長壽福祿之意。"}],"images":[{"file":"文澳 城隍廟 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/%E6%96%87%E6%BE%B3_%E5%9F%8E%E9%9A%8D%E5%BB%9F_%28cropped%29.jpg/960px-%E6%96%87%E6%BE%B3_%E5%9F%8E%E9%9A%8D%E5%BB%9F_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%96%87%E6%BE%B3_%E5%9F%8E%E9%9A%8D%E5%BB%9F_(cropped).jpg","artist":"Boboman","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-wenaochenghuang-0.webp","small":"img/magong-wenaochenghuang-0-s.webp"}]},{"id":"magong-magongchenghuang","name":"媽宮城隍廟","short":"媽宮城隍廟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["寺廟"],"lat":23.566223,"lng":119.566317,"address":"澎湖縣馬公市重慶里光明路8鄰20號","announced":"1987-11-10","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19871110000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2334/photo/e090d8ab-b2ae-4c40-81fa-140c3733670b.jpg","year":1779,"yearText":"1779年（清乾隆44年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"全澎普渡從這裡開始的闔澎公廟","intro":"媽宮城隍廟位於馬公市光明路，是闔澎公廟之一。乾隆44年（1779），澎湖通判謝維祺認為文澳廳署旁的城隍廟規模狹隘，率監生郭志達在媽宮今址新建，此後歷任官員多次修建。光緒11年（1885）清法戰爭法軍攻澎，傳出城隍顯靈庇佑軍民，事後獲賜匾並加封「靈應侯」，格同府城城隍；1889年澎湖廳署移到媽宮城，這裡成為官衙所在的城隍廟。現貌以昭和8年（1933）改建為基礎，面闊五間，融合拜殿、抱廈與大殿，屋頂瓷碗剪粘色彩豐富。每年農曆7月普渡由這裡開始。","highlights":["傳統瓷碗剪粘的屋頂，色彩豐富、題材有趣","腰鼓梭柱、吊筒等具澎湖特色的大木作","登錄為古物的「全澎保障」「悔者遲」等古匾"],"funFact":"澎湖農曆7月普渡由這裡開跑、觀音亭收尾，所以俗諺說「城隍廟放，觀音亭收」。","photoSpot":"在廟埕斜角拍屋頂相連的剪粘","visitMin":20,"openNote":"位於馬公市重慶里光明路，官方開放時間5:00至18:00，參拜請保持肅靜。從中央街、天后宮一帶步行可達。","dialogue":[{"who":"R","text":"Allan，城隍爺到底是管什麼的？聽起來好像很嚴肅。"},{"who":"A","text":"城隍原本是守護城池的神，後來變成地方守護神，有點像陰間的市長兼法官。"},{"who":"R","text":"那澎湖怎麼會有兩間城隍廟？一個市長還不夠嗎？"},{"who":"A","text":"好問題！最早那間在文澳，1779年通判嫌它太小，才在媽宮蓋了這間新廟，後來廳署也搬進媽宮城。"},{"who":"R","text":"所以是市長跟著市政府一起搬家！"},{"who":"A","text":"差不多。1885年法軍攻澎湖時，傳出城隍顯靈護佑軍民，事後還被加封「靈應侯」。"},{"who":"R","text":"打完仗還升官，那現在一年中最熱鬧的是什麼時候？"},{"who":"A","text":"農曆7月！全澎普渡從城隍廟開始，最後到觀音亭結束，俗話說「城隍廟放，觀音亭收」。"},{"who":"R","text":"像大隊接力一樣！那我先抬頭，看看屋頂的剪粘裡藏了哪些人物和動物！"}],"clues":["我被加封為「靈應侯」，格同府城城隍","1779年，我在媽宮落腳，取代狹小的文澳舊廟","澎湖農曆7月普渡從我這裡開始"],"quiz":[{"q":"清法戰爭後，媽宮城隍獲加封什麼爵號？","options":["顯佑伯","靈應侯","威靈公","忠勇侯"],"answer":1,"explain":"傳出顯靈護佑後，加封「靈應侯」，格同府城城隍。"},{"q":"俗諺「城隍廟放，觀音亭收」說的是哪個節俗？","options":["元宵乞龜","媽祖遶境","中秋賞月","農曆7月普渡"],"answer":3,"explain":"全澎普渡由城隍廟開始，到觀音亭結束。"}],"images":[{"file":"PICT84872.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/PICT84872.jpg/960px-PICT84872.jpg","page":"https://commons.wikimedia.org/wiki/File:PICT84872.jpg","artist":"peellden","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","local":"img/magong-magongchenghuang-0.webp","small":"img/magong-magongchenghuang-0-s.webp"}]},{"id":"xiyu-neiantagongtapo","name":"西嶼內垵塔公塔婆","short":"塔公塔婆","category":"縣定古蹟","level":"縣(市)定古蹟","town":"西嶼鄉","types":["其他設施"],"lat":23.573755,"lng":119.499398,"address":"澎湖縣西嶼鄉內垵村北港","announced":"2000-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20000128000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-02/26c4f44e-c7b5-4e3a-9229-0d1532715bb3/IMG_4938_.jpg","year":1843,"yearText":"1843年（清道光23年）","era":"qing","themes":["石塔厭勝"],"yearUnknown":false,"summary":"一陰一陽鎮守內垵的祈福石塔","intro":"西嶼內垵塔公塔婆位於西嶼鄉內垵村北港南側。北港外海有暗礁「海瀨礁」，與北方陸地「鱟仔尾」連成一線，形似一支箭直射村內，居民認為常帶來災厄，於是請地理師勘查，1843年（清道光23年）由內垵呂論倡議，帶領村中青年興建一陰一陽兩座石塔，並以近百公尺的石牆相連，既鎮壓沖煞，也防海水倒灌。東邊較大的塔公為六層實心方塔，高12.35公尺，下層用玄武岩、上層用咕咾石，頂置紅色陶缸；西邊較小的塔婆為一層圓錐形玄武岩塔，頂上倒放陶甕。塔公曾在1986年、2001年颱風中受損後修復。祭塔時分別恭請內塹宮吳府、李府王爺坐鎮，2000年指定為縣定古蹟。","highlights":["塔公頂上的紅色陶缸與葫蘆造型","塔婆頂上倒放的淺綠色陶甕","連接兩塔、長近百公尺的石牆"],"funFact":"因為塔公頭頂有紅色陶缸，村民也在塔婆頂上倒放一個「豆芽菜甕仔」當裝飾。","photoSpot":"從石牆一端把兩塔一起入鏡","visitMin":20,"openNote":"位於西嶼鄉內垵村北港旁，戶外全天開放。石塔為地方信仰設施，請勿攀爬。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"R","text":"Allan，海邊這兩座石塔一大一小，是一對情侶嗎？"},{"who":"A","text":"差不多喔，它們叫塔公、塔婆，是一陰一陽的夫妻塔，1843年蓋來保護內垵村。"},{"who":"R","text":"夫妻塔！那它們要保護村子不被什麼欺負？"},{"who":"A","text":"外海有塊暗礁叫海瀨礁，跟北邊的鱟仔尾連成一線，像一支箭射向村子，村民覺得很不吉利。"},{"who":"R","text":"所以兩座塔就是村子的防箭盾牌！"},{"who":"A","text":"對，中間還用近百公尺的石牆牽在一起，代表兩人聯手抵擋，也能擋海水倒灌。"},{"who":"R","text":"牽手護村，好浪漫！塔公頭上紅紅的是什麼？"},{"who":"A","text":"那是紅色陶缸，所以塔婆頭上也倒放一個陶甕，夫妻帽子要成對才搭嘛。"},{"who":"R","text":"那我要站在石牆一頭，把塔公塔婆一起拍進同一張照片！"}],"clues":["我們一大一小、一陰一陽，守護海邊村落","我們之間有一道近百公尺的石牆牽著","我們在內垵北港旁，1843年由村民合力興建"],"quiz":[{"q":"內垵村民興建這兩座石塔主要是為了什麼？","options":["指引漁船進港","存放漁具","紀念戰役","鎮壓暗礁形成的沖煞"],"answer":3,"explain":"暗礁與鱟仔尾形似箭射向村內，建塔以鎮煞。"},{"q":"塔公與塔婆之間用什麼相連？","options":["木造棧道","近百公尺石牆","石板曲橋","紅磚拱門"],"answer":1,"explain":"村民築約百公尺的石牆將兩塔連接。"}],"images":[{"file":"西嶼內垵塔公塔婆 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/%E8%A5%BF%E5%B6%BC%E5%85%A7%E5%9E%B5%E5%A1%94%E5%85%AC%E5%A1%94%E5%A9%86_%28cropped%29.jpg/960px-%E8%A5%BF%E5%B6%BC%E5%85%A7%E5%9E%B5%E5%A1%94%E5%85%AC%E5%A1%94%E5%A9%86_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%A5%BF%E5%B6%BC%E5%85%A7%E5%9E%B5%E5%A1%94%E5%85%AC%E5%A1%94%E5%A9%86_(cropped).jpg","artist":"Boboman","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/xiyu-neiantagongtapo-0.webp","small":"img/xiyu-neiantagongtapo-0-s.webp"}]},{"id":"magong-caitinglanjinshidi","name":"蔡廷蘭進士第","short":"蔡廷蘭進士第","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["宅第"],"lat":23.550677,"lng":119.611524,"address":"澎湖縣馬公市興仁里雙頭掛29號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000089","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-02-18/37b2da3d-8061-4d66-a661-cfa76c8f0fdb/照片1.jpg","year":1846,"yearText":"1846年（清道光26年）","era":"qing","themes":["名人故居","咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"開澎進士回鄉興建的燕尾宅第","intro":"蔡廷蘭進士第位於馬公市興仁里（舊名雙頭掛），是澎湖唯一進士蔡廷蘭的宅第。蔡廷蘭生於嘉慶6年（1801），13歲入臺灣府學，曾主講引心、崇文、文石等書院；道光15年赴考後返鄉途中遇颱風漂流到越南，歷經100多天水陸行程才回到澎湖，之後刊行《海南雜著》。道光24年（1844）中進士，人稱「開澎進士」，後在江西任官，1859年病逝任所。道光26年（1846）他回鄉祭祖，在舊宅旁興建進士第。宅第為四面有房、中留天井的澎湖傳統民宅，硓𥑮石砌牆，正身屋脊採燕尾，為澎湖民宅僅見。","highlights":["門楣上陰刻「進士第」的玄武岩石匾","澎湖民宅中唯一的燕尾屋脊","正廳門扇「文章千古業、詩禮一家春」刻字"],"funFact":"蔡廷蘭曾因颱風漂流到越南，走了100多天水陸路才回到澎湖，還把經歷寫成《海南雜著》。","photoSpot":"在門口拍「進士第」石匾與燕尾","visitMin":30,"openNote":"位於馬公市興仁里。依官方資料，週日、週一、週四10:30至15:00開放，週五、週六9:00至12:00、14:00至17:00開放，其他時段限10人以上團體預約；因館務休館時另行公告。建議騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這間古厝的屋脊怎麼翹起來了？澎湖的房子不是都比較低調嗎？"},{"who":"A","text":"觀察力滿分！這叫燕尾，在澎湖民宅裡只有這一座，因為主人是全澎湖唯一的進士。"},{"who":"R","text":"唯一的進士？他是不是從小就超會考試？"},{"who":"A","text":"13歲就進府學，不過鄉試也落榜好幾次。有一次考完回家遇到颱風，船一路漂到越南。"},{"who":"R","text":"沒考上還被颱風送出國，也太衰了吧！"},{"who":"A","text":"他倒是很樂觀，花了100多天走水路陸路回澎湖，還寫成一本「海南雜著」，算是古代的旅遊作家。"},{"who":"R","text":"那他後來到底有沒有考上進士啊？"},{"who":"A","text":"1844年中進士，人稱開澎進士。兩年後回鄉祭祖，就在舊宅旁蓋了這座進士第。"},{"who":"R","text":"那我要去正廳門口，找找門扇上刻的「文章千古業」，順便幫考生沾沾文氣！"}],"clues":["我的主人曾因颱風漂流到越南","我是澎湖民宅中唯一有燕尾屋脊的","我是興仁雙頭掛的開澎進士宅第"],"quiz":[{"q":"蔡廷蘭因颱風漂流到哪裡，回來後寫成《海南雜著》？","options":["越南","日本","菲律賓","琉球"],"answer":0,"explain":"道光15年返鄉遇颱風，漂抵越南。"},{"q":"蔡廷蘭進士第在澎湖民宅中有什麼獨特之處？","options":["唯一有燕尾屋脊","唯一兩層樓","唯一用紅磚","唯一有護城河"],"answer":0,"explain":"正身屋脊燕尾起翹，為澎湖民宅僅見。"}],"images":[{"file":"蔡廷蘭進士第 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/%E8%94%A1%E5%BB%B7%E8%98%AD%E9%80%B2%E5%A3%AB%E7%AC%AC_peiiunwu.jpg/960px-%E8%94%A1%E5%BB%B7%E8%98%AD%E9%80%B2%E5%A3%AB%E7%AC%AC_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%94%A1%E5%BB%B7%E8%98%AD%E9%80%B2%E5%A3%AB%E7%AC%AC_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-caitinglanjinshidi-0.webp","small":"img/magong-caitinglanjinshidi-0-s.webp"}]},{"id":"magong-suogangnanbeishita","name":"鎖港南北石塔","short":"鎖港南北石塔","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["其他設施"],"lat":23.52349,"lng":119.602281,"address":"澎湖縣馬公市鎖港南段615地號","announced":"2000-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20000128000002","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1309/photo/鎖港南北石塔1.JPG","year":1900,"yearText":"年代不詳","era":"unknown","themes":["石塔厭勝","聚落地景"],"yearUnknown":true,"summary":"全澎最高、鎮風止煞的九層石塔","intro":"鎖港南北石塔位於馬公市鎖港里舊聚落北方，由南塔與北塔組成。澎湖風沙大，居民常設石塔作為鎮風止煞的辟邪物。據說原址有一座小沙丘是聚落的靠山，被強勁的東北季風吹走，當地諺語說「鎖管港了一個山，豬母水了一個垵」，於是建塔彌補地理缺陷。最初的石塔較矮，民國53年依鎖港北極殿玄天上帝乩示，將倒塌的北塔重建為九層，南塔也一併重建。兩塔以玄武岩疊成九層階梯狀圓錐，高約11公尺，是全澎最高的石塔，形式古拙，2000年指定為縣定古蹟。","highlights":["九層階梯狀、高約11公尺的玄武岩圓錐塔","南北兩塔遙遙相對，共同守護聚落","塔旁解說牌與涼亭，可坐下看塔吹風"],"funFact":"兩座塔都是九層，北塔約10.96公尺、南塔約10.94公尺，只差2公分，堪稱雙胞胎。","photoSpot":"低角度仰拍九層塔身與藍天","visitMin":20,"openNote":"位於馬公市鎖港里，全日開放的戶外空間。石塔是信仰設施，請勿攀爬、勿搬動石塊。建議騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，抓好你的耳機！鎖港的風很有名，傳說連一座小山丘都吹得走。"},{"who":"R","text":"Allan，山丘怎麼可能被吹走？你又在誇張了。"},{"who":"A","text":"這可是有俗諺的，「鎖管港了一個山，豬母水了一個垵」，意思是這裡的沙丘被吹到別的港灣去了。"},{"who":"R","text":"靠山被風吹跑了，那村子怎麼辦？"},{"who":"A","text":"那就自己蓋一座靠山！村民在原地蓋了兩座石塔鎮風止煞，就是你眼前這對南北石塔。"},{"who":"R","text":"好高！一層一層的，好像巨型婚禮蛋糕。"},{"who":"A","text":"九層玄武岩，高約11公尺，是全澎最高的石塔。民國53年依玄天上帝的乩示重建成九層。"},{"who":"R","text":"那我來當裁判，看看南塔和北塔誰比較高！"},{"who":"A","text":"提示一下，官方測量只差2公分。你先數清楚兩座是不是真的都九層吧！"}],"clues":["我所在的地方，原本有座被季風吹走的沙丘","我們兄弟倆都是九層，高度只差2公分","鎖港聚落旁全澎最高的玄武岩石塔"],"quiz":[{"q":"鎖港南北石塔的主要功能是什麼？","options":["指引船隻航行","鎮風止煞","儲存糧食","瞭望敵情"],"answer":1,"explain":"澎湖多風沙，居民設石塔鎮風止煞。"},{"q":"鎖港南北石塔各有幾層？","options":["3層","5層","7層","9層"],"answer":3,"explain":"民國53年重建後兩塔都是九層。"}],"images":[{"file":"鎖港子午塔（北塔） (4) (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/%E9%8E%96%E6%B8%AF%E5%AD%90%E5%8D%88%E5%A1%94%EF%BC%88%E5%8C%97%E5%A1%94%EF%BC%89_%284%29_%28cropped%29.jpg/960px-%E9%8E%96%E6%B8%AF%E5%AD%90%E5%8D%88%E5%A1%94%EF%BC%88%E5%8C%97%E5%A1%94%EF%BC%89_%284%29_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%8E%96%E6%B8%AF%E5%AD%90%E5%8D%88%E5%A1%94%EF%BC%88%E5%8C%97%E5%A1%94%EF%BC%89_(4)_(cropped).jpg","artist":"舟集 Toadboat","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-suogangnanbeishita-0.webp","small":"img/magong-suogangnanbeishita-0-s.webp"}]},{"id":"magong-dashanbaoleipaotai","name":"馬公大山堡壘砲臺","short":"大山堡壘砲臺","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["關塞"],"lat":23.526451,"lng":119.55659,"address":"澎湖縣馬公市嵵裡里（仙人掌公園內）馬公市嵵裡新段1556號","announced":"2010-06-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20100630000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1294/photo/馬公大山堡壘砲臺 1.jpg","year":1900,"yearText":"1900年（明治33年）動工，1902年完成","era":"japan","themes":["城垣礮臺","軍事遺構"],"yearUnknown":false,"summary":"澎湖最早興建的日式堡壘砲臺","intro":"馬公大山堡壘砲臺位於馬公市嵵裡里青灣的大山山頭，今仙人掌公園範圍內。它於明治33年（1900）動工、明治35年（1902）完成，是日治時期澎湖島要塞12座堡壘砲臺之一，也是澎湖創建最早的日式砲臺。主砲為甲午戰爭時日軍擄獲的清軍英製10吋阿姆斯壯後膛砲，4座前圓後平的馬蹄形砲座一字排開，並有觀測所、彈藥支庫、掩蔽部等設施。戰後國軍於1952年在旁改建大山新砲臺，配備3門80公釐高射砲。此地後為青灣營區，營區撤離後規劃為仙人掌公園，2010年公告為縣定古蹟。","highlights":["4座一字排開、前圓後平的馬蹄形砲座","精緻的角石砌工，見證日治營造技術","山頂探照燈臺與周邊仙人掌景觀"],"funFact":"日軍用來守澎湖的主砲，竟是甲午戰爭從清軍手上擄獲的英製阿姆斯壯砲。","photoSpot":"在公園步道遠眺山頭與青灣海景","visitMin":20,"openNote":"位於馬公市嵵裡里青灣仙人掌公園內，官方資料標示砲臺古蹟本體不開放，請勿擅自進入或攀爬，可在公園內外遠觀。建議騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，我們不是來看砲台嗎？怎麼滿山都是仙人掌？"},{"who":"A","text":"因為這裡現在是仙人掌公園，大山堡壘砲臺就藏在青灣的大山山頭上。"},{"who":"R","text":"藏在仙人掌裡，敵人應該也不敢靠近吧！"},{"who":"A","text":"扎手的防線，哈哈！它1900年開工、1902年完成，是澎湖最早的日式砲台。"},{"who":"R","text":"那它當時用的是日本最新的大砲嗎？"},{"who":"A","text":"說出來你不信，主砲是甲午戰爭時日軍擄獲的清軍英製10吋阿姆斯壯砲。"},{"who":"R","text":"拿對手的砲來看家，這招也太省了！"},{"who":"A","text":"4座砲座一字排開，戰後國軍又在旁邊蓋了新砲台。不過古蹟本體不開放，我們在外面看就好。"},{"who":"R","text":"收到！那我在步道上找找看，哪一株仙人掌長得最像一門大砲！"}],"clues":["我的主砲是從甲午戰爭的對手那裡擄獲的","我是澎湖最早興建的日式砲台","我藏在青灣仙人掌公園的大山山頭"],"quiz":[{"q":"大山堡壘砲臺現在位於哪一個公園內？","options":["觀音亭海濱公園","林投公園","仙人掌公園","第三漁港公園"],"answer":2,"explain":"青灣營區撤離後規劃為仙人掌公園。"},{"q":"大山堡壘砲臺的主砲原本屬於誰？","options":["荷蘭東印度公司","清軍","法國艦隊","美軍"],"answer":1,"explain":"主砲是日軍在甲午戰爭擄獲的清軍阿姆斯壯砲。"}],"images":[{"file":"澎湖-馬公大山堡壘砲台3.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/%E6%BE%8E%E6%B9%96-%E9%A6%AC%E5%85%AC%E5%A4%A7%E5%B1%B1%E5%A0%A1%E5%A3%98%E7%A0%B2%E5%8F%B03.jpg/960px-%E6%BE%8E%E6%B9%96-%E9%A6%AC%E5%85%AC%E5%A4%A7%E5%B1%B1%E5%A0%A1%E5%A3%98%E7%A0%B2%E5%8F%B03.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96-%E9%A6%AC%E5%85%AC%E5%A4%A7%E5%B1%B1%E5%A0%A1%E5%A3%98%E7%A0%B2%E5%8F%B03.jpg","artist":"Mimicat1531","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-dashanbaoleipaotai-0.webp","small":"img/magong-dashanbaoleipaotai-0-s.webp"}]},{"id":"magong-gaoxiongguanshuiju","name":"高雄關稅局馬公支關","short":"馬公支關","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["其他設施"],"lat":23.563273,"lng":119.565388,"address":"澎湖縣馬公市臨海路31號","announced":"2000-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20000128000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2280/photo/59f77d7a-9b9a-423b-a111-65936498e875.jpg","year":1906,"yearText":"1906年（明治39年）","era":"japan","themes":["港口海關","公共建築","日式建築"],"yearUnknown":false,"summary":"澎湖最早的洋風官方建築","intro":"高雄關稅局馬公支關位於馬公市臨海路，緊鄰馬公港。清末開港時海關只設在基隆、淡水、高雄與安平，澎湖並未設關。日治後，明治30年（1897）媽宮港成為澎湖唯一的特別輸出入港，隔年設安平稅關媽宮出張所。明治39年（1906）在商用碼頭東側落成這棟稅關辦公廳，是澎湖最早採用洋風式樣的官方建築：主體一層，正面右側角隅有二層樓高的瞭望塔樓，門廊為拱門，辦事處前有巴洛克造形的受付窗口。主體以硓𥑮石砌承重牆，後期增建英式砌法的磚造倉庫。2000年公告為縣定古蹟，至今仍由關務機關使用。","highlights":["角隅二層樓高的瞭望塔樓與攢尖屋頂","拱門門廊與巴洛克造形的受付窗口","硓𥑮石牆與英式砌法紅磚的新舊兩期"],"funFact":"清末開港時澎湖連一個海關都沒分到，直到日治時期媽宮港才成為澎湖唯一的特別輸出入港。","photoSpot":"在臨海路對街拍塔樓與港邊","visitMin":10,"openNote":"位於馬公市臨海路馬公港邊，目前仍為關務機關使用，僅能外觀參觀，入內需先獲機關同意。從天后宮、中央街步行即可到達。","dialogue":[{"who":"R","text":"Allan，這棟黃色房子的角落怎麼有一座小塔？是燈塔嗎？"},{"who":"A","text":"不是燈塔，是瞭望塔樓。這裡是1906年落成的稅關辦公廳，塔樓用來盯著港口的船隻進出。"},{"who":"R","text":"所以是海關的監視器，用眼睛看的那種？"},{"who":"A","text":"對，人肉監視器！清末開港時澎湖沒設海關，日治時期媽宮港才成為澎湖唯一的特別輸出入港。"},{"who":"R","text":"那它在澎湖的建築史上有什麼地位？"},{"who":"A","text":"它是澎湖最早採用洋風式樣的官方建築，拱門門廊、巴洛克窗口，牆裡面卻是澎湖的咕咾石。"},{"who":"R","text":"外表洋派、骨子裡很澎湖，跟Allan穿西裝配拖鞋有點像。"},{"who":"A","text":"喂，我只有在海邊才這樣穿！它現在還是關務機關在用，我們在外面欣賞就好。"},{"who":"R","text":"好！我到對街去，把塔樓和港口一起拍進同一張照片！"}],"clues":["清末開港時澎湖沒分到海關，日治才有了我","我是澎湖最早採用洋風式樣的官方建築","臨海路馬公港邊、角落有瞭望塔樓的稅關"],"quiz":[{"q":"馬公支關角隅的塔樓原本做什麼用？","options":["瞭望港口","鐘樓報時","存放貨物","供奉神明"],"answer":0,"explain":"角隅設有二層樓高的瞭望塔樓。"},{"q":"馬公支關第一期建築的牆體主要用什麼材料？","options":["花崗岩","鋼筋混凝土","木板","硓𥑮石"],"answer":3,"explain":"第一時期主要承重壁體結構為硓𥑮石。"}],"images":[{"file":"高雄關稅局馬公支關 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/%E9%AB%98%E9%9B%84%E9%97%9C%E7%A8%85%E5%B1%80%E9%A6%AC%E5%85%AC%E6%94%AF%E9%97%9C_peiiunwu.jpg/960px-%E9%AB%98%E9%9B%84%E9%97%9C%E7%A8%85%E5%B1%80%E9%A6%AC%E5%85%AC%E6%94%AF%E9%97%9C_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%AB%98%E9%9B%84%E9%97%9C%E7%A8%85%E5%B1%80%E9%A6%AC%E5%85%AC%E6%94%AF%E9%97%9C_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-gaoxiongguanshuiju-0.webp","small":"img/magong-gaoxiongguanshuiju-0-s.webp"}]},{"id":"xiyu-erkanchenzhai","name":"澎湖二崁陳宅","short":"二崁陳宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"西嶼鄉","types":["宅第"],"lat":23.604576,"lng":119.519576,"address":"澎湖縣西嶼鄉二崁村6號","announced":"1988-04-25","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19880425000002","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1287/photo/澎湖二崁陳宅1.jpg","year":1910,"yearText":"1910年（明治43年）起建，約兩年完工","era":"japan","themes":["宅第家族","咕咾石古厝"],"yearUnknown":false,"summary":"漢藥商兄弟返鄉打造的澎湖古厝放大版","intro":"澎湖二崁陳宅位於西嶼鄉二崁村。陳氏先祖約在明末從金門渡海來澎，清道光年間二崁逐漸形成聚落。乙未戰爭後，許多村中青年到臺灣本島謀生，不少人在漢藥店當學徒。陳嶺、陳邦兄弟在臺南府城經營「元益藥鋪」有成，1910年（明治43年）返鄉興建大宅，歷時約兩年完工。陳宅為三進「日」字形封閉格局，門廳、正廳、後堂依序抬高；山牆頂有老鷹塑像與時鐘，正廳前的石水缸一半在天井、一半嵌入廚房，還有交趾陶、陳玉峰彩繪磁磚與木雕對聯。因面向西北迎風，東側轉角外牆嵌有石敢當。官方形容它是澎湖古厝的放大版，1988年指定為縣定古蹟。","highlights":["山牆上的老鷹塑像與時鐘","一半在天井、一半嵌進廚房的石水缸","東側轉角外牆嵌入的石敢當"],"funFact":"兄弟搬檜木藥櫥進店時撞翻水肥擔，陳邦笑說「大肥可比黃金萬兩」，就此息事寧人。","photoSpot":"在外埕拍山牆老鷹與時鐘","visitMin":40,"openNote":"位於西嶼鄉二崁聚落。依官方資料開放時間為8:00–19:00，據資料需購票參觀，請以現場公告為準。二崁聚落仍有居民生活，請勿擅入其他民宅。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"A","text":"阿拉蕾，抬頭看山牆最上面，有一隻老鷹，下面還有一個時鐘。"},{"who":"R","text":"老鷹配時鐘？Allan，這是要提醒老鷹準時打卡上班嗎？"},{"who":"A","text":"哈哈，老鷹諧音英雄，期許家族出英雄。時鐘有人說是金童顧厝，也有人說和日本推行守時有關。"},{"who":"R","text":"好有學問的裝飾！那蓋這間大房子的是誰？"},{"who":"A","text":"陳嶺和陳邦兩兄弟，在臺南府城開元益藥鋪賺了錢，1910年回二崁蓋了這座三進大宅。"},{"who":"R","text":"澎湖人去臺南當藥商，好像勵志連續劇！"},{"who":"A","text":"還有插曲。他們搬藥櫥進店時撞翻水肥擔，陳邦卻說大肥可比黃金萬兩，笑笑就算了。"},{"who":"R","text":"這心胸太寬大了，難怪後來會發財！"},{"who":"A","text":"等一下走到正廳前，找找那口一半在天井、一半嵌進廚房裡的石水缸！"}],"clues":["我的主人是在臺南府城開藥鋪的兩兄弟","我的山牆上住著一隻老鷹和一個時鐘","我在西嶼一座以漢藥歷史聞名的聚落，被稱為澎湖古厝的放大版"],"quiz":[{"q":"陳嶺、陳邦兄弟在臺南府城經營什麼生意？","options":["漢藥鋪","布莊","糖廠","碾米廠"],"answer":0,"explain":"兩兄弟在府城經營「元益藥鋪」。"},{"q":"陳宅東側轉角外牆嵌入石敢當，主要原因是什麼？","options":["標示地界","紀念祖先","因應強勁季風","裝飾門面"],"answer":2,"explain":"宅第面向西北迎風，為因應猛烈東北季風而設。"}],"images":[{"file":"澎湖縣二崁陳宅.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/%E6%BE%8E%E6%B9%96%E7%B8%A3%E4%BA%8C%E5%B4%81%E9%99%B3%E5%AE%85.jpg/960px-%E6%BE%8E%E6%B9%96%E7%B8%A3%E4%BA%8C%E5%B4%81%E9%99%B3%E5%AE%85.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96%E7%B8%A3%E4%BA%8C%E5%B4%81%E9%99%B3%E5%AE%85.jpg","artist":"方珣","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/xiyu-erkanchenzhai-0.webp","small":"img/xiyu-erkanchenzhai-0-s.webp"}]},{"id":"magong-qianyitangzhongyao","name":"乾益堂中藥行","short":"乾益堂中藥行","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["其他設施"],"lat":23.565204,"lng":119.564909,"address":"澎湖縣馬公市中央里中央街42號","announced":"1998-12-10","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19981210000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-27/24d770b0-9bbf-4a12-b681-120fcc040d33/218648.jpg","year":1918,"yearText":"1918年（大正7年）","era":"japan","themes":["產業遺產","日式建築"],"yearUnknown":false,"summary":"四眼井旁傳承四代的百年中藥舖","intro":"乾益堂中藥行位於馬公市中央街北端、四眼井旁。中央街舊稱大井街，清代就是媽宮最熱鬧的街道之一。乾益堂由湖西出身的薛號於大正7年（1918）創立，早年顧客多是漁民、往來商人與官兵，在中央街的幾家藥房中生意最為鼎盛，至今已傳到第四代。建築是日治時期流行的仿巴洛克風格街屋，立面已使用鋼筋混凝土與洗石子；內部保留傳統長條街屋格局，一樓是藥舖，二樓為薛家神明廳，也是烘藥的空間，廳前陽台則用來曝曬藥材。1993年起研發的藥膳蛋，成為觀光客熟悉的招牌。","highlights":["仿巴洛克立面與洗石子的細緻工法","店內年代悠久的藥櫃與櫃台","二樓神明廳前曾用來曬藥的陽台"],"funFact":"創辦人薛號53歲才自己開店，在那之前是中央街另一家藥房聘請的師傅。","photoSpot":"站在四眼井旁拍藥行立面全景","visitMin":15,"openNote":"位於馬公市中央街，仍在營業的中藥行，官方資料為7:00至21:30外貌參觀；入內請尊重店家營業，勿妨礙顧客。可與四眼井、天后宮、施公祠步行串遊。","dialogue":[{"who":"R","text":"Allan，這條街怎麼飄來一股中藥香？你是不是偷偷在燉補？"},{"who":"A","text":"我是很想燉啦！不過香味來自乾益堂中藥行，1918年開到現在，已經傳到第四代。"},{"who":"R","text":"100多年！創辦人一定很年輕就開店了吧？"},{"who":"A","text":"剛好相反，創辦人薛號53歲才自立門戶，之前是中央街另一家藥房請來的師傅。"},{"who":"R","text":"53歲才創業，Allan，那你還有希望耶！"},{"who":"A","text":"謝謝喔，這到底是安慰還是傷害？早年客人多是漁民、商人和官兵，生意在中央街藥房裡最好。"},{"who":"R","text":"這棟樓看起來不像傳統店面，比較洋派。"},{"who":"A","text":"對，它是日治時期流行的仿巴洛克立面，用了洗石子和鋼筋混凝土。二樓是神明廳，以前也在那裡烘藥。"},{"who":"R","text":"那我站到四眼井旁邊，抬頭找找二樓那個曾經用來曬藥材的陽台！"}],"clues":["我的創辦人53歲才自己開店","我的二樓是神明廳，陽台曾經用來曬藥","我是中央街四眼井旁的百年中藥舖"],"quiz":[{"q":"乾益堂中藥行創立於哪一年？","options":["1918年","1895年","1935年","1949年"],"answer":0,"explain":"大正7年（1918）由薛號創立。"},{"q":"乾益堂二樓神明廳前的陽台，早年用來做什麼？","options":["晾曬漁網","觀賞煙火","曝曬中藥","練習書法"],"answer":2,"explain":"神明廳兼作烘藥空間，廳前陽台用來曝曬中藥。"}],"images":[{"file":"澎湖-乾益堂內部.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/%E6%BE%8E%E6%B9%96-%E4%B9%BE%E7%9B%8A%E5%A0%82%E5%85%A7%E9%83%A8.jpg/960px-%E6%BE%8E%E6%B9%96-%E4%B9%BE%E7%9B%8A%E5%A0%82%E5%85%A7%E9%83%A8.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96-%E4%B9%BE%E7%9B%8A%E5%A0%82%E5%85%A7%E9%83%A8.jpg","artist":"Mimicat1531","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-qianyitangzhongyao-0.webp","small":"img/magong-qianyitangzhongyao-0-s.webp"}]},{"id":"xiyu-yuwengdaoshuiguan","name":"漁翁島稅關監視署","short":"稅關監視署","category":"縣定古蹟","level":"縣(市)定古蹟","town":"西嶼鄉","types":["衙署"],"lat":23.565349,"lng":119.482688,"address":"澎湖縣西嶼鄉外垵村8-1號","announced":"2015-06-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150617000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/38311/photo/f87724e1-4717-438e-ae96-d9600a2bffd6.jpg","year":1920,"yearText":"年代不詳（1900年設署，建物較晚興建）","era":"japan","themes":["港口海關","日式建築"],"yearUnknown":true,"summary":"外垵半山腰附監視塔樓的清水紅磚官署","intro":"漁翁島稅關監視署位於西嶼鄉外垵村半山腰。日治時期依總督府令於1900年（明治33年）設置，負責對往來中國與臺澎之間的船隻檢查、徵稅與監視，建物則在設署之後才興建。據曾任職的監吏回憶，監視署因中日戰爭交通中斷而失去功能，約在1941、1942年間撤銷，之後由民間租用、購入。建築為清水紅磚承重牆加木屋架，最醒目的是兩層的清水磚監視塔樓，內有木造旋轉樓梯通往塔頂；內部有辦公空間與數間和室，基礎有洗石子裝飾。它融合內垵工匠技術、英式砌磚法與日式空間，在咕咾石建築普遍的澎湖相當少見，2015年指定為縣定古蹟。目前結構多處受損，正在規劃修復。","highlights":["清水紅磚砌成的兩層監視塔樓","基礎的洗石子裝飾與通氣口","在咕咾石之鄉少見的全磚造官署"],"funFact":"監視塔樓裡有一座木造旋轉樓梯，可以直通塔頂的監視處。","photoSpot":"從坡下仰拍紅磚監視塔樓","visitMin":10,"openNote":"位於西嶼鄉外垵村，目前未開放，建物結構受損，請在外觀參觀、勿進入。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"R","text":"Allan，外垵半山腰那棟紅磚房子，怎麼還長了一座小塔？"},{"who":"A","text":"那是漁翁島稅關監視署的監視塔樓，日治時期用來盯著往來的船，還要收稅。"},{"who":"R","text":"原來是海上的收費站加上監視器！"},{"who":"A","text":"哈哈，很貼切。1900年設署，專門檢查往來中國和臺澎之間的船隻。"},{"who":"R","text":"Allan，那它後來還一直留在這裡收稅嗎？"},{"who":"A","text":"據曾在這裡工作的監吏回憶，中日戰爭後交通中斷，大約1941、1942年就撤銷了。"},{"who":"R","text":"好好奇，那塔樓裡面到底長什麼樣子？"},{"who":"A","text":"有一座木造旋轉樓梯直通塔頂，旁邊還有和室當寢室。可惜現在結構受損，只能在外面看。"},{"who":"R","text":"那我在坡下找個角度，把紅磚塔樓和外垵的海一起拍進來！"}],"clues":["我在日治時期負責檢查往來船隻並收稅","我有一座清水紅磚的兩層監視塔樓","我在外垵村半山腰，名字裡有西嶼的舊稱"],"quiz":[{"q":"漁翁島稅關監視署主要負責什麼業務？","options":["船隻檢查徵稅","燈塔點燈","郵件遞送","漁獲拍賣"],"answer":0,"explain":"負責往來中國與臺澎船隻的檢查、徵稅與監視。"},{"q":"監視署建築最明顯的外觀特徵是什麼？","options":["咕咾石圍牆","紅磚監視塔樓","玄武岩門樓","木造騎樓"],"answer":1,"explain":"清水磚造的二層監視塔樓是最醒目的特徵。"}],"images":[{"file":"漁翁島稅關監視署.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/%E6%BC%81%E7%BF%81%E5%B3%B6%E7%A8%85%E9%97%9C%E7%9B%A3%E8%A6%96%E7%BD%B2.jpg/960px-%E6%BC%81%E7%BF%81%E5%B3%B6%E7%A8%85%E9%97%9C%E7%9B%A3%E8%A6%96%E7%BD%B2.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BC%81%E7%BF%81%E5%B3%B6%E7%A8%85%E9%97%9C%E7%9B%A3%E8%A6%96%E7%BD%B2.jpg","artist":"地下高雄","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/xiyu-yuwengdaoshuiguan-0.webp","small":"img/xiyu-yuwengdaoshuiguan-0-s.webp"}]},{"id":"huxi-longmenlizhengjiao","name":"龍門裡正角日軍上陸紀念碑","short":"裡正角上陸紀念碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"湖西鄉","types":["碑碣"],"lat":23.554499,"lng":119.681525,"address":"澎湖縣湖西鄉龍門南段847地號","announced":"2000-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20000128000005","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1270/photo/龍門裡正角日軍上陸紀念碑1.JPG","year":1924,"yearText":"1924年（大正13年）","era":"japan","themes":["牌坊碑碣","戰爭史蹟"],"yearUnknown":false,"summary":"國內最早的日軍登陸紀念碑，曾被棄置路旁","intro":"龍門裡正角日軍上陸紀念碑位於湖西鄉龍門村的裡正角海岸。1895年甲午戰爭末期、清日雙方商議馬關條約之際，日本於3月23日由伊東中將率12艘軍艦進向澎湖，派4艦在龍門港外以艦砲掩護混成支隊在裡正角登陸，向太武山推進。日本占領澎湖後，於大正13年（1924）在此立碑，碑高約2公尺，花崗岩造，官方稱為國內最早與日軍侵臺有關的紀念碑。戰後碑文被改為台灣光復紀念碑，後來石碑被棄置路旁，原址改建為土地廟；之後由政府將原碑扶正，立在土地廟東側圍牆邊。2000年公告為縣定古蹟。","highlights":["約2公尺高的花崗岩原碑","原址改建的土地廟與東側重新扶正的石碑","1895年日軍登陸澎湖的地點"],"funFact":"碑立的原址後來變成土地廟，原碑一度被丟在路邊，如今和土地公當起了鄰居。","photoSpot":"在土地廟東側圍牆邊拍石碑與海岸","visitMin":15,"openNote":"位於湖西鄉龍門村裡正角海岸，全天開放。可從馬公開車或騎機車前往。旁邊是土地廟，參觀時請保持安靜、尊重信仰。","dialogue":[{"who":"A","text":"來，我們到龍門的裡正角海邊，這裡比林投那座碑更早一步。"},{"who":"R","text":"早一步？兩座碑是在比賽誰先到嗎？"},{"who":"A","text":"可以這樣記。1895年3月23日日軍先在裡正角登陸，隔天才從林投上岸。"},{"who":"R","text":"那這塊碑也像林投那座一樣高大嗎？"},{"who":"A","text":"它只有約2公尺高，1924年立的，比林投那座早12年，官方說是國內最早的日軍侵臺紀念碑。"},{"who":"R","text":"那紀念碑旁邊，怎麼會有一間小土地廟？"},{"who":"A","text":"戰後碑文改成台灣光復紀念碑，後來石碑被丟在路邊，原址蓋成了土地廟，最後政府才把碑扶正立在廟旁。"},{"who":"R","text":"從紀念碑變路邊石，再回來當土地公的鄰居，命運好曲折！"},{"who":"A","text":"一塊碑看盡兩個時代。你到現場找找，石碑立在土地廟的哪一側！"}],"clues":["我比林投那座同類石碑早12年立起","我曾被棄置路旁，原址變成一座土地廟","1924年立在龍門海岸，紀念1895年日軍首次登陸澎湖"],"quiz":[{"q":"1895年日軍登陸澎湖時，最先在哪裡上岸？","options":["林投","裡正角","風櫃尾","西嶼內垵"],"answer":1,"explain":"3月23日日軍由裡正角登陸，隔天再由林投上岸夾擊。"},{"q":"紀念碑原址後來改建成什麼？","options":["派出所","學校","燈塔","土地廟"],"answer":3,"explain":"原碑被棄置後原址建成土地廟，碑後來扶正立在廟旁。"}],"images":[{"file":"龍門裡正角日軍上陸紀念碑1 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/%E9%BE%8D%E9%96%80%E8%A3%A1%E6%AD%A3%E8%A7%92%E6%97%A5%E8%BB%8D%E4%B8%8A%E9%99%B8%E7%B4%80%E5%BF%B5%E7%A2%911_peiiunwu.jpg/960px-%E9%BE%8D%E9%96%80%E8%A3%A1%E6%AD%A3%E8%A7%92%E6%97%A5%E8%BB%8D%E4%B8%8A%E9%99%B8%E7%B4%80%E5%BF%B5%E7%A2%911_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%BE%8D%E9%96%80%E8%A3%A1%E6%AD%A3%E8%A7%92%E6%97%A5%E8%BB%8D%E4%B8%8A%E9%99%B8%E7%B4%80%E5%BF%B5%E7%A2%911_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/huxi-longmenlizhengjiao-0.webp","small":"img/huxi-longmenlizhengjiao-0-s.webp"}]},{"id":"huxi-lintourijunshanglu","name":"林投日軍上陸紀念碑","short":"林投上陸紀念碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"湖西鄉","types":["碑碣"],"lat":23.561594,"lng":119.644877,"address":"澎湖縣湖西鄉林投南段985地號","announced":"2000-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20000128000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-26/de4eaeb2-ae85-4016-b2a4-80cd2aff54f0/DSCN6209.jpg","year":1936,"yearText":"1936年（昭和11年）","era":"japan","themes":["牌坊碑碣","戰爭史蹟"],"yearUnknown":false,"summary":"記錄1895年日軍登陸、戰後改名的紀念碑","intro":"林投日軍上陸紀念碑位於湖西鄉林投村海岸。清光緒21年（1895）3月23日日軍由裡正角登陸澎湖，隨即向太武山推進，次日再派海軍陸戰隊由林投登陸夾擊清軍。昭和11年（1936）日方在林投登陸處立碑紀念，碑高含基座5公尺多，平面八角形，花崗岩造，外形像日本傳統石燈籠，周圍以貓公石築成圓形圍牆。1945年戰後，碑被改為「抗戰勝利紀念碑」，碑體漆白、碑文改紅，圍牆與綠地則維持原貌。同一座碑先後承載兩種截然不同的紀念意義，2000年公告為縣定古蹟。","highlights":["高5公尺多、仿日本石燈籠造型的八角形碑體","以貓公石砌成的圓形圍牆與門柱","戰後改名為「抗戰勝利紀念碑」的痕跡"],"funFact":"這座碑先後代表日軍登陸與抗戰勝利兩種紀念，碑沒換，換的是碑上的字。","photoSpot":"從圍牆入口的貓公石門柱間拍碑體","visitMin":15,"openNote":"位於湖西鄉林投村海岸，全日開放。可從馬公開車或騎機車前往。紀念戰爭的場所，參觀請保持莊重。","dialogue":[{"who":"R","text":"這座碑好高，長得好像一盞巨大的石燈籠！"},{"who":"A","text":"眼力不錯，它的造型就是仿日本傳統石燈籠，高5公尺多，平面是八角形。周圍還有貓公石砌的圓形圍牆。"},{"who":"R","text":"為什麼海邊會有日本風格的石碑？"},{"who":"A","text":"1895年3月日軍從裡正角登陸澎湖，隔天又派海軍陸戰隊從林投這裡上岸，夾擊清軍。對當時的清軍和居民來說，是一場劇變。"},{"who":"R","text":"所以這是日本人紀念自己登陸的碑？"},{"who":"A","text":"對，1936年立的。但戰後被改成「抗戰勝利紀念碑」，碑漆成白色、字改成紅色。"},{"who":"R","text":"同一塊石頭，換了主人就換了台詞，好像演員換角色喔。"},{"who":"A","text":"比喻得好。歷史在這裡留下兩種觀點，我們都該看見。你繞圍牆一圈，摸摸看貓公石的紋路！"}],"clues":["我仿日本傳統石燈籠，平面是八角形","戰後我被改稱為抗戰勝利紀念碑，碑文變成紅色","1936年立在湖西海岸，紀念1895年海軍陸戰隊上岸"],"quiz":[{"q":"這座碑在戰後被改成什麼名稱？","options":["台灣光復紀念碑","抗戰勝利紀念碑","忠烈紀念碑","和平紀念碑"],"answer":1,"explain":"戰後改為抗戰勝利紀念碑，碑白字紅。"},{"q":"紀念碑周圍的圍牆用什麼石材砌成？","options":["青斗石","大理石","紅磚","貓公石"],"answer":3,"explain":"碑以花崗岩造，周圍用貓公石築成圍牆。"}],"images":[{"file":"林投日軍上陸紀念碑 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/%E6%9E%97%E6%8A%95%E6%97%A5%E8%BB%8D%E4%B8%8A%E9%99%B8%E7%B4%80%E5%BF%B5%E7%A2%91_peiiunwu.jpg/960px-%E6%9E%97%E6%8A%95%E6%97%A5%E8%BB%8D%E4%B8%8A%E9%99%B8%E7%B4%80%E5%BF%B5%E7%A2%91_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9E%97%E6%8A%95%E6%97%A5%E8%BB%8D%E4%B8%8A%E9%99%B8%E7%B4%80%E5%BF%B5%E7%A2%91_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/huxi-lintourijunshanglu-0.webp","small":"img/huxi-lintourijunshanglu-0-s.webp"}]},{"id":"magong-diyibinguan","name":"第一賓館","short":"第一賓館","category":"縣定古蹟","level":"縣(市)定古蹟","town":"馬公市","types":["其他設施"],"lat":23.568955,"lng":119.563351,"address":"澎湖縣馬公市中興里介壽路13號","announced":"1998-12-10","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19981210000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-09-02/ebfb2137-cb51-4c85-9166-c2e4b0449de6/第一賓館02-原間影像.jpg","year":1943,"yearText":"日治時期（確切年代待考）","era":"japan","themes":["日式建築","名人故居","軍事遺構"],"yearUnknown":true,"summary":"總統下榻兼作戰指揮所的和洋賓館","intro":"第一賓館位於馬公市介壽路，是日治時期日軍所建的和洋混合式建築。1949年5月17日，已下野的蔣中正首次下榻於此；此後蔣中正、蔣經國、李登輝等總統抵澎巡視時都曾多次入住。1958年八二三砲戰期間，蔣中正坐鎮賓館成立指揮所，它也是現存行館中唯一具有戰略設施的一座。建築外牆為烏石承重牆，入口玄關為「唐博風」式屋頂，玄關地面與牆面使用澎湖特有的「洗砂頭」，內部有編竹夾泥牆。由於長期由軍方管理、很少開放，保存良好，2009年整修完成，2024年再完成修復。","highlights":["入口玄關的「唐博風」式屋頂","玄關地面與牆面使用的澎湖「洗砂頭」","八二三砲戰期間設置指揮所的歷史空間"],"funFact":"1949年蔣中正第一次住進這裡時已經下野，並不是以總統身分入住。","photoSpot":"在玄關前拍唐博風屋頂與烏石牆","visitMin":30,"openNote":"位於馬公市中興里介壽路，官方開放時間週四至週一9:00至12:00、14:00至17:00，週二、週三及國定假日休館。鄰近觀音亭與公賣局北側防空壕，可步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，今天帶你參觀總統套房，不過只能看，不能過夜。"},{"who":"R","text":"Allan，又在畫大餅。這是什麼地方？"},{"who":"A","text":"第一賓館，日治時期日軍蓋的。1949年5月17日，已經下野的蔣中正第一次來澎湖就住在這裡。"},{"who":"R","text":"除了他以外，後來還有誰住過這裡？"},{"who":"A","text":"蔣中正、蔣經國、李登輝三位總統來澎湖巡視時都住過。1958年八二三砲戰時，這裡還成立了指揮所。"},{"who":"R","text":"所以它白天是賓館，打仗時變作戰室？"},{"who":"A","text":"可以這樣想，它是現存行館裡唯一有戰略設施的。外牆是烏石，玄關屋頂卻是日式唐博風，和洋混搭。"},{"who":"R","text":"又日式又洋式，還用澎湖石頭，根本是混血建築！"},{"who":"A","text":"形容得好！進玄關時低頭看看，地面用的是澎湖特有的洗砂頭，找找上面細細的砂粒紋理。"}],"clues":["八二三砲戰期間，我曾是指揮所","三位總統來澎湖巡視時都曾住在我這裡","我是介壽路上和洋混合的日治時期賓館"],"quiz":[{"q":"蔣中正首次下榻第一賓館是哪一年？","options":["1945年","1949年","1958年","1962年"],"answer":1,"explain":"1949年5月17日已下野的蔣中正首次下榻於此。"},{"q":"第一賓館玄關使用的澎湖特有材料叫什麼？","options":["咕咾石","磨石子","紅地磚","洗砂頭"],"answer":3,"explain":"玄關地面和牆面使用澎湖特有的「洗砂頭」。"}],"images":[{"file":"第一賓館2 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/%E7%AC%AC%E4%B8%80%E8%B3%93%E9%A4%A82_peiiunwu.jpg/960px-%E7%AC%AC%E4%B8%80%E8%B3%93%E9%A4%A82_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%AC%AC%E4%B8%80%E8%B3%93%E9%A4%A82_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-diyibinguan-0.webp","small":"img/magong-diyibinguan-0-s.webp"}]},{"id":"xiyu-dongbitouzhenyang","name":"西嶼東鼻頭震洋艇格納壕","short":"震洋艇格納壕","category":"縣定古蹟","level":"縣(市)定古蹟","town":"西嶼鄉","types":["其他設施"],"lat":23.56723,"lng":119.514788,"address":"澎湖縣西嶼鄉內垵三段127-2地號","announced":"2011-03-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20110321000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1292/photo/西嶼東鼻頭震洋艇格納庫1.JPG","year":1944,"yearText":"約1944年（昭和19年）","era":"japan","themes":["軍事遺構","戰爭史蹟"],"yearUnknown":false,"summary":"二戰末期藏放特攻艇的岩壁洞窟","intro":"西嶼東鼻頭震洋艇格納壕位於西嶼鄉內垵東鼻頭一帶，是二次大戰末期日軍藏放「震洋」特攻艇的洞窟。日軍在太平洋戰場失利後，1944年起研製多種特攻兵器，震洋艇由摩托艇改造，艇長約5公尺、寬約1.2公尺，主體為木製合板，艇首裝有約250公斤炸藥，由1名艇員駕駛衝撞敵艦自爆。這處格納壕在石壁上開鑿，內有4條平行的格納庫，各長約32至37公尺、寬3.2公尺，內部互相連通。它見證二戰末期日軍的戰略因應與戰爭的殘酷，屬日治時期稀有的軍事遺構，2011年指定為縣定古蹟。目前位於軍營內，未對外開放。","highlights":["石壁上開鑿的4條平行格納庫","長約32至37公尺、內部相通的洞窟","二戰末期特攻艇的歷史背景"],"funFact":"震洋艇主體用木製合板製成，一方面減輕重量，也反映當時日本鋼材極度匱乏。","photoSpot":"位於營區不開放，請勿拍攝營區","visitMin":10,"openNote":"位於西嶼鄉內垵東鼻頭一帶的軍營內，目前未開放，請勿靠近或拍攝營區。可改參觀附近的西嶼東臺、西嶼彈藥本庫。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"A","text":"阿拉蕾，接下來這處我們只能用聽的，因為它在軍營裡，目前不開放。"},{"who":"R","text":"只能靠想像力逛？好吧，那它是什麼地方？"},{"who":"A","text":"是震洋艇格納壕。二戰末期日軍戰況吃緊，研發一種衝撞敵艦自爆的小艇，叫做震洋。"},{"who":"R","text":"衝撞自爆？那開船的人不就回不來了？"},{"who":"A","text":"是的，這是很沉重的歷史。艇長約5公尺，用木製合板做，艇首裝約250公斤炸藥，只坐1個人。"},{"who":"R","text":"用木板做船，是因為這樣比較輕嗎？"},{"who":"A","text":"一方面減輕重量，也反映當時日本鋼材極度缺乏。這裡在石壁鑿了4條平行的洞窟來藏艇。"},{"who":"R","text":"聽完心情好複雜，戰爭真的讓人好難過。"},{"who":"A","text":"所以更要記住這段歷史。到了附近的西嶼東臺，請朝東鼻頭的方向靜靜望一分鐘。"}],"clues":["我是在石壁上開鑿的洞窟，藏過二戰末期的特攻小艇","我的4條洞窟平行排列，內部互相連通","我在西嶼內垵東鼻頭的營區裡，目前不開放"],"quiz":[{"q":"震洋艇的艇身主體用什麼材料製成？","options":["鋁合金","鋼板","木製合板","玻璃纖維"],"answer":2,"explain":"艇身主體以膠合板（木製合板）製成。"},{"q":"東鼻頭格納壕內共有幾條平行的格納庫？","options":["4條","2條","3條","6條"],"answer":0,"explain":"洞穴內有4條平行配置、互相連通的格納庫。"}],"images":[]},{"id":"magong-wenshishuyuannei","name":"文石書院內石碑（六面）","short":"文石書院石碑","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.567152,"lng":119.580195,"address":"澎湖縣馬公市西文澳104之7號","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000003","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1304/photo/文石書院內石碑（六面）1.jpg","year":1685,"yearText":"1685年前後（清康熙24年）至1931年","era":"qing","themes":["牌坊碑碣","教育書院"],"yearUnknown":false,"summary":"從施琅到昭和年間的六面石碑","intro":"文石書院內石碑（六面）位於馬公市西文里的文石書院（孔子廟）內，2003年登錄為歷史建築。最早的是約康熙24年（1685）的施琅靖台碑記，內容是施琅自述平台事功，碑額與邊框刻有龍紋；原立於施公祠，輾轉移到馬公市公所前庭，再遷到孔子廟前院，但碑文不知何時、被何人全部磨平。其餘五面包括嘉慶4年（1799）刻有「皇清」與雙龍紋飾的文石書院門額、道光23年（1843）倡捐襄舉賓興記，以及昭和6年（1931）的孔子廟重修捐題碑記、古蹟保存所記與聖廟重修落成記，前後跨越兩百多年。","highlights":["碑文被磨平、只剩龍紋雕飾的施琅靖台碑","嘉慶4年刻有「皇清」與雙龍紋的書院門額","昭和6年聖廟重修落成記上的雙麒麟紋飾"],"funFact":"施琅靖台碑的字不知何時、被誰全部磨平，只剩邊框龍紋，成了一塊說不出字的石碑。","photoSpot":"近拍磨平碑面旁的龍紋邊框","visitMin":20,"openNote":"位於馬公市西文里文石書院（孔子廟）內，官方資料為週三至週六9:00至16:00開放，週一、週二休息，其他日期請以現場公告為準。附近有文澳城隍廟，可一併參觀。","dialogue":[{"who":"R","text":"Allan，這塊石碑上面怎麼一個字都沒有？是還沒刻完嗎？"},{"who":"A","text":"不是沒刻，是被磨掉了！這是施琅自述平台功勞的靖台碑記，大約刻於1685年。"},{"who":"R","text":"誰把它磨掉的？這是古代版的刪文嗎？"},{"who":"A","text":"這個懸案到現在都沒破，不知道是什麼時候、誰磨的，只剩碑額和邊框的龍紋還在。"},{"who":"R","text":"那它從以前就一直放在文石書院嗎？"},{"who":"A","text":"它原本立在施公祠，後來搬到馬公市公所前庭，再遷到孔子廟前院，是一塊很會搬家的石碑。"},{"who":"R","text":"那旁邊其他五塊碑又是什麼來頭？"},{"who":"A","text":"有嘉慶4年的文石書院門額、道光23年的賓興記，還有昭和6年孔子廟重修的三塊碑，跨越兩百多年。"},{"who":"R","text":"我要當一次偵探，找到那塊沒字的石碑，數數邊框上刻了幾條龍！"}],"clues":["我們之中有一位，碑文被人全部磨平","我們跨越清康熙到日治昭和，一共六面","我們收藏在西文里的書院與孔子廟裡"],"quiz":[{"q":"施琅靖台碑記現在是什麼狀況？","options":["碑文被全部磨平","斷成兩截","被移到故宮","碑文重新上色"],"answer":0,"explain":"碑文不知何時被人全部磨平，只剩雕飾。"},{"q":"刻有「皇清」與雙龍紋飾的文石書院門額刻於哪個年號？","options":["康熙","嘉慶","道光","昭和"],"answer":1,"explain":"文石書院門額刻於嘉慶4年（1799）。"}],"images":[{"file":"Wenshi College Plaque (cropped).JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Wenshi_College_Plaque_%28cropped%29.JPG/960px-Wenshi_College_Plaque_%28cropped%29.JPG","page":"https://commons.wikimedia.org/wiki/File:Wenshi_College_Plaque_(cropped).JPG","artist":"Sekisama","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","local":"img/magong-wenshishuyuannei-0.webp","small":"img/magong-wenshishuyuannei-0-s.webp"}]},{"id":"xiyu-xianghuangshizong","name":"西嶼鄉黃氏宗祠","short":"黃氏宗祠","category":"歷史建築","level":"","town":"西嶼鄉","types":["祠堂"],"lat":23.598549,"lng":119.504663,"address":"澎湖縣西嶼鄉池西村小池角166號","announced":"2010-09-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20100902000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1290/photo/西嶼鄉黃氏宗祠1.JPG","year":1766,"yearText":"年代不詳（據資料為清乾隆年間創建）","era":"qing","themes":["宗祠家廟"],"yearUnknown":true,"summary":"小池角黃氏家族祭祖的閩南式宗祠","intro":"西嶼鄉黃氏宗祠位於西嶼鄉池西村，舊稱小池角，2010年登錄為歷史建築。據相關資料，小池角黃氏家族祖籍金門，清乾隆年間創建宗祠，日治大正年間（1914–1920）重修，1979年再整修並擴建廣場。宗祠為典型閩南合院的外貌與格局，結合民居與宮廟的建築架構，前埕的庭院圍牆呈現日治時期的特色。內部石工與彩繪做工細緻、保存完整，兩側圖樣豐富；祠內保有黃氏家族的歷史文物與牌匾，包括第六世石製香爐、第八世銅製香爐，反映家族的歷史。至今仍是黃氏族人返鄉祭祖的地方。","highlights":["細緻完整的石工與彩繪","第六世石製香爐與第八世銅製香爐","日治時期風格的前埕庭院圍牆"],"funFact":"祠內保存不同世代的香爐，第六世是石製、第八世是銅製，見證家族代代祭祀。","photoSpot":"在前埕拍閩南式屋脊與圍牆","visitMin":15,"openNote":"位於西嶼鄉池西村，宗祠平時不開放，請在外觀參觀，祭祖期間請勿打擾族人。鄰近池西41號古宅。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"R","text":"Allan，這座建築屋頂好華麗，是廟嗎？"},{"who":"A","text":"很像廟對吧！其實是黃氏宗祠，小池角黃家祭拜祖先的地方，兼具民居和宮廟的味道。"},{"who":"R","text":"原來是家族的總部！黃家人是從哪裡來的？"},{"who":"A","text":"據資料記載，他們祖籍金門，清乾隆年間建了宗祠，日治大正年間又大修一次。"},{"who":"R","text":"那宗祠裡面有沒有什麼傳家寶呢？"},{"who":"A","text":"有第六世的石製香爐，還有第八世的銅製香爐，一代一代換材質，像家族的升級紀錄。"},{"who":"R","text":"香爐也會升級，而且比我的手機耐用好幾百倍！"},{"who":"A","text":"哈哈。官方特別稱讚這裡的石工和彩繪保存完整。平常不開放，我們在外面看就好。"},{"who":"R","text":"那我在前埕找找看，圍牆上有沒有日治時期風格的裝飾！"}],"clues":["我是小池角一個家族祭祖的地方","我保存著第六世石香爐和第八世銅香爐","我在西嶼池西村，是閩南合院式的祭祖建築"],"quiz":[{"q":"據資料，小池角黃氏家族的祖籍是哪裡？","options":["泉州","金門","漳浦","廈門"],"answer":1,"explain":"據資料，小池角黃氏家族原籍金門。"},{"q":"宗祠保存的第八世香爐是什麼材質？","options":["石製","陶製","木製","銅製"],"answer":3,"explain":"祠內有第六世石製香爐與第八世銅製香爐。"}],"images":[{"file":"西嶼鄉黃氏宗祠.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/%E8%A5%BF%E5%B6%BC%E9%84%89%E9%BB%83%E6%B0%8F%E5%AE%97%E7%A5%A0.jpg/960px-%E8%A5%BF%E5%B6%BC%E9%84%89%E9%BB%83%E6%B0%8F%E5%AE%97%E7%A5%A0.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%A5%BF%E5%B6%BC%E9%84%89%E9%BB%83%E6%B0%8F%E5%AE%97%E7%A5%A0.jpg","artist":"地下高雄","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/xiyu-xianghuangshizong-0.webp","small":"img/xiyu-xianghuangshizong-0-s.webp"}]},{"id":"baisha-tonglianglinjiagu","name":"通梁林家古宅","short":"通梁林家古宅","category":"歷史建築","level":"","town":"白沙鄉","types":["宅第"],"lat":23.656686,"lng":119.557753,"address":"澎湖縣白沙鄉通梁村47號","announced":"2007-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071121000004","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1280/photo/通梁林家古宅1.JPG","year":1768,"yearText":"1768年（清乾隆33年）以前","era":"qing","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"緊鄰通樑古榕、二百多年的林家老厝","intro":"通梁林家古宅位於白沙鄉通梁村東甲的林氏宗親聚落，右側隔著道路就是通樑保安宮與著名的通樑古榕。依文獻、口述與實體史料研判，古宅創建至少在清乾隆33年（1768）以前，已有二百多年歷史。通梁林氏開基祖林四原籍福建漳浦，明崇禎年間的1643年來澎。古宅大厝身為三開間，中央為廳，是祭祀神明祖先、接待賓客的重要空間，左右兩側房皆採通舖。古宅格局大致維持原貌，並留有豐富的契約與族譜可以佐證，在傳統民宅中相當少見，2007年登錄為歷史建築。官方資料也提到，古宅前方只剩牆基的空地，就是當年種下古榕那戶人家的舊居。","highlights":["大厝身三開間、中央為廳的傳統格局","兩側房間採通舖的生活空間","隔路相望的通樑保安宮與古榕"],"funFact":"古宅前方只剩牆基的空地，據官方資料就是當年種下通樑古榕那戶人家的舊居。","photoSpot":"從保安宮前望向古宅與古榕","visitMin":15,"openNote":"位於白沙鄉通梁村、通樑保安宮旁，私人住宅，目前不開放，請在外觀參觀、勿擅入私人住宅。鄰近澎湖跨海大橋白沙端，可順遊通樑古榕。從馬公經中正橋、永安橋開車或騎機車可達白沙，也可搭澎湖縣公車前往。","dialogue":[{"who":"R","text":"Allan，這棵榕樹的氣根好多，整片像綠色的天花板！"},{"who":"A","text":"這就是通樑古榕。不過今天的主角在對面，隔一條路的通梁林家古宅。"},{"who":"R","text":"要跟古榕搶鋒頭，這間房子壓力好大喔。"},{"who":"A","text":"它可是有實力的，史料研判至少在清乾隆33年，也就是1768年以前就蓋好了。"},{"who":"R","text":"那林家的祖先當年是從哪裡搬來的？"},{"who":"A","text":"開基祖林四原籍福建漳浦，1643年來到澎湖。家裡還留著很多契約跟族譜，證據滿滿。"},{"who":"R","text":"古人也會保留收據，比我還會記帳！"},{"who":"A","text":"屋子三開間，中間大廳拜神祭祖，兩邊房間睡通舖。這是私人住宅，我們在外面看就好。"},{"who":"R","text":"那我去找找，古宅前面那塊只剩牆基的空地在哪裡！"}],"clues":["我隔著一條路，和一棵很有名的老榕樹當鄰居","我的主人家族留下很多契約與族譜","我是白沙鄉通梁村東甲二百多年的林氏老厝"],"quiz":[{"q":"依史料研判，這座古宅至少在何時以前就已創建？","options":["清康熙22年","清乾隆33年","清道光23年","日治明治43年"],"answer":1,"explain":"依史料研判至少在清乾隆33年（1768）以前。"},{"q":"古宅隔著道路與哪一處著名景點相鄰？","options":["二崁聚落","西嶼燈塔","通樑古榕","吉貝沙尾"],"answer":2,"explain":"古宅右側隔道路就是通樑保安宮與古榕。"}],"images":[{"file":"通梁林家古宅.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/%E9%80%9A%E6%A2%81%E6%9E%97%E5%AE%B6%E5%8F%A4%E5%AE%85.jpg/960px-%E9%80%9A%E6%A2%81%E6%9E%97%E5%AE%B6%E5%8F%A4%E5%AE%85.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%80%9A%E6%A2%81%E6%9E%97%E5%AE%B6%E5%8F%A4%E5%AE%85.jpg","artist":"Philoschen","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/baisha-tonglianglinjiagu-0.webp","small":"img/baisha-tonglianglinjiagu-0-s.webp"}]},{"id":"huxi-xinjiaguzhai","name":"湖西辛家古宅","short":"湖西辛家古宅","category":"歷史建築","level":"","town":"湖西鄉","types":["宅第"],"lat":23.585864,"lng":119.658702,"address":"澎湖縣湖西鄉湖西村11號","announced":"2009-06-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090608000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-27/ab6277fd-51af-4c87-abc6-0649c6c49c48/53490.jpg","year":1815,"yearText":"約1810年代（清嘉慶年間）","era":"qing","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"舉人祖宅之說被調查翻案的辛家老厝","intro":"湖西辛家古宅位於湖西鄉湖西村，以硓𥑮石砌牆、覆閩式屋瓦，屋頂多為硬山，瓦片採疊三砌法；大厝身前後兩坡落水，依傳統陰陽坡觀念，前坡簷口略高、深度較淺，山牆脊頭多為圓頭形。2009年登錄時，理由是嘉慶18年（1813）癸酉科欽賜舉人辛齊光的祖宅；但2015年的調查研究確認，古宅所有權人的祖先屬於辛瑜所領的大房，而非辛齊光所屬的三房辛瑚派下，辛齊光故居其實在古宅右後方。古宅左側的辛氏家廟據族譜是最早的辛氏宗祠所在，1991年重建。古宅目前閒置。","highlights":["前高後低的陰陽坡屋頂","硓𥑮石牆與疊三砌瓦","左側重建的辛氏家廟"],"funFact":"登錄時說是舉人辛齊光的祖宅，後來調查發現屋主是大房後代，舉人故居在右後方。","photoSpot":"在巷道外拍圓頭脊與前後不等高的屋坡","visitMin":10,"openNote":"位於湖西鄉湖西村，官方資料為不開放，目前閒置，請在外觀參觀、勿擅入。","dialogue":[{"who":"R","text":"Allan，這間古宅的介紹寫著舉人祖宅，好厲害！"},{"who":"A","text":"先別急著拜，這裡有個翻案故事。2009年登錄時，說它是1813年舉人辛齊光的祖宅。"},{"who":"R","text":"翻案？難道這位舉人是冒牌的嗎？"},{"who":"A","text":"舉人是真的，房子主人搞錯了。2015年調查發現屋主是大房辛瑜的後代，辛齊光屬三房。"},{"who":"R","text":"所以是大哥家被當成小弟家，親戚都要分不清了！"},{"who":"A","text":"沒錯，辛齊光的故居其實在古宅右後方，左邊則是1991年重建的辛氏家廟，據族譜是最早的辛氏宗祠所在。"},{"who":"R","text":"那這間房子本身，有什麼地方值得看？"},{"who":"A","text":"看屋頂！前坡簷口比後坡高一點，這是陰陽坡的講究。你從側面拍一張，比比看前後兩邊的高度！"}],"clues":["我曾被認為是一位嘉慶年間舉人的祖宅","2015年的調查發現，我的主人其實是大房的後代","湖西村的咕咾石古厝，左邊有辛氏家廟"],"quiz":[{"q":"2015年調查發現，古宅屋主的祖先屬於哪一房？","options":["三房辛瑚","二房","大房辛瑜","四房"],"answer":2,"explain":"人文調查確定屋主祖先是辛瑜所領的大房。"},{"q":"古宅屋頂前坡較高、後坡較低的作法叫什麼？","options":["陰陽坡","燕尾脊","馬背脊","歇山頂"],"answer":0,"explain":"依傳統陰陽坡觀念，前坡簷高略高於後坡。"}],"images":[{"file":"湖西辛家古宅 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/%E6%B9%96%E8%A5%BF%E8%BE%9B%E5%AE%B6%E5%8F%A4%E5%AE%85_peiiunwu.jpg/960px-%E6%B9%96%E8%A5%BF%E8%BE%9B%E5%AE%B6%E5%8F%A4%E5%AE%85_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%B9%96%E8%A5%BF%E8%BE%9B%E5%AE%B6%E5%8F%A4%E5%AE%85_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/huxi-xinjiaguzhai-0.webp","small":"img/huxi-xinjiaguzhai-0-s.webp"}]},{"id":"magong-wenshishuyuankui","name":"馬公文石書院魁星樓","short":"文石書院魁星樓","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.566691,"lng":119.580193,"address":"澎湖縣馬公市西文里104之7號","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2018-07-11/ee330af6-fdfe-4021-945b-dea91ccc1f38/DSCN4189.jpg","year":1829,"yearText":"1829年（清道光9年）改建","era":"qing","themes":["教育書院","宗教信仰"],"yearUnknown":false,"summary":"官方稱臺灣唯一留有魁星樓的書院","intro":"馬公文石書院魁星樓位於馬公市西文里的澎湖孔廟內。澎湖孔廟的前身是1766年（清乾隆31年）創建的文石書院，日治時期才轉為孔廟。書院創建時就設有魁星樓，1829年（道光9年）改建於書院的巽方，也就是東南方，就是現在這座。1963年孔廟重修時，魁星樓是唯一保留原貌的建築，官方資料稱它也是臺灣唯一留有魁星樓的書院。樓為二層傳統木、磚造建築，平面呈四角形，簷廊下四角各有拱形開口，色彩鮮豔而裝飾樸實；一樓供奉魁星爺，二樓供奉文昌帝君，一、二樓外有狹長廊道與嵌花磚的矮牆。","highlights":["一樓魁星爺、二樓文昌帝君的上下供奉","簷廊四角的拱形開口","嵌有花磚的矮牆與狹長廊道"],"funFact":"1963年澎湖孔廟大整修時，整座書院只有魁星樓被原樣保留下來。","photoSpot":"在孔廟東南角拍二層魁星樓全景","visitMin":20,"openNote":"位於馬公市西文里澎湖孔廟（文石書院）內。依官方資料開放時間9:00–16:00，週一、週二休館；一樓開放民眾參拜，二樓暫不對外開放，以現場公告為準。可從馬公市區騎機車或開車前往。","dialogue":[{"who":"A","text":"考試前要拜誰？阿拉蕾，答案就在這座魁星樓裡。"},{"who":"R","text":"我知道！要拜魁星爺，求考試拿高分，作文不要寫錯字！"},{"who":"A","text":"答對加10分！一樓供奉魁星爺，二樓供奉文昌帝君，一棟樓住了兩位考運大神。"},{"who":"R","text":"那這棟魁星樓已經在這裡站了幾年了？"},{"who":"A","text":"文石書院1766年創建時就有魁星樓，現在這座是1829年改建在東南方的。"},{"who":"R","text":"可是這裡明明叫孔廟，書院後來怎麼變成孔廟了？"},{"who":"A","text":"日治時期書院轉成孔廟，1963年大整修時，魁星樓是唯一保留原貌的建築。"},{"who":"R","text":"整修時只留下它，這麼說它是不是很稀有？"},{"who":"A","text":"官方說它是臺灣唯一還留有魁星樓的書院。去簷廊下數數四個角的拱形開口，順便請魁星爺保佑你！"}],"clues":["我一樓拜魁星爺、二樓拜文昌帝君","1963年整修時，我是唯一保留原貌的建築","澎湖孔廟裡、1829年改建在東南方的二層樓閣"],"quiz":[{"q":"魁星樓的二樓供奉哪一位神明？","options":["魁星爺","孔子","關聖帝君","文昌帝君"],"answer":3,"explain":"一樓供奉魁星爺，二樓供奉文昌帝君。"},{"q":"澎湖孔廟的前身是哪一座書院？","options":["文石書院","海東書院","崇文書院","奎壁書院"],"answer":0,"explain":"澎湖孔廟前身是1766年創建的文石書院。"}],"images":[{"file":"澎湖孔廟：魁星樓 (2) (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/%E6%BE%8E%E6%B9%96%E5%AD%94%E5%BB%9F%EF%BC%9A%E9%AD%81%E6%98%9F%E6%A8%93_%282%29_%28cropped%29.jpg/960px-%E6%BE%8E%E6%B9%96%E5%AD%94%E5%BB%9F%EF%BC%9A%E9%AD%81%E6%98%9F%E6%A8%93_%282%29_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96%E5%AD%94%E5%BB%9F%EF%BC%9A%E9%AD%81%E6%98%9F%E6%A8%93_(2)_(cropped).jpg","artist":"舟集 Boattoad","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-wenshishuyuankui-0.webp","small":"img/magong-wenshishuyuankui-0-s.webp"}]},{"id":"huxi-nanliaoxufanguzhai","name":"南寮許返古宅","short":"南寮許返古宅","category":"歷史建築","level":"","town":"湖西鄉","types":["宅第"],"lat":23.585458,"lng":119.669688,"address":"澎湖縣湖西鄉南寮村111號","announced":"2010-02-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20100211000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1262/photo/南寮許返古宅1.jpg","year":1855,"yearText":"約1850年代（清代）","era":"qing","themes":["咕咾石古厝","宅第家族","宗教信仰"],"yearUnknown":false,"summary":"小法師的老家，鰲魚洩水口與泥塑獅超吸睛","intro":"南寮許返古宅位於湖西鄉南寮村，屋主許返早年在中國大陸習得呂山法派的小法，是南寮保寧宮小法的開基傳人。呂山法派又稱三奶教、夫人教，只做驅凶納吉的紅事科法。古宅裝飾非常豐富，有泥塑、釉上彩與釉下彩的彩繪磁磚、剪黏、彩繪與水泥塑橫窗；大間與庭壁交接處的洩水口做成龍頭鯉身的鰲魚剪黏，門樓為「倒吞砱」形式，左右門柱頂嵌入泥塑石獅，墀頭也有細緻的泥塑獅子。2010年登錄為歷史建築，2018年修復完成，現由澎湖縣政府文化局作為文物展示館開放參觀。","highlights":["龍頭鯉身的鰲魚剪黏洩水口","門柱頂與墀頭的泥塑獅子","彩繪磁磚、剪黏、水泥塑橫窗等多種裝飾"],"funFact":"呂山法派的傳說說，閭山洞門本是30年一開，因碑文被劃了一筆變成3000年，才去掉門字改稱呂山。","photoSpot":"仰拍門柱頂的泥塑獅子與門樓","visitMin":30,"openNote":"位於湖西鄉南寮村，作為文物展示館，週六、週日09:00–12:00、14:00–17:00開放，開放時間請以澎湖縣政府文化局公告為準。可從馬公開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間古厝的屋簷角落有一隻龍頭魚身的怪獸在吐水耶！"},{"who":"A","text":"那是鰲魚洩水口，用剪黏做的。下雨時雨水從牠嘴裡流出來，超有戲。龍頭鯉身，就是鰲魚的招牌造型。"},{"who":"R","text":"誰家這麼講究，連排水孔都要請神獸？"},{"who":"A","text":"屋主許返早年學了呂山法派的小法，是南寮保寧宮小法的開基傳人。這一派又叫三奶教或夫人教。"},{"who":"R","text":"小法是什麼？是小小的、迷你版的法術嗎？"},{"who":"A","text":"是澎湖廟宇的法師傳統，呂山法派只做驅凶納吉的紅事科法，所以家裡的裝飾也很有宗教味，很特別吧。"},{"who":"R","text":"難怪門柱上還蹲著兩隻泥塑獅子在站崗！"},{"who":"A","text":"2018年修好後變成文物展示館。進門前先抬頭，找找墀頭上的泥塑獅子有幾隻！"}],"clues":["我的屋主是村廟小法的開基傳人","我的洩水口是一隻龍頭鯉身的鰲魚","南寮村的古厝，週末開放當文物展示館"],"quiz":[{"q":"古宅的洩水口做成什麼造型？","options":["石獅子","葫蘆","鰲魚","八卦"],"answer":2,"explain":"洩水口是龍頭鯉身的鰲魚剪黏。"},{"q":"屋主許返學習的是哪一個法派？","options":["呂山法派","茅山法派","天師法派","普庵法派"],"answer":0,"explain":"許返習得呂山法派小法，是保寧宮小法開基傳人。"}],"images":[{"file":"南寮許返古宅 peiiunwu (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/%E5%8D%97%E5%AF%AE%E8%A8%B1%E8%BF%94%E5%8F%A4%E5%AE%85_peiiunwu_%28cropped%29.jpg/960px-%E5%8D%97%E5%AF%AE%E8%A8%B1%E8%BF%94%E5%8F%A4%E5%AE%85_peiiunwu_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8D%97%E5%AF%AE%E8%A8%B1%E8%BF%94%E5%8F%A4%E5%AE%85_peiiunwu_(cropped).jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/huxi-nanliaoxufanguzhai-0.webp","small":"img/huxi-nanliaoxufanguzhai-0-s.webp"}]},{"id":"magong-fengguiweihaogu","name":"風櫃尾74號古宅","short":"風櫃尾74號古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.540005,"lng":119.546727,"address":"澎湖縣馬公市風櫃里74號","announced":"2013-08-05","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20130805000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-10/74d9856d-ccc3-4cfe-8ffc-b57c54a0e832/照片.jpg","year":1870,"yearText":"清代庚子年（確切年代待考）","era":"qing","themes":["咕咾石古厝","宅第家族"],"yearUnknown":true,"summary":"地下挖出清代庚子年地磚的四櫸頭古厝","intro":"風櫃尾74號古宅位於馬公市風櫃里，是典型的澎湖四櫸頭民宅。古厝於2010年標售易主，整修時在地下挖出清代庚子年間的地磚，確認是清代留下的老屋。門樓為傳統「師公翹」形式，脊頭作如意頭，半截堵以洗石子加燕紋磚框，框內有萬字不斷線灰刻，亭下三爪水泥窗頂上有泥塑書券圖樣；玄武岩組砌工法甚佳。室內採見光半截作法，大廳安有地磚，左大間仔為廚房，保留傳統雙口灶，通巷門則是清水磚砌的圓拱門。2013年登錄為歷史建築並完成修復。正後方的風櫃962地號古宅原為同族兄弟親屬所建，目前尚未修復開放。","highlights":["師公翹門樓與如意頭脊頭","萬字不斷線灰刻與泥塑書券","清水磚砌圓拱通巷門與雙口灶"],"funFact":"整修時從地底挖出清代庚子年間的地磚，才確認這間古厝是清代留下來的老屋。","photoSpot":"在門口埕拍師公翹門樓","visitMin":25,"openNote":"位於馬公市風櫃里。官方資料標示每週六、日上午8時至12時、下午1時至5時開放，實際以現場公告為準；其餘時間請在外觀參觀，勿擅入私人住宅。後方為不開放的風櫃962地號古宅，可順遊風櫃尾荷蘭城堡。","dialogue":[{"who":"A","text":"阿拉蕾，風櫃這一帶風很大，先到74號古宅的門口埕避避風吧。"},{"who":"R","text":"好！這個門樓兩邊高高翹起來，好像在熱情地跟我們揮手。"},{"who":"A","text":"那叫師公翹門樓，脊頭還做成如意頭，整個門面就是一句吉祥話。"},{"who":"R","text":"這間房子看起來很有年紀，它到底有多老啊？"},{"who":"A","text":"整修時在地底下挖出清代庚子年間的地磚，才確認它是清代的老房子。"},{"who":"R","text":"挖地基挖出自己的出生證明，這也太剛好了吧，根本是天意！"},{"who":"A","text":"屋裡還保留傳統雙口灶，可以同時煮飯又燒菜，古早廚房效率很高。"},{"who":"R","text":"那後面緊貼著的那一間，也是它的家人嗎？"},{"who":"A","text":"對，後面是兄弟親屬蓋的962地號古宅。請你找到清水磚砌的圓拱通巷門，從拱門往外拍一張！"}],"clues":["我整修時從地底挖出清代庚子年間的地磚","我的門樓是師公翹，脊頭是如意頭","風櫃里已修復開放、後方還有兄弟厝的四櫸頭古厝"],"quiz":[{"q":"這座古宅的門樓屬於哪一種傳統形式？","options":["八卦頭","牌樓式","師公翹","馬背式"],"answer":2,"explain":"門樓為傳統師公翹形式，脊頭為如意頭。"},{"q":"古宅左大間仔的廚房保留了什麼設施？","options":["傳統雙口灶","日式浴缸","手壓抽水機","石臼磨坊"],"answer":0,"explain":"左大間仔為廚房，內有傳統雙口灶。"}],"images":[]},{"id":"magong-fengguidihaoguzhai","name":"風櫃962地號古宅","short":"風櫃962地號古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.540005,"lng":119.546727,"address":"澎湖縣馬公市風櫃里74號（歷史建築風櫃尾74號古宅）後方之傳統建築。","announced":"2016-06-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160628000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/132524/photo/風櫃962地號古宅代表圖像.jpg","year":1880,"yearText":"清領時期（確切年代待考）","era":"qing","themes":["咕咾石古厝","宅第家族"],"yearUnknown":true,"summary":"74號古宅後方、尚待修復的清代兄弟厝","intro":"風櫃962地號古宅位於馬公市風櫃里，就在歷史建築風櫃尾74號古宅的正後方，兩棟彼此緊鄰，官方座標也相同。官方資料指出它是清領時期建築，與前方已修復的74號古宅原為兄弟親屬所建，呈現同一族群建築成長、親族共同生活的紋理。古宅為澎湖早期四櫸頭民宅的典型作法，屬傳統合院形制，基地格局完整，門口埕腹地完整，門樓比例優美，牆體與秀面也保存完整。大廳同樣安有地契，確切年代要等修復時取出才能確定。和已修復、定時開放的74號古宅不同，這棟目前尚未開放。","highlights":["完整的門口埕腹地","比例優美的門樓","保存完整的牆體與秀面"],"funFact":"大廳裡的安地契要等修復時取出來，才能確定這棟古厝到底幾歲。","photoSpot":"從巷道遠拍門樓，勿進入私人土地","visitMin":10,"openNote":"位於馬公市風櫃里，在風櫃尾74號古宅後方。官方資料標示不開放，請在巷道外觀欣賞，勿擅入私人土地與住宅。風櫃一帶可騎機車或開車前往，可順遊風櫃尾荷蘭城堡。","dialogue":[{"who":"R","text":"Allan，我們剛看過風櫃尾74號古宅，怎麼後面還有一間？"},{"who":"A","text":"這就是風櫃962地號古宅，它和前面那間原本是兄弟親屬蓋的，前後排在一起。"},{"who":"R","text":"哥哥住前面、弟弟住後面，吵架了還可以隔著牆喊話！"},{"who":"A","text":"哈哈，這就是官方說的親族共同生活紋理。它是清領時期的四櫸頭民宅，門樓比例很優美。"},{"who":"R","text":"那這棟清代古厝，到底已經幾歲了呢？"},{"who":"A","text":"大廳裡安有地契，要等修復時取出來才知道，所以年齡目前還是個謎。"},{"who":"R","text":"好像一個還沒拆開的生日禮物！那我們可以進去看嗎？"},{"who":"A","text":"不行喔，目前不開放，也是私人土地，我們只能在巷子裡遠遠欣賞。"},{"who":"R","text":"那我要比一比前後兩棟的門樓，看看哪一棟的門口埕比較寬！"}],"clues":["我大廳裡的安地契還沒取出，年齡是個謎","我和前方的古厝原是兄弟親屬所建","風櫃里74號古宅正後方、尚未開放的清代四櫸頭民宅"],"quiz":[{"q":"這棟古宅和前方74號古宅是什麼關係？","options":["同一座廟的廂房","兄弟親屬所建","日治時期的宿舍","同一位匠師的作品展示"],"answer":1,"explain":"官方說明兩棟原為兄弟親屬所建，具親族生活紋理。"},{"q":"要怎樣才能確定這棟古宅的年代？","options":["看門牌號碼","量牆壁厚度","查日治戶口簿","修復時取出安地契"],"answer":3,"explain":"大廳安有地契，要待修復時取出才知年代。"}],"images":[]},{"id":"magong-wudeqiweixiangde","name":"馬公武德騎尉項得生古宅","short":"項得生古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.564606,"lng":119.564488,"address":"澎湖縣馬公市\t中央里中央街1巷4號","announced":"2016-04-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160414000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/132468/photo/馬公武德騎尉項得生古宅.JPG","year":1880,"yearText":"清領時期（確切年代待考）","era":"qing","themes":["咕咾石古厝","宅第家族"],"yearUnknown":true,"summary":"中央街區唯一原貌尚存的清代街屋","intro":"馬公武德騎尉項得生古宅位於馬公市中央里中央街一帶，是中央里街區僅存、原貌仍在的清領時期街屋。雖然是街屋，卻以合院概念佈局，前後落之間夾著天井。牆體高達兩層，為了結構安全，構築方式很有特色：轉角以汕石為材，中間夾紅磚定平；外牆則是硓𥑮石、紅磚與石材交錯的磚石共砌，並以紅磚為角柱，展現澎湖島嶼獨特的建材風貌，具技術史價值。2016年登錄為歷史建築，確切建造年代官方資料未載。附近的四眼井、施公祠及萬軍井、乾益堂中藥行都在步行範圍內，可串成中央老街散步路線。","highlights":["轉角汕石間夾紅磚定平的牆體","咕咾石、紅磚、石材交錯的磚石共砌","街屋裡以合院概念佈局的天井"],"funFact":"牆體高達兩層，師傅在轉角用汕石，中間夾紅磚來定平，就是為了結構安全。","photoSpot":"在巷口拍咕咾石與紅磚交錯的外牆","visitMin":10,"openNote":"位於馬公市中央里中央街一帶的老街巷弄內。官方資料為外貌參觀，請勿擅入、保持安靜。可與四眼井、施公祠及萬軍井、乾益堂中藥行一起步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，中央老街逛到這裡，先停一下，看看這棟不起眼的老街屋。"},{"who":"R","text":"它看起來舊舊的，夾在巷子裡，有什麼了不起？"},{"who":"A","text":"了不起在它是中央里街區唯一原貌還在的清領時期街屋，叫做武德騎尉項得生古宅。"},{"who":"R","text":"名字好長，聽起來像武俠小說裡會飛簷走壁的大俠！"},{"who":"A","text":"武功沒有，建築功夫倒是一流。牆體高兩層，轉角用汕石，中間夾紅磚來定平。"},{"who":"R","text":"用一層層紅磚當水平儀，古早的師傅真的好聰明！"},{"who":"A","text":"外牆還是咕咾石、紅磚和石材交錯砌成，像一塊澎湖口味的千層蛋糕。"},{"who":"R","text":"那它的裡面，也是一條直直長長的街屋嗎？"},{"who":"A","text":"雖然是街屋，卻用合院概念，前後落夾著天井。請你在外面找出牆上的紅磚夾層！"}],"clues":["我的轉角用汕石，中間夾紅磚定平","我是中央里街區唯一原貌尚存的清代街屋","中央老街裡名字帶著清代武職封銜的古厝"],"quiz":[{"q":"這棟古宅牆體轉角使用什麼石材？","options":["花崗岩","汕石","大理石","觀音山石"],"answer":1,"explain":"轉角以汕石為材，其間夾紅磚定平。"},{"q":"這棟街屋的佈局有什麼特色？","options":["一條龍單排","三層樓洋樓","以合院概念夾天井","前店後廠"],"answer":2,"explain":"雖是街屋，但以合院概念佈局，前後落間夾天井。"}],"images":[{"file":"澎湖馬公武德騎尉項得生古宅 01 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/%E6%BE%8E%E6%B9%96%E9%A6%AC%E5%85%AC%E6%AD%A6%E5%BE%B7%E9%A8%8E%E5%B0%89%E9%A0%85%E5%BE%97%E7%94%9F%E5%8F%A4%E5%AE%85_01_%28cropped%29.jpg/960px-%E6%BE%8E%E6%B9%96%E9%A6%AC%E5%85%AC%E6%AD%A6%E5%BE%B7%E9%A8%8E%E5%B0%89%E9%A0%85%E5%BE%97%E7%94%9F%E5%8F%A4%E5%AE%85_01_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96%E9%A6%AC%E5%85%AC%E6%AD%A6%E5%BE%B7%E9%A8%8E%E5%B0%89%E9%A0%85%E5%BE%97%E7%94%9F%E5%8F%A4%E5%AE%85_01_(cropped).jpg","artist":"雲角","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-wudeqiweixiangde-0.webp","small":"img/magong-wudeqiweixiangde-0-s.webp"}]},{"id":"wangan-xianxuzhenguzhai","name":"西安許真古宅","short":"許真古宅","category":"歷史建築","level":"","town":"望安鄉","types":["宅第"],"lat":23.358605,"lng":119.497208,"address":"澎湖縣望安鄉西安村8鄰57號","announced":"2014-05-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140522000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-27/07a40f7f-34e0-4ea4-9b34-3553760450cb/53492.jpg","year":1880,"yearText":"1880年（清光緒6年）","era":"qing","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"望安帆船商家族的精美咕咾石古厝","intro":"西安許真古宅位於望安鄉望安島西安村，創建於1880年（清光緒6年）。許氏家族在望安的移民開發中地位重要，許真家族在西安村以帆船貿易為業，古宅也曾接待有商業往來的商販住宿，見證海洋貿易拓墾的歷史。古宅為格局完整的「一落四櫸頭」，九成以上建材是咕咾石，只在門豎、窗框、門臼等處用玄武岩，並以紅磚走線框邊；中亭南面半截牆以刨平、圓如滿月的咕咾石砌成，相當罕見。屋頂排水有魚吐水泥塑，門樓有木雕劍獅，屋內還有大型陶缸、甕與木傢俱等文物。2014年登錄為歷史建築，目前閒置。","highlights":["刨平如滿月的咕咾石半截牆堵","門樓上風化的木雕劍獅","屋頂排水口的魚吐水泥塑"],"funFact":"古宅九成以上建材是咕咾石，連厝角、圓拱都用咕咾石，玄武岩只用在門窗框等少數地方。","photoSpot":"拍咕咾石牆面與紅磚框線","visitMin":15,"openNote":"位於望安鄉望安島西安村，目前不開放、建物閒置，請在外觀參觀、勿擅入。望安需從馬公南海遊客服務中心搭船，船程約40到50分鐘。冬季東北季風期（約10月到隔年3月）風浪大，船班減少、常停航，出發前請先查詢船班。","dialogue":[{"who":"A","text":"搭船到望安，阿拉蕾，今天帶你看一間幾乎整棟用咕咾石蓋的老房子。"},{"who":"R","text":"咕咾石就是珊瑚礁石嘛！整棟都是，那不是很浪費海洋的寶貝？"},{"who":"A","text":"那是古早就地取材的方式，現在可不能隨便採了。這間許真古宅九成以上都是咕咾石。"},{"who":"R","text":"能蓋這種房子，主人一定很有錢吧？"},{"who":"A","text":"許真家族以帆船貿易為業，1880年蓋了這間房子，還常接待做生意的商販來住。"},{"who":"R","text":"古早版的商務旅館！那有什麼特別的地方？"},{"who":"A","text":"中亭南面有一段半截牆，咕咾石刨得平平圓圓，像一輪滿月，在澎湖很少見。"},{"who":"R","text":"滿月牆！好浪漫，比你的光頭還要圓嗎？"},{"who":"A","text":"嘿，我的光頭可是無可取代的！你去門樓找找那隻木雕劍獅，看牠被海風吹成什麼模樣。"}],"clues":["我的主人家族在望安經營帆船貿易","我有一段刨平如滿月的咕咾石半截牆","我在望安鄉西安村，1880年創建"],"quiz":[{"q":"許真家族在西安村以什麼行業為業？","options":["帆船貿易","燒製石灰","經營鹽田","打石造屋"],"answer":0,"explain":"許真家族在西安村以商帆貿易為業。"},{"q":"許真古宅最主要的建材是什麼？","options":["玄武岩","紅磚","咕咾石","花崗石"],"answer":2,"explain":"約九成以上採用咕咾石為主要建材。"}],"images":[]},{"id":"magong-dongweilvdingsigu","name":"東衛呂丁思古宅","short":"呂丁思古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.568316,"lng":119.602335,"address":"澎湖縣馬公市東衛里69號","announced":"2009-05-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090512000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2300/photo/6930ac18-fda0-4932-a717-d4336699f0af.jpg","year":1885,"yearText":"約清光緒年間","era":"qing","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"保有師公翹門樓原形的百年古厝","intro":"東衛呂丁思古宅位於馬公市東衛里，約建於清光緒年間，已逾百年，2009年登錄為歷史建築。東衛呂氏宗族由福建金門遷來澎湖定居，古宅材料多由福建運來，以福建青花石及「壓艙石」為基礎，再以澎湖本地硓𥑮石砌牆。它屬於澎湖早期四櫸頭民宅的典型作法，門樓線條簡潔，被視為澎湖早期「師公翹」門樓形式的原形；玄武岩窗櫺極具地方特色，東牆留有少見的三角形出水口。古宅牆面曾有嚴重的灰泥剝落與鹽化，2010年獲縣府補助進行修復。","highlights":["線條簡潔、被視為師公翹原形的門樓","具地方特色的玄武岩窗櫺","東牆少見的三角形出水口"],"funFact":"古宅地基用的是壓艙石，這些石頭原本是讓帆船穩住重心的，到了澎湖變成房子的腳。","photoSpot":"在門樓前拍簡潔的門樓線條","visitMin":15,"openNote":"位於馬公市東衛里，官方資料記載每週六、日14:00至18:00開放；其他時間請在外觀參觀，勿擅入私人住宅、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，師公翹是什麼？聽起來像師公在翹腳喝茶。"},{"who":"A","text":"畫面很生動！它其實是澎湖早期的一種門樓形式，而呂丁思古宅的門樓，被認為是它的原形。"},{"who":"R","text":"原形？所以它算是門樓界的初代機？"},{"who":"A","text":"可以這麼說。門樓線條很簡潔，沒有花俏裝飾，卻是後來同類門樓的老前輩。"},{"who":"R","text":"那這間古厝大概是什麼時候蓋的？"},{"who":"A","text":"大約清光緒年間，已經超過百年。東衛呂氏從金門遷來，很多材料也從福建運過來。"},{"who":"R","text":"從那麼遠搬材料，難怪房子看起來特別有份量。"},{"who":"A","text":"地基用福建青花石和壓艙石，牆再用澎湖的咕咾石，窗櫺則是玄武岩，很有地方味。"},{"who":"R","text":"那我繞到東邊牆面，找找那個少見的三角形出水口！"}],"clues":["我的門樓被認為是師公翹形式的原形","我東邊的牆上有個少見的三角形出水口","東衛呂氏從金門遷來後蓋的光緒年間古厝"],"quiz":[{"q":"呂丁思古宅的門樓被視為哪一種門樓形式的原形？","options":["師公翹","燕尾脊","馬背脊","唐博風"],"answer":0,"explain":"門樓線條簡潔，為澎湖早期「師公翹」門樓的原形。"},{"q":"古宅東牆有什麼少見的設施？","options":["圓形槍眼","磚雕八卦窗","石刻門神","三角形出水口"],"answer":3,"explain":"東牆留有三角形出水口，為少見的古厝設施。"}],"images":[{"file":"東衛呂丁思古宅 peiiunwu (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/%E6%9D%B1%E8%A1%9B%E5%91%82%E4%B8%81%E6%80%9D%E5%8F%A4%E5%AE%85_peiiunwu_%28cropped%29.jpg/960px-%E6%9D%B1%E8%A1%9B%E5%91%82%E4%B8%81%E6%80%9D%E5%8F%A4%E5%AE%85_peiiunwu_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9D%B1%E8%A1%9B%E5%91%82%E4%B8%81%E6%80%9D%E5%8F%A4%E5%AE%85_peiiunwu_(cropped).jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-dongweilvdingsigu-0.webp","small":"img/magong-dongweilvdingsigu-0-s.webp"}]},{"id":"huxi-xujiadihaoguzhai","name":"許家403地號古宅","short":"許家403地號古宅","category":"歷史建築","level":"","town":"湖西鄉","types":["宅第"],"lat":23.587267,"lng":119.607218,"address":"澎湖縣湖西鄉許家村港仔尾37號右側之傳統建築","announced":"2016-04-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160414000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-11/39a3ca1a-71ef-4392-8b3f-210df8ff62e6/圖像.jpg","year":1896,"yearText":"約19世紀末（登錄時約120年歷史）","era":"japan","themes":["咕咾石古厝"],"yearUnknown":false,"summary":"沒蓋完的右邊，透露分年蓋房的故事","intro":"許家403地號古宅位於湖西鄉許家村港仔尾一帶，2016年登錄為歷史建築，當時已有約120年歷史。它是硓𥑮石造的一落二櫸頭加左護龍，格局少見地不對稱：右邊的間仔沒有蓋，只在右房前方加建一座草坡頂的小屋，而且和大厝身不是同一時期興建。這種「分年興建」是澎湖居民依經濟能力逐步擴建房屋的典型例子，也見證許家村的發展。牆面半截堵以汕石和玄武岩組砌，作工精細，窗櫺則用水泥仿木作，十分有特色。","highlights":["少見的不對稱一落二櫸頭加左護龍格局","汕石與玄武岩組砌的半截堵","水泥做的仿木窗櫺"],"funFact":"名字裡的403不是門牌號碼，而是土地地號，登錄時就用地籍編號來稱呼它。","photoSpot":"從正面拍左右不對稱的屋身","visitMin":10,"openNote":"位於湖西鄉許家村港仔尾一帶，官方資料為不開放，屬私人古厝，請在外觀參觀、勿擅入私人住宅。","dialogue":[{"who":"R","text":"Allan，這間房子怎麼左邊長、右邊短，是不是蓋到一半錢花完了？"},{"who":"A","text":"你說對一半！它是一落二櫸頭加左護龍，右邊的間仔真的沒蓋，只在前面加了一間草坡頂小屋。"},{"who":"R","text":"那這樣不就很像只剪了一邊的瀏海？"},{"who":"A","text":"哈哈，可以這樣記。古早澎湖人常常有錢再蓋，分好幾年慢慢擴建，這間就是活教材，2016年登錄時已有約120年歷史。"},{"who":"R","text":"分期付款蓋房子，古人也這麼精打細算！"},{"who":"A","text":"牆面也很講究，下半截用汕石和玄武岩組砌，窗櫺是用水泥做成木頭的樣子。"},{"who":"R","text":"水泥假裝成木頭，這是房子界的變裝秀耶！"},{"who":"A","text":"這是私人古厝，請在外面欣賞。站在正面數一數，左右兩邊各有幾間房，對不對稱！"}],"clues":["我的名字裡有一個土地編號","我的右邊間仔沒蓋，只有一間草坡頂小屋","許家村的不對稱咕咾石古厝，約有120年歷史"],"quiz":[{"q":"這間古宅的格局有什麼特別？","options":["有三層樓","左右不對稱","全用紅磚","沒有屋頂"],"answer":1,"explain":"一落二櫸頭加左護龍，右間仔未建，形成不對稱。"},{"q":"古宅的窗櫺用什麼材料仿木作？","options":["鐵件","陶瓷","竹子","水泥"],"answer":3,"explain":"窗櫺以水泥仿木作，極具特色。"}],"images":[]},{"id":"baisha-mudouyudengta","name":"目斗嶼燈塔","short":"目斗嶼燈塔","category":"歷史建築","level":"","town":"白沙鄉","types":["其他設施"],"lat":23.786315,"lng":119.600417,"address":"澎湖縣白沙鄉吉貝村186號","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-26/10936e75-14af-4a93-b485-3d5ccf08ec93/DSC_0549.jpg","year":1899,"yearText":"1899年（明治32年）動工，1902年完工","era":"japan","themes":["燈塔航運"],"yearUnknown":false,"summary":"臺灣塔身最高的黑白條紋鑄鐵燈塔","intro":"目斗嶼燈塔位於白沙鄉吉貝嶼北方外海的目斗嶼，是澎湖群島最北端的燈塔。這一帶珊瑚礁遍布、海況險惡，日治時期為了航行安全，於1899年（明治32年）動工、1902年完工，最初稱為「北島燈台」。燈塔塔高39.9公尺、燈高49公尺，塔身為圓形銑鐵構造，外觀黑白相間，白天也很醒目；塔基為磚造，基座分為三層，內有儲水槽，塔內以旋轉樓梯登頂。官方說明它是臺灣塔身最高的燈塔，也是遠東最高的銑鐵製燈塔，反映澎湖北海航路的險惡與重要。二戰期間曾遭空襲損壞，戰後修復，2003年登錄為歷史建築。","highlights":["黑白相間橫條紋的圓形銑鐵塔身","塔高39.9公尺，臺灣塔身最高的燈塔","從跳島船上遠眺孤島上的燈塔身影"],"funFact":"孤島沒有自來水，燈塔基座裡設有儲水槽，據記載是收集燈塔與宿舍屋頂的雨水來用。","photoSpot":"在船上用望遠鏡頭拍黑白塔身與海面","visitMin":15,"openNote":"位於白沙鄉吉貝嶼北方外海的目斗嶼，島上無人居住、沒有一般交通船，燈塔也不開放參觀，一般民眾無法自行登島。可參加吉貝一帶的跳島行程從船上遠眺；吉貝需從白沙赤崁的北海遊客服務中心搭船，船程約20分鐘。冬季東北季風期（約10月到隔年3月）風浪大，船班減少、常停航，出發前請先查詢船班。","dialogue":[{"who":"R","text":"Allan，海平面上那根黑白條紋的柱子是什麼？好像一支超大的理髮店招牌！"},{"who":"A","text":"哈哈，那是目斗嶼燈塔，澎湖最北邊的燈塔，塔高39點9公尺，是臺灣塔身最高的燈塔。"},{"who":"R","text":"為什麼要漆成黑白條紋？全部漆白色不是比較乾淨嗎？"},{"who":"A","text":"黑白相間在白天比較醒目，讓船隻遠遠就看得到。這一帶珊瑚礁很多，以前常發生船難。"},{"who":"R","text":"原來是在海上當交通警察！那它是什麼時候開始站崗的？"},{"who":"A","text":"日治時期1899年動工，1902年完工。塔身用銑鐵打造，官方說它是遠東最高的銑鐵燈塔。"},{"who":"R","text":"那我們可以上去爬塔裡的旋轉樓梯嗎？"},{"who":"A","text":"可惜不行，目斗嶼沒有交通船，也不開放登島，只能搭跳島行程的船，從海上遠遠欣賞。"},{"who":"R","text":"好吧，那我在船上數數看，塔身到底有幾條黑色橫紋！"}],"clues":["我站在無人小島上，官方說我是遠東最高的銑鐵燈塔","我穿著黑白條紋外衣，日治時期完工","我在吉貝北方外海，是臺灣塔身最高的燈塔"],"quiz":[{"q":"目斗嶼燈塔的塔身是用什麼材料打造？","options":["圓形銑鐵","鋼筋混凝土","花崗石","清水紅磚"],"answer":0,"explain":"塔身為圓形銑鐵構造，外觀黑白相間。"},{"q":"一般遊客要怎麼欣賞目斗嶼燈塔？","options":["從跳島船上遠眺","搭交通船登島","走潮間帶過去","從吉貝騎車前往"],"answer":0,"explain":"目斗嶼沒有一般交通船，多從跳島船上遠眺。"}],"images":[{"file":"目斗嶼燈塔 01.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/%E7%9B%AE%E6%96%97%E5%B6%BC%E7%87%88%E5%A1%94_01.jpg/960px-%E7%9B%AE%E6%96%97%E5%B6%BC%E7%87%88%E5%A1%94_01.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%9B%AE%E6%96%97%E5%B6%BC%E7%87%88%E5%A1%94_01.jpg","artist":"Mimicat1531","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/baisha-mudouyudengta-0.webp","small":"img/baisha-mudouyudengta-0-s.webp"}]},{"id":"magong-suogangxuzuqugu","name":"鎖港許祖取古宅","short":"鎖港許祖取古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.524948,"lng":119.600606,"address":"澎湖縣馬公市鎖港里1186號","announced":"2010-04-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20100408000002","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2296/photo/b0aa33c9-0e48-4cb2-bd44-897f1ad7df76.jpg","year":1900,"yearText":"年代不詳","era":"unknown","themes":["咕咾石古厝","宅第家族"],"yearUnknown":true,"summary":"八卦頭門樓與古鼎形磁磚楹聯的四櫸頭古厝","intro":"鎖港許祖取古宅位於馬公市鎖港里，由許氏家族興建。確切年代不詳，官方說明為年代久遠，從磁磚對聯可看出日治時期曾用心整修，用料講究，是澎湖早期經濟實力較佳人家的住宅。它是澎湖典型的四櫸頭民宅，入口為「八卦頭」門樓，泥塑作工細緻、比例優美，內側加磚坪並設中亭，屋面三種作法俱備，反映民宅因應產業需求的調整。大廳彩繪磁磚楹聯以古鼎形變體字寫「春暖觀龍變，秋高聽鹿鳴」，兩側另有歷史人物與二十四孝題材；興建時行「安厝」，神龕下埋有安地磚。與相鄰、有防空壕的許監督古宅相比，這裡以八卦樓門面與磁磚藝術見長。","highlights":["八卦頭門樓與細緻泥塑","古鼎形變體字的彩繪磁磚楹聯","可從屋內外取水的泥塑水缸"],"funFact":"興建時舉行「安厝」，在神龕八仙桌下靠後壁處埋了「安地磚」，官方說這種見證非常少見。","photoSpot":"在門口埕拍八卦頭門樓全景","visitMin":20,"openNote":"位於馬公市鎖港里，與許監督古宅相鄰。官方資料標示每週二上午9時至下午4時開放，實際以現場公告為準；其餘時間請在外觀參觀，勿擅入私人住宅。可騎機車或開車前往，順遊鎖港南北石塔。","dialogue":[{"who":"R","text":"Allan，看完許監督古宅，隔壁這間許祖取古宅的門口怎麼尖尖的？"},{"who":"A","text":"那叫八卦頭，是澎湖四櫸頭民宅的一種入口門樓，泥塑做得很細，比例也漂亮。"},{"who":"R","text":"四櫸頭？聽起來像四個人在舉頭望明月？"},{"who":"A","text":"跟月亮沒關係啦！櫸頭是廳堂前面左右的廂房，四間圍出中間的深井。"},{"who":"R","text":"好啦好啦，那大廳裡有什麼寶貝？"},{"who":"A","text":"有一對彩繪磁磚楹聯，用古鼎形變體字寫著春暖觀龍變，秋高聽鹿鳴，旁邊還有二十四孝圖案。"},{"who":"R","text":"字寫得像古鼎，這是書法界的變形金剛吧！"},{"who":"A","text":"更特別的是，蓋房子時舉行安厝儀式，在神龕下埋了安地磚，官方說非常少見。"},{"who":"R","text":"等開放日進大廳，我要用眼睛找出楹聯裡哪一個字最像一只鼎！"}],"clues":["我的大廳楹聯用古鼎形變體字寫成","我的神龕下埋著安厝時的安地磚","鎖港里有八卦頭門樓的四櫸頭許家古厝"],"quiz":[{"q":"這座古宅的入口門樓屬於哪一種形式？","options":["師公翹","八卦頭","燕尾脊","馬背"],"answer":1,"explain":"入口為八卦頭，是四櫸頭民宅的八卦樓類型。"},{"q":"大廳磁磚楹聯的字體有什麼特色？","options":["古鼎形變體字","篆書刻字","金漆楷書","英文花體"],"answer":0,"explain":"楹聯「春暖觀龍變，秋高聽鹿鳴」採古鼎形變體字。"}],"images":[{"file":"鎖港許祖取古宅 01 立面 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/%E9%8E%96%E6%B8%AF%E8%A8%B1%E7%A5%96%E5%8F%96%E5%8F%A4%E5%AE%85_01_%E7%AB%8B%E9%9D%A2_%28cropped%29.jpg/960px-%E9%8E%96%E6%B8%AF%E8%A8%B1%E7%A5%96%E5%8F%96%E5%8F%A4%E5%AE%85_01_%E7%AB%8B%E9%9D%A2_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%8E%96%E6%B8%AF%E8%A8%B1%E7%A5%96%E5%8F%96%E5%8F%A4%E5%AE%85_01_%E7%AB%8B%E9%9D%A2_(cropped).jpg","artist":"雲角","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-suogangxuzuqugu-0.webp","small":"img/magong-suogangxuzuqugu-0-s.webp"}]},{"id":"huxi-chenggongxiaoke","name":"成功蕭克讓古宅","short":"蕭克讓古宅","category":"歷史建築","level":"","town":"湖西鄉","types":["宅第"],"lat":23.577974,"lng":119.62163,"address":"澎湖縣湖西鄉成功村8號","announced":"2019-12-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20200717000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-27/28ac69c5-04df-4378-9d03-9216e6205eed/20240210_132827.jpg","year":1900,"yearText":"年代不詳","era":"unknown","themes":["咕咾石古厝"],"yearUnknown":true,"summary":"有咕咾石擋風牆與水井的傳統合院","intro":"成功蕭克讓古宅位於湖西鄉成功村，2019年登錄為歷史建築。它是澎湖傳統的合院建築，形貌完整，保有傳統古宅的格局；屋脊、門樓與捲簾棚等裝飾保存得還不錯。最有特色的是建築北側以硓𥑮石（咕咾石）砌成的擋風牆和一口水井。澎湖冬季東北季風強勁，古厝常以石牆擋風，這道擋風牆與水井一起，具體呈現了澎湖傳統合院因應海島氣候與生活的樣貌。官方資料沒有記載確切的興建年代，目前不開放入內。","highlights":["建築北側的咕咾石擋風牆","合院旁的老水井","保存尚好的屋脊、門樓與捲簾棚裝飾"],"funFact":"擋風牆特地砌在建築北側，正好迎著冬天的東北季風。","photoSpot":"在巷道外拍門樓與咕咾石牆面紋理","visitMin":10,"openNote":"位於湖西鄉成功村，官方資料為不開放，屬私人古厝，請在外觀參觀、勿擅入私人住宅。","dialogue":[{"who":"A","text":"到成功村了，我們這次不看屋頂，先繞到房子的北邊。"},{"who":"R","text":"北邊有什麼？難道住了一隻北極熊？"},{"who":"A","text":"北極熊沒有，但有一道用咕咾石砌的擋風牆，專門擋冬天的東北季風。"},{"who":"R","text":"澎湖的風真的大到要特別蓋一道牆嗎？"},{"who":"A","text":"東北季風大約從10月吹到隔年3月，風大到騎機車都會被推著走，老房子當然要自備防風盾牌。"},{"who":"R","text":"那牆旁邊那個圓圓的石頭圈，是什麼呀？"},{"who":"A","text":"是一口水井。擋風牆加水井，是澎湖傳統合院生活的標準配備。門樓和捲簾棚的裝飾也保存得不錯。"},{"who":"R","text":"有水有牆，古早生活的基本款都到齊了！"},{"who":"A","text":"這是私人古厝，請在外面看，也別擋到住戶進出。你找找門樓上的屋脊裝飾，拍一張就收工！"}],"clues":["我的北側有一道咕咾石擋風牆","我的合院旁有一口水井，門樓與捲簾棚保存尚好","湖西鄉成功村的傳統合院，2019年登錄歷史建築"],"quiz":[{"q":"古宅北側的擋風牆用什麼石材砌成？","options":["花崗岩","大理石","青斗石","咕咾石"],"answer":3,"explain":"北側擋風牆以硓𥑮石，也就是咕咾石砌成。"},{"q":"古宅北側除了擋風牆，還保存了什麼？","options":["一口水井","一座防空壕","一座灰窯","一座燈塔"],"answer":0,"explain":"北側有咕咾石擋風牆和一口井。"}],"images":[]},{"id":"baisha-xiaochicunlvshilao","name":"白沙小赤村呂石硓古宅","short":"呂石硓古宅","category":"歷史建築","level":"","town":"白沙鄉","types":["宅第"],"lat":23.66029,"lng":119.596114,"address":"澎湖縣白沙鄉小赤村32號","announced":"2013-01-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20130108000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-12-07/06e3b901-4450-40b9-9d46-ee8c4438c40d/P_20191118_095524_vHDR_Auto.jpg","year":1900,"yearText":"年代不詳","era":"unknown","themes":["咕咾石古厝","宅第家族"],"yearUnknown":true,"summary":"藏著張百萬傳說的老門樓古宅","intro":"白沙小赤村呂石硓古宅位於白沙鄉小赤村，官方資料指出它的創建時代早於地方傳說中的「張百萬」時期。宅主呂石硓是具時代背景的地區代表人物，屋後的後壁溝是張百萬前往瓦硐運送貨物的牛車路必經之地，兩人的相關傳說見證了當時的地方歷史。古宅門樓形式完整，可看出澎湖早期門樓的樣貌；前有外埕、水井和菜宅，後有靠山，整個生活場域相當完整。2013年登錄為歷史建築，2019年修復完成。和同村開放參觀的林氏宗祠不同，這裡是私人古厝，確切興建年代不詳。","highlights":["保存完整的早期澎湖門樓","外埕、水井與菜宅俱全的生活場域","屋後張百萬運貨牛車路經過的後壁溝"],"funFact":"屋後的後壁溝，傳說是張百萬往瓦硐運貨時，牛車一定會經過的路。","photoSpot":"在外埕外拍完整的門樓","visitMin":10,"openNote":"位於白沙鄉小赤村，官方資料為不開放，屬私人古厝，請在外觀參觀、勿擅入私人住宅。同村的小赤林氏宗祠有開放時間，可一起安排。","dialogue":[{"who":"A","text":"剛看完林氏宗祠，我們在小赤村再走幾步，來聽一個百萬富翁的傳說。"},{"who":"R","text":"百萬富翁？在哪裡？我要去借錢！"},{"who":"A","text":"來不及了啦，是地方傳說裡的張百萬。這間呂石硓古宅屋後的後壁溝，就是他的牛車往瓦硐運貨的必經之路。"},{"who":"R","text":"所以這裡是百萬富翁的運貨高速公路？"},{"who":"A","text":"可以這樣想像。而且官方資料說，這間古宅蓋得比張百萬的時代還早。"},{"who":"R","text":"那宅主呂石硓，在當時一定也很有名吧？"},{"who":"A","text":"他是當時的地方代表人物。古宅前有外埕、水井和菜宅，後有靠山，生活機能一應俱全。"},{"who":"R","text":"有菜園又有水井，根本是古早版的自給自足套房！"},{"who":"A","text":"這是私人古厝，請在外面看。你站遠一點，把完整的門樓拍下來！"}],"clues":["我的屋後有一條百萬富翁牛車必經的溝路","我的創建時代比張百萬時期還早","小赤村一座門樓完整的私人古宅，宅主名字裡有個石字"],"quiz":[{"q":"傳說張百萬的牛車經過古宅屋後，是要前往哪裡運貨？","options":["瓦硐","吉貝","媽宮","西嶼"],"answer":0,"explain":"後壁溝是張百萬到瓦硐運貨的牛車路必經之地。"},{"q":"呂石硓古宅前方有什麼生活設施？","options":["防空壕與砲台","外埕、水井和菜宅","灰窯與儲水槽","碼頭與燈塔"],"answer":1,"explain":"前有外埕、水井、菜宅，後有靠山，場域完整。"}],"images":[{"file":"小赤崁呂石老古厝.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/%E5%B0%8F%E8%B5%A4%E5%B4%81%E5%91%82%E7%9F%B3%E8%80%81%E5%8F%A4%E5%8E%9D.jpg/960px-%E5%B0%8F%E8%B5%A4%E5%B4%81%E5%91%82%E7%9F%B3%E8%80%81%E5%8F%A4%E5%8E%9D.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%B0%8F%E8%B5%A4%E5%B4%81%E5%91%82%E7%9F%B3%E8%80%81%E5%8F%A4%E5%8E%9D.jpg","artist":"洪玉真","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/baisha-xiaochicunlvshilao-0.webp","small":"img/baisha-xiaochicunlvshilao-0-s.webp"}]},{"id":"magong-pengfangbujianzhu","name":"澎防部建築群","short":"澎防部建築群","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.565391,"lng":119.561743,"address":"澎湖縣馬公市馬公段2652-4地號","announced":"2019-07-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190724000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2019-07-24/58950b4f-59a1-46bf-b5c2-fdae28844501/圖片4.jpg","year":1908,"yearText":"1908年（明治41年）竣工","era":"japan","themes":["軍事遺構","戰爭史蹟"],"yearUnknown":false,"summary":"日治要塞重砲兵營舍，至今仍在軍事營區內","intro":"澎防部建築群位於馬公市的莒光營區內。1895年日軍占領澎湖後，1896年（明治29年）成立澎湖島要塞砲兵大隊，1902年在媽宮設澎湖島要塞司令部，1903年於清代大校場舊址興建新營舍。1904年日俄戰爭期間，澎湖升為戰時編制，戒備東來的波羅的海艦隊，所幸雙方未交火。1907年改稱澎湖島重砲兵大隊，1908年新營舍竣工遷入，就是今天的建築群。戰後由國軍接收，作為陸軍澎湖防衛部隊駐地沿用至今。2019年登錄為歷史建築，營區內有日治紅磚營舍與國軍興建的建物，可看出不同時期的工法，官方特別指出這是日治時期難得的紅磚建築。","highlights":["日治時期少見的紅磚營舍","日軍與國軍不同時期的建築工法並存","要塞司令部與重砲兵大隊兩座營門相連的格局"],"funFact":"1904年日俄戰爭時，澎湖為了東來的波羅的海艦隊嚴陣以待，還運來新式大砲，最後雙方沒有交火。","photoSpot":"營區不開放，請勿拍攝營門與軍事設施","visitMin":10,"openNote":"位於馬公市莒光營區內，目前仍是軍方使用的營區，不對外開放。請勿在營門附近逗留，也不要拍攝營區與軍事設施；可改到附近的媽宮古城、篤行十村認識這段要塞歷史。","dialogue":[{"who":"A","text":"阿拉蕾，前面那道營門請不要靠太近，這裡到現在還是軍事營區喔。"},{"who":"R","text":"好啦，我站遠一點。那我們來這裡要看什麼？"},{"who":"A","text":"營區裡有日治時期的重砲兵營舍，1908年竣工，2019年登錄成歷史建築，叫做澎防部建築群。"},{"who":"R","text":"重砲兵？聽起來砲彈一定很重，搬起來會閃到腰！"},{"who":"A","text":"沒錯，澎湖是日軍的要塞，1904年日俄戰爭時，還為了東來的波羅的海艦隊嚴陣以待。"},{"who":"R","text":"那艦隊後來真的開到澎湖，雙方有打起來嗎？"},{"who":"A","text":"所幸沒有交火，戰爭結束就恢復平時編制，新運來的大砲白白緊張了一場。"},{"who":"R","text":"既然看不到，那這些營舍到底有什麼特別的地方？"},{"who":"A","text":"官方說它們是日治時期難得的紅磚建築。我們不拍營區，改去附近的媽宮古城城牆走一圈，想像當年的要塞防線吧！"}],"clues":["我曾為了東來的波羅的海艦隊嚴陣以待","我是日治時期難得的紅磚營舍，至今仍在營區裡","1908年竣工的重砲兵大隊營舍，戰後成為防衛部隊駐地"],"quiz":[{"q":"1904年哪一場戰爭讓澎湖要塞進入戰時編制？","options":["清法戰爭","甲午戰爭","日俄戰爭","第一次世界大戰"],"answer":2,"explain":"日俄戰爭時，澎湖戒備東來的波羅的海艦隊。"},{"q":"官方特別指出這些營舍是日治時期難得的哪一種建築？","options":["紅磚建築","木造建築","咕咾石建築","鋼骨建築"],"answer":0,"explain":"營舍為日治時期難得的紅磚建築。"}],"images":[]},{"id":"magong-duxingshicun","name":"馬公篤行十村","short":"篤行十村","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.563858,"lng":119.56098,"address":"澎湖縣馬公市馬公市復興里","announced":"2007-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071121000002","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1297/photo/馬公篤行十村1.JPG","year":1911,"yearText":"1911年起（明治44年）興建日式宿舍","era":"japan","themes":["眷村聚落","日式建築"],"yearUnknown":false,"summary":"澎湖僅存的日式宿舍群，也是知名眷村","intro":"馬公篤行十村位於馬公市媽宮古城西側城牆外。明治44年（1911）日方遷移墳地，興建澎湖島重砲兵大隊的將校宿舍，周邊陸續建起要塞司令部等單位的官舍。戰後國軍接收成立馬公要塞司令部，1949年後湧入大量軍眷，一棟常住進兩三戶，形成大雜院景象；1960年起又有被拆遷的軍眷，把日式房舍的樑柱搬來重建家園。2007年住戶全數遷往龍行新城，同年登錄為歷史建築。這裡是澎湖僅存的日式宿舍群，木造雨淋板牆、日式瓦屋頂與戰後石造屋並存，現有潘安邦紀念館、張雨生故事館與文創進駐。","highlights":["日式木造雨淋板宿舍與戰後石造眷舍並存","潘安邦紀念館與張雨生故事館","緊鄰媽宮古城城牆與順承門"],"funFact":"1960年被拆屋的軍眷，把日治時期房舍的樑柱搬到這裡重建，老木頭就這樣搬家續命。","photoSpot":"在巷弄裡拍日式雨淋板牆與古城牆同框","visitMin":60,"openNote":"位於馬公市媽宮古城西側，巷弄可自由散步；資訊服務站週四至週一09:00–12:00、14:00–17:00開放，週二、週三及國定假日休館。各館與店家營業時間不一，請以現場公告為準。","dialogue":[{"who":"R","text":"這裡的房子好有味道，木板牆一片一片疊起來，像千層蛋糕！"},{"who":"A","text":"那叫雨淋板，木板一片片往下疊，雨水就順著流走。1911年日軍在這裡蓋重砲兵大隊的將校宿舍。"},{"who":"R","text":"那怎麼又變成眷村了？日本軍官退租了嗎？"},{"who":"A","text":"戰後國軍接收，1949年以後軍眷變多，一棟房子常擠兩三戶，大家只好自己加蓋。那時候看起來就像一個大雜院。"},{"who":"R","text":"兩三家人擠一間，那吵架的聲音應該很立體環繞吧！"},{"who":"A","text":"哈哈，聽說熱鬧得很。1960年還有被拆屋的軍眷，把日式房子的樑柱搬來這裡重建。"},{"who":"R","text":"樑柱也能搬家，這比搬冰箱還辛苦耶！"},{"who":"A","text":"現在有潘安邦紀念館和張雨生故事館。你去找找哪一面牆是木板、哪一面是石頭砌的！"}],"clues":["1911年因遷墳而興建的砲兵將校宿舍是我的起點","2007年住戶全部搬到龍行新城，我才安靜下來","媽宮古城牆外的眷村，有潘安邦紀念館"],"quiz":[{"q":"篤行十村的住戶在2007年遷往哪裡？","options":["龍行新城","隘門新村","金龜頭營區","西嶼外垵"],"answer":0,"explain":"民國96年（2007）全體住戶遷至龍行新城。"},{"q":"篤行十村的日式宿舍牆面常見哪一種作法？","options":["玄武岩疊砌","木造雨淋板","紅磚清水牆","鐵皮浪板"],"answer":1,"explain":"日式宿舍多為基礎抬高的木造雨淋板建築。"}],"images":[{"file":"Duxingshi Village.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/Duxingshi_Village.jpg/960px-Duxingshi_Village.jpg","page":"https://commons.wikimedia.org/wiki/File:Duxingshi_Village.jpg","artist":"Jgfhhgf942zo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-duxingshicun-0.webp","small":"img/magong-duxingshicun-0-s.webp"}]},{"id":"baisha-jibeilinjiangxigu","name":"吉貝林江西古宅","short":"吉貝林江西古宅","category":"歷史建築","level":"","town":"白沙鄉","types":["宅第"],"lat":23.742771,"lng":119.61259,"address":"澎湖縣白沙鄉吉貝村124號","announced":"2013-03-18","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20130318000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1285/photo/吉貝林江西古宅1.jpg","year":1915,"yearText":"約1910年代（日治時期）","era":"japan","themes":["咕咾石古厝","宅第家族","石滬漁業"],"yearUnknown":false,"summary":"雙心石滬設計者林博的老家，中西合璧","intro":"吉貝林江西古宅位於白沙鄉吉貝嶼的吉貝村，是傳統合院結合西式廊柱騎樓的中西合璧建築：正身是傳統形式，前庭則由林博的長子林江德與兄弟出資興建，給父親居住。林博是吉貝特有滬房的設計者，也是七美雙心石滬的設計者，讓這棟房子有特別的歷史意義。林博有四個兒子，二子林江西生於1935年，年輕時回吉貝定居、教授漢文。古宅曾借給葉茂霖醫師行醫，西側作為醫療事務所。建築以島上的硓𥑮石砌造，是吉貝少見的二落四櫸頭帶後庭格局，窗框鑲嵌細緻，並有平面幾何花紋與浮雕。2013年登錄為歷史建築。","highlights":["傳統合院加西式廊柱的中西合璧立面","七美雙心石滬設計者林博的老家","吉貝少見的二落四櫸頭帶後庭格局"],"funFact":"七美有名的雙心石滬，設計者林博就是從吉貝這間古宅的家族走出來的。","photoSpot":"在巷道外拍西式廊柱與硓𥑮石牆","visitMin":15,"openNote":"位於白沙鄉吉貝嶼吉貝村，需從白沙赤崁的北海遊客服務中心搭船，船程約20分鐘；冬季東北季風期間船班常減少或停航，出發前請查詢船班。官方資料為不開放，屬私人古厝，請在外觀參觀、勿擅入。","dialogue":[{"who":"R","text":"Allan，搭了船來到吉貝，我們不是要去玩水嗎？"},{"who":"A","text":"玩水前先來朝聖一下！這間古宅和七美的雙心石滬有關係喔。它是傳統合院加西式廊柱的中西合璧建築。"},{"who":"R","text":"雙心石滬不是在七美嗎？吉貝離那裡很遠耶！"},{"who":"A","text":"沒錯，但雙心石滬的設計者林博就是吉貝人，他也設計了吉貝特有的滬房，這裡是他家族的古宅。"},{"who":"R","text":"原來浪漫的愛心是吉貝阿伯設計的，太反差萌了！"},{"who":"A","text":"前庭是林博的長子和兄弟們出錢蓋給爸爸住的，有西式廊柱，正身還是傳統合院，很有心意吧。"},{"who":"R","text":"兒子們合資幫爸爸蓋房子，這孝心也是雙心等級！"},{"who":"A","text":"後來還借給醫師行醫。這是私人古厝，請在外面看，你數數正面有幾根廊柱！"}],"clues":["我的家族裡出了一位石滬設計高手","我的前庭有西式廊柱，還曾借給醫師當診所","吉貝島上，雙心石滬設計者林博的老家"],"quiz":[{"q":"林博除了吉貝的滬房，還設計了哪個有名的石滬？","options":["馬公風櫃石滬","望安網垵石滬","七美雙心石滬","西嶼合界石滬"],"answer":2,"explain":"林博是七美雙心石滬的設計者。"},{"q":"古宅曾借給哪一種行業使用？","options":["郵局","醫師行醫","漁會","學校"],"answer":1,"explain":"曾借給葉茂霖醫師行醫，西側作為醫療事務所。"}],"images":[]},{"id":"magong-hechangjiancaixing","name":"馬公合昌建材行","short":"合昌建材行","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.567745,"lng":119.568487,"address":"澎湖縣馬公市新生路14號","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-04/4f05b960-7845-48de-ab26-f55a404509d4/馬公市合昌建材 行.jpg","year":1919,"yearText":"1919年（大正8年）","era":"japan","themes":["名人故居","宅第家族"],"yearUnknown":false,"summary":"浮雕白牆、門上木獅的兩層巴洛克洋樓","intro":"馬公合昌建材行位於馬公市新生路，建於1919年（大正8年），以硓𥑮石與磚塊砌成，是兩層樓的巴洛克式洋樓。這裡是澎湖第7任縣長呂安德的故居，當年呂安德的父親經營合昌建材行，屋內建材因此都用上等檜木。立面為店面形式，由柱基、柱身、水平裝飾帶、矩形分割窗、牛眼窗、橢圓形勳章飾、四葉飾柱頭與山頭等元素構成；白色牆面上有浮雕紋飾，大門上方的2座木雕獅子象徵興旺與財勢。二樓大致維持舊貌，有兩間8疊、兩間6疊的日式臥房與廊道。2003年登錄為歷史建築。","highlights":["大門上方的2座木雕獅子","牛眼窗與橢圓形勳章飾","二樓8疊與6疊的日式臥房"],"funFact":"洋樓外觀是巴洛克式，二樓卻是榻榻米日式臥房，外西內和。","photoSpot":"在新生路對面拍白色浮雕立面與山頭","visitMin":15,"openNote":"位於馬公市新生路，一樓目前為餐飲店面，依官方資料營業時間約11:00–23:00，以店家公告為準；入內請尊重營業場所，也可在外觀欣賞立面。從馬公市區步行可到。","dialogue":[{"who":"R","text":"Allan，這棟白色洋樓好華麗，大門上面怎麼趴著兩隻獅子？"},{"who":"A","text":"那是2座木雕獅子，象徵興旺和財勢，等於在門口貼了一張招財符。"},{"who":"R","text":"能蓋這麼華麗的房子，屋主一定很有錢吧！"},{"who":"A","text":"這是1919年蓋的合昌建材行，也是澎湖第7任縣長呂安德的故居，他父親當年經營建材行。"},{"who":"R","text":"開建材行的人蓋自己的房子，材料一定挑最好的！"},{"who":"A","text":"沒錯，屋內都用上等檜木，外面是巴洛克立面，二樓卻是日式榻榻米臥房。"},{"who":"R","text":"外表像歐洲紳士，裡面藏著日本房間，根本是混血建築嘛！"},{"who":"A","text":"形容得好！牆面上還有浮雕、牛眼窗和橢圓形勳章飾，裝飾一層又一層。"},{"who":"R","text":"那我要站在對街，找出立面上那個圓圓的牛眼窗在哪裡！"}],"clues":["我的大門上方有2座木雕獅子","我是一位澎湖縣長的故居，屋內用上等檜木","新生路上以建材行為名的白色巴洛克洋樓"],"quiz":[{"q":"這棟洋樓是哪一位澎湖縣長的故居？","options":["李玉林","呂安德","謝有溫","王乾同"],"answer":1,"explain":"官方資料說這裡是澎湖第7任縣長呂安德的故居。"},{"q":"大門上方的木雕獅子象徵什麼？","options":["驅邪避煞","金榜題名","興旺與財勢","出海平安"],"answer":2,"explain":"2座木雕獅子是象徵興旺與財勢的圖騰。"}],"images":[]},{"id":"baisha-jiangmeiwuyushugu","name":"講美吳玉樹古宅","short":"吳玉樹古宅","category":"歷史建築","level":"","town":"白沙鄉","types":["宅第"],"lat":23.632756,"lng":119.600071,"address":"澎湖縣白沙鄉講美村35號","announced":"2022-02-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20220607000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-06/7b5eb680-0a52-4413-bcc2-a8be55776896/IMG_1780.jpg","year":1920,"yearText":"年代不詳（屬日治時期改良式作法）","era":"japan","themes":["咕咾石古厝","宅第家族"],"yearUnknown":true,"summary":"打石之鄉講美的精緻咕咾石古厝","intro":"講美吳玉樹古宅位於白沙鄉講美村，2022年登錄為歷史建築。古宅牆面以咕咾石細緻砌築，收頭完整，花台與水缸造型別具特色，大門兩側柱頭、柱腳的收邊工法講究，還有石刻門聯，反映講美地區早期打石業的興盛。格局上，大厝身與亭之間的水槽樑直接架在大廳正面壁上，省略了「簾前」，讓亭直接與大厝身相接，是日治時期的改良式作法；亭的深度比一般四櫸頭民宅大，玄武岩通樑跨距長且一體成型，保存完整。確切興建年代官方資料未載，目前為私人住宅。","highlights":["大門兩側柱頭柱腳的石作收邊與石刻門聯","造型特別的水缸與花台","一體成型、跨距很長的玄武岩通樑"],"funFact":"這間古宅省略了傳統的「簾前」，讓亭直接接上大厝身，是日治時期的改良式作法。","photoSpot":"在巷口拍大門石刻門聯與咕咾石牆","visitMin":15,"openNote":"位於白沙鄉講美村，私人住宅，請在外觀參觀、勿擅入私人住宅，也請勿打擾住戶。從馬公經中正橋、永安橋開車或騎機車可達白沙，也可搭澎湖縣公車前往。","dialogue":[{"who":"A","text":"阿拉蕾，來講美村要先看牆，這裡早年打石業很興盛，石頭功夫特別好。"},{"who":"R","text":"看牆？Allan，你是不是又在找藉口罰站？"},{"who":"A","text":"才不是！你看這面咕咾石牆砌得多細緻，收頭整整齊齊，像是石頭界的西裝筆挺。"},{"who":"R","text":"真的耶，大門兩邊的柱子還有石刻門聯，好有氣質！"},{"who":"A","text":"柱頭柱腳的收邊也很講究。屋裡還有一根玄武岩通樑，跨距很長，而且是一整塊石頭做的。"},{"who":"R","text":"一整塊？那搬進來的時候不就要好多人一起扛？"},{"who":"A","text":"一定很辛苦。更特別的是它省略了傳統的簾前，讓亭直接接上大厝身，是日治時期的改良版。"},{"who":"R","text":"原來古人蓋房子也會改版升級喔！"},{"who":"A","text":"對啊。這裡還有人住，我們在外面欣賞就好。找找門口的石刻門聯，拍一張給我看。"}],"clues":["我的大門兩側有石刻門聯，柱頭柱腳收邊很講究","我省略了簾前，讓亭直接接上大厝身","我在白沙鄉講美村，2022年登錄為歷史建築"],"quiz":[{"q":"古宅細緻的石作，反映講美早期哪種產業興盛？","options":["曬鹽業","打石業","製糖業","釀酒業"],"answer":1,"explain":"石作細緻，反映講美地區早期打石業興盛。"},{"q":"古宅省略「簾前」、讓亭直接接大厝身，屬於哪個時期的作法？","options":["明鄭時期","清代初期","戰後時期","日治時期"],"answer":3,"explain":"官方說明這是日治時期的改良式作法。"}],"images":[]},{"id":"xiyu-waianerpao","name":"外垵餌砲","short":"外垵餌砲","category":"歷史建築","level":"","town":"西嶼鄉","types":["其他設施"],"lat":23.56466,"lng":119.475733,"address":"澎湖縣西嶼鄉外垵村西埔頂","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-10-27/4a0f48d5-c2aa-4b9b-9677-f4cc87208bc1/外垵餌砲.jpg","year":1923,"yearText":"1923年（大正12年）","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"用來欺敵的日治時期假砲","intro":"外垵餌砲位於西嶼鄉外垵村西埔頂，建於1923年（大正12年）。當時美、英、日、法、義五國已簽署《華盛頓海軍條約》限制海軍軍備，日軍在這裡設置外觀像砲臺的假砲，用來欺騙敵人。餌砲由八角形砲座與雙砲管構成，底座每邊寬約4.4公尺，砲管長12.3公尺，兩根砲管間距1.93公尺，體積相當龐大。官方說明，這種假餌砲是相當稀少、特殊的軍事設施，是因應戰爭的產物，也反映外垵在戰略地理上的重要性。2003年登錄為歷史建築，是西嶼南端軍事遺構中很特別的一處。","highlights":["長達12.3公尺的雙砲管","八角形砲座的龐大體積","西埔頂的開闊海景"],"funFact":"這兩根長12.3公尺的砲管其實不能發射，是專門用來欺騙敵人的假砲。","photoSpot":"站在砲管旁拍出假砲的巨大尺寸","visitMin":15,"openNote":"位於西嶼鄉外垵村西埔頂，戶外全天開放，請勿攀爬砲身。可與西嶼西臺、西嶼燈塔串遊。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"R","text":"哇，Allan，這兩根大砲管好長，對著大海超威風！"},{"who":"A","text":"先別被騙，它的名字叫餌砲，是假的！1923年日軍做來欺敵用的。"},{"who":"R","text":"假的？蓋這麼大一座假砲，是在錄整人節目嗎？"},{"who":"A","text":"有點像。當時五國已簽了華盛頓海軍條約限制軍備，日軍就在這裡做了一座以假亂真的砲。"},{"who":"R","text":"那這座假砲的尺寸到底有多大呢？"},{"who":"A","text":"砲管長12點3公尺，兩根間距1點93公尺，底座每邊約4點4公尺，比一般客廳還寬。"},{"who":"R","text":"好吧，這絕對是全澎湖最會演戲的大砲！"},{"who":"A","text":"哈哈，演技派。等一下站到砲管旁邊拍一張，看看你跟它比起來有多迷你！"}],"clues":["我長得很像大砲，其實一發也不能打","我有八角形砲座和兩根長12.3公尺的砲管","我在外垵西埔頂，1923年為了欺敵而建"],"quiz":[{"q":"外垵餌砲建造的主要目的是什麼？","options":["實際砲擊敵艦","欺騙敵人的假砲","慶典鳴放禮砲","訓練新兵射擊"],"answer":1,"explain":"餌砲是日軍為欺敵所建的假砲。"},{"q":"外垵餌砲的砲管大約有多長？","options":["4.4公尺","1.93公尺","20.5公尺","12.3公尺"],"answer":3,"explain":"砲管長度為12.3公尺。"}],"images":[{"file":"澎湖-外垵餌砲.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/%E6%BE%8E%E6%B9%96-%E5%A4%96%E5%9E%B5%E9%A4%8C%E7%A0%B2.JPG/960px-%E6%BE%8E%E6%B9%96-%E5%A4%96%E5%9E%B5%E9%A4%8C%E7%A0%B2.JPG","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96-%E5%A4%96%E5%9E%B5%E9%A4%8C%E7%A0%B2.JPG","artist":"Mimicat1531","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/xiyu-waianerpao-0.webp","small":"img/xiyu-waianerpao-0-s.webp"}]},{"id":"magong-youbianju","name":"澎湖郵便局","short":"澎湖郵便局","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.563428,"lng":119.563903,"address":"澎湖縣馬公市中山路75號之1","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-23/9abf3eb1-39f5-4fe4-ab13-928dfa373ec0/澎湖郵便局.jpg","year":1924,"yearText":"1924年（大正13年）","era":"japan","themes":["日式建築","公共建築"],"yearUnknown":false,"summary":"切角頂入口的百年郵電局，見證澎湖通信史","intro":"澎湖郵便局位於馬公市中山路，建於1924年（大正13年），是日治時期的郵電所，在澎湖通信資訊史上具有歷史價值，也具建築史意義。建築屋頂採兩坡頂設計，大門入口以「切角頂」突破山牆的單調，屋頂出簷深遠，下方以三角木架支撐，屋面鋪水泥製日式文化瓦；外牆為水泥漿打毛，基座刻意粉刷成方石砌的模樣，窗戶都是方形，室內地坪則為磨石子。戰後這裡曾由郵局與電信單位使用，2002年登錄為歷史建築；依中文維基百科，2018年起修復再利用為澎湖水下考古工作站等展示空間。","highlights":["入口的切角頂與三角木架支撐的深出簷","粉刷成方石砌模樣的基座","室內的磨石子地坪"],"funFact":"基座看起來像一塊塊方石堆砌，其實是用水泥粉刷做出來的仿石效果。","photoSpot":"在中山路對面拍切角頂入口","visitMin":30,"openNote":"位於馬公市中山路，中央老街與馬公港一帶。依官方資料每週三至週一09:00–17:00開放，週二休館，以澎湖縣政府文化局公告為準。可與天后宮、水上警察官吏派出所一起步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，寄明信片之前，先來認識1924年蓋好的澎湖郵便局。"},{"who":"R","text":"郵便局？聽起來好像一間賣便當的店耶！"},{"who":"A","text":"郵便是日文的郵政啦，這裡是日治時期的郵電所，寄信、打電報都在這裡辦。"},{"who":"R","text":"那它的門口怎麼斜斜的，好像被人切掉一角？"},{"who":"A","text":"那叫切角頂，入口屋頂出簷很深，下面還有三角木架撐著，像幫大門撐一把傘。"},{"who":"R","text":"那牆壁下面那一圈是石頭砌的嗎？看起來好整齊喔。"},{"who":"A","text":"再靠近一點看，那是用水泥粉刷做出方石砌的效果，算是百年前的仿石貼皮。"},{"who":"R","text":"原來是建築界的化妝術，連我這個人工智慧都被騙到了！"},{"who":"A","text":"進去後找找磨石子地坪，再到對街拍一張切角頂入口，當作寄給自己的明信片！"}],"clues":["我的基座是用粉刷假裝成方石砌","我的入口有切角頂和三角木架撐著的深出簷","1924年在中山路落成的日治郵電所"],"quiz":[{"q":"郵便局大門入口的屋頂採用哪一種形式？","options":["歇山頂","攢尖頂","圓拱頂","切角頂"],"answer":3,"explain":"入口以切角頂突破山牆單調，下方有三角木架。"},{"q":"郵便局的基座用什麼方式呈現方石砌模樣？","options":["粉刷仿石","真石鑲嵌","磁磚拼貼","木板彩繪"],"answer":0,"explain":"基座是粉刷成像方石砌的構造。"}],"images":[{"file":"澎湖-澎湖郵便局.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/%E6%BE%8E%E6%B9%96-%E6%BE%8E%E6%B9%96%E9%83%B5%E4%BE%BF%E5%B1%80.jpg/960px-%E6%BE%8E%E6%B9%96-%E6%BE%8E%E6%B9%96%E9%83%B5%E4%BE%BF%E5%B1%80.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96-%E6%BE%8E%E6%B9%96%E9%83%B5%E4%BE%BF%E5%B1%80.jpg","artist":"Mimicat1531","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-youbianju-0.webp","small":"img/magong-youbianju-0-s.webp"}]},{"id":"huxi-longmenlvnenggu","name":"龍門呂能古宅","short":"龍門呂能古宅","category":"歷史建築","level":"","town":"湖西鄉","types":["宅第"],"lat":23.564616,"lng":119.670377,"address":"澎湖縣湖西鄉龍門村162號","announced":"2012-02-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20120312000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1258/photo/龍門呂能古宅1.JPG","year":1925,"yearText":"約1920年代（日治時期）","era":"japan","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"彩繪壁畫加玻璃護層的四櫸頭古厝","intro":"龍門呂能古宅位於湖西鄉龍門村，是日治時期興建的傳統四櫸頭古厝，2012年登錄為歷史建築。正面壁上有油漆彩繪壁畫，外面還加裝玻璃保護，這種作法與畫風在澎湖相當少見；大門兩側書寫治世格言，楹聯完好，見證那個時代的風氣。圓光門以汕石組砌，作工細緻；立面泥塑花飾優美，牆面鑲著綠釉花磚，大厝身兩旁的水泥條形窗搭配立體圖案。亭的屋脊型制恢宏，與大厝身屋頂連成富有韻律感的天際線，深井的兩處落水口造型也很優美。","highlights":["加裝玻璃護層的彩繪壁畫","汕石細緻組砌的圓光門","大門兩側的治世格言與綠釉花磚"],"funFact":"壁畫外面加一層玻璃保護，等於一百年前就幫壁畫貼上了螢幕保護貼。","photoSpot":"在屋外拍大厝身與亭連成的屋頂天際線","visitMin":10,"openNote":"位於湖西鄉龍門村，官方資料為不開放，屬私人古厝，請在外觀參觀、勿擅入私人住宅。","dialogue":[{"who":"R","text":"Allan，這間古厝的牆上有畫，外面怎麼還蓋著一層玻璃？"},{"who":"A","text":"這就是呂能古宅的招牌！正面壁的油漆彩繪壁畫加了玻璃護層，在澎湖很少見。"},{"who":"R","text":"原來古人就知道要幫畫貼保護貼，比我還懂保養手機！"},{"who":"A","text":"哈哈，而且大門兩邊寫著治世格言，等於把家訓直接貼在門口，天天提醒。這是日治時期蓋的四櫸頭古厝。"},{"who":"R","text":"那個圓圓的門洞好漂亮，是用什麼砌的？"},{"who":"A","text":"那是圓光門，用汕石一塊塊組砌，接縫做得很細。牆上還有綠釉花磚，這些在澎湖都算講究。"},{"who":"R","text":"壁畫、格言、花磚，這間房子根本是一本立體雜誌！"},{"who":"A","text":"這是私人古厝，請在外面欣賞。你退後幾步，看亭的屋脊和大厝身怎麼連成一條天際線！"}],"clues":["我的壁畫外面加了一層玻璃保護","我的大門兩側寫著治世格言，還有汕石圓光門","龍門村的日治時期四櫸頭古厝"],"quiz":[{"q":"呂能古宅的彩繪壁畫有什麼特殊保護作法？","options":["塗一層蠟","覆蓋玻璃","掛上布簾","加鐵窗"],"answer":1,"explain":"彩繪上覆玻璃的裝飾作法極具特色。"},{"q":"古宅的圓光門用什麼石材組砌？","options":["青斗石","大理石","花崗岩","汕石"],"answer":3,"explain":"圓光門以汕石組砌，作工細緻。"}],"images":[]},{"id":"xiyu-chixihaoguzhai","name":"池西41號古宅","short":"池西41號古宅","category":"歷史建築","level":"","town":"西嶼鄉","types":["宅第"],"lat":23.603483,"lng":119.506484,"address":"澎湖縣西嶼鄉池西村41號","announced":"2020-02-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20200717000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-07-17/6595e016-4c42-48e4-8e79-e463f9213d7a/IMGP4928.jpg","year":1925,"yearText":"年代不詳","era":"unknown","themes":["咕咾石古厝","宅第家族"],"yearUnknown":true,"summary":"「陋巷堂」匾額與水墨壁畫的四櫸頭古厝","intro":"池西41號古宅位於西嶼鄉池西村，2020年登錄為歷史建築。古宅為澎湖傳統的「一落四櫸頭」形式，牆基用玄武岩，並混用咕咾石等在地建材。入口為前磚坪式，門樓門豎有石雕對聯，橫批為「五福盈門」。大廳正面壁的匾額堵題「陋巷堂」，左右分別是「竹鹿」與「松鶴」水墨畫，門柱用清水紅磚，還有燕子磚砌、石作門窗框與花格磚等細節；深井、水缸、彩繪、花磚與花窗也都保存完整，具有民間藝術特色與澎湖民居的地方風貌。確切興建年代官方資料未載，目前為私人住宅，不對外開放。","highlights":["門樓石雕對聯與「五福盈門」橫批","大廳「陋巷堂」匾額與竹鹿、松鶴水墨畫","燕子磚砌與花格磚等磚作細節"],"funFact":"古宅牆基用玄武岩、牆身混用咕咾石，澎湖兩大傳統石材在同一間房子裡就能看到。","photoSpot":"在門樓前拍「五福盈門」橫批","visitMin":15,"openNote":"位於西嶼鄉池西村，私人住宅，目前不開放，請在外觀參觀、勿擅入私人住宅。鄰近西嶼鄉黃氏宗祠。從馬公經澎湖跨海大橋開車或騎機車可達西嶼，也可搭澎湖縣公車前往。","dialogue":[{"who":"A","text":"阿拉蕾，看古宅先看門面。這座門樓的石雕對聯，橫批寫著五福盈門。"},{"who":"R","text":"五福一次到齊，Allan，這家人的運氣也太好了吧！"},{"who":"A","text":"祝福都寫在門口了嘛。這是澎湖傳統的一落四櫸頭，牆基用玄武岩，牆身混用咕咾石。"},{"who":"R","text":"一間房子用兩種石頭，是石頭界的混搭風！"},{"who":"A","text":"說得好。官方資料記載，大廳正面有一塊陋巷堂匾額，左右還有竹鹿和松鶴水墨畫。"},{"who":"R","text":"陋巷？房子這麼漂亮，還說自己簡陋，也太謙虛了！"},{"who":"A","text":"堂號的典故我們就不亂猜了。這裡是私人住宅，在外面欣賞就好，別探頭探腦喔。"},{"who":"R","text":"好，那我在門外找找燕子磚砌和花格磚，看看藏在哪裡！"}],"clues":["我的大廳匾額題著陋巷堂","我的門樓橫批寫著五福盈門","我在西嶼池西村，用門牌號碼當名字的四櫸頭古厝"],"quiz":[{"q":"這座古宅門樓對聯的橫批是什麼？","options":["紫氣東來","福壽康寧","五福盈門","竹苞松茂"],"answer":2,"explain":"門樓門豎為石雕對聯，橫批為「五福盈門」。"},{"q":"古宅大廳正面壁的匾額題的是什麼？","options":["陋巷堂","存養軒","紫雲堂","元益堂"],"answer":0,"explain":"大廳正面壁匾額堵題「陋巷堂」。"}],"images":[]},{"id":"magong-dongjiabeijidian","name":"馬公東甲北極殿","short":"東甲北極殿","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.56493,"lng":119.566866,"address":"澎湖縣馬公市啟明里啟明街1鄰2號","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-23/d6207868-ac33-44f9-8cb8-f7eb27b09149/馬公東甲北極殿.jpg","year":1927,"yearText":"1927年（昭和2年）","era":"japan","themes":["宗教信仰"],"yearUnknown":false,"summary":"馬公東甲的甲頭廟，少數保留傳統廟貌","intro":"馬公東甲北極殿位於馬公市啟明里啟明街，主體於1927年（昭和2年）完工，1949年修建，2009年再由東甲居民勘損重修。它是馬公東甲居民的「甲頭廟」，與當地居民互動密切；官方資料稱它是澎湖目前少數仍維持傳統廟貌的寺廟。廟宇正面五開間，內有天井，為縱深兩進的平面格局，內部以木棟架為主，棟架上布滿彩繪與雕刻，木雕、石雕與彩繪都深具藝術價值，也深具文化意義。2002年登錄為歷史建築。廟宇位在馬公舊市區，可與中央老街一帶的古蹟一起步行參觀。","highlights":["正面五開間的傳統廟貌","木棟架上的彩繪與雕刻","兩進格局與中間天井"],"funFact":"這座廟是東甲居民的「甲頭廟」，2009年的重修也是由東甲居民勘損進行的。","photoSpot":"在廟埕拍五開間的正面全景","visitMin":20,"openNote":"位於馬公市啟明里啟明街，依官方資料每日05:00–20:00開放。參觀時請尊重信眾參拜，拍攝神像前先詢問廟方。可從中央老街一帶步行前往。","dialogue":[{"who":"R","text":"Allan，這座廟的雕刻好密，看得我眼花撩亂！"},{"who":"A","text":"這是1927年完工的馬公東甲北極殿，也是東甲居民的甲頭廟，官方說它是澎湖少數還維持傳統廟貌的廟。"},{"who":"R","text":"甲頭廟是什麼意思？聽起來像甲殼類的頭頭。"},{"who":"A","text":"哈哈，不是龍蝦啦！它是東甲這一帶居民的地方大廟，2009年重修也是居民自己出力。"},{"who":"R","text":"那它跟附近的新廟比起來，有什麼特別？"},{"who":"A","text":"正面五開間，兩進格局中間夾著天井，裡面以木棟架為主，上面全是彩繪和雕刻。"},{"who":"R","text":"一直抬頭看棟架，脖子會不會扭到啊？"},{"who":"A","text":"所以要慢慢看，就像吃一碗澎湖小管麵線，要一口一口細細品嚐。"},{"who":"R","text":"好，我要走到天井，抬頭找出棟架上最可愛的一個彩繪人物！"}],"clues":["我是東甲居民的甲頭廟","我的正面五開間，兩進之間夾著天井","啟明街上1927年完工、保留傳統廟貌的廟宇"],"quiz":[{"q":"北極殿屬於馬公哪一區居民的甲頭廟？","options":["西甲","南甲","北甲","東甲"],"answer":3,"explain":"本廟是馬公東甲居民的甲頭廟。"},{"q":"北極殿的平面格局為何？","options":["單進三開間","兩進五開間","三進七開間","四合院式"],"answer":1,"explain":"正面五開間，內有天井，為縱深兩進格局。"}],"images":[{"file":"東甲北極殿 山門 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/%E6%9D%B1%E7%94%B2%E5%8C%97%E6%A5%B5%E6%AE%BF_%E5%B1%B1%E9%96%80_%28cropped%29.jpg/960px-%E6%9D%B1%E7%94%B2%E5%8C%97%E6%A5%B5%E6%AE%BF_%E5%B1%B1%E9%96%80_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9D%B1%E7%94%B2%E5%8C%97%E6%A5%B5%E6%AE%BF_%E5%B1%B1%E9%96%80_(cropped).jpg","artist":"雲角","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-dongjiabeijidian-0.webp","small":"img/magong-dongjiabeijidian-0-s.webp"}]},{"id":"magong-shuidaozhushuisui","name":"馬公水道貯水隧道","short":"馬公水道貯水隧道","category":"歷史建築","level":"","town":"馬公市","types":["產業"],"lat":23.569891,"lng":119.57367,"address":"澎湖縣馬公市馬公段16、16-8、18、280、275-4地號","announced":"2019-04-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190429000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-17/f5176ed3-1842-4480-a219-87c997e13df6/圖檔.jpg","year":1927,"yearText":"1927年（昭和2年）","era":"japan","themes":["水利設施","產業遺產"],"yearUnknown":false,"summary":"藏在地底10.6公尺、近百年仍在用的水道","intro":"馬公水道貯水隧道位於澎湖本島馬公市區，創建於日治昭和2年（1927），是當時離島唯一的自來水道系統。六口地下深井在地底10.6公尺處以貯水隧道相連，總長824公尺，湧出的地下水先貯留在隧道內，再由揚水唧筒加壓送到30公尺高的貯水塔，經鐵管配水到市街。地面上的井倉房採巴洛克風格，揚水所內還保留機械式水位計。民國83年至93年（1994–2004）以船運臺灣自來水救急期間，它仍發揮貯水功能，協助緩解水荒，2019年登錄為歷史建築，見證澎湖的水資源歷史。","highlights":["總長824公尺、深入地底10.6公尺的貯水隧道","巴洛克風格的井倉房建築","揚水所內保留的機械式水位計"],"funFact":"這套水道蓋好將近百年還在服役，1994到2004年澎湖缺水、靠船運水時，它也出力貯水。","photoSpot":"在公開道路旁拍井倉房的巴洛克立面","visitMin":15,"openNote":"位於馬公市區，官方資料為不開放，屬供水設施，請勿進入管制範圍，僅能在公開道路旁看外觀。市區景點可步行或騎機車前往。","dialogue":[{"who":"R","text":"Allan，你一直盯著地板看，是掉錢了嗎？"},{"who":"A","text":"我在想腳底下超過10公尺深的地方，藏著一條824公尺長的貯水隧道，比掉錢有趣多了！"},{"who":"R","text":"地底下藏水？這是要開地下游泳池嗎？"},{"who":"A","text":"是1927年日治昭和2年蓋的馬公水道，六口深井用隧道串起來，地下水就存在隧道裡。"},{"who":"R","text":"那水要怎麼送到大家家裡？用水桶一桶一桶提嗎？"},{"who":"A","text":"用揚水唧筒把水打到30公尺高的貯水塔，再靠高度從鐵管流到市街，很聰明吧。地面上的井倉房還是巴洛克風格喔。"},{"who":"R","text":"居然到現在還在用，這水道比我的耳機還耐操耶！"},{"who":"A","text":"1994到2004年澎湖缺水、靠船運水，它還是幫忙貯水。等一下找找看井倉房的巴洛克裝飾在哪裡！"}],"clues":["我深入地底超過10公尺，總長824公尺","六口深井在地下被我串成一體，湧水先在我體內貯存","日治時期離島唯一的自來水道，近百年後仍在供水"],"quiz":[{"q":"馬公水道的貯水隧道位在地底大約多深？","options":["3.5公尺","10.6公尺","25公尺","52公尺"],"answer":1,"explain":"六口深井在地下10.6公尺處以隧道相連。"},{"q":"水從隧道抽出後，先送到哪裡再配水到市街？","options":["天后宮水井","海邊碼頭","成功水庫","30公尺高的貯水塔"],"answer":3,"explain":"以唧筒加壓送到30公尺高貯水塔，再用鐵管配水。"}],"images":[]},{"id":"magong-shiliguzhai","name":"嵵裡古宅","short":"嵵裡古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.525442,"lng":119.570518,"address":"澎湖縣馬公市嵵裡里77號","announced":"2008-12-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20081203000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/38133/photo/e183127d-d3f6-4381-8966-4d9972bfefc5.JPG","year":1930,"yearText":"約1920至1930年代（日治時期）","era":"japan","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"屋主親自潛水採石、蓋了8年的古厝","intro":"嵵裡古宅位於馬公市嵵裡里，由在地人陳恭（1909至1988年）興建。他16歲起在青灣內海後港邊潛水挖取硓𥑮石，前後長達7年，再花1年起厝，總共耗時8年才完成；玄武岩則購自石材店，木料與屋瓦購自大陸。官方資料記載，二戰期間屋頂曾遭砲彈炸毀，後來聘請大陸師傅修建，把紅瓦改為黑瓦。古宅由在地人士合作完成，形制、建材與裝飾具地方特色，2008年登錄為歷史建築，之後獲縣府補助修復，目前多作為祭祀使用。","highlights":["屋主親自潛水採來的硓𥑮石牆","戰後修建時改成的黑瓦屋頂","玄武岩與硓𥑮石搭配的澎湖古厝工法"],"funFact":"陳恭16歲開始潛水挖硓𥑮石，挖了整整7年才夠蓋房子，比現在存頭期款還辛苦。","photoSpot":"在屋前拍硓𥑮石牆面的紋理","visitMin":15,"openNote":"位於馬公市嵵裡里，官方資料記載每日10:00至17:00開放；現況以祭祀使用為主，參觀請保持安靜、尊重屋主，勿擅入未開放空間。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，蓋房子的石頭不是用買的嗎？你說這間是自己潛水撈的？"},{"who":"A","text":"沒錯！嵵裡古宅的主人陳恭，16歲就開始在青灣內海潛水，一塊一塊挖咕咾石。"},{"who":"R","text":"天啊，要挖多久才夠蓋一間房子？"},{"who":"A","text":"挖了7年，再花1年蓋房子，前後整整8年，堪稱澎湖版愚公移山，只是他搬的是海底。"},{"who":"R","text":"好熱血！那其他材料也是自己撈的嗎？"},{"who":"A","text":"那倒沒有，玄武岩是跟石材店買的，木料和屋瓦則從大陸買來。"},{"who":"R","text":"那屋頂現在怎麼是黑色的瓦片呢？"},{"who":"A","text":"二戰時屋頂被砲彈炸毀，後來請師傅修建，就把紅瓦改成黑瓦。現在主要作祭祀使用，參觀要保持安靜。"},{"who":"R","text":"了解！那我走到牆邊，找找哪一塊咕咾石上還看得到珊瑚的孔洞紋路！"}],"clues":["我的主人花了7年在海底挖我的牆","二戰時我的屋頂被炸毀，紅瓦改成了黑瓦","我是嵵裡里由陳恭興建的古厝"],"quiz":[{"q":"陳恭蓋房子的硓𥑮石是怎麼來的？","options":["向石材店購買","自己潛水挖取","從福建運來","拆城牆取得"],"answer":1,"explain":"他16歲起在青灣內海潛水挖取硓𥑮石，長達7年。"},{"q":"嵵裡古宅屋頂修建後，瓦片有什麼改變？","options":["黑瓦改紅瓦","改成綠琉璃瓦","紅瓦改黑瓦","改成鐵皮"],"answer":2,"explain":"屋頂遭砲彈炸毀後修建，紅瓦改為黑瓦。"}],"images":[]},{"id":"magong-tingxianbingdui","name":"澎湖廳憲兵隊","short":"澎湖廳憲兵隊","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.564519,"lng":119.56379,"address":"澎湖縣馬公市民族路22號","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-10-26/f10b921d-85da-4abe-ac12-0bfd09cb8c7c/憲兵隊.jpg","year":1931,"yearText":"1931年（昭和6年）改建","era":"japan","themes":["軍事遺構","日式建築","公共建築"],"yearUnknown":false,"summary":"從清代衙門、憲兵隊到美術館的天后宮鄰居","intro":"澎湖廳憲兵隊位於馬公市民族路、澎湖天后宮西側。這塊地在清代是澎湖水師協鎮署，1889年（光緒15年）改為通判衙門；日治時期成為澎湖島憲兵分隊，1931年（昭和6年）拆除舊署改建，興建L形大廳、武道廳、馬房與日式宿舍，1941年又在北側土丘挖了2座防空洞。戰後先由澎防部運輸組使用，1958年金門砲戰後改組為馬公港口指揮部，增建地下戰堡與防空砲座。2002年登錄為歷史建築，2004年軍方移交縣政府，劍擊室與馬房在2016年修復，現為洪根深美術館。","highlights":["1931年鋼筋混凝土L形大廳，地樑抬高約1公尺防潮","被誤稱為「水牢」的大廳階梯下匯水處","土丘上的國軍防空砲座與西側玄武岩圍牆"],"funFact":"大廳階梯下那個長寬深各約1公尺的坑常被誤傳是「水牢」，其實是收集雨水的匯水處。","photoSpot":"在L形大廳迴廊拍日式建築與營區混搭景象","visitMin":40,"openNote":"位於馬公市民族路、天后宮西側，現為洪根深美術館。依官方資料週三至週日09:00–12:00、14:00–17:00開放，週一、週二及國定假日休館，以澎湖縣政府文化局公告為準。可與天后宮、中央老街一起步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，天后宮隔壁這片營舍，你猜它總共換過幾種身分？"},{"who":"R","text":"看起來就是一座軍營，我猜大概只有兩種身分吧？"},{"who":"A","text":"太少了！清代是水師協鎮署，1889年改成通判衙門，日治變憲兵分隊，戰後又成了馬公港口指揮部。"},{"who":"R","text":"哇，這塊地根本是轉職最多次的冠軍！那現在呢？"},{"who":"A","text":"現在是洪根深美術館，從拿槍改成拿畫筆，退休生活超級文青。"},{"who":"R","text":"我聽說大廳階梯下面有一個水牢，好恐怖！"},{"who":"A","text":"那是誤會啦，那個約1公尺見方的坑其實是匯水處，把雨水集中後排進下水道。"},{"who":"R","text":"原來是排水系統被冤枉了幾十年，好可憐喔。"},{"who":"A","text":"到現場先找北邊土丘上那座圓形防空砲座，再看看大廳的地基抬高了多少！"}],"clues":["我的大廳階梯下有個被誤傳成水牢的匯水處","我當過通判衙門、憲兵分隊和港口指揮部","天后宮西側，如今掛著畫家名字的美術館營舍"],"quiz":[{"q":"大廳階梯下被誤稱為「水牢」的坑，其實是什麼？","options":["匯水處","囚室","彈藥庫","儲酒窖"],"answer":0,"explain":"它長寬深各約1公尺，用來匯集雨水再排入下水道。"},{"q":"1958年金門砲戰後，這處營區改組為什麼單位？","options":["要塞司令部","憲兵分隊","海軍造船廠","馬公港口指揮部"],"answer":3,"explain":"為支援金門前線運補，改組為馬公港口指揮部。"}],"images":[{"file":"Penghu Prefecture Military Police Office 02 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Penghu_Prefecture_Military_Police_Office_02_%28cropped%29.jpg/960px-Penghu_Prefecture_Military_Police_Office_02_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Penghu_Prefecture_Military_Police_Office_02_(cropped).jpg","artist":"舟集 Boattoad","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-tingxianbingdui-0.webp","small":"img/magong-tingxianbingdui-0-s.webp"}]},{"id":"magong-shuishangjingcha","name":"馬公水上警察官吏派出所","short":"水上警察派出所","category":"歷史建築","level":"","town":"馬公市","types":["衙署"],"lat":23.563206,"lng":119.563623,"address":"澎湖縣馬公市復興里臨海路40號","announced":"2007-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071121000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-23/0d7e2fbe-e692-4438-8268-92a2929b7e85/馬公水上警察官吏派出所.jpg","year":1931,"yearText":"1931年（昭和6年）落成","era":"japan","themes":["港口海關","公共建築"],"yearUnknown":false,"summary":"守望馬公港的轉角型日治水上派出所","intro":"馬公水上警察官吏派出所位於馬公市復興里臨海路，面向馬公港。日治初期澎湖設水上警察署，1898年（明治31年）改設水上警察官吏派出所，此後隸屬單位幾經變動，制度延續到終戰。依中文維基百科，現存的第三代廳舍於1931年（昭和6年）落成。建築接近簡化的現代主義風格，屬轉角型配置：六角形平面的中央棟為二層樓，西、北兩翼為一層磚造，整體近似L形；轉角主入口採切角，以洗石子線條營造石造立面的粗獷感，上方有西方古典語彙的泥塑裝飾。二樓可遠眺馬公港，推測兼有觀測港口的功能。現再利用為藝文展覽空間。","highlights":["六角形中央棟與切角主入口","入口上方的西方古典泥塑裝飾","二樓遠眺馬公港的觀測空間"],"funFact":"原本轉角的主入口後來被磚牆封住了，現在要從內庭的後門進出。","photoSpot":"在臨海路轉角拍切角入口與二樓窗","visitMin":20,"openNote":"位於馬公市復興里臨海路，近馬公港。依官方資料9:00–17:00開放，每週二休館，以澎湖縣政府文化局公告為準。可與澎湖郵便局、天后宮、中央老街一起步行串遊。","dialogue":[{"who":"R","text":"Allan，港邊這棟轉角房子，門口斜斜地切了一刀，是被船撞到嗎？"},{"who":"A","text":"哈哈，那是刻意設計的切角入口，這裡是日治時期的馬公水上警察官吏派出所。"},{"who":"R","text":"水上警察？是開著船抓壞人的警察嗎？"},{"who":"A","text":"對，他們負責港區和海上的警務。現在這棟是1931年落成的第三代廳舍。"},{"who":"R","text":"第三代！原來派出所也會換新家喔。"},{"who":"A","text":"這一代的中央棟是六角形的二層樓，兩邊接上一層樓的翼樓，整體排成一個直角轉彎的形狀。"},{"who":"R","text":"兩邊都是一層，為什麼中間要特別蓋兩層樓？"},{"who":"A","text":"二樓視野好，可以遠眺馬公港，官方推測當年也是觀察港口動靜的地方。"},{"who":"R","text":"那我要上二樓，從窗口拍一張馬公港，假裝自己正在值勤！"}],"clues":["我的中央棟是六角形平面，二樓可以遠眺港口","我是第三代廳舍，原本的轉角入口已被封住","臨海路上負責馬公港警務的日治派出所"],"quiz":[{"q":"派出所的中央棟平面是什麼形狀？","options":["圓形","八角形","正方形","六角形"],"answer":3,"explain":"中央棟為六角形平面，西、北側再連接矩形翼樓。"},{"q":"派出所二樓在日治時期推測還有什麼功能？","options":["觀測港口","存放武器","拘留嫌犯","員警宿舍"],"answer":0,"explain":"二樓可遠眺馬公港，推測包括觀望港口的觀測空間。"}],"images":[{"file":"澎湖-馬公水上警察官吏派出所.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/%E6%BE%8E%E6%B9%96-%E9%A6%AC%E5%85%AC%E6%B0%B4%E4%B8%8A%E8%AD%A6%E5%AF%9F%E5%AE%98%E5%90%8F%E6%B4%BE%E5%87%BA%E6%89%80.jpg/960px-%E6%BE%8E%E6%B9%96-%E9%A6%AC%E5%85%AC%E6%B0%B4%E4%B8%8A%E8%AD%A6%E5%AF%9F%E5%AE%98%E5%90%8F%E6%B4%BE%E5%87%BA%E6%89%80.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96-%E9%A6%AC%E5%85%AC%E6%B0%B4%E4%B8%8A%E8%AD%A6%E5%AF%9F%E5%AE%98%E5%90%8F%E6%B4%BE%E5%87%BA%E6%89%80.jpg","artist":"Mimicat1531","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-shuishangjingcha-0.webp","small":"img/magong-shuishangjingcha-0-s.webp"}]},{"id":"baisha-xiaochilinshizong","name":"小赤林氏宗祠","short":"小赤林氏宗祠","category":"歷史建築","level":"","town":"白沙鄉","types":["宅第"],"lat":23.661131,"lng":119.597656,"address":"澎湖縣白沙鄉小赤村12號","announced":"2014-08-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140827000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-11/c7b5fb47-4105-42e4-b7e1-9e215d8664ee/圖像.jpg","year":1932,"yearText":"1932年（昭和7年）","era":"japan","themes":["宗祠家廟"],"yearUnknown":false,"summary":"牆上留有二戰駐軍床架鑿痕的宗祠","intro":"小赤林氏宗祠位於白沙鄉小赤村，建於昭和7年（1932），見證林氏家族在白沙的開拓。林氏是小赤村的代表性家族，後代多從事文教工作，對澎湖地方教育貢獻良多。宗祠以硓𥑮石為內外牆基礎，搭配玄武岩，展現白沙地區的建築特色；裙堵、窗堵以洗石子貼磁磚，配上壽字窗框，亭下兩側以洗石子浮雕穿斗式屋架，長度超過2公尺的青斗石則是帆船時代從唐山運來的建材。傳統建築美學與日治時期的水泥、洗石子技術在此交融。廳堂壁面留有二戰末期駐軍床架的鑿痕，2014年登錄為歷史建築，2017年修復。","highlights":["二戰末期駐軍床架留下的壁面鑿痕","洗石子浮雕的穿斗式屋架與壽字窗框","長度超過2公尺的青斗石"],"funFact":"廳堂牆上的鑿痕，是二戰末期軍隊借住時架床留下的痕跡。","photoSpot":"在亭下拍洗石子浮雕屋架與壽字窗","visitMin":20,"openNote":"位於白沙鄉小赤村，官方資料為每日09:00–16:00開放，宗祠為家族祭祀場所，參觀請保持安靜、尊重祭祀。從馬公經中正橋、永安橋可開車或騎機車抵達。","dialogue":[{"who":"R","text":"Allan，這面牆上一排一排的小洞，是被白蟻吃掉的嗎？"},{"who":"A","text":"不是白蟻，是二戰末期軍隊駐紮在宗祠裡，架床時鑿出來的痕跡，很有歷史感。"},{"who":"R","text":"在祖先面前搭床睡覺，壓力應該很大吧！"},{"who":"A","text":"哈哈，戰爭年代大家都沒得選。這座宗祠是1932年蓋的，見證林氏家族在白沙的開拓。林氏後代很多人投入教育工作。"},{"who":"R","text":"那宗祠裡面，還有什麼特別的地方？"},{"who":"A","text":"看亭下兩側，用洗石子做出木頭屋架的浮雕，還有壽字窗框，是傳統和日治水泥技術的混搭。"},{"who":"R","text":"水泥假扮木頭屋架，這是建築界的角色扮演！"},{"who":"A","text":"還有一塊超過2公尺長的青斗石，是帆船時代從唐山運來的。你去量量看，它有幾個阿拉蕾那麼長！"}],"clues":["我的廳堂牆上留有二戰駐軍架床的鑿痕","我有超過2公尺長、帆船時代運來的青斗石","白沙小赤村1932年建的家族宗祠"],"quiz":[{"q":"宗祠廳堂牆上的鑿痕是怎麼來的？","options":["颱風損壞","白蟻蛀蝕","二戰駐軍架床","地震裂縫"],"answer":2,"explain":"廳堂壁面有二戰末期駐軍床構鑿痕。"},{"q":"宗祠的窗框以什麼字樣為特色？","options":["福字","壽字","喜字","祿字"],"answer":1,"explain":"以洗石子貼磁磚及壽字窗框為特色。"}],"images":[{"file":"小赤林氏宗祠 07 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/%E5%B0%8F%E8%B5%A4%E6%9E%97%E6%B0%8F%E5%AE%97%E7%A5%A0_07_%28cropped%29.jpg/960px-%E5%B0%8F%E8%B5%A4%E6%9E%97%E6%B0%8F%E5%AE%97%E7%A5%A0_07_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%B0%8F%E8%B5%A4%E6%9E%97%E6%B0%8F%E5%AE%97%E7%A5%A0_07_(cropped).jpg","artist":"雲角","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/baisha-xiaochilinshizong-0.webp","small":"img/baisha-xiaochilinshizong-0-s.webp"}]},{"id":"magong-tingshe","name":"澎湖廳舍","short":"澎湖廳舍","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.57007,"lng":119.566468,"address":"澎湖縣馬公市中興里治平路32 號","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-23/40696155-e383-453f-84b2-47cc06ca3295/澎湖廳舍.jpg","year":1933,"yearText":"1933–1934年（昭和8至9年）","era":"japan","themes":["日式建築","公共建築"],"yearUnknown":false,"summary":"日治五州三廳唯一留存的廳舍，至今仍是縣政府","intro":"澎湖廳舍位於馬公市中興里治平路，是澎湖縣政府所在地。日治初期澎湖廳借用清代總鎮署辦公，1933年（昭和8年）在媽宮城外北側興建新廳舍，1934年底竣工、隔年啟用。戰後1946年澎湖縣政府成立，沿用這棟廳舍辦公至今。官方資料指出，它是日治時期「五州三廳」中唯一留存下來的廳役所，在政治、建築與歷史上都深具意義。建築屬帝冠樣式，一樓牆基以玄武岩砌築，外牆以水泥砂漿打毛，配上長方形上下推窗與日式黑色水泥瓦；內部原規劃廳長室、會議室、禮堂及總務、稅務、警務、教育等各科辦公室。","highlights":["玄武岩砌築的一樓牆基","對稱格局與日式黑色水泥瓦屋頂","長方形上下推窗"],"funFact":"縣府前廣場東南角那座綠色圓形碉堡，是1951年前後加蓋的，後來也登錄為歷史建築。","photoSpot":"在治平路對面拍左右對稱的正立面","visitMin":15,"openNote":"位於馬公市中興里治平路，至今仍是澎湖縣政府辦公廳舍。官方資料標示開放時間為縣府上班時間8:00–17:30，以外觀參觀為主，入內請保持安靜、勿打擾洽公民眾。從馬公市區步行可到，旁邊就是廳長官舍。","dialogue":[{"who":"R","text":"Allan，這棟房子門口好多人進進出出，是熱門景點嗎？"},{"who":"A","text":"他們是來辦事的啦！這是澎湖縣政府，前身是日治時期的澎湖廳舍，1933年開始興建。"},{"who":"R","text":"九十多歲的老房子還在當縣政府，也太勤勞了吧！"},{"who":"A","text":"官方資料說，日治時期五州三廳的廳舍，只有它一棟留下來，真的是碩果僅存。"},{"who":"R","text":"那旁邊的廳長官舍也是同一時期蓋的嗎？"},{"who":"A","text":"對，差不多同時興建，一個辦公一個住家，通勤距離短到讓上班族羨慕到哭。"},{"who":"R","text":"我也想要這種通勤！那建築有什麼看點？"},{"who":"A","text":"一樓牆基是澎湖在地的玄武岩，外牆用水泥砂漿打毛，屋頂鋪日式黑色水泥瓦。"},{"who":"R","text":"好，我要在對街拍一張左右對稱的正面，再數數看有幾扇上下推窗！"}],"clues":["我是日治五州三廳中唯一留下來的廳舍","我的一樓牆基用澎湖玄武岩砌成","1933年起建，至今仍是縣政府的辦公大樓"],"quiz":[{"q":"澎湖廳舍戰後一直作為什麼機關使用？","options":["澎湖縣政府","澎湖地方法院","馬公市公所","澎湖縣議會"],"answer":0,"explain":"1946年澎湖縣政府成立後沿用至今。"},{"q":"廳舍一樓牆基使用哪一種在地石材？","options":["玄武岩","咕咾石","花崗岩","觀音山石"],"answer":0,"explain":"一樓牆體基座以澎湖玄武岩砌築。"}],"images":[{"file":"Penghu County Hall 20150618.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Penghu_County_Hall_20150618.jpg/960px-Penghu_County_Hall_20150618.jpg","page":"https://commons.wikimedia.org/wiki/File:Penghu_County_Hall_20150618.jpg","artist":"Wei-Te Wong","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/magong-tingshe-0.webp","small":"img/magong-tingshe-0-s.webp"}]},{"id":"magong-tingtingzhangguan","name":"澎湖廳廳長官舍","short":"澎湖廳長官舍","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.569942,"lng":119.567316,"address":"澎湖縣馬公市中興里治平路30 號","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-10-26/daa5cbd1-d68a-4e7e-ad9a-bd85e26ee7f4/澎湖廳廳長官舍-1.jpg","year":1935,"yearText":"1933–1935年（昭和8至10年）","era":"japan","themes":["日式建築","公共建築"],"yearUnknown":false,"summary":"從廳長官舍到縣長公館，如今是澎湖開拓館","intro":"澎湖廳廳長官舍位於馬公市中興里治平路，緊鄰澎湖縣政府（原澎湖廳舍）。1933年（昭和8年）興建、1935年落成，是日治時期澎湖廳長的官邸；戰後沿用為澎湖縣長公館，多位官派與民選縣長曾經入住，1992年後不再有縣長居住而閒置。2002年登錄為歷史建築，修復後以「澎湖開拓館」之名開放，被視為歷史空間再利用的典範。建築為一層樓的「和洋折衷」官舍，牆基洗石子、磚造牆身外敷水泥，屋面鋪日式文化瓦；洋式待客室與餐廳負責社交，起居則用和式座敷與床之間，另有台所、女中室、廊下等服務空間。","highlights":["洋式待客室與和式座敷並存的和洋折衷格局","座敷裡的床之間與黑褐色方形床柱","台所、女中室與廊下組成的服務動線"],"funFact":"戰後這裡當了幾十年的縣長公館，1992年後才不再有縣長入住，之後修復成澎湖開拓館。","photoSpot":"在庭院拍玄關門廊與日式文化瓦屋頂","visitMin":40,"openNote":"位於馬公市中興里治平路，澎湖縣政府旁，現為澎湖開拓館。依官方資料週四至週一09:00–12:00、14:00–17:00開放，週二、週三及國定假日休館，實際以澎湖縣政府文化局公告為準。從馬公市區步行即可到達。","dialogue":[{"who":"R","text":"Allan，這棟日式房子門口寫著開拓館，裡面是在賣開山刀的嗎？"},{"who":"A","text":"哈哈，開拓的是澎湖的歷史啦！這裡原本是日治時期澎湖廳長的官舍，1935年落成。"},{"who":"R","text":"廳長住的地方耶，那戰後換誰住進來？"},{"who":"A","text":"戰後變成縣長公館，好幾任縣長都住過，1992年以後才沒人入住，後來修復成澎湖開拓館。"},{"who":"R","text":"我看外面像洋房，裡面卻有榻榻米，到底是日式還是西式？"},{"who":"A","text":"這叫和洋折衷。接待客人用洋式待客室和餐廳，自己生活就換成和式座敷，好像上班穿西裝、回家換浴衣。"},{"who":"R","text":"那官舍裡的廚房和傭人房，又藏在哪個角落呢？"},{"who":"A","text":"有台所，也就是廚房，還有女中室和廊下，是僕人服務主人的專用動線，主僕走的路線不一樣喔。"},{"who":"R","text":"好，我要去座敷找那根黑褐色的方形床柱，看看它有沒有比Allan的頭還亮！"}],"clues":["我戰後當了幾十年的縣長公館","我的座敷裡有床之間與黑褐色方形床柱","縣政府隔壁、修復後叫做開拓館的日治官邸"],"quiz":[{"q":"這棟官舍修復後以什麼名稱對外開放？","options":["澎湖文化館","媽宮紀念館","西瀛生活館","澎湖開拓館"],"answer":3,"explain":"修復後以「澎湖開拓館」之名開放，是再利用典範。"},{"q":"官舍的建築風格屬於哪一種？","options":["巴洛克式","閩南合院","和洋折衷","現代主義"],"answer":2,"explain":"洋式待客室加上和式座敷，是典型和洋折衷官舍。"}],"images":[{"file":"澎湖廳廳長官舍 (3).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/%E6%BE%8E%E6%B9%96%E5%BB%B3%E5%BB%B3%E9%95%B7%E5%AE%98%E8%88%8D_%283%29.jpg/960px-%E6%BE%8E%E6%B9%96%E5%BB%B3%E5%BB%B3%E9%95%B7%E5%AE%98%E8%88%8D_%283%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96%E5%BB%B3%E5%BB%B3%E9%95%B7%E5%AE%98%E8%88%8D_(3).jpg","artist":"Jimmy Yao from Taipei, Taiwan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/magong-tingtingzhangguan-0.webp","small":"img/magong-tingtingzhangguan-0-s.webp"}]},{"id":"huxi-dachengbeilindeng","name":"大城北林登豫古宅","short":"林登豫古宅","category":"歷史建築","level":"","town":"湖西鄉","types":["宅第"],"lat":23.565162,"lng":119.624999,"address":"澎湖縣湖西鄉城北村50號","announced":"2012-02-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20120208000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1260/photo/城北林登豫古宅1.JPG","year":1935,"yearText":"約1930年代（日治時期）","era":"japan","themes":["咕咾石古厝","防空設施"],"yearUnknown":false,"summary":"後院藏防空壕的日治時期四櫸頭古厝","intro":"大城北林登豫古宅位於湖西鄉城北村，是日治時期興建的傳統古厝，格局為前有磚坪的四櫸頭。因興建時正逢戰時，屋後高丘設有防空襲避難用的防空壕；建築右側空地原有豬稠、牛稠，反映當時的農家生活。古宅融合澎湖傳統建築與日治時期引進的歐風工法，亭與前磚坪以玄武岩鋪砌，深井周邊以形狀自然的大石鋪面，中庭屏堵用洗石子刻出八達龜殼紋，窗戶花磚與中庭儲水槽也都保存下來。左右兩側立面一側開窗、一側不開，看得出使用需求對建築的影響。2012年登錄為歷史建築，2013年修復。","highlights":["屋後高丘的日治時期防空壕","中庭屏堵洗石子八達龜殼紋","深井周圍不規則玄武岩大石鋪面"],"funFact":"古宅左右兩側立面一邊開窗、一邊不開窗，是依照周邊使用需求調整的設計。","photoSpot":"在中庭拍龜殼紋屏堵與玄武岩鋪面","visitMin":25,"openNote":"位於湖西鄉城北村，官方資料為每週三09:00–12:00、13:00–17:00開放，出發前請向澎湖縣政府文化局確認；其他時間請在外觀參觀，勿擅入。","dialogue":[{"who":"A","text":"阿拉蕾，參觀古厝先別急著進門，你看後面那個小山丘。"},{"who":"R","text":"小山丘有什麼好看？上面有寶藏嗎？"},{"who":"A","text":"有一座防空壕！這間古宅是日治時期戰時蓋的，屋主乾脆在後院高丘挖了避難的地方。"},{"who":"R","text":"自備防空壕，這是古代的安全屋吧！"},{"who":"A","text":"旁邊空地以前還有豬稠和牛稠，就是豬舍和牛舍，很有農家生活感。房子左右兩側還一邊開窗、一邊不開呢。"},{"who":"R","text":"那屋子裡面，有什麼特別的裝飾可以看？"},{"who":"A","text":"中庭屏堵用洗石子刻出八達龜殼紋，深井周圍鋪著形狀自然的玄武岩大石，像拼圖一樣。"},{"who":"R","text":"龜殼紋配防空壕，這間房子把長壽和保命都包了！"},{"who":"A","text":"說得好！到中庭數數看，龜殼紋一共有幾格，再找找儲水槽在哪裡。"}],"clues":["我的後院高丘上有一座戰時防空壕","我的中庭屏堵刻著八達龜殼紋","城北村的日治時期四櫸頭古厝，旁邊原有豬稠牛稠"],"quiz":[{"q":"古宅屋後的高丘上有什麼設施？","options":["燈塔","水井","防空壕","砲台"],"answer":2,"explain":"興建時適逢戰時，後院高丘設有防空壕。"},{"q":"中庭屏堵以洗石子刻了什麼紋樣？","options":["回字紋","八達龜殼紋","卍字紋","蝙蝠紋"],"answer":1,"explain":"中庭屏堵以洗石子刻八達龜殼紋。"}],"images":[]},{"id":"magong-houkutanlvshijiegu","name":"後窟潭呂石碣古厝","short":"呂石碣古厝","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.584123,"lng":119.569305,"address":"澎湖縣馬公市重光里90號","announced":"2010-11-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20101109000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/2298/photo/321b3d2d-f145-4fb6-97a5-50be8930bc43.JPG","year":1938,"yearText":"日治末期（約1930年代）","era":"japan","themes":["宅第家族","戰爭史蹟"],"yearUnknown":false,"summary":"側門留著彈痕、裝飾華麗的日治古厝","intro":"後窟潭呂石碣古厝位於馬公市重光里（舊稱後窟潭），2010年登錄為歷史建築。古厝建於日治末期，是當時土水名師「開通師」的作品，屬於四櫸頭民宅，融合傳統格局與日治時期的材料工法。八卦樓加前磚坪、間仔磚坪加高欄杆的作法，在當時馬公地區相當特殊；前磚坪周邊有預鑄水泥欄杆，牆頂貼釉花磚，大廳正面壁保有傳統彩繪，大廳地面以朱砂擬油面磚工法鋪設，大厝身的「安地磚」尤具特色。東面側門圓拱留有子彈痕跡，是馬公戰史的見證。目前不開放參觀。","highlights":["東面側門圓拱上的子彈痕跡","牆頂釉花磚與預鑄水泥欄杆","八卦樓加前磚坪的特殊作法"],"funFact":"同一棟古厝裡，彩繪磁磚同時用了釉上彩和釉下彩兩種技法，裝飾相當講究。","photoSpot":"從巷道外觀拍牆頂釉花磚","visitMin":10,"openNote":"位於馬公市重光里，屬私人古厝，官方資料標示不開放。請在外觀參觀，勿擅入私人住宅、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"A","text":"有些古厝是屋主自己動手蓋，這一間可是請到當年的土水名師開通師出手。"},{"who":"R","text":"開通師？聽起來像會幫人開運的老師耶！"},{"who":"A","text":"他開的是房子不是運啦！這間後窟潭呂石碣古厝建於日治末期，就是他的作品。"},{"who":"R","text":"名師作品耶，有什麼招牌設計嗎？"},{"who":"A","text":"八卦樓加前磚坪、間仔磚坪再加高欄杆，在當時的馬公很少見，牆頂還貼了漂亮的釉花磚。"},{"who":"R","text":"聽起來好華麗！那它有沒有什麼驚險的故事？"},{"who":"A","text":"有。東面側門的圓拱上留有子彈痕，官方說它是馬公戰史的見證。"},{"who":"R","text":"美麗的房子帶著傷痕，讓人看了很有感觸。"},{"who":"A","text":"這是私人古厝，目前不開放。我們在巷道外看看就好，找找牆頂那一排釉花磚有哪些顏色吧！"}],"clues":["我的東側門圓拱上留著子彈痕","我是土水名師「開通師」的作品","我是重光里後窟潭的日治末期四櫸頭古厝"],"quiz":[{"q":"呂石碣古厝是哪一位土水名師的作品？","options":["謝江","藍木","陳恭","開通師"],"answer":3,"explain":"建築本體為當時土水名師「開通師」的作品。"},{"q":"古厝東面側門的圓拱上留有什麼？","options":["題字詩句","子彈痕跡","洪水水位線","工匠落款"],"answer":1,"explain":"東面側門圓拱的子彈痕，是馬公戰史見證。"}],"images":[]},{"id":"magong-jimuwuguzhai","name":"雞母塢古宅","short":"雞母塢古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.528872,"lng":119.586073,"address":"澎湖縣馬公市五德里雞母塢77之8號","announced":"2008-07-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20080704000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/38591/photo/T035澎湖縣雞母塢古宅(歷建)(2).JPG","year":1938,"yearText":"1938年（昭和13年）","era":"japan","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"傳統格局融入混凝土屋頂與水泥塑模窗","intro":"雞母塢古宅位於馬公市五德里雞母塢，建於1938年（昭和13年），原屬歐陽家族所有，是傳統形式融合近代構造材料的民宅。它保有澎湖傳統民宅的特色，同時引進西式建築技術，可以看到混凝土灌漿屋頂、水泥屋瓦與水泥塑模窗，建築形式為「前磚坪」。2007年古宅經法院拍賣易主，新屋主有感老屋長年閒置、損壞嚴重，為讓文化資產風華再現，主動向文化局提報，2008年登錄為歷史建築，並獲澎湖縣傳統古厝維護及再利用獎助計畫補助修復。","highlights":["混凝土灌漿屋頂與水泥屋瓦","水泥塑模窗","前磚坪的建築形式"],"funFact":"這間古厝是新屋主買下後，自己向文化局提報登錄為歷史建築的。","photoSpot":"在屋前拍水泥塑模窗與前磚坪","visitMin":20,"openNote":"位於馬公市五德里雞母塢。官方資料標示每週六及週日下午2時至6時開放，實際以現場公告為準；其餘時間請在外觀參觀，勿擅入私人住宅。建議騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，雞母塢這個地名，是不是聽起來就很想去撿雞蛋？"},{"who":"R","text":"對啊！聽名字我還以為這裡是一座養雞場呢！"},{"who":"A","text":"名字很可愛吧，不過今天不撿雞蛋，是來看1938年蓋的雞母塢古宅。"},{"who":"R","text":"好吧，那這間古宅跟其他古厝哪裡不一樣？"},{"who":"A","text":"它保留澎湖傳統民宅格局，卻用上新材料，混凝土灌漿屋頂、水泥屋瓦，連窗戶都是水泥塑模。"},{"who":"R","text":"等於穿著傳統服裝，腳上卻踩著新款球鞋！"},{"who":"A","text":"形容得好！而且2007年它被拍賣，新屋主不嫌老屋破舊，還主動提報成歷史建築。"},{"who":"R","text":"新屋主好有心喔，那我們到現場要怎麼欣賞它？"},{"who":"A","text":"開放時段到屋前，找找水泥塑模窗的花樣，再看看屋前的磚坪長什麼樣子！"}],"clues":["我被法院拍賣後，新屋主主動提報我登錄","我的窗戶是水泥塑模，屋頂是混凝土灌漿","五德里一座1938年興建的前磚坪古厝"],"quiz":[{"q":"古宅的窗戶採用什麼工法？","options":["木雕花窗","鐵窗花","水泥塑模窗","彩色玻璃窗"],"answer":2,"explain":"古宅可見水泥塑模窗，融入近代材料。"},{"q":"這座古宅原本屬於哪一個家族？","options":["陳氏家族","許氏家族","洪氏家族","歐陽家族"],"answer":3,"explain":"原為歐陽家族所有，2007年經法院拍賣易主。"}],"images":[{"file":"雞母塢古宅 peiiunwu (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/%E9%9B%9E%E6%AF%8D%E5%A1%A2%E5%8F%A4%E5%AE%85_peiiunwu_%28cropped%29.jpg/960px-%E9%9B%9E%E6%AF%8D%E5%A1%A2%E5%8F%A4%E5%AE%85_peiiunwu_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%9B%9E%E6%AF%8D%E5%A1%A2%E5%8F%A4%E5%AE%85_peiiunwu_(cropped).jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-jimuwuguzhai-0.webp","small":"img/magong-jimuwuguzhai-0-s.webp"}]},{"id":"magong-taiwanzongdufu","name":"臺灣總督府專賣局澎湖出張所","short":"專賣局澎湖出張所","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.567846,"lng":119.563931,"address":"澎湖縣馬公市民生路42號","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-10-26/1ad14b1d-3bf9-4a67-b3e1-6210de02be9c/台灣總督府專賣局澎湖出張所.jpg","year":1939,"yearText":"1939年（昭和14年）遷入現址","era":"japan","themes":["日式建築","產業遺產","公共建築"],"yearUnknown":false,"summary":"馬蹄形入口的菸酒專賣老廳舍","intro":"臺灣總督府專賣局澎湖出張所位於馬公市民生路。出張所於1922年（大正11年）成立，附設在澎湖廳財務課之下，除了菸、酒，也販售鹽、油、火柴與樟腦油等日常必需品；1939年（昭和14年）遷入現址，並逐年增建倉庫。戰後1946年由政府接收，歷經省專賣局澎湖辦事處、菸酒公賣局澎湖營業所、辦事處與分局等改制，菸酒民營化後由台灣菸酒公司使用。建築正面中央為兩層樓的圓形主體，入口呈半圓馬蹄形，兩翼為一層樓，讓圓形主體成為視覺焦點；後方有酒類與菸草倉庫，另有防空洞、圍牆與日式庭院。","highlights":["正面中央兩層樓圓形主體與馬蹄形入口","南翼酒類倉庫與北翼菸草倉庫","附屬防空洞與日式庭院"],"funFact":"日治時期的專賣局除了菸酒，還賣鹽、油、火柴和樟腦油，像一間官方雜貨店。","photoSpot":"在民生路對面拍圓形主體與馬蹄形入口","visitMin":10,"openNote":"位於馬公市民生路。官方資料為外貌參觀；正面圓形主體因內部破損嚴重不開放進入，兩側建築暫作倉庫使用，請勿擅入。附近有西瀛勝境牌樓、第三水源地配水塔，可步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，你看這棟建築正中間圓圓鼓起來，像不像一個大酒桶？"},{"who":"R","text":"有點像！而且門口是半圓形的，好像一塊馬蹄鐵。"},{"who":"A","text":"很接近，這就叫馬蹄形入口。這裡是日治時期的專賣局澎湖出張所，1939年搬來這裡。"},{"who":"R","text":"專賣局聽起來很威風，它是專門賣什麼東西的？"},{"who":"A","text":"菸和酒之外，還賣鹽、油、火柴和樟腦油，簡直是官方開的柑仔店。"},{"who":"R","text":"那主體後面那幾棟長長的房子，又是做什麼用的？"},{"who":"A","text":"南翼是酒類倉庫，北翼是菸草倉庫，戰後改成菸酒公賣局，現在由台灣菸酒公司使用。"},{"who":"R","text":"菸跟酒還分開住，這樣就不會吵架了！"},{"who":"A","text":"中間的圓形主體內部破損，目前不開放，請你在對街找找圓形主體二樓的窗戶是什麼形狀！"}],"clues":["我日治時期除了菸酒，也賣鹽、油、火柴和樟腦油","我的南翼放酒、北翼放菸草","民生路上中央圓形主體、入口像馬蹄的專賣廳舍"],"quiz":[{"q":"出張所正面中央的入口是什麼形狀？","options":["尖拱形","馬蹄形","八角形","方形"],"answer":1,"explain":"正面中央出入口設計為半圓形的馬蹄形。"},{"q":"出張所北翼的倉庫原本存放什麼？","options":["菸草","鹽","樟腦油","米糧"],"answer":0,"explain":"南翼為酒類倉庫，北翼為菸草倉庫。"}],"images":[{"file":"台灣總督府專賣局澎湖出張所 peiiunwu (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/%E5%8F%B0%E7%81%A3%E7%B8%BD%E7%9D%A3%E5%BA%9C%E5%B0%88%E8%B3%A3%E5%B1%80%E6%BE%8E%E6%B9%96%E5%87%BA%E5%BC%B5%E6%89%80_peiiunwu_%28cropped%29.jpg/960px-%E5%8F%B0%E7%81%A3%E7%B8%BD%E7%9D%A3%E5%BA%9C%E5%B0%88%E8%B3%A3%E5%B1%80%E6%BE%8E%E6%B9%96%E5%87%BA%E5%BC%B5%E6%89%80_peiiunwu_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%B0%E7%81%A3%E7%B8%BD%E7%9D%A3%E5%BA%9C%E5%B0%88%E8%B3%A3%E5%B1%80%E6%BE%8E%E6%B9%96%E5%87%BA%E5%BC%B5%E6%89%80_peiiunwu_(cropped).jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-taiwanzongdufu-0.webp","small":"img/magong-taiwanzongdufu-0-s.webp"}]},{"id":"baisha-zhenhaizhangyuangu","name":"鎮海長源古宅","short":"長源古宅","category":"歷史建築","level":"","town":"白沙鄉","types":["宅第"],"lat":23.643557,"lng":119.5994,"address":"澎湖縣白沙鄉鎮海村18號","announced":"2011-03-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110321000002","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1277/photo/鎮海長源古宅1.jpg","year":1939,"yearText":"1939年（昭和14年）整修成今貌","era":"japan","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"臺南皮革商返鄉整修的日治民宅經典","intro":"鎮海長源古宅位於白沙鄉鎮海村，是陳家的祖厝。陳雅的長子陳長源到臺南經營皮革原料「長源商行」有成，1939年（昭和14年）返鄉修復祖厝，請中屯匠師依原格局整修：大廳泥地改鋪尺二磚，櫸頭的瓦作斜屋頂改為磚坪，灶台改為磚砌，並加建半樓。長條玄武岩過樑、門臼柱礎等石作也出自在地匠師之手。屋頂花磚為澎湖民間製作，六角窗與可收藏農作物的半樓糧倉很有特色，屋內還留有日治時期的神主牌。1986年韋恩颱風後大厝身屋頂改為水泥瓦，2011年登錄為歷史建築並完成修復，呈現傳統工法過渡到近代材料的融合。","highlights":["澎湖民間製作的精緻屋頂花磚","六角窗與可收藏農作物的半樓糧倉","長條玄武岩過樑與門臼柱礎石作"],"funFact":"古宅加建的半樓兼作糧倉，可以收藏農作物，是1939年整修時才加上去的。","photoSpot":"拍六角窗與咕咾石牆面","visitMin":25,"openNote":"位於白沙鄉鎮海村。依官方資料，每週六、日上午9時至12時、下午2時至5時開放，實際開放情形請以現場公告為準；其他時間請在外觀參觀、勿擅入。從馬公經中正橋、永安橋開車或騎機車可達白沙，也可搭澎湖縣公車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你知道澎湖人到臺南打拚，賺了錢常常第一件事做什麼嗎？"},{"who":"R","text":"買一大堆臺南小吃回來？那是你吧，Allan！"},{"who":"A","text":"被你說中一半。長源古宅的主人陳長源，在臺南做皮革原料生意成功，1939年回鄉修祖厝。"},{"who":"R","text":"衣錦還鄉！那他怎麼改造老房子？"},{"who":"A","text":"大廳泥地改鋪尺二磚，灶台改成磚砌，還加蓋一層半樓，可以收藏農作物。"},{"who":"R","text":"半樓當糧倉，等於老房子加裝儲藏室，好實用！"},{"who":"A","text":"屋頂花磚是澎湖民間做的，很細緻，還有六角窗。傳統跟近代工法在這裡混搭得剛剛好。"},{"who":"R","text":"那什麼時候可以進去裡面參觀呢？"},{"who":"A","text":"官方資料是週末開放，出發前先確認。進去後找一找那扇六角窗，從窗裡往外拍一張！"}],"clues":["我的主人在臺南經營皮革原料生意","我在1939年整修，加了半樓糧倉與磚砌灶台","我在白沙鄉鎮海村，名字取自主人的商行字號"],"quiz":[{"q":"陳長源在臺南經營哪一類生意有成？","options":["皮革原料","中藥材","布匹","漁貨"],"answer":0,"explain":"他在臺南經營皮革原料「長源商行」有成。"},{"q":"1939年整修時，古宅加建了什麼空間？","options":["地下室","洋樓陽台","半樓","防空洞"],"answer":2,"explain":"整修時加建半樓，可收藏農作物。"}],"images":[{"file":"鎮海長源古宅 peiiunwu (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/%E9%8E%AE%E6%B5%B7%E9%95%B7%E6%BA%90%E5%8F%A4%E5%AE%85_peiiunwu_%28cropped%29.jpg/960px-%E9%8E%AE%E6%B5%B7%E9%95%B7%E6%BA%90%E5%8F%A4%E5%AE%85_peiiunwu_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%8E%AE%E6%B5%B7%E9%95%B7%E6%BA%90%E5%8F%A4%E5%AE%85_peiiunwu_(cropped).jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/baisha-zhenhaizhangyuangu-0.webp","small":"img/baisha-zhenhaizhangyuangu-0-s.webp"}]},{"id":"magong-jingantujiaociqi","name":"井垵凸角磁氣探知機防備衛所","short":"井垵磁氣探知衛所","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.509758,"lng":119.572889,"address":"澎湖縣馬公市井垵東段795地號","announced":"2019-05-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190618000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2019-06-18/cf926672-6547-4340-9e90-cfb694110811/IMG_0911.jpg","year":1940,"yearText":"日治時期（確切年代不詳）","era":"japan","themes":["軍事遺構","戰爭史蹟"],"yearUnknown":false,"summary":"井垵海岸凸角上的日治軍事衛所","intro":"井垵凸角磁氣探知機防備衛所位於馬公市井垵里海岸的凸角地帶，是日治時期軍事設施的舊址，2019年登錄為歷史建築。從名稱看，它是為防備、守護磁氣探知設備而設的衛所，這類設備一般用來探測經過海域的金屬船艦。建物牆身以石材砌造，屋頂為鋼筋混凝土拱頂，工法細緻，構造與形式保存完整，具建築技術史價值。它也見證了二戰時期到國軍接手後，澎湖海岸防禦要塞的延續。官方公開史料有限，確切興建年代與原本配置仍待進一步研究，目前不開放參觀。","highlights":["砌石牆身搭配鋼筋混凝土拱頂","位在海岸凸角地形上的防備位置","見證日治到國軍時期海防的延續"],"funFact":"它的正式名稱有13個字，從地名、地形、設備到用途全寫進去，像一張濃縮的說明書。","photoSpot":"在公共道路遠拍海岸與衛所外觀","visitMin":10,"openNote":"位於馬公市井垵里海岸一帶，官方資料標示不開放，請勿擅入或攀爬，只能在公共道路遠觀；若有管制標示請遵守。建議騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，下一個地方的名字好長，井垵凸角磁氣探知機防備衛所，我差點斷氣。"},{"who":"A","text":"13個字一口氣念完，肺活量可以去考潛水執照了！不過拆開來看就懂了。"},{"who":"R","text":"那請Allan老師逐字翻譯一下。"},{"who":"A","text":"井垵是地名，凸角是海岸突出的地形，磁氣探知機是探測海上金屬船艦的設備，衛所就是守護它的小據點。"},{"who":"R","text":"原來名字就是說明書！那它是什麼時候蓋的？"},{"who":"A","text":"它是日治時期的軍事設施，確切年代的史料不多。牆是砌石造，屋頂是鋼筋混凝土拱頂，工法很細。"},{"who":"R","text":"那戰爭結束以後，它就沒人用了嗎？"},{"who":"A","text":"國軍接著使用，見證澎湖海防從日治到戰後的延續。目前不開放，我們在路邊遠遠看就好。"},{"who":"R","text":"收到！那我從遠處找找看，它的拱形屋頂有沒有露出來。"}],"clues":["我的名字有13個字，像一張說明書","我的牆身砌石、屋頂是混凝土拱頂","我是井垵海岸凸角上的日治軍事衛所"],"quiz":[{"q":"名稱中的「凸角」指的是什麼？","options":["海岸突出的地形","屋頂的形狀","砲台的編號","廟宇的方位"],"answer":0,"explain":"凸角指海岸向外突出的地形。"},{"q":"這座衛所的屋頂是哪一種構造？","options":["茅草屋頂","鋼筋混凝土拱頂","紅瓦斜屋頂","鐵皮平頂"],"answer":1,"explain":"牆為砌石造，屋頂為鋼筋混凝土拱頂。"}],"images":[]},{"id":"magong-yiyuanfangkongdong","name":"澎湖醫院防空洞","short":"澎湖醫院防空洞","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.564556,"lng":119.565401,"address":"澎湖縣馬公市中正路10號","announced":"2013-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20131011000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-12-12/ff04210c-d5d7-45f0-a24e-bc13b9a4d506/S__102694943.jpg","year":1940,"yearText":"1940年（昭和15年）","era":"japan","themes":["防空設施"],"yearUnknown":false,"summary":"醫院地底下可當臨時醫療中心的防空洞","intro":"澎湖醫院防空洞位於馬公市中正路的澎湖醫院院區內。1940年（昭和15年）建造第一代洞窟式地下防空洞，可容納當時的醫護人員與病患，用來躲避戰時轟炸，也能透過地下通道疏散病人。1958年（民國47年）進行第二代整建，擴大地洞容積，約可容納百人。地道以水泥壁面延伸，設有地面出入口，洞內保留傳聲孔、通氣孔、病床與告示牌，必要時可作為臨時醫療中心，見證戰時的醫療與生活場景，官方認為極為特殊。2013年登錄為歷史建築，目前以外貌參觀為主。","highlights":["洞內的傳聲孔與通氣孔","可當臨時醫療中心的病床與告示牌","1940年與1958年兩代防空洞工程"],"funFact":"這座防空洞不只用來躲空襲，洞裡還擺了病床，等於一間藏在地底的備用醫院。","photoSpot":"在出入口外拍防空洞外觀，勿擋醫院動線","visitMin":15,"openNote":"位於馬公市中正路澎湖醫院院區內。官方資料為外貌參觀，請勿擅入防空洞，並保持安靜、不要妨礙病患與醫護人員。從馬公市區步行可到。","dialogue":[{"who":"R","text":"Allan，我們來醫院做什麼？你哪裡不舒服嗎？"},{"who":"A","text":"我健康得很！今天要看的是醫院地底下的防空洞，1940年就挖好了。"},{"who":"R","text":"醫院也要躲空襲喔？病人不是很難移動嗎？"},{"who":"A","text":"當然，戰時醫護人員和病患都要避難，還能從地下通道把病人疏散出去。"},{"who":"R","text":"那大家躲進去以後，病人還能繼續接受治療嗎？"},{"who":"A","text":"1958年擴建成第二代，約可容納百人，裡面有病床和告示牌，可以當臨時醫療中心。"},{"who":"R","text":"我還聽說裡面有傳聲孔，是古早的地下對講機嗎？"},{"who":"A","text":"差不多，不用插電的那種，傳得比Allan的冷笑話還遠，還有通氣孔讓空氣流通。"},{"who":"R","text":"我到現場要找到防空洞的出入口，不過在醫院裡記得輕聲細語！"}],"clues":["我的洞裡有傳聲孔、通氣孔和病床","我1940年挖成，1958年擴建到可容納約百人","藏在中正路醫院地底的戰時避難空間"],"quiz":[{"q":"1958年整建後，防空洞約可容納多少人？","options":["約20人","約50人","約百人","約500人"],"answer":2,"explain":"第二代防空洞擴增容積，約可容納百人。"},{"q":"防空洞內保留哪一種設施，可當臨時醫療中心？","options":["手術燈塔","病床與告示牌","藥品倉庫","發電機房"],"answer":1,"explain":"洞內有病床、告示牌、傳聲孔與通氣孔。"}],"images":[]},{"id":"huxi-zhaoribeikougong","name":"湖西朝日貝釦工廠","short":"朝日貝釦工廠","category":"歷史建築","level":"","town":"湖西鄉","types":["其他設施"],"lat":23.582913,"lng":119.638825,"address":"澎湖縣湖西鄉西溪村101號","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000008","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1273/photo/湖西朝日貝釦工廠1.jpg","year":1940,"yearText":"1940年（昭和15年）","era":"japan","themes":["產業遺產"],"yearUnknown":false,"summary":"用鐘螺殼做鈕釦的日治時期工廠","intro":"湖西朝日貝釦工廠位於湖西鄉西溪村，建於昭和15年（1940），由陳松柏、陳松林兄弟開設，以鐘螺殼為原料加工成鈕釦。二戰後與父親陳第創立的成吉製油所合併，改名「大光工業社」。1956年以後，貝殼鈕釦逐漸被國外的塑膠仿製品取代；1964年起配合鼓勵日商投資，聘請3位日本技師前來研發珊瑚加工並直接外銷，成為澎湖傳統產業發展的代表。建築以硓𥑮石與石灰砌牆、水泥粉光，牆邊以西溪石疊砌，中間是四坡的「興亞式」屋頂、兩側為兩坡，入口是折衷式的立方體突出造型。屋內仍留有鈕釦生產機具與製油時期的大型儲油鐵桶。","highlights":["中間四坡興亞式、兩側兩坡的組合屋頂","立方體突出的折衷式入口","留存的鐘螺殼鈕釦加工機具與儲油鐵桶"],"funFact":"以前的鈕釦是用鐘螺殼一顆顆加工出來的，後來被塑膠仿貝殼鈕釦打敗。","photoSpot":"在路旁拍正面立方體入口與屋頂線","visitMin":10,"openNote":"位於湖西鄉西溪村，官方資料為不開放，請在外觀參觀，勿擅入。可從馬公開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，你襯衫上的鈕釦好亮，是貝殼做的嗎？"},{"who":"A","text":"這是塑膠的啦。不過在湖西鄉西溪村，1940年就有一間工廠專門用鐘螺殼做鈕釦。"},{"who":"R","text":"用海螺殼做鈕釦？那穿在身上會不會聽到海浪聲？"},{"who":"A","text":"哈哈，想像力滿分。工廠是陳松柏、陳松林兄弟開的，戰後和爸爸的製油所合併成大光工業社。"},{"who":"R","text":"那後來這間工廠，怎麼就不做鈕釦了？"},{"who":"A","text":"1956年以後被國外的塑膠仿貝殼鈕釦取代，1964年起又請日本技師來研發珊瑚加工外銷。"},{"who":"R","text":"從貝殼轉珊瑚，這轉型速度比我換手機殼還快！"},{"who":"A","text":"建築本身也很有看頭，你在外面看看，中間和兩側的屋頂斜面數量是不是不一樣，再找找立方體突出的入口！"}],"clues":["我曾把鐘螺殼加工成鈕釦","戰後我和製油所合併，改名大光工業社","1940年西溪村陳氏兄弟開設的貝殼鈕釦工廠"],"quiz":[{"q":"朝日貝釦工廠用什麼原料做鈕釦？","options":["牛角","椰子殼","鐘螺殼","珍珠母貝"],"answer":2,"explain":"以鐘螺殼為原料加工成鈕釦。"},{"q":"1964年起工廠聘請日本技師研發什麼加工？","options":["珊瑚加工","海鹽精製","魚乾製作","玻璃燒製"],"answer":0,"explain":"聘請3位日本技術師研發珊瑚加工並直接外銷。"}],"images":[{"file":"湖西朝日貝釦工廠 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/%E6%B9%96%E8%A5%BF%E6%9C%9D%E6%97%A5%E8%B2%9D%E9%87%A6%E5%B7%A5%E5%BB%A0_peiiunwu.jpg/960px-%E6%B9%96%E8%A5%BF%E6%9C%9D%E6%97%A5%E8%B2%9D%E9%87%A6%E5%B7%A5%E5%BB%A0_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%B9%96%E8%A5%BF%E6%9C%9D%E6%97%A5%E8%B2%9D%E9%87%A6%E5%B7%A5%E5%BB%A0_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/huxi-zhaoribeikougong-0.webp","small":"img/huxi-zhaoribeikougong-0-s.webp"}]},{"id":"magong-gongmaijubeicefang","name":"澎湖公賣局北側防空壕","short":"公賣局防空壕","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.568551,"lng":119.564249,"address":"澎湖縣馬公市民族路、介壽路和民生路交會三角地帶，介於菸酒公司與中正堂之間","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-04/29b348d9-0d7a-449c-85d7-e6b58f8aec99/澎湖公賣局北側防空壕.jpg","year":1941,"yearText":"1941年（昭和16年）","era":"japan","themes":["防空設施","戰爭史蹟"],"yearUnknown":false,"summary":"水泥涵管加玄武岩擋牆的二戰防空壕","intro":"澎湖公賣局北側防空壕位於馬公市民族路、介壽路與民生路交會的三角地帶，介於菸酒公司與中正堂之間。它建於昭和16年（1941），是二戰期間日軍大規模興建的防空避難設施之一，當時位在臺灣總督府專賣局澎湖出張所旁，供出張所人員避難使用。主體是一條長4.8公尺、直徑1.5公尺的圓形水泥涵管，上方及左右砌有約60公分厚的石塊護牆，再覆土種植草木；出入口前後兩側以黑色玄武岩疊砌擋牆，阻擋砲彈碎片。內部約可容納15到20人，外貌樸實，2003年登錄為歷史建築。","highlights":["長4.8公尺、直徑1.5公尺的圓形水泥涵管主體","出入口兩側擋砲彈碎片的玄武岩矮牆","上方覆土、長滿草木的頂部"],"funFact":"這座防空壕的主體其實是一根長4.8公尺的水泥涵管，裡面約可容納15到20人。","photoSpot":"在出入口前拍玄武岩擋牆與涵管","visitMin":10,"openNote":"位於馬公市民族路、介壽路與民生路交會的三角地帶，全天開放的戶外空間。位在車流較多的路口，請注意交通安全。鄰近第一賓館與觀音亭，可步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，看到路口那座長滿草的小土丘了嗎？它不是花圃，是1941年的防空壕。"},{"who":"R","text":"防空壕？Allan，它看起來好小，躲得進去嗎？"},{"who":"A","text":"裡面大約可以容納15到20個人。主體是一根將近5公尺長、直徑1公尺半的水泥涵管。"},{"who":"R","text":"所以大家是躲進一根大水管裡？好像一條巨大的竹輪！"},{"who":"A","text":"形容得太好吃了！涵管上方和兩側砌了約60公分厚的石牆，再蓋土種草。"},{"who":"R","text":"那門口那兩道矮牆又是做什麼的？"},{"who":"A","text":"那是玄武岩砌的擋牆，用來擋住從兩側飛來的砲彈碎片。這裡原本是給專賣局出張所員工避難用的。"},{"who":"R","text":"想到當年躲空襲的人，就覺得這個小土丘一點都不輕鬆。"},{"who":"A","text":"是啊。走到出入口前，看看那道玄武岩矮牆是怎麼擋在門口的，拍張照記下這段歷史。"}],"clues":["我的身體是一根直徑1.5公尺的水泥涵管","我原本是給專賣局出張所員工避難用的","介壽路、民族路口長滿草的二戰避難設施"],"quiz":[{"q":"公賣局北側防空壕的主體結構是什麼？","options":["木造地下室","鐵皮貨櫃","圓形水泥涵管","磚砌拱窖"],"answer":2,"explain":"主體是一條長4.8公尺、直徑1.5公尺的水泥涵管。"},{"q":"防空壕出入口兩側的矮牆主要用途是？","options":["阻擋砲彈碎片","擋住海風","當作座椅","標示路線"],"answer":0,"explain":"出入口兩側砌石堆擋牆，阻擋砲彈碎片。"}],"images":[{"file":"澎湖公賣局北側防空壕 peiiunwu (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/%E6%BE%8E%E6%B9%96%E5%85%AC%E8%B3%A3%E5%B1%80%E5%8C%97%E5%81%B4%E9%98%B2%E7%A9%BA%E5%A3%95_peiiunwu_%28cropped%29.jpg/960px-%E6%BE%8E%E6%B9%96%E5%85%AC%E8%B3%A3%E5%B1%80%E5%8C%97%E5%81%B4%E9%98%B2%E7%A9%BA%E5%A3%95_peiiunwu_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96%E5%85%AC%E8%B3%A3%E5%B1%80%E5%8C%97%E5%81%B4%E9%98%B2%E7%A9%BA%E5%A3%95_peiiunwu_(cropped).jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-gongmaijubeicefang-0.webp","small":"img/magong-gongmaijubeicefang-0-s.webp"}]},{"id":"baisha-chengqianxiaoshi","name":"城前蕭氏前原居古宅","short":"城前蕭氏古宅","category":"歷史建築","level":"","town":"白沙鄉","types":["宅第"],"lat":23.626304,"lng":119.596377,"address":"澎湖縣白沙鄉城前村301-1地號上傳統建築","announced":"2013-08-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20130821000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1281/photo/城前蕭氏前原居古宅1.jpg","year":1942,"yearText":"二戰期間（約1940年代）","era":"japan","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"門聯藏著村子日治舊名「前原」的古宅","intro":"城前蕭氏前原居古宅位於白沙鄉城前村，由蕭補（1913–2004）在二戰期間興建，他是城前村第一位通過日本警察考試的人；戰後國軍曾在這裡駐紮救護連。古宅本體是典型三合院，又融入日治時期的改良作法：楹仔用方材，廳與亭之間的水槽樑直接架在大廳正面壁上。青斗石門框刻有門聯「前向青山光振家聲遠，原披綠野裕貽世澤長」，兩句開頭合起來就是城前在日治時期的地名「前原」。中軸線上的門比一般民宅大、房間門窗較小；水井以洗石子做出八卦圖像，廚房內外都能取水；屋頂鋪尺磚，可曝曬米糧與漁獲。2013年登錄為歷史建築。","highlights":["藏頭「前原」二字的青斗石門聯","洗石子八卦圖像水井，廚房內外都能取水","可曬米糧漁獲的尺磚屋頂"],"funFact":"門聯上下聯第一個字是「前」和「原」，正好是城前村在日治時期的舊地名。","photoSpot":"在屋外拍大門與青斗石門框","visitMin":10,"openNote":"位於白沙鄉城前村，從馬公經中正橋、永安橋可開車或騎機車抵達。官方資料為不開放，目前閒置，請在外觀參觀、勿擅入私人住宅。","dialogue":[{"who":"A","text":"阿拉蕾，考你一題藏頭詩，前向青山光振家聲遠，原披綠野裕貽世澤長。"},{"who":"R","text":"藏頭？第一個字是前跟原，前原是什麼？某個人的名字嗎？"},{"who":"A","text":"是地名！城前村在日治時期就叫前原，屋主把村名藏進大門門聯，兩句開頭合起來就是前原。"},{"who":"R","text":"好有心機，這是古早版的地址自我介紹吧！"},{"who":"A","text":"屋主蕭補是城前村第一位通過日本警察考試的人，二戰期間蓋了這間房子。"},{"who":"R","text":"那戰後呢？還是他們家自己住嗎？"},{"who":"A","text":"戰後國軍曾把這裡當救護連的駐地。屋頂鋪尺磚，以前還能曬米和魚乾。"},{"who":"R","text":"屋頂兼曬穀場，一屋多用，超級省空間！"},{"who":"A","text":"這是私人古宅，請在外面看。你到大門前，找找上下聯的第一個字，親眼看看前原藏在哪裡！"}],"clues":["我的門聯把村子的日治舊地名藏在開頭","戰後國軍曾在我這裡駐紮救護連","白沙鄉城前村，由第一位考上日本警察的村民所建"],"quiz":[{"q":"門聯藏頭的「前原」是什麼？","options":["屋主的名字","城前村的日治舊地名","一座廟名","一艘船名"],"answer":1,"explain":"前原是城前在日治時期的地名。"},{"q":"戰後國軍曾把這間古宅作為什麼用途？","options":["彈藥庫","通訊站","軍官宿舍","救護連駐地"],"answer":3,"explain":"二戰後曾由國軍徵召為救護連駐紮地。"}],"images":[]},{"id":"magong-suogangxujiandugu","name":"鎖港許監督古宅","short":"鎖港許監督古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.524674,"lng":119.600078,"address":"澎湖縣馬公市鎖港里1237號","announced":"2014-09-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140911000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-11/fbbc05af-4d59-4795-9e5f-12d30c35f42f/圖像.jpg","year":1944,"yearText":"1944年（昭和19年）","era":"japan","themes":["咕咾石古厝","宅第家族","防空設施"],"yearUnknown":false,"summary":"偏間地下藏著S型防空壕的澎南古厝","intro":"鎖港許監督古宅位於馬公市鎖港里，由許氏家族興建，官方資料記載建於1944年（昭和19年）二戰末期，與左右兩棟古厝同一時期建造，工法與飾件風格相近，展現手足相親、共榮共生的家族紋理。建築坐北朝南，以硓𥑮石為主建材，厝角、過路、門豎佐以矩形玄武岩加強，深井上方設磚坪頂作為曝曬收成的場所，是澎南漁村民宅的典型。門樓有細膩的泥塑雕花與洗石子浮雕，門葉楹聯書法秀逸；外牆四角採「吐交丁」砌法。最特別的是右偏間地下有S型防空壕，通往西邊古厝，是澎湖民居少見的室內防空壕。相鄰的許祖取古宅則以八卦頭門樓與磁磚楹聯見長。","highlights":["右偏間地下通往西邊古厝的S型防空壕","門樓泥塑雕花與洗石子浮雕","門葉楹聯的秀逸書法"],"funFact":"外牆四個牆角都用澎湖傳統的「吐交丁」砌法，讓結構更穩固。","photoSpot":"在巷口拍門樓泥塑與玄武岩門豎","visitMin":20,"openNote":"位於馬公市鎖港里，與許祖取古宅相鄰。官方資料標示每週一至週六上午8時至12時開放，實際以現場或文化局公告為準；這是私人古宅，未開放時請在外觀參觀、勿擅入。可騎機車或開車前往，順遊鎖港南北石塔。","dialogue":[{"who":"A","text":"阿拉蕾，鎖港這兩間許家古厝是鄰居，今天先看許監督古宅，它藏了一個秘密基地。"},{"who":"R","text":"秘密基地？是藏在屋頂上，還是藏在牆壁裡面？"},{"who":"A","text":"在地底下！右邊偏間的地底下有一條彎來彎去的防空壕，還能一路通到西邊的古厝。"},{"who":"R","text":"在家裡挖防空壕，這是二戰版的地下室吧！"},{"who":"A","text":"因為它就是1944年二戰末期蓋的，和左右兩棟古厝同時期建造，工法裝飾都很像。"},{"who":"R","text":"兄弟一起蓋房子，還用地道串門子，感情真好！"},{"who":"A","text":"主建材是咕咾石，牆角用玄武岩加強，深井上方還有磚坪頂，可以曬收成。"},{"who":"R","text":"那隔壁的許祖取古宅也長這樣嗎？"},{"who":"A","text":"不太一樣，那間是八卦頭門樓。你先在這裡找找門樓的泥塑雕花，再讀讀門板上的楹聯書法！"}],"clues":["我的右偏間地下有一條S型防空壕","我在二戰末期和左右兩棟古厝同時興建","鎖港里以咕咾石為主、門樓有泥塑雕花的許家古厝"],"quiz":[{"q":"這座古宅最特別的地下設施是什麼？","options":["地下水井","S型防空壕","藏寶地窖","排水暗渠"],"answer":1,"explain":"右偏間地下有S型防空壕，通往西邊古厝。"},{"q":"官方資料記載這座古宅建於哪一年？","options":["1904年","1924年","1944年","1964年"],"answer":2,"explain":"建於昭和19年，也就是1944年二戰末期。"}],"images":[]},{"id":"magong-wukanhongxinrengu","name":"烏崁洪辛任古宅","short":"烏崁洪辛任古宅","category":"歷史建築","level":"","town":"馬公市","types":["宅第"],"lat":23.547431,"lng":119.620069,"address":"澎湖縣馬公市烏崁里96號","announced":"2016-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20161121000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-02-21/78e70d74-c3d6-4e3d-b650-b89abbcaaa16/IMG_20191007_091927.jpg","year":1947,"yearText":"約1947年（民國36年前後）","era":"postwar","themes":["咕咾石古厝","宅第家族"],"yearUnknown":false,"summary":"彩繪磁磚楹聯與玄武岩亂石砌的合院古厝","intro":"烏崁洪辛任古宅位於馬公市烏崁里。屋主洪辛任生於1919年，29歲時興建這座宅第，木作由他本人親手施作，土水則由洪水雲師傅負責。古宅為傳統合院形式，大厝身以硓𥑮石與汕石砌成接近封閉的矩形平面；正面半截堵以玄武岩亂石砌，作工精緻，廳門立面的楹聯與窗堵貼著名師彩繪磁磚與「馬約里卡」磁磚，釉上彩保存完整。室內大廳以尺磚人字形鋪地，左右大房採交丁鋪法，簾前地坪中央人字、兩側交丁，相當講究。2016年登錄為歷史建築。","highlights":["廳門楹聯與窗堵的名師彩繪磁磚","正面半截堵的玄武岩亂石砌","大廳尺磚人字形鋪地"],"funFact":"屋主洪辛任親自負責木作，自己的房子自己做門窗。","photoSpot":"在村路上拍正面彩繪磁磚與玄武岩牆","visitMin":15,"openNote":"位於馬公市烏崁里，是私人古厝。官方資料標示獎助整修中、尚未開放，請在外觀參觀、勿擅入私人住宅，也不要打擾居民。建議租機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這間古厝門口貼滿花花綠綠的磁磚，好像彩色拼布！"},{"who":"A","text":"那是名師彩繪磁磚和馬約里卡磁磚，楹聯和窗堵都用它來裝飾，保存得很完整。"},{"who":"R","text":"下面那一截黑黑的石頭牆又是什麼？"},{"who":"A","text":"那是玄武岩亂石砌，不規則的石頭拼得密密實實，師傅的手藝一看就知道。"},{"who":"R","text":"這麼講究的房子，當初到底是誰蓋的呀？"},{"who":"A","text":"屋主洪辛任生於1919年，29歲蓋了這座宅第，木作還是他自己動手做的。"},{"who":"R","text":"自己蓋房子還自己做門窗，這是古早版的居家修繕達人吧！"},{"who":"A","text":"沒錯，土水則交給洪水雲師傅。這裡是私人古厝，還在整修中，記得只在外面欣賞。"},{"who":"R","text":"好，我要在路邊找出楹聯上的彩繪磁磚，數數看用了幾種顏色！"}],"clues":["我的屋主29歲時蓋我，還親手做了木作","我的廳門楹聯貼著名師彩繪磁磚與馬約里卡磁磚","烏崁里一座玄武岩亂石砌半截堵的合院古厝"],"quiz":[{"q":"古宅正面半截堵使用哪一種砌法？","options":["斗子砌","玄武岩亂石砌","人字砌","清水磚砌"],"answer":1,"explain":"正面半截堵以玄武岩亂石砌，作工精緻。"},{"q":"古宅的木作是由誰施作的？","options":["洪水雲師傅","外地匠師團隊","屋主洪辛任","日本木工"],"answer":2,"explain":"木作由洪辛任本人施作，土水由洪水雲師傅負責。"}],"images":[{"file":"烏崁洪辛任古宅 01 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/%E7%83%8F%E5%B4%81%E6%B4%AA%E8%BE%9B%E4%BB%BB%E5%8F%A4%E5%AE%85_01_%28cropped%29.jpg/960px-%E7%83%8F%E5%B4%81%E6%B4%AA%E8%BE%9B%E4%BB%BB%E5%8F%A4%E5%AE%85_01_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%83%8F%E5%B4%81%E6%B4%AA%E8%BE%9B%E4%BB%BB%E5%8F%A4%E5%AE%85_01_(cropped).jpg","artist":"雲角","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-wukanhongxinrengu-0.webp","small":"img/magong-wukanhongxinrengu-0-s.webp"}]},{"id":"magong-xiyingshengjingpai","name":"西瀛勝境牌樓","short":"西瀛勝境牌樓","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.567702,"lng":119.56298,"address":"澎湖縣馬公市民生路和介壽路交叉口","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-23/2b8bb49f-aa40-41a5-9d2e-1e7961cfe04a/西瀛勝境牌樓.jpg","year":1947,"yearText":"1947年（民國36年）","era":"postwar","themes":["牌坊碑碣","紀念地景"],"yearUnknown":false,"summary":"碑文記載二二八事件的戰後牌樓","intro":"西瀛勝境牌樓位於馬公市民生路與介壽路口，建於1947年（民國36年），「西瀛」是澎湖的古稱。依中文維基百科，二二八事件期間，澎湖在地方士紳奔走協調下未發生大規模衝突；事後國民政府撥款賑濟澎湖，地方各界以此款在觀音亭附近興建公園，並於同年12月在公園入口立牌樓，記載事件始末。牌樓為牙白色，正反面頂端有金黃色「西瀛勝境」四字與兩個國民黨黨徽，兩側下方碑文記載二二八事件，是澎湖少數與二二八事件相關的紀念物，具歷史文化意義。2005年曾遭貨櫃車撞損，2007年修復完成。","highlights":["金黃色的「西瀛勝境」題字","兩側記載二二八事件的碑文","頂端兩個國民黨黨徽"],"funFact":"依中文維基百科，牌樓2005年曾被貨櫃車撞成嚴重損壞，2007年才修復完成。","photoSpot":"在路口安全處拍牌樓正面題字","visitMin":10,"openNote":"位於馬公市民生路與介壽路口，全天開放。牌樓緊鄰車道，閱讀碑文與拍照時請注意來車。附近有專賣局澎湖出張所與第三水源地配水塔，可步行串遊。","dialogue":[{"who":"R","text":"Allan，這座白色牌樓上寫著西瀛勝境，西瀛是哪裡啊？"},{"who":"A","text":"西瀛就是澎湖的古稱，這座牌樓1947年蓋的，在路口站了快八十年。"},{"who":"R","text":"為什麼要在這個路口特地蓋一座牌樓呢？"},{"who":"A","text":"兩側的碑文記載了二二八事件，它是澎湖少數和二二八事件有關的紀念物。"},{"who":"R","text":"原來背後是很嚴肅的歷史，當時澎湖發生了什麼事？"},{"who":"A","text":"根據記載，澎湖在地方士紳奔走協調下沒有大規模衝突，事後政府撥款賑濟，地方用來蓋公園並立牌樓。"},{"who":"R","text":"我看到牌樓頂端有兩個圓圓的圖案，那是什麼？"},{"who":"A","text":"那是國民黨黨徽，也是那個年代的痕跡。2005年它還被貨櫃車撞壞，2007年才修好。"},{"who":"R","text":"那我要站在路口安全的地方，找到碑文，靜靜讀一讀上面寫的經過。"}],"clues":["我曾在2005年被貨櫃車撞壞","我的兩側碑文記載二二八事件","頂端寫著澎湖古稱四字的牙白色牌樓"],"quiz":[{"q":"牌樓上的「西瀛」指的是哪裡？","options":["廈門","金門","澎湖","臺南"],"answer":2,"explain":"西瀛是澎湖的古稱。"},{"q":"牌樓兩側的碑文記載了哪一個歷史事件？","options":["二二八事件","清法戰爭","八二三砲戰","韓戰"],"answer":0,"explain":"官方說明碑文記載二二八事件，具歷史意義。"}],"images":[{"file":"澎湖-西瀛勝境牌樓.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/%E6%BE%8E%E6%B9%96-%E8%A5%BF%E7%80%9B%E5%8B%9D%E5%A2%83%E7%89%8C%E6%A8%93.jpg/960px-%E6%BE%8E%E6%B9%96-%E8%A5%BF%E7%80%9B%E5%8B%9D%E5%A2%83%E7%89%8C%E6%A8%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96-%E8%A5%BF%E7%80%9B%E5%8B%9D%E5%A2%83%E7%89%8C%E6%A8%93.jpg","artist":"Mimicat1531","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-xiyingshengjingpai-0.webp","small":"img/magong-xiyingshengjingpai-0-s.webp"}]},{"id":"magong-tianxiangyingqu","name":"天祥營區連級兵舍","short":"天祥營區兵舍","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.566043,"lng":119.587009,"address":"澎湖縣馬公市中衛段1337地號","announced":"2019-07-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20200717000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-07-17/a01b47d1-d2f8-4357-a687-83e101fd18ee/天祥圖片1.jpg","year":1950,"yearText":"戰後初期（確切年代不詳）","era":"postwar","themes":["軍事遺構"],"yearUnknown":false,"summary":"國軍在澎湖第一批興建的連級兵舍","intro":"天祥營區連級兵舍位於馬公市中衛一帶，2019年登錄為歷史建築。官方資料指出，它是國民政府時期澎湖第一批興建的兵舍，屬於連級官士兵的生活與活動場域。兵舍以漿砌石造，外觀與構造都呈現早期國軍兵舍的特色；三棟建築的配置格局圍出標準的連集合場，具有軍事歷史文化價值。對許多曾在澎湖服役的人來說，這樣的營舍是共同的記憶。它見證了澎湖作為要塞基地時期，基層連隊的居住狀況。確切興建年代官方資料未載明，目前不開放參觀。","highlights":["三棟兵舍圍成的標準連集合場","漿砌石造的厚實牆體","早期國軍兵舍的樸素外觀"],"funFact":"三棟兵舍的擺法就是標準的連集合場配置，建築本身就像一張排好的隊形圖。","photoSpot":"在可通行處遠拍石砌兵舍外牆","visitMin":10,"openNote":"位於馬公市中衛段一帶，官方資料標示不開放，請勿擅入營區範圍，只能在外圍遠觀；若有管制標示請遵守，勿拍攝管制區域。","dialogue":[{"who":"A","text":"阿拉蕾，你有沒有聽過長輩聊當兵？很多人一開口就是：想當年我在澎湖啊。"},{"who":"R","text":"有！而且一講就停不下來。Allan，你也是嗎？"},{"who":"A","text":"我就不暴露年紀了。這處天祥營區連級兵舍，是國民政府時期澎湖第一批興建的兵舍。"},{"who":"R","text":"連級是什麼意思？是要連續住很多年嗎？"},{"who":"A","text":"不是啦，連是部隊的編制單位，這裡就是一個連的官兵生活、活動的地方。"},{"who":"R","text":"原來如此。那這些房子有什麼特別？"},{"who":"A","text":"牆是漿砌石造，樣子樸素又厚實。三棟兵舍圍出一個標準的連集合場，大家就在中間集合。"},{"who":"R","text":"建築自己先排好隊形了，比我們排隊買小吃還整齊。"},{"who":"A","text":"目前不開放，我們在外圍看就好。數數看能看到幾棟石砌兵舍，回家再問問長輩有沒有在澎湖當過兵！"}],"clues":["我們三棟圍成一個標準的連集合場","我們是國民政府時期澎湖第一批興建的兵舍","我們是馬公中衛一帶漿砌石造的連級營舍"],"quiz":[{"q":"天祥營區連級兵舍的牆體是哪一種構造？","options":["木構造","鐵皮屋","漿砌石造","竹編夾泥"],"answer":2,"explain":"兵舍以漿砌石造，是早期國軍兵舍的特色。"},{"q":"三棟兵舍的配置構成了什麼？","options":["廟宇三合院","標準連集合場","市場攤位","砲台陣地"],"answer":1,"explain":"三棟建築的配置格局為標準的連集合場。"}],"images":[]},{"id":"magong-zhengfuqiandiaobao","name":"澎湖縣政府前碉堡","short":"縣府前碉堡","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.569691,"lng":119.566936,"address":"澎湖縣馬公市忠孝路與治平路交口西北側","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-23/5c2e9876-0c97-47c9-a5ce-7c81b52779f8/澎湖縣政府前碉堡.jpg","year":1951,"yearText":"約1951年（民國40年）","era":"postwar","themes":["軍事遺構"],"yearUnknown":false,"summary":"縣政府前廣場角落的綠色圓形碉堡","intro":"澎湖縣政府前碉堡位於馬公市忠孝路與治平路口西北側，就在縣政府前廣場東南角。官方資料記載約建於1951年（民國40年），當時設置目的是保衛重要機關、防範民間暴動衝突，反映戰後初期澎湖濃厚的軍事化氛圍。碉堡為直徑2.4公尺的圓形半地下化掩體，主體為混凝土造，外觀漆成綠色彩繪，周圍設有3個穹窖式射擊口，內緣約30公分見方，外緣高30公分、寬50公分，另有出入口。這一帶歷經多次道路規劃，碉堡都沒有被拆除，2003年登錄為歷史建築。","highlights":["直徑僅2.4公尺的圓形半地下掩體","內窄外寬的穹窖式射擊口","綠色圓形彩繪外觀"],"funFact":"碉堡直徑只有2.4公尺，還有一半埋在地下，卻設了3個射擊口。","photoSpot":"在廣場邊拍碉堡與後方縣府廳舍同框","visitMin":10,"openNote":"位於馬公市忠孝路與治平路口，縣政府前廣場東南角。官方資料標示不開放，碉堡內部無法進入，只能在外觀參觀；路口車多，拍照請注意安全。可與澎湖廳舍、廳長官舍一起步行參觀。","dialogue":[{"who":"R","text":"Allan，縣政府門口怎麼有一顆綠色的大饅頭？"},{"who":"A","text":"那不是饅頭，是碉堡！官方資料說大約1951年蓋的，用來保衛重要機關。"},{"who":"R","text":"縣政府前面擺碉堡，也太有安全感了吧！"},{"who":"A","text":"那個年代澎湖軍事氣氛很濃，碉堡是為了防範暴動衝突，守護政府機關。"},{"who":"R","text":"它看起來好小，裡面塞得下幾個人啊？"},{"who":"A","text":"直徑只有2點4公尺，大概比Allan家浴室大一點，而且有一半埋在地下。"},{"who":"R","text":"躲在那麼小的碉堡裡，裡面的人要怎麼看外面？"},{"who":"A","text":"周圍有3個穹窖式射擊口，內窄外寬。道路改了好幾次，它都沒被拆，是很有毅力的老前輩。"},{"who":"R","text":"那我要繞著碉堡走一圈，數數射擊口，看看它們分別朝向哪幾條馬路！"}],"clues":["我直徑只有2.4公尺，一半藏在地下","我身上有3個穹窖式射擊口","縣政府前廣場東南角那顆綠色圓形掩體"],"quiz":[{"q":"官方資料記載，這座碉堡大約建於哪一年？","options":["1931年","1945年","1951年","1970年"],"answer":2,"explain":"約建於民國40年，也就是1951年。"},{"q":"碉堡周圍設有幾個穹窖式射擊口？","options":["2個","4個","6個","3個"],"answer":3,"explain":"周圍設有3個射擊口，另有出入口。"}],"images":[{"file":"澎湖縣政府前碉堡 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/%E6%BE%8E%E6%B9%96%E7%B8%A3%E6%94%BF%E5%BA%9C%E5%89%8D%E7%A2%89%E5%A0%A1_peiiunwu.jpg/960px-%E6%BE%8E%E6%B9%96%E7%B8%A3%E6%94%BF%E5%BA%9C%E5%89%8D%E7%A2%89%E5%A0%A1_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96%E7%B8%A3%E6%94%BF%E5%BA%9C%E5%89%8D%E7%A2%89%E5%A0%A1_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-zhengfuqiandiaobao-0.webp","small":"img/magong-zhengfuqiandiaobao-0-s.webp"}]},{"id":"magong-ziyouta","name":"自由塔","short":"自由塔","category":"歷史建築","level":"","town":"馬公市","types":["碑碣"],"lat":23.569958,"lng":119.571273,"address":"澎湖縣馬公市馬公段227地號上之定著基地。","announced":"2015-06-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150622000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-11/4dec0619-82e4-416b-8dec-8b6365d4f512/圖像.jpg","year":1954,"yearText":"1954年（民國43年）","era":"postwar","themes":["紀念地景"],"yearUnknown":false,"summary":"澎湖青年為韓戰「自由日」所建的紀念塔","intro":"自由塔位於馬公市光復里一帶的公車站旁。1950年韓戰爆發，1953年停戰後，不願遣返的中國人民志願軍戰俘約1萬4,000餘人交由中立國遣返委員會監管。中華民國將戰俘預定獲釋的1954年1月23日定為「自由日」，民間發起「反共義士自由日運動」，澎湖各界青年發表響應宣言，並建造這座塔紀念。塔身以黑白兩色碎石與水泥為材，正面書「自由塔」，背面書「中華民國四十三年一月二十三日 澎湖各界青年建」，塔頂嵌有繪上中華民國與韓國國旗的「自由徽」。官方資料稱它是韓戰歷史的見證，也是馬公人的共同記憶，2015年登錄為歷史建築。","highlights":["黑白兩色碎石與水泥砌成的塔身","塔頂繪有中華民國與韓國國旗的自由徽","背面「澎湖各界青年建」的題字"],"funFact":"依中文維基百科，自由塔1954年3月6日開工，3月29日就竣工，前後不到一個月。","photoSpot":"在公車站旁仰拍塔頂的自由徽","visitMin":10,"openNote":"位於馬公市光復里一帶的公車站旁，全天開放。周邊人車往來頻繁，拍照請注意安全；可從馬公市區騎機車前往，或搭澎湖縣公車在附近下車。","dialogue":[{"who":"R","text":"Allan，公車站旁邊這座黑白相間的塔，是等公車等太久的人蓋的嗎？"},{"who":"A","text":"哈哈，不是啦！這是1954年澎湖各界青年蓋的自由塔，和韓戰有關。"},{"who":"R","text":"韓戰？澎湖離朝鮮半島很遠耶，怎麼會扯上關係？"},{"who":"A","text":"1953年韓戰停戰，約1萬4000多名不願遣返的志願軍戰俘，交給中立國委員會監管。"},{"who":"R","text":"那這些戰俘的事情，跟澎湖青年又有什麼關係呢？"},{"who":"A","text":"當時中華民國把1954年1月23日定為自由日，澎湖青年響應這個運動，就蓋了這座塔紀念。"},{"who":"R","text":"原來1月23日自由日的故事，在澎湖還留著一座塔！上面有什麼特別的？"},{"who":"A","text":"塔頂有個自由徽，畫著中華民國和韓國國旗，塔身是黑白碎石加水泥，樸實又耐看。"},{"who":"R","text":"那我要從公車站這一側抬頭，找出自由徽上的兩面國旗！"}],"clues":["我的塔頂有一枚畫著兩國國旗的徽章","我背面寫著四十三年一月二十三日澎湖各界青年建","公車站旁、為韓戰戰俘自由日而建的黑白紀念塔"],"quiz":[{"q":"這座塔是為了響應哪一個運動而建？","options":["反共義士自由日運動","新生活運動","國語運動","勤儉建國運動"],"answer":0,"explain":"澎湖青年響應反共義士自由日運動而建塔紀念。"},{"q":"塔頂自由徽上畫的是哪兩國國旗？","options":["中華民國與美國","中華民國與日本","美國與韓國","中華民國與韓國"],"answer":3,"explain":"自由徽上繪有中華民國與韓國國旗。"}],"images":[{"file":"自由塔 Tower of Freedom, Penghu 15.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/%E8%87%AA%E7%94%B1%E5%A1%94_Tower_of_Freedom%2C_Penghu_15.jpg/960px-%E8%87%AA%E7%94%B1%E5%A1%94_Tower_of_Freedom%2C_Penghu_15.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%87%AA%E7%94%B1%E5%A1%94_Tower_of_Freedom,_Penghu_15.jpg","artist":"舟集 Boattoad","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/magong-ziyouta-0.webp","small":"img/magong-ziyouta-0-s.webp"}]},{"id":"magong-shidisanshuiyuandi","name":"馬公市第三水源地一千噸配水塔","short":"第三水源地配水塔","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.568649,"lng":119.564509,"address":"澎湖縣馬公市中正堂後方介壽路和民族路交叉口處","announced":"2002-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-23/46b84b87-93c8-40c7-968a-f9b33b8f600a/馬公市第三水源地一千噸配水塔.jpg","year":1960,"yearText":"1960年（民國49年）","era":"postwar","themes":["水利設施"],"yearUnknown":false,"summary":"高17公尺、可貯水一千噸的馬公地標水塔","intro":"馬公市第三水源地一千噸配水塔位於馬公市介壽路與民族路口、中正堂後方。1960年（民國49年）自來水廠在第一賓館附近鑿新深水井，並在此設置第三水源地，興建直徑10公尺、高17公尺、可貯水一千噸的配水塔。當時以馬達把各深水井的水抽送到17公尺高的貯水槽，再利用地勢高低差與水壓，把水配送到馬公市區各戶。如今深水井大多已停用，只剩第一賓館庭園北側的16號深水井，配水塔改為直接連結自來水公司水源，擔任貯存與調節供水的角色。它與馬公市民的生活息息相關，也是具稀少性的地標。","highlights":["直徑10公尺、高17公尺的圓筒塔身","可貯水一千噸的塔頂貯水槽","與第一賓館庭園16號深水井相連的供水故事"],"funFact":"第三水源地的深水井大多停用了，只剩第一賓館庭園北側那口16號深水井。","photoSpot":"在介壽路口仰拍17公尺高的塔身","visitMin":10,"openNote":"位於馬公市介壽路與民族路口、中正堂後方，全天可在外觀參觀，請勿攀爬水塔或進入設施。可與第一賓館、西瀛勝境牌樓一起步行串遊。","dialogue":[{"who":"R","text":"Allan，路口那根圓圓的大柱子好高，是燈塔嗎？"},{"who":"A","text":"不是燈塔，是1960年蓋的第三水源地配水塔，高17公尺，可以裝一千噸的水。"},{"who":"R","text":"一千噸！那要多少瓶礦泉水才裝得滿？"},{"who":"A","text":"用600毫升的瓶子算，大概要166萬多瓶，你要幫忙搬嗎？"},{"who":"R","text":"我投降！那塔裡的水，又是怎麼送到大家家裡的？"},{"who":"A","text":"先用馬達把深水井的水抽到塔頂，再靠高低差和水壓，一路流到馬公市區各戶。"},{"who":"R","text":"原來是靠地心引力送水，不用騎車也不會塞車，比外送員還準時。"},{"who":"A","text":"現在深水井大多停用了，水塔改接自來水公司水源，繼續幫忙調節供水。"},{"who":"R","text":"那我要在路口找個安全的位置，抬頭把整座水塔完整拍進一張照片裡！"}],"clues":["我高17公尺，肚子裡可以裝一千噸的水","我靠高低差和水壓把水送進馬公市區","中正堂後方、1960年興建的圓筒形供水地標"],"quiz":[{"q":"這座配水塔可以貯存多少水？","options":["一百噸","五百噸","一千噸","一萬噸"],"answer":2,"explain":"配水塔可貯水一千噸，也就是1000立方公尺。"},{"q":"配水塔主要靠什麼把水送到市區各戶？","options":["人力挑水","高低差與水壓","風車抽水","蒸汽機"],"answer":1,"explain":"利用地勢高低差及水壓將水配送到各用戶。"}],"images":[{"file":"馬公市第三水源地一千噸配水塔 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/%E9%A6%AC%E5%85%AC%E5%B8%82%E7%AC%AC%E4%B8%89%E6%B0%B4%E6%BA%90%E5%9C%B0%E4%B8%80%E5%8D%83%E5%99%B8%E9%85%8D%E6%B0%B4%E5%A1%94_peiiunwu.jpg/960px-%E9%A6%AC%E5%85%AC%E5%B8%82%E7%AC%AC%E4%B8%89%E6%B0%B4%E6%BA%90%E5%9C%B0%E4%B8%80%E5%8D%83%E5%99%B8%E9%85%8D%E6%B0%B4%E5%A1%94_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%A6%AC%E5%85%AC%E5%B8%82%E7%AC%AC%E4%B8%89%E6%B0%B4%E6%BA%90%E5%9C%B0%E4%B8%80%E5%8D%83%E5%99%B8%E9%85%8D%E6%B0%B4%E5%A1%94_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/magong-shidisanshuiyuandi-0.webp","small":"img/magong-shidisanshuiyuandi-0-s.webp"}]},{"id":"huxi-guoyehuiyao","name":"湖西菓葉灰窯","short":"菓葉灰窯","category":"歷史建築","level":"","town":"湖西鄉","types":["產業"],"lat":23.57533,"lng":119.680606,"address":"澎湖縣湖西鄉菓葉村","announced":"2007-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071121000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-26/26be5bed-5028-41ee-8cba-44ea3d7405f5/DSC_0056.jpg","year":1960,"yearText":"約1960年（民國49年）前後","era":"postwar","themes":["產業遺產"],"yearUnknown":false,"summary":"澎湖現存最壯觀的燒石灰窯","intro":"湖西菓葉灰窯位於湖西鄉菓葉村。1960年前後臺灣大量興建販厝，當時水泥、油漆還不普遍，牆面多用石灰粉光；澎湖有又白又好的「砂砱」，燒成的石灰大受建築業歡迎，訂單湧入，灰窯業盛極一時。後來受紅磚、水泥等現代建材競爭，約1970年生意一落千丈，1973年以後幾乎停擺。菓葉灰窯有大小兩座窯：大窯的圓形窯爐包在四方形無頂的窯體內，設有倒入砂砱的樓梯；小窯的窯爐直接露在外面，有多次改建痕跡，旁邊還有拌煤炭、灑水取灰的場所與儲水槽。它是全縣僅存灰窯中最壯觀的一座，見證牡蠣殼灰與砂砱灰的生產歷程，2007年登錄為歷史建築。","highlights":["包在方形窯體內的大窯圓形窯爐","窯爐外露、多次改建的小窯","倒砂砱的樓梯與灑水取灰的場所"],"funFact":"1960年代臺灣蓋房子的牆面石灰，有不少是用澎湖白色的砂砱燒出來的。","photoSpot":"在外圍拍大窯方形窯體與圓形窯口","visitMin":15,"openNote":"位於湖西鄉菓葉村，官方資料為不開放，窯體老舊，請在外圍觀看，勿攀爬。可從馬公開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你看這座方方正正的大塊頭，猜猜它以前是做什麼的？"},{"who":"R","text":"看起來像巨大的烤箱，是烤蛋糕的嗎？"},{"who":"A","text":"很接近！它是灰窯，烤的是澎湖的白色砂砱，燒成石灰拿去蓋房子。窯旁還有灑水取灰的地方。"},{"who":"R","text":"石灰蓋房子？那不是要用水泥嗎？"},{"who":"A","text":"1960年前後水泥還不普遍，臺灣大量蓋販厝，牆面都用石灰粉光，澎湖的訂單接不完。"},{"who":"R","text":"生意那麼好，那後來怎麼會停下來了？"},{"who":"A","text":"紅磚、水泥普及後，1970年左右生意一落千丈，1973年以後就幾乎停擺了。"},{"who":"R","text":"原來超大烤箱也會失業，聽起來好心酸喔。"},{"who":"A","text":"它是澎湖現存最壯觀的灰窯。你在外圍比一比，大窯和小窯的窯爐哪一個有包外殼！"}],"clues":["我曾把澎湖白色的砂砱燒成石灰","我有一大一小兩座窯，大窯的圓爐包在方形窯體裡","菓葉村最壯觀的灰窯，1970年代後停產"],"quiz":[{"q":"菓葉灰窯主要燒製什麼原料？","options":["花崗岩","砂砱","玄武岩","黏土"],"answer":1,"explain":"以澎湖又白又好的砂砱燒成石灰。"},{"q":"灰窯業在哪個年份以後幾乎停擺？","options":["1945年","1955年","1960年","1973年"],"answer":3,"explain":"受紅磚水泥競爭，1973年以後接近停滯。"}],"images":[{"file":"湖西菓葉灰窯 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/%E6%B9%96%E8%A5%BF%E8%8F%93%E8%91%89%E7%81%B0%E7%AA%AF_peiiunwu.jpg/960px-%E6%B9%96%E8%A5%BF%E8%8F%93%E8%91%89%E7%81%B0%E7%AA%AF_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%B9%96%E8%A5%BF%E8%8F%93%E8%91%89%E7%81%B0%E7%AA%AF_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/huxi-guoyehuiyao-0.webp","small":"img/huxi-guoyehuiyao-0-s.webp"}]},{"id":"huxi-aimenxincun","name":"隘門新村","short":"隘門新村","category":"歷史建築","level":"","town":"湖西鄉","types":["宅第"],"lat":23.557465,"lng":119.632912,"address":"澎湖縣湖西鄉湖西鄉隘門村","announced":"2007-11-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071121000003","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1296/photo/隘門新村1.JPG","year":1964,"yearText":"1964年（民國53年）","era":"postwar","themes":["眷村聚落"],"yearUnknown":false,"summary":"機場旁的空軍眷村，玄武岩砌成的連棟屋","intro":"隘門新村位於湖西鄉隘門村南側，西邊緊鄰縣道204與馬公機場，是空軍基地的眷舍。1964年興建，1965年住戶遷入。住屋分為甲A、甲B兩種大坪數，以及乙種小坪數，由北到南排列，第一排為甲種、第二三排為乙種。實際戶數31戶，全盛時期約40戶；1970年代起人口漸漸外移，2006年只剩15戶，2007年3月全部遷往龍行新城。眷舍為戶戶相連的連棟建築，大約兩戶共用一座階梯，以澎湖在地的玄武岩塊砌牆、水泥填縫，代表1960年代國軍眷舍工法。它是澎湖少數保存下來的軍方眷舍。","highlights":["玄武岩塊以水泥填縫的牆面","兩戶共用一座階梯的連棟眷舍","甲A、甲B大坪數與乙種小坪數住屋"],"funFact":"這裡的住戶和馬公篤行十村一樣，2007年都搬進了龍行新城。","photoSpot":"在外圍拍玄武岩牆與共用階梯","visitMin":15,"openNote":"位於湖西鄉隘門村，緊鄰馬公機場，官方資料為不開放，請在外圍觀看、勿擅入。從機場開車或騎機車距離不遠。","dialogue":[{"who":"A","text":"剛下飛機的朋友注意，機場旁邊就有一座眷村，叫隘門新村。"},{"who":"R","text":"眷村我知道，馬公篤行十村那種日式木頭房子對吧？"},{"who":"A","text":"這裡不一樣喔！它是1964年蓋的空軍眷舍，牆是用澎湖玄武岩一塊塊砌起來，再用水泥填縫。"},{"who":"R","text":"黑黑的石頭牆，看起來超堅固，颱風應該吹不倒！"},{"who":"A","text":"沒錯。房子是連棟的，大約兩戶共用一座階梯，鄰居天天在樓梯口打招呼。"},{"who":"R","text":"那以前住在這裡的人，現在都去哪了？"},{"who":"A","text":"全盛時期約40戶，後來人口外移，2007年3月全部搬到龍行新城了。"},{"who":"R","text":"飛機一起飛就聽得到，住這裡的小孩應該都很會分辨飛機吧！"},{"who":"A","text":"也許喔！你在外圍找找看，哪兩戶人家共用同一座階梯。"}],"clues":["我的牆用黑色火山岩塊砌成，再用水泥填縫","我的住戶分為甲A、甲B、乙三種屋型","馬公機場旁的空軍眷村，1964年興建"],"quiz":[{"q":"隘門新村原本是哪一個軍種的眷舍？","options":["陸軍","空軍","海軍","憲兵"],"answer":1,"explain":"隘門新村是空軍基地的眷舍。"},{"q":"隘門新村的牆面主要用什麼石材？","options":["玄武岩","大理石","花崗岩","青斗石"],"answer":0,"explain":"以玄武岩塊砌築、水泥填縫，具在地特色。"}],"images":[{"file":"隘門新村 peiiunwu.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/%E9%9A%98%E9%96%80%E6%96%B0%E6%9D%91_peiiunwu.jpg/960px-%E9%9A%98%E9%96%80%E6%96%B0%E6%9D%91_peiiunwu.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%9A%98%E9%96%80%E6%96%B0%E6%9D%91_peiiunwu.jpg","artist":"吳沛芸","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/huxi-aimenxincun-0.webp","small":"img/huxi-aimenxincun-0-s.webp"}]},{"id":"huxi-jianshanxianjidian","name":"尖山顯濟殿","short":"尖山顯濟殿","category":"歷史建築","level":"","town":"湖西鄉","types":["寺廟"],"lat":23.569939,"lng":119.662167,"address":"澎湖縣湖西鄉尖山村8鄰尖山81號","announced":"2017-03-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20170314000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-17/d8a743a8-e992-4365-b585-e15fa5316ec1/圖檔.jpg","year":1965,"yearText":"1965年動工、1967年落成（廟史可溯至1781年）","era":"postwar","themes":["宗教信仰"],"yearUnknown":false,"summary":"供奉謝安謝玄，名匠葉根壯的木構廟宇","intro":"尖山顯濟殿位於湖西鄉尖山村。依廟內〈顯濟殿重建誌〉，乾隆46年（1781）由王維羆倡建於坑仔頂，後由洪豁倡議遷到現址。王維羆擁有三桅帆船往來上海、天津通商，自唐山分靈謝安金身，神號後改稱顯濟靈王，與謝府元帥謝玄合祀，村民稱為「文官掛武帥」。大正10年（1921）洪瑞徵倡議重建，到1965年才動工，歷時2年3個月、耗資新臺幣50萬元，於1967年完工。廟為承重牆混合RC柱與木樑的結構，大木作出自名匠葉根壯，彩繪為黃友謙作品，是澎湖民國50年代廟宇的代表。2017年神明已出火移駕第五代新廟。","highlights":["名匠葉根壯的木構與RC混構大木作","黃友謙彩繪與鑿花、剪黏、彩繪瓷磚","刻有嘉慶21年（1816）字樣的石香爐"],"funFact":"謝安是東晉宰相、謝玄是他的姪子兼名將，一文一武同祀，村民就叫「文官掛武帥」。","photoSpot":"在廟埕外拍三川脊與八卦脊的屋頂線","visitMin":15,"openNote":"位於湖西鄉尖山村，官方資料為不開放，神明已移駕新廟，舊廟請在外觀參觀。可從馬公開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間廟拜誰呀？門口寫顯濟靈王，我沒聽過耶。"},{"who":"A","text":"主神是東晉的謝安，還有他的姪子謝玄。一個宰相、一個名將，村民叫它「文官掛武帥」。"},{"who":"R","text":"一文一武，好像辦公室的主管加保全組合！"},{"who":"A","text":"哈哈。廟史可以追溯到1781年，創建人王維羆有三桅帆船，往來上海、天津做生意。"},{"who":"R","text":"那我們眼前這棟廟，就是那時候蓋的嗎？"},{"who":"A","text":"不是，1921年就有人倡議重建，拖到1965年才動工，1967年完工，等了四十幾年，工期2年3個月、花了新臺幣50萬元。"},{"who":"R","text":"四十幾年！比我等網購包裹還久太多了！"},{"who":"A","text":"大木作是名匠葉根壯，彩繪是黃友謙。你在外面抬頭，比較一下前後屋頂的屋脊造型哪裡不一樣！"}],"clues":["我的廟史從1781年在坑仔頂開始","我供奉一位東晉宰相和他當將軍的姪子","尖山村的廟，1967年由名匠葉根壯完成大木作"],"quiz":[{"q":"顯濟殿合祀謝安與謝玄，村民怎麼稱呼這個組合？","options":["文官掛武帥","雙王鎮海","叔姪同心","文武雙全"],"answer":0,"explain":"謝安為文官、謝玄為武將，村民稱為文官掛武帥。"},{"q":"顯濟殿的大木作出自哪位匠師？","options":["黃友謙","朱錫甘","葉根壯","陳應彬"],"answer":2,"explain":"大木作為澎湖名匠葉根壯的作品。"}],"images":[{"file":"尖山顯濟殿｜立面 (4) (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/%E5%B0%96%E5%B1%B1%E9%A1%AF%E6%BF%9F%E6%AE%BF%EF%BD%9C%E7%AB%8B%E9%9D%A2_%284%29_%28cropped%29.jpg/960px-%E5%B0%96%E5%B1%B1%E9%A1%AF%E6%BF%9F%E6%AE%BF%EF%BD%9C%E7%AB%8B%E9%9D%A2_%284%29_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%B0%96%E5%B1%B1%E9%A1%AF%E6%BF%9F%E6%AE%BF%EF%BD%9C%E7%AB%8B%E9%9D%A2_(4)_(cropped).jpg","artist":"舟集 Toadboat","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/huxi-jianshanxianjidian-0.webp","small":"img/huxi-jianshanxianjidian-0-s.webp"}]},{"id":"baisha-kuahaidaqiao","name":"澎湖跨海大橋","short":"澎湖跨海大橋","category":"歷史建築","level":"","town":"白沙鄉","types":["其他設施"],"lat":23.658029,"lng":119.554602,"address":"澎湖縣白沙鄉通樑村與西嶼鄉橫礁村之間","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-10-27/87a179c0-9458-471b-bd94-14367ba7e463/跨海大橋.jpg","year":1965,"yearText":"1965年動工、1970年完工（1996年改建通車）","era":"postwar","themes":["交通建設"],"yearUnknown":false,"summary":"連接白沙與西嶼、曾稱遠東第一的跨海橋","intro":"澎湖跨海大橋位於白沙鄉通樑村與西嶼鄉橫礁村之間，跨越吼門水道，把白沙島與西嶼連在一起，讓澎湖本島、白沙、西嶼三大島可以開車直達，是澎湖重要的交通命脈。第一代大橋1965年動工、1970年完工，初建時長2160公尺，當年號稱遠東第一跨海大橋。長年受海風、鹽分侵蝕，舊橋鏽蝕嚴重，1984年起興建第二代大橋，於1996年3月正式通車；文化資產登錄資料記載改建後長度為2600公尺，竣工年份則記為1994年，各方記載略有出入。橋兩端設有拱形橋門與紀念碑亭，2003年登錄為歷史建築。","highlights":["橋兩端的拱形橋門與紀念碑亭","橋下湍急的吼門水道","北端通樑一帶的海景與周邊景點"],"funFact":"大橋通車前，白沙和西嶼之間主要靠船往來；大橋一通，西嶼的渡船生意就漸漸沒落了。","photoSpot":"在橋頭拱門旁的安全處拍大橋與海","visitMin":30,"openNote":"位於白沙鄉通樑村與西嶼鄉橫礁村之間，全天開放，是前往西嶼的必經之路，可開車、騎機車或搭澎湖縣公車經過。冬季東北季風強勁，騎機車過橋請減速、注意側風，拍照請在橋頭安全處，勿在橋上任意停車。","dialogue":[{"who":"R","text":"哇，這座橋好長，一直延伸到海的另一邊！"},{"who":"A","text":"這就是澎湖跨海大橋，連接白沙和西嶼，橋下是水流很急的吼門水道。"},{"who":"R","text":"那以前沒有橋的時候，大家怎麼過去？游泳嗎？"},{"who":"A","text":"主要靠搭船。第一代大橋1965年動工、1970年完工，當年還號稱遠東第一跨海大橋，兩端設有拱形橋門。"},{"who":"R","text":"遠東第一！那我們現在走的就是那座嗎？"},{"who":"A","text":"不是喔，舊橋被海風鹽分侵蝕得很嚴重，1984年起蓋第二代，1996年通車的才是現在這座，特別加強了防鏽。"},{"who":"R","text":"原來大橋也會被海風醃成鹹魚，還要換新的！"},{"who":"A","text":"比喻得好鹹。冬天風超大，過橋要放慢速度。你到橋頭拱門找找看，橋頭的紀念碑亭上寫了什麼！"}],"clues":["我跨越湍急的吼門水道","我初建時曾號稱遠東第一，後來因鹽害改建第二代","連接白沙通樑與西嶼橫礁的長橋"],"quiz":[{"q":"第一代跨海大橋在哪一年完工？","options":["1955年","1962年","1970年","1984年"],"answer":2,"explain":"第一代大橋1965年動工、1970年完工。"},{"q":"跨海大橋連接白沙島和哪一個島？","options":["吉貝嶼","望安島","七美嶼","西嶼"],"answer":3,"explain":"大橋連接白沙鄉通樑與西嶼鄉橫礁。"}],"images":[{"file":"Penghu Great Bridge 20150619.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Penghu_Great_Bridge_20150619.jpg/960px-Penghu_Great_Bridge_20150619.jpg","page":"https://commons.wikimedia.org/wiki/File:Penghu_Great_Bridge_20150619.jpg","artist":"翁維德 (Wei-Te Wong)","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/baisha-kuahaidaqiao-0.webp","small":"img/baisha-kuahaidaqiao-0-s.webp"}]},{"id":"huxi-chenggongshuiku","name":"成功水庫水壩","short":"成功水庫水壩","category":"歷史建築","level":"","town":"湖西鄉","types":["其他設施"],"lat":23.579301,"lng":119.624132,"address":"澎湖縣湖西鄉成功村","announced":"2003-12-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-19/93aca7c4-f84f-4e39-bb99-cab2d488ced9/成功水庫水壩.jpg","year":1972,"yearText":"1972年動工、1973年完工","era":"postwar","themes":["水利設施"],"yearUnknown":false,"summary":"澎湖最大也最早的水庫，解馬公水荒","intro":"成功水庫水壩位於湖西鄉成功村，成功舊名港底，正好位在兩個半島之間的海灣，被選為蓄水的良池，在灣內築長堤蓄水。水壩1972年興建、1973年完工，由長290公尺的混凝土重力壩與173公尺的堆石壩組成，壩頂標高11公尺，最大壩高10.5公尺，蓄水量達102萬公噸，超過滿水位的水會自動溢流入海。水源主要靠降雨，用來解決馬公和湖西的飲水困難，是澎湖最大也最早興建的水庫。水庫周邊集水區也是賞鳥地點，2003年登錄為歷史建築，目前仍以供水為主要功能。","highlights":["混凝土重力壩加堆石壩的組合","蓄水量102萬公噸，澎湖最大最早的水庫","周邊集水區是賞鳥地點"],"funFact":"成功村舊名「港底」，水庫其實是在海灣裡築堤，把原本的海灣變成蓄雨水的水庫。","photoSpot":"在公開道路安全處遠拍水庫水面與壩體","visitMin":15,"openNote":"位於湖西鄉成功村，官方資料為不開放，屬供水設施，請勿進入管制範圍或下水，可在公開道路旁遠眺。","dialogue":[{"who":"R","text":"Allan，澎湖四面都是海，怎麼還會缺水？"},{"who":"A","text":"海水不能喝啊！澎湖雨少風大，以前馬公夏天常缺水，所以1972年開始蓋成功水庫來幫大家解渴。"},{"who":"R","text":"水庫要蓋在山谷裡，澎湖哪來的山谷？"},{"who":"A","text":"好問題。成功村舊名港底，剛好夾在兩個半島中間，就在海灣裡築長堤蓄雨水。水源主要靠下雨。"},{"who":"R","text":"把海灣變水庫，這招叫乾坤大挪移吧！"},{"who":"A","text":"壩有兩種，290公尺長的混凝土重力壩加上173公尺的堆石壩，可以存102萬公噸的水。"},{"who":"R","text":"那水滿了怎麼辦？會不會淹到馬路上？"},{"who":"A","text":"超過滿水位就自動溢流到海裡。這座澎湖最大最早的水庫，還是賞鳥好地方，帶望遠鏡在路邊找找看有幾種鳥！"}],"clues":["我所在的村子舊名叫港底","我由混凝土重力壩和堆石壩組成，能存102萬公噸的水","1973年完工，澎湖最大也最早的水庫"],"quiz":[{"q":"成功水庫所在的成功村，舊名叫什麼？","options":["媽宮","前原","港底","坑仔頂"],"answer":2,"explain":"成功舊名港底，位在兩個半島之間的海灣。"},{"q":"成功水庫的蓄水量大約是多少？","options":["10萬公噸","102萬公噸","1,020萬公噸","1億公噸"],"answer":1,"explain":"蓄水量高達102萬公噸。"}],"images":[{"file":"澎湖湖西成功水庫水壩 02 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/%E6%BE%8E%E6%B9%96%E6%B9%96%E8%A5%BF%E6%88%90%E5%8A%9F%E6%B0%B4%E5%BA%AB%E6%B0%B4%E5%A3%A9_02_%28cropped%29.jpg/960px-%E6%BE%8E%E6%B9%96%E6%B9%96%E8%A5%BF%E6%88%90%E5%8A%9F%E6%B0%B4%E5%BA%AB%E6%B0%B4%E5%A3%A9_02_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%BE%8E%E6%B9%96%E6%B9%96%E8%A5%BF%E6%88%90%E5%8A%9F%E6%B0%B4%E5%BA%AB%E6%B0%B4%E5%A3%A9_02_(cropped).jpg","artist":"雲角","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/huxi-chenggongshuiku-0.webp","small":"img/huxi-chenggongshuiku-0-s.webp"}]},{"id":"magong-jinlongtouqingnian","name":"澎湖金龍頭青年活動中心","short":"金龍頭青年活動中心","category":"歷史建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.561415,"lng":119.558902,"address":"澎湖縣馬公市馬公段2665地號","announced":"2020-02-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20200717000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-07-17/2d2bb96a-8ac8-4a46-87e8-387204fc5113/189702.jpg","year":1980,"yearText":"1980年（民國69年）啟用","era":"postwar","themes":["公共建築"],"yearUnknown":false,"summary":"建築師漢寶德在澎湖的第一件作品","intro":"澎湖金龍頭青年活動中心位於馬公市西南側的金龍頭，是知名建築師漢寶德在澎湖的第一棟作品，漢寶德也曾就讀馬公高中。依中文維基百科，救國團1976年借用國防部金龍頭招待所興建活動中心，1980年落成啟用，1982年國防部收回土地，活動中心另在觀音亭旁遷建。建築以方形、圓形、三角形等幾何圖形發想，屋頂採格子樑，清水紅磚牆面帶有粗獷主義的趣味，像一座海上堡壘；三組不同尺度的活動空間交織，用來抵擋東北季風。A棟為辦公與住宿，B棟設有可容納350人的餐廳及集會室。2020年登錄為歷史建築。","highlights":["清水紅磚牆面，像一座海上堡壘","方、圓、三角幾何造型與格子樑屋頂","三組活動空間交織，抵擋東北季風"],"funFact":"它啟用沒幾年就因軍方收回土地而遷建，觀音亭旁的第二代活動中心同樣由漢寶德設計。","photoSpot":"目前不開放，請勿進入管制區域拍攝","visitMin":10,"openNote":"位於馬公市金龍頭一帶，官方資料標示不開放，請勿擅自進入；周邊有軍方營區，請遵守現場管制、勿拍攝軍事設施。注意：觀音亭旁營運中的澎湖青年活動中心是後來遷建的第二代，和這處歷史建築不是同一棟。","dialogue":[{"who":"R","text":"Allan，這棟紅磚建築方方圓圓的，好像積木城堡！"},{"who":"A","text":"你眼光不錯，這是建築師漢寶德在澎湖的第一件作品，金龍頭青年活動中心。"},{"who":"R","text":"漢寶德？他是很有名的建築師嗎？我好像在課本看過。"},{"who":"A","text":"非常有名，而且他也在馬公高中念過書，所以這棟對澎湖特別有意義。"},{"who":"R","text":"為什麼牆壁用紅磚，而且看起來好厚重？"},{"who":"A","text":"這是清水紅磚，追求材料的真實感，三組活動空間交錯排列，就是要擋澎湖的東北季風。"},{"who":"R","text":"澎湖的風真的可以把我的耳機吹走！那現在可以進去住嗎？"},{"who":"A","text":"不行喔，官方資料寫目前不開放。觀音亭旁那間是後來遷建的第二代，別跑錯地方。"},{"who":"R","text":"那我在允許停留的地方遠遠看，找找方形、圓形、三角形各藏在哪裡！"}],"clues":["我的屋頂是格子樑，造型來自方、圓、三角","我啟用不久就因土地被收回，另在觀音亭旁遷建","漢寶德在澎湖的第一件作品，清水紅磚像海上堡壘"],"quiz":[{"q":"這座活動中心是哪一位建築師在澎湖的第一件作品？","options":["王大閎","李祖原","姚仁喜","漢寶德"],"answer":3,"explain":"官方資料指出它是漢寶德在澎湖的第一棟作品。"},{"q":"活動中心的牆面主要使用什麼材料？","options":["玄武岩","咕咾石","清水紅磚","洗石子"],"answer":2,"explain":"清水紅磚牆面讓建築像海上的堡壘。"}],"images":[]},{"id":"baisha-wadongxulingyunxiu","name":"瓦硐許凌雲秀才紀念館","short":"許凌雲秀才館","category":"紀念建築","level":"","town":"白沙鄉","types":["宅第"],"lat":23.656998,"lng":119.586347,"address":"澎湖縣白沙鄉瓦硐村5鄰51號","announced":"2023-07-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/commemorativeBuilding/20240524000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-12-12/33820d20-dc4c-49fe-b833-7f6d1ebd7a5f/IMG20210510163523.jpg","year":1920,"yearText":"年代不詳","era":"unknown","themes":["名人故居","教育書院"],"yearUnknown":true,"summary":"秀才講學、兼當村裡郵件集散地的老宅","intro":"瓦硐許凌雲秀才紀念館位於白沙鄉瓦硐村，2023年登錄為紀念建築。許凌雲（名漢厚，1862–1944）出身瓦硐望族，清光緒年間考取生員，也就是秀才，後來與兄長一同接受基督教，在長老教中學、女學及神學校執教18年。1920年（大正9年）他返鄉設「存養軒」書房教授漢文，又教了18年，白沙才子方思溫就是他的學生。據後人口述，這裡是他居住與講學的地方。建物在二戰後改建，仍保留部分牆體，以及澎湖少見的「三關六扇門」廳門形式。早年瓦硐和馬公之間沒有橋，信件、貨物運抵瓦硐後都以秀才館為集散點，再分送村內。","highlights":["澎湖少見的「三關六扇門」廳門","保留下來的舊牆體與戰後改建痕跡","曾是瓦硐信件貨物集散點的故事"],"funFact":"早年瓦硐和馬公之間沒有橋，信件和貨物會先送到秀才館，再分送到村裡各家。","photoSpot":"在門外拍三關六扇門與老牆面","visitMin":15,"openNote":"位於白沙鄉瓦硐村，官方資料未載開放時間，請在外觀參觀，勿擅入或打擾住戶。從馬公經中正橋、永安橋開車或騎機車可達白沙，也可搭澎湖縣公車前往。","dialogue":[{"who":"R","text":"Allan，秀才館聽起來好文青，是要來這裡考試嗎？"},{"who":"A","text":"不用考試啦！這裡是清代秀才許凌雲的家，他晚年回瓦硐開書房，教鄉親讀漢文。"},{"who":"R","text":"秀才老師耶！那他之前在哪裡工作？"},{"who":"A","text":"他和哥哥接受基督教，在長老教中學、女學和神學校教了18年書，回鄉又教了18年。"},{"who":"R","text":"18年再18年，根本是教書馬拉松選手！"},{"who":"A","text":"還有更妙的，以前瓦硐和馬公之間沒有橋，信件貨物都先送到秀才館，再分給村民。"},{"who":"R","text":"所以秀才館也是村裡的郵局兼物流中心！"},{"who":"A","text":"沒錯。房子戰後改建過，但保留了澎湖少見的三關六扇門。在門外數一數，六扇門是不是都到齊了！"}],"clues":["我的主人考取生員，也曾在長老教會學校執教","我保留澎湖少見的三關六扇門","我在白沙鄉瓦硐，紀念一位清代秀才"],"quiz":[{"q":"許凌雲晚年返鄉後在瓦硐做什麼？","options":["開設中藥行","擔任燈塔看守","設書房教漢文","經營帆船貿易"],"answer":2,"explain":"1920年返鄉設存養軒書房，教授漢文18年。"},{"q":"早年瓦硐和馬公間沒有橋時，秀才館扮演什麼角色？","options":["信件貨物集散點","漁獲拍賣場","軍隊指揮所","廟會集合地"],"answer":0,"explain":"信件、貨物運抵瓦硐後，以秀才館為集散地點。"}],"images":[]},{"id":"huxi-zhuxiganpenghusha","name":"朱錫甘澎湖沙港旅居住所","short":"朱錫甘沙港旅居所","category":"紀念建築","level":"","town":"湖西鄉","types":["宅第"],"lat":23.604724,"lng":119.621959,"address":"澎湖縣湖西鄉沙港村150號前","announced":"2019-12-06","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/commemorativeBuilding/20200212000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-06-18/a37911d6-bd69-4047-9419-65e743a19fbe/圖檔.jpg","year":1923,"yearText":"1923年底（大正12年）繪製壁板","era":"japan","themes":["名人故居","咕咾石古厝"],"yearUnknown":false,"summary":"天后宮匠師過年暫住、留下雙面書畫的棧間","intro":"朱錫甘澎湖沙港旅居住所位於湖西鄉沙港村。朱錫甘又名朱水林，是福建東山的匠師，1922年與師兄朱欽、師弟黃文華來澎湖，參與澎湖天后宮重建的鑿花木雕與彩繪，1925年完工返鄉；1927年再到沙港村為廣聖殿做裝飾，1929年完工後就沒再來過澎湖。這處建築是陳家祖厝的「棧間」，也就是存放物資的空間，屋頂鋪磚坪。屋內壁板一面畫李鐵拐，落款「癸亥冬月」，另一面是書法，落款「甲子人日」，可知繪於1923年底到1924年初，是目前所知朱錫甘有明確落款年份的作品中最早的一件。地方研究推測，他是應在中央街做生意的陳連發之邀來此過年。2019年登錄為紀念建築。","highlights":["一面李鐵拐彩繪、一面書法的雙面壁板","落款「癸亥冬月」與「甲子人日」","屋頂鋪磚坪的傳統棧間建築"],"funFact":"「人日」是農曆正月初七，書法落款在年後，人物畫落款在年前，剛好跨了一個年。","photoSpot":"在屋外拍磚坪屋頂的棧間外觀","visitMin":10,"openNote":"位於湖西鄉沙港村，官方資料為不開放，壁板在屋內無法參觀，請在外觀參觀、勿擅入私人住宅。可與馬公的澎湖天后宮一起認識朱錫甘的作品。","dialogue":[{"who":"R","text":"Allan，這間小石屋看起來好普通，為什麼是紀念建築？"},{"who":"A","text":"因為一位大師在這裡過過年！他叫朱錫甘，是參與澎湖天后宮重建的福建東山匠師。"},{"who":"R","text":"大師不回家過年，跑來沙港做什麼？"},{"who":"A","text":"天后宮工程還沒做完，地方研究推測，是在中央街做生意的陳連發邀他來祖厝過年。"},{"who":"R","text":"然後他就在牆上畫畫當紅包回禮嗎？"},{"who":"A","text":"差不多！屋內壁板一面畫李鐵拐，寫癸亥冬月，另一面寫書法，寫甲子人日。"},{"who":"R","text":"人日是什麼日子？人人放假日嗎？"},{"who":"A","text":"人日是農曆正月初七。畫在年前、字在年後，一塊板子跨了一個年。"},{"who":"R","text":"原來大師的過年作業這麼有誠意！"},{"who":"A","text":"這裡不開放，請在外面看。之後到天后宮，記得抬頭找找朱錫甘的木雕與彩繪！"}],"clues":["我屋裡有一塊兩面都有作品的壁板","一位福建東山匠師曾在我這裡跨年作畫","沙港村的棧間，與天后宮重建匠師有關"],"quiz":[{"q":"壁板書法落款的「人日」是農曆哪一天？","options":["正月初一","正月十五","正月初七","五月初五"],"answer":2,"explain":"人日是農曆正月初七，可知書法寫於1924年初。"},{"q":"朱錫甘來澎湖最初是為了參與哪項工程？","options":["澎湖天后宮重建","西嶼燈塔興建","跨海大橋興建","媽宮城興築"],"answer":0,"explain":"1922年他來澎湖參與天后宮重建的鑿花與彩繪。"}],"images":[]},{"id":"magong-zongnanting","name":"宗南亭","short":"宗南亭","category":"紀念建築","level":"","town":"馬公市","types":["其他設施"],"lat":23.561036,"lng":119.558559,"address":"澎湖縣馬公市金龍頭營區","announced":"2019-05-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/commemorativeBuilding/20200221000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-09-08/39754091-6bbd-4857-ab56-6fe2b766c75e/LINE_ALBUM_2023820_230820_15.jpg","year":1963,"yearText":"1963年（民國52年）","era":"postwar","themes":["紀念地景","軍事遺構"],"yearUnknown":false,"summary":"營區裡紀念胡宗南將軍的洗石子涼亭","intro":"宗南亭位於馬公市金龍頭營區內，民國52年（1963）由黃杰將軍興建，紀念國軍退守臺澎時期駐守澎湖的司令官胡宗南將軍。亭子造型優美，運用洗石子、磨石子等澎湖在地常見的技法，登錄資料也指出它具有崗哨監視處所的功能。2019年登錄為紀念建築，可與湖西鄉林投公園內的胡宗南紀念雕像互相對照，見證戰後初期澎湖的軍事防衛歷史。因位在營區內，目前不對外開放。","highlights":["洗石子、磨石子的在地工法","紀念戰後駐守澎湖的胡宗南將軍","可與林投公園的胡宗南雕像對照"],"funFact":"這座亭子是紀念建築，名字直接取自胡宗南將軍的「宗南」二字。","photoSpot":"營區內不開放，請勿拍攝軍事設施","visitMin":5,"openNote":"位於馬公市金龍頭營區內，不對外開放，請勿擅入或拍攝軍事設施。可改到湖西鄉林投公園看胡宗南紀念雕像。","dialogue":[{"who":"R","text":"Allan，地圖上這個亭子叫宗南亭，是賣粽子的南部亭子嗎？"},{"who":"A","text":"粽子要等端午節啦。宗南是胡宗南將軍，這座亭子是黃杰將軍在1963年蓋來紀念他的。"},{"who":"R","text":"那位胡宗南將軍，跟澎湖有什麼關係呢？"},{"who":"A","text":"國軍退守臺澎時，他是駐守澎湖的司令官，所以這裡是紀念建築。亭子用了洗石子、磨石子，是澎湖在地常見的工法。"},{"who":"R","text":"那我們進去坐坐、乘個涼好不好？"},{"who":"A","text":"不行喔，它在金龍頭營區裡，不對外開放，經過營區時也請不要停下來拍攝軍事設施喔。"},{"who":"R","text":"好吧，那有沒有一般人看得到的紀念地方？"},{"who":"A","text":"去湖西林投公園找胡宗南將軍的雕像吧，到了現場，記得站在雕像旁邊安靜拍一張合照留念！"}],"clues":["我是1963年由黃杰將軍主持興建的","我身上有洗石子、磨石子的在地工法，還當過崗哨","金龍頭營區裡紀念胡宗南將軍的亭子"],"quiz":[{"q":"宗南亭是為了紀念哪一位將軍？","options":["黃杰","劉銘傳","胡宗南","沈有容"],"answer":2,"explain":"黃杰將軍興建此亭，紀念曾駐守澎湖的胡宗南將軍。"},{"q":"宗南亭可以和哪裡的紀念雕像互相對照？","options":["西嶼燈塔","成功水庫","吉貝沙尾","林投公園"],"answer":3,"explain":"登錄資料提到它可與林投公園的胡宗南雕像相互輝映。"}],"images":[]},{"id":"wangan-huazhaijuluo","name":"望安花宅聚落","short":"花宅聚落","category":"聚落建築群","level":"重要聚落建築群","town":"望安鄉","types":["漢人街庄"],"lat":23.373323,"lng":119.496576,"address":"澎湖縣望安鄉望安鄉中社村","announced":"2010-04-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/groupsOfBuildings/20100414000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/community/114194/photo/望安花宅重要聚落照片原始檔.JPG","year":1685,"yearText":"清康熙年間（約1685年）已見於方志","era":"qing","themes":["聚落地景","咕咾石古厝"],"yearUnknown":false,"summary":"臺灣第一處重要聚落建築群","intro":"望安花宅聚落位於望安鄉望安島中社村，舊名「花宅」，西臨花宅灣，北以天台山為屏障，是澎湖傳統聚落的經典。「花宅」之名在清康熙年間的方志就已出現，居民祖籍以泉州同安為主，分屬頂寮、下寮、尾寮、山仔后四個甲頭，至今仍輪流主持廟宇祭祀。民居多為「一落四櫸頭」「一落二櫸頭」，以咕咾石、玄武岩與在地燒製的白灰砌造，整體風貌均質統一。2003年入選世界文化紀念物基金會的百大守護名單；2006年先由澎湖縣登錄為聚落，2010年再由文化部登錄為臺灣第一處「重要聚落建築群」。近年人口外移，許多房舍傾頹，保存需要大家共同珍惜。","highlights":["色調統一的咕咾石與玄武岩民居群","一落四櫸頭民居的深井、亭與磚坪空間","四個甲頭分布在聚落四邊的空間紋理"],"funFact":"花宅四個甲頭至今仍輪流擔任爐主，共同分擔祭祀與廟宇整修費用。","photoSpot":"從聚落外圍高處拍整片古厝屋頂","visitMin":60,"openNote":"位於望安鄉望安島中社村，聚落為開放空間，但多數古厝為私人所有或仍有人居住，請在外觀參觀、勿擅入私人住宅；部分房舍傾頹，請勿靠近危險建物。望安需從馬公南海遊客服務中心搭船，船程約40到50分鐘。冬季東北季風期（約10月到隔年3月）風浪大，船班減少、常停航，出發前請先查詢船班。","dialogue":[{"who":"R","text":"Allan，這整片老房子的顏色好一致，好像被誰調過濾鏡一樣！"},{"who":"A","text":"這就是花宅的魅力，房子都用咕咾石、玄武岩和在地燒的白灰蓋，整體風貌很統一。"},{"who":"R","text":"那它為什麼叫花宅？是因為種很多花嗎？"},{"who":"A","text":"官方說是因地勢形貌而得名。這個地名在清康熙年間的方志就出現了，資歷很深。"},{"who":"R","text":"資深的名字加上資深的房子，難怪受到重視！"},{"who":"A","text":"沒錯。2006年澎湖縣先登錄為聚落，2010年文化部又登錄為臺灣第一處重要聚落建築群。"},{"who":"R","text":"一口氣升級兩階，是聚落界的模範生！住在這裡的人怎麼分組？"},{"who":"A","text":"分成頂寮、下寮、尾寮、山仔后四個甲頭，輪流當爐主。很多房子還有人住，記得只在外面看。"},{"who":"R","text":"收到！那我去巷子裡找一間一落四櫸頭，數數它有幾個櫸頭！"}],"clues":["2003年我入選世界百大值得關注的文化紀念物","我的居民分成四個甲頭，輪流主持祭祀","我在望安島中社村，是臺灣第一處重要聚落建築群"],"quiz":[{"q":"這處聚落在2010年被文化部登錄為什麼？","options":["重要文化景觀","國定古蹟群","國家級史蹟","重要聚落建築群"],"answer":3,"explain":"2010年登錄為臺灣第一處重要聚落建築群。"},{"q":"花宅居民分成幾個甲頭輪流主掌祭祀？","options":["兩個","三個","四個","五個"],"answer":2,"explain":"分為頂寮、下寮、尾寮、山仔后四個甲頭。"}],"images":[{"file":"P 20201009 145836 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/P_20201009_145836_%28cropped%29.jpg/960px-P_20201009_145836_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:P_20201009_145836_(cropped).jpg","artist":"Tcchang0825","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wangan-huazhaijuluo-0.webp","small":"img/wangan-huazhaijuluo-0-s.webp"}],"extraLinks":[{"title":"文資局官方資料（2006 年澎湖縣登錄「望安花宅」聚落）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/groupsOfBuildings/20061227000001"}]},{"id":"qimei-shiqianshiqizhizao","name":"七美史前石器製造場考古遺址群（包含南港遺址第一、二、三、四地點、東湖遺址、西北灣遺址、西湖遺址）","short":"七美石器製造場","category":"考古遺址","level":"縣(市)定考古遺址","town":"七美鄉","types":[],"lat":23.19144,"lng":119.42558,"address":"澎湖縣七美鄉","announced":"2020-10-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20210303000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-03/86f4c7e9-e12b-407a-bfb9-cef30154e684/DSC_0644.jpg","year":-2500,"yearText":"距今約4500至3000多年前","era":"prehistoric","themes":["考古史前"],"yearUnknown":false,"summary":"四千多年前遠銷臺灣的玄武岩石器工廠","intro":"七美史前石器製造場考古遺址群位於七美鄉七美嶼，包含南港遺址第一至第四地點、東湖、西北灣與西湖遺址，2020年指定為縣定考古遺址。1983年考古學者臧振華在七美發現南港遺址，出土大量玄武岩石器與廢料；2000年他與夏威夷大學學者等人為追查臺灣玄武岩石器的來源再度調查，陸續發現多處大型打石場。研究顯示，距今四千多至三千多年前，七美已有人開採玄武岩、打製石器，並把石器運到約50公里外的臺灣西南部，甚至140公里遠的福建東山島，形成遠古的石器貿易體系。官方說明這是繼東部玉礦產區後，我國第二處重要的石器製造場。","highlights":["地表散落的玄武岩打石廢料與粗胚","南港遺址一帶的史前聚落與打石場","橫渡海峽的史前石器貿易故事"],"funFact":"學者以螢光分析比對石器成分，才發現臺灣西南部的玄武岩石器很可能來自澎湖。","photoSpot":"拍地表玄武岩碎片，但不要帶走","visitMin":30,"openNote":"遺址群分布於七美鄉七美嶼多處（南港、東湖、西北灣、西湖一帶），為戶外考古遺址，請勿撿拾、挖掘或帶走石器與廢料。七美可從馬公搭船經望安前往，或搭小飛機到七美機場。冬季東北季風期（約10月到隔年3月）風浪大，船班減少、常停航，出發前請先查詢船班。","dialogue":[{"who":"R","text":"Allan，地上怎麼散了一堆黑色碎石片，是誰在這裡亂丟石頭？"},{"who":"A","text":"亂丟的人大概是四千多年前的史前工匠！這裡是七美的史前石器製造場。"},{"who":"R","text":"四千多年前就有工廠？那他們生產什麼？"},{"who":"A","text":"用七美的玄武岩打製石器，再運到臺灣西南部，最遠還到140公里外的福建東山島。"},{"who":"R","text":"漂洋過海出口石器？史前人類也太會做國際貿易了吧！"},{"who":"A","text":"這需要長距離航海的本事。1983年臧振華先在這裡發現南港遺址，後來又找到好幾處打石場。"},{"who":"R","text":"那這些碎片就是當年的工廠垃圾囉？"},{"who":"A","text":"沒錯，這些廢料和打石工具正是研究的寶貝，所以千萬不能撿回家當紀念品。"},{"who":"R","text":"好，我只用相機帶走它們，拍一張碎石片的特寫就好！"}],"clues":["四千多年前，有人在我這裡把玄武岩打成石器","我的產品曾漂洋過海到臺灣西南部","我是七美島上好幾處史前打石場組成的遺址群"],"quiz":[{"q":"這處史前石器製造場主要開採哪種石材？","options":["玄武岩","花崗石","大理石","玉石"],"answer":0,"explain":"七美島上的史前打石場開採的是玄武岩。"},{"q":"七美出產的石器最遠曾被運到哪裡？","options":["日本九州","菲律賓呂宋","福建東山島","臺灣東部"],"answer":2,"explain":"考古證據顯示石器曾運到140公里遠的福建東山島。"}],"images":[]},{"id":"baisha-shihuwenhuajing","name":"澎湖石滬文化景觀－吉貝石滬群","short":"吉貝石滬群","category":"文化景觀","level":"文化景觀","town":"白沙鄉","types":["農林漁牧景觀"],"lat":23.736451,"lng":119.611236,"address":"澎湖縣白沙鄉吉貝村週邊海域石滬群","announced":"2008-06-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20080602000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/cultural_tourism/214/photo/澎湖石滬文化景觀－吉貝石滬群.jpg","year":1800,"yearText":"清代已有，確切年代不詳","era":"qing","themes":["石滬漁業","聚落地景"],"yearUnknown":true,"summary":"百餘口石滬環繞，人稱「石滬的故鄉」","intro":"吉貝石滬群位於白沙鄉吉貝嶼周邊海域，2008年登錄為澎湖縣文化景觀。石滬是用玄武岩或咕咾石在潮間帶堆疊成的石堤，漲潮時魚群隨海水游進滬內，退潮時被困在滬房裡，漁民再入滬撿拾漁獲，是順應潮汐的傳統捕魚設施。吉貝在清代就有大滬1口、小滬4口，到1950年代吉貝人已修造超過百口，2007年依衛星航照清查至少有103口。澎湖累計石滬將近600口，可能是全世界石滬最多的地方，吉貝更以密度高、結構多樣稱冠，有「石滬的故鄉」美名。不過許多石滬因無人維護而崩塌，需要匠師一石一石修復，在地也有保滬隊投入修造技術的傳承。","highlights":["退潮時浮現的石堤弧線與滬房","密度少見、型態多樣的百餘口石滬","石滬順應潮汐捕魚的古老智慧"],"funFact":"吉貝在清代只有大小石滬5口，到1950年代吉貝人已修造超過百口，2007年清查至少103口。","photoSpot":"退潮時在岸邊高處拍石滬弧線","visitMin":60,"openNote":"位於白沙鄉吉貝嶼周邊海域，需從白沙赤崁的北海遊客服務中心搭船，船程約20分鐘。請在岸上或觀景處欣賞，不要踩踏、攀爬石滬，也不要搬動石頭；退潮時看得最清楚，下潮間帶請留意漲潮時間。冬季東北季風期（約10月到隔年3月）風浪大，船班減少、常停航，出發前請先查詢船班。","dialogue":[{"who":"A","text":"阿拉蕾，退潮了！你看海面上一圈一圈的石牆，那就是吉貝的石滬。"},{"who":"R","text":"好像有人在海裡畫了好多愛心和箭頭，那是做什麼用的？"},{"who":"A","text":"那是古早的捕魚陷阱。漲潮時魚跟著海水游進來，退潮後出不去，就被困在滬房裡。"},{"who":"R","text":"魚自己走進來？這根本是海上的吃到飽餐廳，只是吃的人是漁民！"},{"who":"A","text":"哈哈，比喻滿分。吉貝在清代只有5口石滬，到1950年代已經修造超過百口，所以叫石滬的故鄉。"},{"who":"R","text":"一百多口！那現在都還好好的嗎？"},{"who":"A","text":"很多石滬因為沒人維護，被風浪打得崩塌，需要匠師一塊一塊再疊回去，非常費工。"},{"who":"R","text":"所以我們只能用眼睛看，不能跳上去走伸展台囉？"},{"who":"A","text":"答對了！不要踩、不要爬、不要搬石頭。請從岸邊數數看，你能看見幾口石滬！"}],"clues":["我是潮間帶上用石頭圍成的捕魚陷阱，數量上百","漲潮魚游進來，退潮就被困在我的滬房裡","我在白沙鄉一座要搭船才到的小島周邊，被稱為石滬的故鄉"],"quiz":[{"q":"石滬主要利用什麼自然現象捕魚？","options":["季風風向","洋流溫差","潮汐漲退","月光照明"],"answer":2,"explain":"漲潮時魚群游進滬內，退潮時被困在滬房裡。"},{"q":"2007年依衛星航照清查，吉貝至少有幾口石滬？","options":["48口","5口","600口","103口"],"answer":3,"explain":"2007年依衛星航照比對，吉貝至少有103口石滬。"}],"images":[]},{"id":"qimei-shuangxinshihu","name":"七美雙心石滬","short":"雙心石滬","category":"文化景觀","level":"文化景觀","town":"七美鄉","types":["農林漁牧景觀"],"lat":23.220252,"lng":119.446974,"address":"澎湖縣七美鄉東湖村頂隙","announced":"2006-10-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20061027000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/cultural_tourism/269/photo/七美雙心石滬.JPG","year":1937,"yearText":"約1937年（昭和12年）前後","era":"japan","themes":["石滬漁業"],"yearUnknown":false,"summary":"兩顆心相連、澎湖最知名的石滬","intro":"七美雙心石滬位於七美鄉東湖村頂隙北面海崖下，又稱「頂隙滬」，2006年登錄為澎湖縣文化景觀。石滬是在潮間帶以石塊圍成的石堤，漲潮時魚群隨海水進入覓食，退潮後被困在滬房裡，漁民再入滬捕撈。雙心石滬以玄武岩建造，有內、外滬房，左伸腳末端彎成螺鉤狀，右伸腳銜接岸邊，滬內還設有魚井。據澎湖縣文化資產手冊，這口石滬約在1937年前後建造，後來因風浪傾倒而重新設計，形成今天兩顆心相連的模樣，象徵「心心相印」，成為七美最受歡迎的景點。澎湖許多石滬因無人維護而崩塌，需要匠師修復，雙心石滬也曾因受損而進行修復。","highlights":["從海崖觀景台俯瞰兩顆相連的心形滬房","左伸腳末端彎成螺鉤狀的設計","退潮時清楚浮現的石堤與魚井"],"funFact":"雙心石滬原本不是雙心，舊滬被風浪打倒後重新設計，多了一個滬房才變成兩顆心。","photoSpot":"退潮時在觀景台俯拍兩顆心","visitMin":30,"openNote":"位於七美鄉東湖村頂隙北側海崖下，請在上方觀景台或岸上欣賞，不要踩踏、攀爬石滬，也不要搬動石頭；退潮時最容易看見完整心形。七美可從馬公搭船經望安前往，或搭小飛機到七美機場。冬季東北季風期（約10月到隔年3月）風浪大，船班減少、常停航，出發前請先查詢船班。","dialogue":[{"who":"R","text":"哇，Allan，海裡真的有兩顆愛心！是哪對情侶這麼浪漫，用石頭在海裡告白？"},{"who":"A","text":"哈哈，它其實是捕魚陷阱，叫雙心石滬。漲潮時魚游進來吃東西，退潮就被困在滬房裡。"},{"who":"R","text":"所以魚是被愛心騙進來的？好心機喔！"},{"who":"A","text":"這叫順著潮汐的智慧。它用玄武岩疊成，有內外兩個滬房，左邊伸腳的尾端還彎成螺鉤狀。"},{"who":"R","text":"那它一開始就是設計成兩顆心嗎？"},{"who":"A","text":"不是喔。據文化資產手冊，大約1937年前後建造，後來被風浪打倒，重新設計才變成雙心。"},{"who":"R","text":"被打倒還能變得更美，根本是石滬界的勵志故事！"},{"who":"A","text":"不過石滬很怕被踩，很多石滬就是沒人維護才崩塌的。請在觀景台上看，不要下去踩、也不要搬石頭。"},{"who":"R","text":"遵命！那我等退潮的時候，從觀景台把兩顆心完整拍進來！"}],"clues":["我是潮間帶上的捕魚石堤，有內外兩個滬房","我在東湖村頂隙北面海崖下，又叫頂隙滬","我長得像兩顆相連的心，是七美最熱門的景點"],"quiz":[{"q":"這口石滬主要用什麼石材建造？","options":["咕咾石","花崗石","玄武岩","大理石"],"answer":2,"explain":"雙心石滬以玄武岩建造。"},{"q":"欣賞雙心石滬時，正確的做法是什麼？","options":["退潮時下去撿魚","在觀景台上欣賞","爬上石堤拍照","搬石頭疊愛心"],"answer":1,"explain":"請在觀景台或岸上欣賞，不要踩踏、攀爬石滬。"}],"images":[{"file":"Double-Heart of Stacked Stones 20150721.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Double-Heart_of_Stacked_Stones_20150721.jpg/960px-Double-Heart_of_Stacked_Stones_20150721.jpg","page":"https://commons.wikimedia.org/wiki/File:Double-Heart_of_Stacked_Stones_20150721.jpg","artist":"Zeze0729","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","local":"img/qimei-shuangxinshihu-0.webp","small":"img/qimei-shuangxinshihu-0-s.webp"}]}],"eras":[{"id":"dutch","name":"宋元明與荷蘭時期","range":"史前–1662","cityName":"彭湖、平湖（元明設澎湖寨巡檢司，屬同安縣）","title":"海峽中央的漁人之島","summary":"澎湖至少在五千年前就有人居住，距今四千多年前，七美島上已有玄武岩打石場，石材遠送到臺灣西南部。南宋時泉州知州汪大猷曾在澎湖造屋駐軍；元代設澎湖寨巡檢司，設置年代說法不一。明代海禁時期巡檢司曾廢而復設，仍有許多閩南漁民來此捕魚，葡萄牙人因此稱這裡為漁人之島。1604年荷蘭人韋麻郎進入澎湖求通商，沈有容率兵船交涉，荷蘭人於年底離開，天后宮至今保存「沈有容諭退紅毛番韋麻郎等」石碑。1622年荷蘭東印度公司在風櫃尾蛇頭山築城，並從中國沿海擄來一千多名漢人修城，許多人病死、餓死；荷蘭方面則記載談判代表遭毒殺扣押。1624年明軍圍城，雙方議定荷蘭人撤往大員，同年9月拆城離去。此後澎湖重回明朝掌握。","events":[{"year":"距今約4000多至3000多年前","text":"七美島出現玄武岩打石場，石材運往臺灣西南部"},{"year":"南宋","text":"泉州知州汪大猷在澎湖造屋，派兵戍守"},{"year":"元代","text":"設澎湖寨巡檢司，隸屬福建同安縣"},{"year":"1384","text":"明朝實施海禁，廢澎湖巡檢司；1563年復設"},{"year":"1604","text":"沈有容率兵船到澎湖，諭退荷蘭人韋麻郎"},{"year":"1622","text":"荷蘭東印度公司在風櫃尾蛇頭山築城"},{"year":"1624","text":"明軍圍城，荷蘭人拆城撤往大員"}],"population":"","landmarks":[{"name":"七美史前石器製造場考古遺址群","lat":23.19144,"lng":119.42558,"note":"距今四千多年前的玄武岩打石場，石材遠銷臺灣西南部","approx":false},{"name":"澎湖天后宮（娘媽宮）","lat":23.564832,"lng":119.563924,"note":"保存1604年沈有容諭退紅毛番碑，明代稱娘媽宮","approx":false},{"name":"萬軍井","lat":23.564605,"lng":119.56427,"note":"1622年荷蘭艦隊日誌記載在小廟旁水井取水，推測即此井","approx":true},{"name":"風櫃尾荷蘭城堡（蛇頭山）","lat":23.553719,"lng":119.548544,"note":"1622年築城，邊長約55公尺的方形稜堡，1624年拆除","approx":false},{"name":"鎮海（明軍築城處）","lat":23.6436,"lng":119.5994,"note":"1624年明軍在北方的鎮海一帶築石城，進攻風櫃尾城","approx":true},{"name":"娘媽宮前架砲處","lat":23.5646,"lng":119.5636,"note":"1624年明軍在娘媽宮架設火砲，隔海對準風櫃尾城","approx":true}],"view":{"lat":23.43,"lng":119.53,"zoom":11},"dialogue":[{"who":"R","text":"Allan，時光機好像故障了，怎麼一口氣倒退到四千多年前？"},{"who":"A","text":"沒故障啦！澎湖的故事就是這麼長。那時七美島上已經有人在敲玄武岩，做石器出口到臺灣。"},{"who":"R","text":"史前就有外銷產業？那七美算是石器界的科學園區耶！"},{"who":"A","text":"比喻滿分！到了宋元明，澎湖有駐軍、有巡檢司，漁民來來去去，葡萄牙人乾脆叫這裡漁人之島。"},{"who":"R","text":"那荷蘭人呢？我記得他們不是在臺南嗎？"},{"who":"A","text":"他們其實先來澎湖！1604年韋麻郎來求通商，沈有容帶兵船來談判，荷蘭人年底就離開了。"},{"who":"R","text":"可是1622年他們又回來，還在風櫃尾蓋了城堡，對吧？"},{"who":"A","text":"沒錯，還從沿海抓了上千名漢人來修城，很多人死在工地。1624年明軍圍城，雙方談妥，荷蘭人拆城搬去大員。"},{"who":"R","text":"原來熱蘭遮城的故事，是從澎湖的一座拆掉的城堡開始的！"},{"who":"A","text":"到天后宮的清風閣找那塊沈有容石碑，數數看碑上的字，跟四百多年前的談判打聲招呼。"}],"quiz":[{"q":"天后宮保存的「沈有容諭退紅毛番韋麻郎等」石碑，記錄的是哪一年的事？","options":["1604年","1622年","1661年","1683年"],"answer":0,"explain":"1604年荷蘭艦隊司令韋麻郎進入澎湖求通商，都司沈有容前來交涉，荷蘭人於當年底離開。"},{"q":"1622年荷蘭人在澎湖哪裡築城？","options":["西嶼外垵","馬公金龜頭","風櫃尾蛇頭山","七美南港"],"answer":2,"explain":"荷蘭東印度公司在風櫃尾蛇頭山的小半島上築城，1624年拆城撤往大員。"}],"sources":[{"title":"七美史前石器製造場考古遺址群（包含南港遺址第一、二、三、四地點、東湖遺址、西北灣遺址、西湖遺址）（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20210303000001"},{"title":"澎湖天后宮（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19831228000013"},{"title":"馬公風櫃尾荷蘭城堡（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20011121000001"},{"title":"施公祠及萬軍井（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000092"},{"title":"澎湖寨巡檢司（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖寨巡檢司"},{"title":"沈有容（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/沈有容"},{"title":"風櫃尾荷蘭城堡（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/風櫃尾荷蘭城堡"},{"title":"澎湖縣，歷史章節（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖縣"}]},{"id":"zheng","name":"明鄭時期","range":"1662–1683","cityName":"澎湖（明鄭政權轄下）","title":"東寧門戶與澎湖海戰","summary":"1661年鄭成功率軍東征，艦隊以澎湖為前進基地與補給中繼站，隔年逐走大員的荷蘭人，澎湖成為明鄭政權的海上門戶。1683年清廷派福建水師提督施琅攻臺，明鄭由劉國軒坐鎮澎湖，在媽宮、風櫃尾、四角山、雞籠山、東西嵵內及西嶼內外塹等處趕築砲城、砲臺，沿岸可登陸處也築起短牆。同年農曆六月十六日到二十二日（西曆約7月上旬至中旬），雙方在澎湖海域激戰，清軍取得決定性勝利，明鄭將領多人陣亡，劉國軒率殘部由吼門撤回臺灣。9月鄭克塽向施琅投降，明鄭政權結束。這場海戰雙方傷亡慘重。後來流傳施琅入媽祖宮見神衣半濕、井湧甘泉等故事，天后宮東側的大井因此被稱為萬軍井，屬民間傳說。","events":[{"year":"1661","text":"鄭成功東征，以澎湖為艦隊中繼站"},{"year":"1662","text":"荷蘭人投降，澎湖成為明鄭的海上門戶"},{"year":"1683","text":"劉國軒坐鎮澎湖，各地趕築砲城與砲臺"},{"year":"1683","text":"7月澎湖海戰，施琅擊敗劉國軒"},{"year":"1683","text":"劉國軒由吼門撤回臺灣"},{"year":"1683","text":"9月鄭克塽投降，明鄭政權結束"}],"population":"","landmarks":[{"name":"媽祖宮（今澎湖天后宮）","lat":23.564832,"lng":119.563924,"note":"相傳施琅戰後入廟拜謁，後奏請加封媽祖","approx":false},{"name":"萬軍井（大井）","lat":23.564605,"lng":119.56427,"note":"民間傳說施琅大軍取水不竭而得名","approx":false},{"name":"西嶼內外塹砲臺（今西嶼西臺一帶）","lat":23.564073,"lng":119.489281,"note":"施琅奏疏記載西嶼頭一列砲臺四座，西臺始創於此時","approx":true},{"name":"風櫃尾砲城","lat":23.553719,"lng":119.548544,"note":"荷蘭城堡舊址，明鄭在此築砲城一座","approx":false},{"name":"東西嵵內砲臺一帶","lat":23.525442,"lng":119.570518,"note":"奏疏記載東西嵵內一列砲臺四座，位置為推定","approx":true},{"name":"媽宮嶼頭砲城（金龜頭一帶）","lat":23.563284,"lng":119.557737,"note":"奏疏記載媽宮嶼頭上下添築砲城二座，位置為推定","approx":true}],"view":{"lat":23.56,"lng":119.54,"zoom":12},"dialogue":[{"who":"A","text":"時間來到1661年，鄭成功的艦隊浩浩蕩蕩經過澎湖，在這裡補給，再一路開往大員。"},{"who":"R","text":"所以澎湖就像高速公路的休息站？加油、上廁所、買茶葉蛋？"},{"who":"A","text":"差不多啦，只是休息站後來變成前線。1683年施琅帶清軍打過來，劉國軒在澎湖到處趕蓋砲臺。"},{"who":"R","text":"到處是多到處？地圖上這麼多點，都是砲臺嗎？"},{"who":"A","text":"媽宮、風櫃尾、嵵裡、西嶼都有，海邊能上岸的地方還砌短牆，施琅形容得像鐵桶一樣。"},{"who":"R","text":"鐵桶也擋不住嗎？最後到底是誰打贏了？"},{"who":"A","text":"農曆六月那一戰打了好幾天，清軍大勝，雙方死傷都很慘重，劉國軒從吼門退回臺灣，幾個月後鄭克塽投降。"},{"who":"R","text":"聽起來好沉重，那萬軍井的故事又是怎麼來的？"},{"who":"A","text":"傳說施琅大軍缺水，井裡湧出甘泉，幾萬人喝不完，這是後人記下的傳說，聽聽就好。"},{"who":"A","text":"到中央街附近找萬軍井，低頭看看井口，想想三百多年前排隊打水的士兵。"}],"quiz":[{"q":"1683年澎湖海戰中，率領清軍的是誰？","options":["鄭經","施琅","劉國軒","沈有容"],"answer":1,"explain":"福建水師提督施琅率軍攻澎，擊敗坐鎮澎湖的明鄭將領劉國軒。"},{"q":"澎湖海戰後，劉國軒從哪裡撤回臺灣？","options":["吼門","鹿耳門","林投","風櫃尾"],"answer":0,"explain":"劉國軒戰敗後率殘部由澎湖北面的吼門撤回臺灣。"}],"sources":[{"title":"澎湖海戰（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖海戰"},{"title":"西嶼西臺（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19831228000014"},{"title":"施公祠及萬軍井（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000092"},{"title":"澎湖天后宮（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19831228000013"},{"title":"澎湖縣，歷史章節（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖縣"}]},{"id":"qing","name":"清代","range":"1683–1895","cityName":"澎湖廳（廳治先在文澳，1889年遷入媽宮城）","title":"媽宮街、書院與海防城","summary":"清廷領有澎湖後，1684年先在文澳設巡檢司，1727年改設通判，是澎湖廳的開始。媽宮港四季可泊船，逐漸發展出「七街一市」的熱鬧市街，施琅戰後奏請加封媽祖為天后，媽祖宮也改稱天后宮。1766年創建文石書院，1844年澎湖人蔡廷蘭考中進士。1778年西嶼建七級石塔燈，1875年改建為鑄鐵西式燈塔。1885年清法戰爭中，法軍孤拔艦隊於3月29日攻澎，3月31日占領媽宮，孤拔也在6月病逝澎湖，法軍因疫病死者近千人，和議後撤離。戰後清廷記取教訓，總兵吳宏洛在1887年至1889年間興建媽宮城，以及金龜頭、大城北（拱北）、西嶼東臺、西嶼西臺等新式礮臺，配置英國製後膛砲。1889年通判衙門也遷入媽宮城。","events":[{"year":"1684","text":"清廷在文澳設巡檢司，媽祖加封天后"},{"year":"1727","text":"裁巡檢、設通判，澎湖廳成立"},{"year":"1766","text":"創建文石書院，後成為澎湖文教中心"},{"year":"1778","text":"蔣元樞在西嶼創建七級石塔燈"},{"year":"1844","text":"蔡廷蘭考中進士，人稱開澎進士"},{"year":"1875","text":"西嶼改建鑄鐵西式燈塔，命名漁翁島燈塔"},{"year":"1885","text":"清法戰爭，法軍攻占澎湖，和議後撤離"},{"year":"1887–1889","text":"興建媽宮城與四座新式礮臺"}],"population":"","landmarks":[{"name":"媽宮城（順承門）","lat":23.563036,"lng":119.562201,"note":"1887年動工、1889年竣工，臺灣清代最後一座城","approx":false},{"name":"澎湖天后宮","lat":23.564832,"lng":119.563924,"note":"1684年媽祖加封天后，媽祖宮改稱天后宮","approx":false},{"name":"文澳（巡檢司、通判衙門一帶）","lat":23.565515,"lng":119.583669,"note":"1684年起的行政中心，文澳城隍廟在廳署東側","approx":true},{"name":"文石書院魁星樓","lat":23.566691,"lng":119.580193,"note":"書院1766年創建，魁星樓1829年改建","approx":false},{"name":"蔡廷蘭進士第","lat":23.550677,"lng":119.611524,"note":"開澎進士蔡廷蘭1846年返鄉所建","approx":false},{"name":"西嶼燈塔（漁翁島燈塔）","lat":23.562421,"lng":119.46958,"note":"1778年石塔燈，1875年改建為鑄鐵西式燈塔","approx":false},{"name":"西嶼西臺","lat":23.564073,"lng":119.489281,"note":"1887年起興建，門額「西嶼西臺」為劉銘傳所題","approx":false},{"name":"拱北礮臺（大城北）","lat":23.562691,"lng":119.609654,"note":"掩護媽宮港背面的內陸礮臺","approx":false}],"view":{"lat":23.565,"lng":119.54,"zoom":12},"dialogue":[{"who":"R","text":"Allan，清代的媽宮聽說很熱鬧，有七條街一個市場！"},{"who":"A","text":"對啊，港口四季能停船，又有軍隊駐紮，買賣做不完。不過一開始官府其實設在文澳，不在媽宮。"},{"who":"R","text":"那讀書人呢？澎湖風那麼大，書會不會被吹走？"},{"who":"A","text":"所以要用石頭壓著讀啊！1766年蓋了文石書院，後來蔡廷蘭還考上進士，是澎湖唯一的進士。"},{"who":"R","text":"那西嶼那座有名的燈塔，也是這時候蓋的嗎？"},{"who":"A","text":"1778年先蓋七層石塔，頂上點長明燈，1875年海關再改建成鑄鐵燈塔，是臺澎第一座西式燈塔。"},{"who":"R","text":"可是1885年法國艦隊打過來了，對吧？"},{"who":"A","text":"是的，法軍三天就占了媽宮，可是自己也因疫病死了近千人，連司令孤拔都病逝在澎湖，戰爭對誰都不好受。"},{"who":"R","text":"所以後來才蓋媽宮城和那些大砲臺？"},{"who":"A","text":"沒錯，打開地圖上的1904年堡圖，沿著民生路和中山路描一圈，就是媽宮城的範圍，到順承門找找城牆上的石頭。"}],"quiz":[{"q":"媽宮城是在哪一場戰爭之後興建的？","options":["鴉片戰爭","清法戰爭","甲午戰爭","林爽文事件"],"answer":1,"explain":"1885年清法戰爭中法軍輕易占領澎湖，清廷記取教訓，1887年至1889年興建媽宮城與新式礮臺。"},{"q":"創建於1766年、日治時期改為孔廟的書院是哪一所？","options":["文石書院","崇文書院","海東書院","明志書院"],"answer":0,"explain":"文石書院創建於1766年，日治時期改為孔廟，魁星樓至今保存。"}],"sources":[{"title":"媽宮古城（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/媽宮古城"},{"title":"澎湖廳（清治時期）（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖廳_(清治時期)"},{"title":"澎湖之役（1885年）（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖之役_(1885年)"},{"title":"媽宮古城（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000086"},{"title":"文澳城隍廟（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000090"},{"title":"馬公文石書院魁星樓（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000007"},{"title":"蔡廷蘭進士第（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000089"},{"title":"西嶼燈塔(漁翁島燈塔)（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19870417000003"},{"title":"西嶼西臺（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19831228000014"},{"title":"西嶼東臺（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19911123000004"}]},{"id":"japan","name":"日治時期","range":"1895–1945","cityName":"澎湖廳（1920至1926年為高雄州澎湖郡）；媽宮1920年改稱馬公","title":"要塞、軍港與新市街","summary":"1895年甲午戰爭議和期間，日軍於3月23日在湖西龍門的裡正角一帶登陸，隔日攻下拱北礮臺，媽宮城隨即失守。清軍守將與兵勇死傷，日軍在戰前已爆發霍亂，病死者遠多於戰死者。4月馬關條約割讓臺灣、澎湖。日本先設澎湖列島行政廳，1897年改稱澎湖廳。澎湖被定為要塞，1901年馬公港設海軍要港部，1902年成立澎湖島要塞司令部，西嶼一帶的礮臺與彈藥庫陸續擴建。當局推動市區改正、築港、自來水與郵電等建設，同時也分段拆除媽宮城牆填海造港。1920年媽宮改名馬公，同年澎湖廳改為高雄州澎湖郡，1926年復設澎湖廳，1933年興建今縣政府所在的廳舍。二戰末期澎湖遭美軍空襲，日軍也在西嶼等地挖掘震洋特攻艇的格納壕。","events":[{"year":"1895","text":"3月23日日軍在裡正角登陸，媽宮城失守"},{"year":"1897","text":"改稱澎湖廳，治所在媽宮"},{"year":"1901","text":"馬公港定為要港，設海軍要港部"},{"year":"1902","text":"成立澎湖島要塞司令部"},{"year":"1920","text":"媽宮改名馬公，澎湖廳改為高雄州澎湖郡"},{"year":"1926","text":"復設澎湖廳"},{"year":"1933","text":"澎湖廳舍興建，今為澎湖縣政府"},{"year":"1945","text":"二戰末期遭美軍空襲，同年日本戰敗"}],"population":"","landmarks":[{"name":"龍門裡正角日軍上陸紀念碑","lat":23.554499,"lng":119.681525,"note":"1895年日軍登陸處，1924年立碑，戰後碑文曾被改寫","approx":false},{"name":"林投日軍上陸紀念碑","lat":23.561594,"lng":119.644877,"note":"1936年立碑，戰後改為抗戰勝利紀念碑","approx":false},{"name":"拱北礮臺","lat":23.562691,"lng":119.609654,"note":"1895年日軍首要攻占目標，今仍為軍事用地","approx":false},{"name":"澎湖廳舍","lat":23.57007,"lng":119.566468,"note":"1933年興建，五州三廳唯一留存的廳舍","approx":false},{"name":"澎湖島要塞司令部（今澎防部建築群）","lat":23.565391,"lng":119.561743,"note":"1903年起在清代大校場興建營舍","approx":false},{"name":"澎湖郵便局","lat":23.563428,"lng":119.563903,"note":"1924年創建的郵電所","approx":false},{"name":"馬公水道貯水隧道","lat":23.569891,"lng":119.57367,"note":"1927年創建，當時離島唯一的水道系統","approx":false},{"name":"西嶼東鼻頭震洋艇格納壕","lat":23.56723,"lng":119.514788,"note":"二戰末期藏放震洋特攻艇的洞窟","approx":false}],"view":{"lat":23.57,"lng":119.575,"zoom":12},"dialogue":[{"who":"R","text":"1895年的地圖上，湖西海邊怎麼多了兩塊紀念碑？"},{"who":"A","text":"那是日軍登陸的地方。3月23日在龍門裡正角上岸，隔天打下拱北礮臺，媽宮城很快就失守了。"},{"who":"R","text":"奇怪，那時候馬關條約不是還沒簽嗎？"},{"who":"A","text":"對，日本趁議和時先拿下澎湖當籌碼。清軍有不少傷亡，日軍反而是霍亂病死的人比戰死的多。"},{"who":"R","text":"好沉重。那接下來五十年，澎湖變成什麼樣子？"},{"who":"A","text":"變成大要塞，馬公還設了海軍要港部，同時也有築港、自來水、郵局這些建設，可是城牆被拆去填海。"},{"who":"R","text":"等一下，媽宮什麼時候變成馬公的？"},{"who":"A","text":"1920年改的，發音差不多，字變了，就像換了一個新名牌，人還是同一個人。"},{"who":"R","text":"那今天的縣政府，是不是也是那時候蓋的？"},{"who":"A","text":"1933年興建的澎湖廳舍。去治平路看看它的玄武岩牆基，數數看有幾扇上下推窗。"}],"quiz":[{"q":"1895年日軍在澎湖的登陸地點是哪裡？","options":["西嶼外垵","湖西龍門裡正角","白沙赤崁","望安花宅"],"answer":1,"explain":"日軍於1895年3月23日在湖西龍門的裡正角一帶登陸，今有上陸紀念碑。"},{"q":"「媽宮」在哪一年改名為「馬公」？","options":["1895年","1901年","1920年","1945年"],"answer":2,"explain":"1920年日本政府將媽宮改名為馬公。"}],"sources":[{"title":"澎湖之役（1895年）（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖之役_(1895年)"},{"title":"澎湖廳（日治時期）（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖廳_(日治時期)"},{"title":"馬公要港部（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/馬公要港部"},{"title":"媽宮古城（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/媽宮古城"},{"title":"龍門裡正角日軍上陸紀念碑（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20000128000005"},{"title":"林投日軍上陸紀念碑（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20000128000004"},{"title":"湖西拱北礮臺（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20011121000003"},{"title":"澎湖廳舍（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000001"},{"title":"澎防部建築群（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190724000001"},{"title":"西嶼東鼻頭震洋艇格納壕（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20110321000001"},{"title":"西嶼燈塔(漁翁島燈塔)（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19870417000003"}]},{"id":"early-roc","name":"戰後初期","range":"1945–1960年代","cityName":"澎湖縣（縣治馬公鎮）","title":"海峽前哨的軍事重鎮","summary":"1945年日本戰敗，中華民國接管澎湖，澎湖廳改制為澎湖縣，縣治設在馬公鎮。軍方利用日軍原有營舍成立馬公要塞司令部，1949年政府撤退來臺，大批軍人與眷屬來到澎湖，日式官舍成了一棟住兩三戶的眷舍，就是後來的篤行十村。同年5月蔣中正首次下榻日軍所建的第一賓館，1958年八二三砲戰時也曾在此設指揮所。1950年廢除縣轄區，各鄉鎮改由縣直轄。冷戰氛圍下，西嶼燈塔在1951年因防空需要塗上迷彩，1954年澎湖青年響應自由日運動決議興建自由塔。1962年媽宮城大西門改建，改稱中興門。這段時期的澎湖既是軍事前哨，也是許多人重新落腳的新家，戒嚴體制下軍方對地方事務影響很大。","events":[{"year":"1945","text":"中華民國接管，澎湖廳改制為澎湖縣"},{"year":"1949","text":"大批軍民撤退來澎，日式官舍成為眷舍"},{"year":"1949","text":"5月蔣中正首次下榻第一賓館"},{"year":"1950","text":"廢除縣轄區，鄉鎮改由縣直轄"},{"year":"1951","text":"西嶼燈塔因防空需要塗上迷彩"},{"year":"1954","text":"響應自由日運動，決議興建自由塔"},{"year":"1958","text":"八二三砲戰期間，第一賓館設指揮所"},{"year":"1962","text":"媽宮城大西門改建，改稱中興門"}],"population":"","landmarks":[{"name":"第一賓館","lat":23.568955,"lng":119.563351,"note":"日軍所建，1949年起成為總統行館，兼作戰指揮所","approx":false},{"name":"篤行十村","lat":23.563858,"lng":119.56098,"note":"日治官舍群，戰後成為眷村，2007年眷戶遷出","approx":false},{"name":"澎防部建築群","lat":23.565391,"lng":119.561743,"note":"日軍營舍，戰後由國軍沿用","approx":false},{"name":"自由塔","lat":23.569958,"lng":119.571273,"note":"響應1954年自由日運動而建","approx":false},{"name":"媽宮古城（順承門）","lat":23.563036,"lng":119.562201,"note":"城牆因位在營區外圍而保存下來","approx":false},{"name":"西瀛勝境牌樓","lat":23.567702,"lng":119.56298,"note":"1947年創建的牌樓","approx":false},{"name":"澎湖縣政府（原澎湖廳舍）","lat":23.57007,"lng":119.566468,"note":"戰後沿用為縣政府","approx":false}],"view":{"lat":23.566,"lng":119.565,"zoom":14},"dialogue":[{"who":"R","text":"1945年以後，地圖上的名字從澎湖廳變成澎湖縣了！"},{"who":"A","text":"對，日本戰敗後中華民國接管，縣治設在馬公鎮。不過最大的改變發生在1949年。"},{"who":"R","text":"1949年發生什麼事？怎麼地圖上突然多了好多房子？"},{"who":"A","text":"政府撤退來臺，很多軍人和家眷來到澎湖。日本軍官的宿舍一棟擠兩三戶，就變成了篤行十村。"},{"who":"R","text":"一棟住三家人？那早上搶廁所一定很刺激！"},{"who":"A","text":"所以大家發明了排隊的藝術啊。同一年蔣中正也住進第一賓館，八二三砲戰時這裡還當過指揮所。"},{"who":"R","text":"那西嶼燈塔怎麼變成迷彩的？是要去參加變裝派對嗎？"},{"who":"A","text":"是防空啦，1951年塗上迷彩，免得被當成目標，後來才恢復白色。"},{"who":"A","text":"去篤行十村走走，找一找順承門旁邊的老城牆，看看眷村的屋子怎麼貼著城牆過日子。"}],"quiz":[{"q":"篤行十村的眷舍，前身主要是什麼建築？","options":["清代兵營","日治時期軍官宿舍","荷蘭商館","日治時期的學校"],"answer":1,"explain":"篤行十村一帶原是日治時期澎湖島要塞司令部、重砲兵大隊等的官舍，戰後成為眷舍。"},{"q":"西嶼燈塔在1951年為什麼塗上迷彩？","options":["拍電影需要","颱風季節保護","防空需要","慶祝通車"],"answer":2,"explain":"1951年3月西嶼燈塔因防空需要塗上迷彩色，後來才恢復白色。"}],"sources":[{"title":"澎湖縣，歷史與行政區劃章節（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖縣"},{"title":"媽宮古城（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/媽宮古城"},{"title":"第一賓館（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19981210000001"},{"title":"馬公篤行十村（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071121000002"},{"title":"自由塔（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150622000002"},{"title":"西嶼燈塔(漁翁島燈塔)（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19870417000003"},{"title":"澎防部建築群（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190724000001"},{"title":"西瀛勝境牌樓（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000008"}]},{"id":"roc60","name":"民國60年前後","range":"約1963–1981","cityName":"澎湖縣（1981年馬公鎮升格為縣轄市）","title":"跨海大橋把島嶼連起來","summary":"1960年代起，澎湖的建設重點是交通與民生。最具代表性的是澎湖跨海大橋：1965年3月動工，1970年12月完工通車，連接白沙島與西嶼，原橋長2160公尺，當年被稱為遠東第一跨海大橋，從此本島、白沙、西嶼開車就能直達。為了解決缺水，1972年起興建成功水庫，是澎湖最早也最大的水庫。1963年孔廟重修時，只有文石書院的魁星樓保留原貌；1964年在馬公機場旁興建空軍眷村隘門新村；同年起也引進日商技術發展珊瑚加工。1966年西嶼燈塔改裝電燈，光程更遠。不過就業機會有限，人口外移是澎湖長期的課題。1981年馬公鎮升格為縣轄市，形成今天一市五鄉的格局。","events":[{"year":"1963","text":"孔廟重修，魁星樓保留原貌"},{"year":"1964","text":"興建空軍眷村隘門新村"},{"year":"1965","text":"澎湖跨海大橋動工"},{"year":"1966","text":"西嶼燈塔改裝四等旋轉透鏡電燈"},{"year":"1970","text":"12月跨海大橋完工通車，連接白沙與西嶼"},{"year":"1973","text":"成功水庫完工，紓解馬公缺水"},{"year":"1981","text":"馬公鎮升格為縣轄市，全縣一市五鄉"}],"population":"","landmarks":[{"name":"澎湖跨海大橋","lat":23.658029,"lng":119.554602,"note":"1970年通車，原橋長2160公尺","approx":false},{"name":"成功水庫","lat":23.579301,"lng":119.624132,"note":"1972年興建、1973年完工，澎湖最早的水庫","approx":false},{"name":"隘門新村","lat":23.557465,"lng":119.632912,"note":"1964年興建的空軍眷村，緊鄰馬公機場","approx":false},{"name":"澎湖孔廟魁星樓","lat":23.566691,"lng":119.580193,"note":"1963年孔廟重修時唯一保留原貌的建築","approx":false},{"name":"西嶼燈塔","lat":23.562421,"lng":119.46958,"note":"1966年改裝電燈，光程約25海浬","approx":false},{"name":"湖西朝日貝釦工廠","lat":23.582913,"lng":119.638825,"note":"貝釦產業式微後，1964年起轉型發展珊瑚加工","approx":false}],"view":{"lat":23.6,"lng":119.57,"zoom":12},"dialogue":[{"who":"R","text":"Allan快看！1970年白沙和西嶼之間多了一條長長的線！"},{"who":"A","text":"那就是澎湖跨海大橋！1965年動工，1970年12月通車，原橋長2160公尺，當年號稱遠東第一。"},{"who":"R","text":"以前去西嶼要搭船，現在騎機車就到了，太方便了吧！"},{"who":"A","text":"對啊，三個大島從此手牽手。不過風大的時候過橋，帽子記得抓緊，不然它會先幫你游到對岸。"},{"who":"R","text":"那澎湖一直缺水的問題，又是怎麼解決的？"},{"who":"A","text":"1972年開始蓋成功水庫，隔年完工，是澎湖最早的水庫，周邊現在也是賞鳥的好地方。"},{"who":"R","text":"有橋有水庫，這時候人口是不是越來越多？"},{"who":"A","text":"其實相反，工作機會少，很多年輕人到臺灣本島打拼。1981年馬公鎮升格為市，變成今天一市五鄉。"},{"who":"A","text":"到跨海大橋兩端的橋門，找找紀念碑，看看上面刻的是哪一年。"}],"quiz":[{"q":"第一代澎湖跨海大橋是哪一年完工通車？","options":["1962年","1970年","1981年","1996年"],"answer":1,"explain":"跨海大橋1965年動工，1970年12月完工通車。"},{"q":"澎湖跨海大橋連接哪兩個島？","options":["澎湖本島與白沙","白沙與西嶼","西嶼與望安","望安與七美"],"answer":1,"explain":"跨海大橋連接白沙島的通樑與西嶼的橫礁。"}],"sources":[{"title":"澎湖跨海大橋（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖跨海大橋"},{"title":"澎湖縣，行政區劃章節（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖縣"},{"title":"澎湖跨海大橋（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000007"},{"title":"成功水庫水壩（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000009"},{"title":"隘門新村（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071121000003"},{"title":"馬公文石書院魁星樓（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021213000007"},{"title":"西嶼燈塔(漁翁島燈塔)（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19870417000003"},{"title":"湖西朝日貝釦工廠（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000008"}]},{"id":"now","name":"現在","range":"1982–今","cityName":"澎湖縣（馬公市、湖西鄉、白沙鄉、西嶼鄉、望安鄉、七美鄉）","title":"從軍事前線到文化之島","summary":"1980年代以後，澎湖的古蹟陸續被指定保存，1983年天后宮列為一級古蹟，1985年媽宮古城公告為古蹟，2001年風櫃尾荷蘭城堡等成為國定古蹟。跨海大橋因長年風浪侵蝕，1984年動工改建，1996年3月新橋通車。1995年成立澎湖國家風景區，觀光取代漁業成為重要產業；軍隊逐步撤出後，篤行十村等眷村與營區也開始修復再利用。石滬是澎湖獨特的漁業智慧，以石塊在潮間帶圍成堤，漲潮時魚群游入、退潮時被困在滬房內，七美雙心石滬與吉貝石滬群先後登錄為文化景觀，但許多石滬因無人維護而崩塌，需要匠師修復。2010年望安花宅登錄為重要聚落建築群，2020年七美史前石器製造場指定為考古遺址。人口外移仍是澎湖的挑戰。","events":[{"year":"1983","text":"澎湖天后宮列為一級古蹟"},{"year":"1985","text":"媽宮古城公告為古蹟"},{"year":"1995","text":"成立澎湖國家風景區"},{"year":"1996","text":"3月改建後的跨海大橋通車"},{"year":"2006","text":"七美雙心石滬登錄為文化景觀"},{"year":"2010","text":"望安花宅登錄為重要聚落建築群"},{"year":"2014","text":"澎湖南方四島國家公園成立"},{"year":"2020","text":"七美史前石器製造場考古遺址群指定公告"}],"population":"約10.8萬人（2023年底戶籍人口）","landmarks":[{"name":"澎湖天后宮","lat":23.564832,"lng":119.563924,"note":"1983年列為一級古蹟，今為國定古蹟","approx":false},{"name":"篤行十村","lat":23.563858,"lng":119.56098,"note":"修復後設有潘安邦紀念館、張雨生故事館等","approx":false},{"name":"澎湖跨海大橋","lat":23.658029,"lng":119.554602,"note":"1996年改建完成通車","approx":false},{"name":"七美雙心石滬","lat":23.220252,"lng":119.446974,"note":"2006年登錄文化景觀，請在觀景台欣賞","approx":false},{"name":"吉貝石滬群","lat":23.736451,"lng":119.611236,"note":"2008年登錄文化景觀，石滬密度很高","approx":false},{"name":"望安花宅聚落","lat":23.373323,"lng":119.496576,"note":"2010年登錄為重要聚落建築群","approx":false},{"name":"七美史前石器製造場考古遺址群","lat":23.19144,"lng":119.42558,"note":"2020年指定公告","approx":false},{"name":"西嶼燈塔","lat":23.562421,"lng":119.46958,"note":"至今仍在運作的國定古蹟","approx":false}],"view":{"lat":23.46,"lng":119.55,"zoom":11},"dialogue":[{"who":"R","text":"回到現在了！澎湖到處都是遊客，跟以前的軍事前線差好多。"},{"who":"A","text":"對啊，1995年成立國家風景區，古蹟一個個被指定保存，天后宮在1983年就列為一級古蹟。"},{"who":"R","text":"跨海大橋好像跟舊照片長得不一樣？"},{"who":"A","text":"因為海風和鹽分把舊橋吃得太兇，1984年動工改建，1996年新橋通車，算是大橋的第二代。"},{"who":"R","text":"那七美的雙心石滬到底怎麼抓魚？"},{"who":"A","text":"用石頭在潮間帶圍成堤，漲潮魚游進來，退潮就被困在滬房裡，等於海水自動幫你關門。"},{"who":"R","text":"好聰明！那我可以下去踩踩看嗎？"},{"who":"A","text":"千萬不行，很多石滬已經崩塌，要靠匠師修。請在觀景台或岸上看就好，不要踩、不要搬石頭。"},{"who":"A","text":"下次到七美觀景台，數一數雙心石滬有幾個滬房，拍一張完整的愛心給我看。"}],"quiz":[{"q":"石滬捕魚主要利用什麼自然現象？","options":["季風","潮汐漲退","洋流方向","日照長短"],"answer":1,"explain":"石滬在潮間帶以石塊圍成堤，漲潮時魚群進入，退潮時被困在滬房內。"},{"q":"參觀七美雙心石滬時，正確的做法是什麼？","options":["下去踩在石堤上拍照","搬幾塊石頭當紀念","在觀景台或岸上欣賞","攀爬到滬房中央"],"answer":2,"explain":"許多石滬因無人維護而崩塌，請在觀景台或岸上欣賞，不要踩踏、攀爬或搬動石頭。"}],"sources":[{"title":"澎湖跨海大橋（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖跨海大橋"},{"title":"澎湖縣，歷史與人口章節（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/澎湖縣"},{"title":"澎湖天后宮（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19831228000013"},{"title":"媽宮古城（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000086"},{"title":"馬公篤行十村（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071121000002"},{"title":"七美雙心石滬（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20061027000001"},{"title":"澎湖石滬文化景觀－吉貝石滬群（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20080602000001"},{"title":"望安花宅聚落（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/groupsOfBuildings/20100414000001"},{"title":"七美史前石器製造場考古遺址群（包含南港遺址第一、二、三、四地點、東湖遺址、西北灣遺址、西湖遺址）（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20210303000001"},{"title":"澎湖跨海大橋（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031211000007"}]}],"qingCity":{"name":"清代媽宮城（澎湖廳城）城垣","represents":"光緒15年（1889年）竣工後、1907年前後首次拆除南側城牆以前的城垣範圍，依1904年日治臺灣堡圖描繪。今僅存順承門、大西門與西側城牆一段。","outline":[[23.565777,119.561452],[23.566446,119.561484],[23.566908,119.561591],[23.567331,119.561827],[23.567616,119.562203],[23.567744,119.562578],[23.567822,119.563007],[23.567862,119.563651],[23.567921,119.564252],[23.56796,119.564939],[23.568039,119.56569],[23.568058,119.566441],[23.568078,119.567299],[23.568019,119.567964],[23.567763,119.568318],[23.567331,119.56864],[23.566859,119.568715],[23.566269,119.568747],[23.565728,119.568726],[23.565364,119.568318],[23.56499,119.567728],[23.564695,119.567642],[23.564302,119.567513],[23.563908,119.567299],[23.563712,119.567138],[23.563663,119.566441],[23.563663,119.565421],[23.563663,119.564724],[23.563663,119.563973],[23.563613,119.563437],[23.563417,119.563007],[23.563141,119.562289],[23.563073,119.56172],[23.563515,119.561559],[23.564105,119.561484],[23.564548,119.561377],[23.565089,119.561419],[23.565777,119.561452]],"gates":[{"name":"東門","gateName":"朝陽門","lat":23.565728,"lng":119.568726,"modernSpot":"約在今三民路、民福路與仁愛路交會處一帶。1895年日軍由此門攻入；東門段城牆在1937年起的築港工程中拆除，今已無遺跡。"},{"name":"北門","gateName":"拱辰門","lat":23.567921,"lng":119.564252,"modernSpot":"約在今民生路與民族路口一帶；北側城牆大致沿今民生路，1937年起拆除，今已無遺跡。"},{"name":"大西門","gateName":"大西門（未設城樓）","laterGateName":"中興門（1962年改建後名稱）","lat":23.564548,"lng":119.561377,"modernSpot":"今介壽路東側、軍事營區西緣的城牆上，與順承門同為國定古蹟媽宮古城的一部分；位在軍方範圍，請依現場公告參觀。"},{"name":"小西門","gateName":"順承門","lat":23.563141,"lng":119.562289,"modernSpot":"今中山路西端、新復路旁，現存唯一保有門樓的城門，旁邊就是篤行十村。"},{"name":"南面西側城門","gateName":"即敘門或迎薰門（兩種說法）","lat":23.563663,"lng":119.563973,"modernSpot":"約在今中山路與民族路口一帶。文獻對南門、小南門的名稱有兩種對應說法，這裡依1904年地圖上南面兩座城門的位置標示。1907年前後拆除南側城牆填海造港。"},{"name":"南面東側城門","gateName":"迎薰門或即敘門（兩種說法）","lat":23.563663,"lng":119.565421,"modernSpot":"約在今中山路與中正路口一帶，城門外的道路通往當時的碼頭，就是今天中正路的南段。"}],"batteries":[{"spot":"城外西南方的金龜頭礮臺（1887年吳宏洛所建，今國定古蹟）","lat":23.563284,"lng":119.557737}],"perimeterMeters":2261,"method":"以中央研究院臺灣百年歷史地圖WMTS之1904年日治臺灣堡圖（明治版）在縮放等級17描繪城牆雙線中心線，得36個頂點。與OpenStreetMap現代街道疊合比對，金龜頭海岸、民生路、中山路等與城牆走向吻合，順承門今址（OpenStreetMap）與堡圖上西南段城門位置相距約10公尺，因此未再做平移校正。城門名稱依中文維基百科「媽宮古城」「順承門」條目：東門朝陽、北門拱辰、小西門順承、大西門無城樓；南門與小南門的名稱，兩條目分別記為即敘、迎薰的不同對應，故兩座南面城門並列兩說。城門位置取堡圖上城牆的缺口與道路交會點。描繪周長約2.26公里，文獻記載城周789丈2尺5寸（約2.5公里），面積文獻記約26公頃，描繪約33公頃，偏大的原因可能是描繪線位於雙線中心及轉角處簡化。文獻記載東側城牆設有礮位一尊（東門砲台），確切位置不明，未標示。","confidence":"中等偏低。1904年堡圖在馬公市區與現代街道大致吻合，城牆輪廓一般誤差約20至60公尺，東南角與西北角圓弧段最不確定；城門位置為依地圖缺口推定，順承門有現存實物，誤差最小。南面兩座城門的名稱有爭議。請以「約略範圍」呈現，勿標示為精確城址。","sources":[{"title":"媽宮古城（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/媽宮古城"},{"title":"順承門（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/順承門"},{"title":"媽宮古城（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000086"},{"title":"馬公金龜頭礮臺（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20011121000002"},{"title":"臺灣百年歷史地圖：1904日治臺灣堡圖（中央研究院人社中心 GIS專題中心 WMTS）","url":"https://gis.sinica.edu.tw/tileserver/"},{"title":"OpenStreetMap 現代道路資料（用於比對與定位）","url":"https://www.openstreetmap.org/"}]},"ich":{"items":[],"venues":[]},"ubike":{"meta":{},"stations":[]},"extra":{"intro":[{"who":"A","text":"嗨，我是 Allan Lo！這一站我們坐船、搭飛機，來到臺灣海峽中間的澎湖群島，大大小小有好幾十座島嶼。"},{"who":"R","text":"我是阿拉蕾！澎湖不就是仙人掌冰、黑糖糕，還有夏天的花火節嗎？"},{"who":"A","text":"那些都很棒，不過澎湖的歷史更精彩，宋元時期就有漢人在這裡活動的記載，比臺灣本島還早。"},{"who":"R","text":"真的假的？那澎湖有多少文化資產？"},{"who":"A","text":"有形的一共90處，國定古蹟就有9處，像澎湖天后宮、媽宮古城，還有荷蘭人在風櫃尾築過的城堡。"},{"who":"R","text":"我還聽說西嶼有好多礮臺，還有一座很老的燈塔！"},{"who":"A","text":"對，清代為了守住澎湖這個海上門戶，在西嶼、金龜頭、拱北山都蓋了礮臺。戰爭的故事，我們用平靜的心情好好聽。"},{"who":"R","text":"那些用咕咾石蓋的古厝也好漂亮，可以進去看嗎？"},{"who":"A","text":"很多古厝還有人住，在外面欣賞就好，雙心石滬也請在岸上看，千萬不要踩上去。"},{"who":"R","text":"了解！騎上跨海大橋、搭船跳島，我們出發逛菊島囉！"}],"timeIntro":[{"who":"R","text":"Allan，澎湖的時光地圖第一站怎麼不是荷蘭時期，而是宋元明與荷蘭時期？"},{"who":"A","text":"因為澎湖的故事開始得比較早，宋代就有漢人漁民與駐軍的記載，元代還設了澎湖巡檢司。"},{"who":"A","text":"接著是明鄭、清代的媽宮城和礮臺，再到日治時期的馬公要港，一直到戰後和今天。"},{"who":"R","text":"清代以後的時期，還可以疊上1904年的臺灣堡圖和日治時期的地形圖！"},{"who":"A","text":"沒錯，拉一下透明度，看看媽宮城的城牆今天變成了哪條路。"}],"planIntro":[{"who":"A","text":"澎湖沒有火車也沒有 YouBike，最方便的是租機車或開車，本島、白沙和西嶼都有橋相連。"},{"who":"R","text":"騎上跨海大橋，就能去西嶼看礮臺和燈塔！"},{"who":"A","text":"吉貝、望安、七美要搭船，冬天東北季風強，船班少又常停航，一定要先查船班。目斗嶼燈塔一般人不能登島，我會在行程上標出來。"},{"who":"R","text":"中午記得留肚子給小管料理，飯後再來一碗仙人掌冰！"}],"gameIntro":[{"who":"R","text":"菊島遊戲場開張！問答王、時光排序、猜猜我是誰、翻翻樂，還有菊島擲骰大冒險！"},{"who":"A","text":"題目從澎湖天后宮、媽宮古城，一路考到西嶼礮臺和雙心石滬，看你能不能全部答對。"},{"who":"R","text":"Allan，這次擲骰子我一定贏你！"},{"who":"A","text":"哈哈，那就從馬公港出發，比比看吧！"}],"reactions":[{"who":"R","text":"答對了！你根本就是澎湖通！"},{"who":"A","text":"正確答案！給你一個大大的讚。"},{"who":"R","text":"哎呀，答錯了，沒關係，看看解說再挑戰！"},{"who":"A","text":"可惜！差一點點，下次一定行。"},{"who":"R","text":"換我擲骰子囉！看我的！"},{"who":"A","text":"恭喜你贏了！今天的仙人掌冰算我的！"},{"who":"R","text":"耶！這一局是我贏了，要不要再來一局？"},{"who":"A","text":"平手！你們兩個都是文資高手。"},{"who":"R","text":"時光排序完成！你從七美的史前石器工場一路排到今天的澎湖，好厲害！"},{"who":"A","text":"恭喜集到新的護照印章！"},{"who":"R","text":"全部配對成功，記憶力滿分！"},{"who":"A","text":"嗯，這一題我們一起看看解說。"}],"starts":[{"id":"magong-port","name":"馬公港（南海遊客服務中心）","lat":23.56645,"lng":119.57242},{"id":"airport","name":"澎湖機場（馬公機場）","lat":23.56879,"lng":119.62901},{"id":"tianhou","name":"馬公市區（澎湖天后宮）","lat":23.564832,"lng":119.563924},{"id":"chikan","name":"白沙赤崁（北海遊客服務中心）","lat":23.66877,"lng":119.60305},{"id":"gps","name":"我的目前位置","lat":null,"lng":null},{"id":"pick","name":"在地圖上點選出發點","lat":null,"lng":null}],"plans":{"1":{"name":"一日：馬公市區（天后宮、中央老街、四眼井、媽宮古城順承門、金龜頭礮臺）","days":[["magong-tianhougong","magong-shigongcijiwanjun","magong-siyanjing","magong-qianyitangzhongyao","magong-taishajiaohuiguan","magong-magongchenghuang","magong-tingshe","magong-diyibinguan","magong-guanyinting","magong-magonggucheng","magong-jinguitoupaotai","magong-duxingshicun"]]},"2":{"name":"二日：馬公市區 ＋ 白沙、西嶼（瓦硐、跨海大橋、二崁、西嶼東臺與西臺、西嶼燈塔）","days":[["magong-tianhougong","magong-shigongcijiwanjun","magong-siyanjing","magong-qianyitangzhongyao","magong-taishajiaohuiguan","magong-magongchenghuang","magong-tingshe","magong-diyibinguan","magong-guanyinting","magong-magonggucheng","magong-jinguitoupaotai","magong-duxingshicun"],["baisha-wadongxulingyunxiu","baisha-tonglianglinjiagu","baisha-kuahaidaqiao","xiyu-erkanchenzhai","xiyu-xianghuangshizong","xiyu-danyaobenku","xiyu-dongtai","xiyu-xitai","xiyu-dengta"]]},"3":{"name":"三日：馬公、白沙、西嶼 ＋ 望安（花宅聚落、西安許真古宅）","days":[["magong-tianhougong","magong-shigongcijiwanjun","magong-siyanjing","magong-qianyitangzhongyao","magong-taishajiaohuiguan","magong-magongchenghuang","magong-tingshe","magong-diyibinguan","magong-guanyinting","magong-magonggucheng","magong-jinguitoupaotai","magong-duxingshicun"],["baisha-wadongxulingyunxiu","baisha-tonglianglinjiagu","baisha-kuahaidaqiao","xiyu-erkanchenzhai","xiyu-xianghuangshizong","xiyu-danyaobenku","xiyu-dongtai","xiyu-xitai","xiyu-dengta"],["wangan-huazhaijuluo","wangan-xianxuzhenguzhai"]]},"qimei":{"label":"三日（七美版）","name":"三日七美版：馬公、白沙、西嶼 ＋ 七美（雙心石滬、史前石器製造場遺址）","days":[["magong-tianhougong","magong-shigongcijiwanjun","magong-siyanjing","magong-qianyitangzhongyao","magong-taishajiaohuiguan","magong-magongchenghuang","magong-tingshe","magong-diyibinguan","magong-guanyinting","magong-magonggucheng","magong-jinguitoupaotai","magong-duxingshicun"],["baisha-wadongxulingyunxiu","baisha-tonglianglinjiagu","baisha-kuahaidaqiao","xiyu-erkanchenzhai","xiyu-xianghuangshizong","xiyu-danyaobenku","xiyu-dongtai","xiyu-xitai","xiyu-dengta"],["qimei-shiqianshiqizhizao","qimei-shuangxinshihu"]]},"jibei":{"label":"三日（吉貝版）","name":"三日吉貝版：馬公、白沙、西嶼 ＋ 吉貝（林江西古宅、吉貝石滬群）","days":[["magong-tianhougong","magong-shigongcijiwanjun","magong-siyanjing","magong-qianyitangzhongyao","magong-taishajiaohuiguan","magong-magongchenghuang","magong-tingshe","magong-diyibinguan","magong-guanyinting","magong-magonggucheng","magong-jinguitoupaotai","magong-duxingshicun"],["baisha-wadongxulingyunxiu","baisha-tonglianglinjiagu","baisha-kuahaidaqiao","xiyu-erkanchenzhai","xiyu-xianghuangshizong","xiyu-danyaobenku","xiyu-dongtai","xiyu-xitai","xiyu-dengta"],["baisha-jibeilinjiangxigu","baisha-shihuwenhuajing"]]}},"food":[]}};
